/* View: AUSGBUCH_ADR_OHNE_VERBUCHEN_2, Owner: SYSDBA */
CREATE VIEW AUSGBUCH_ADR_OHNE_VERBUCHEN_2 (RECH_DAT, RE_LAUF, FAKT_LNR, MAND_NR, BUDAT, LNR_LEIST, BEZEICHN, RECHNR, LNR_CO, BETRAG, HG, WG, KONTONR, DURCHL, KONTOBEZ, MERKER, TAG_ABS, ZINR, ANREDE, NAME1, NAME2, STRASSE, PLZ, ORT, DB_STATUS, ADR_LNR) AS

SELECT DISTINCT AUSGBUCH.rech_dat as RECH_DAT, AUSGBUCH.re_lauf, AUSGBUCH.LNR, ausgbuch.mand_nr, ausgbuch.rech_dat, ausgbuch.leist_lnr AS LNR_LEIST, ausgbuch.bezeichn,
       ausgbuch.rechnr, ausgbuch.lnr_co, ausgbuch.umsatz AS BETRAG,
       LEISTSTA.HG, LEISTSTA.WG, LEISTSTA.KONTONR, WARENGRU.DURCHL,
       kontstam.bezeichn as kontobez, kontstam.merker,
       FAKT_ERLOESE.TAG_ABS,zimmstam.zinr, adressen.anrede, adressen.name1, adressen.name2, adressen.strasse, adressen.plz, adressen.ort,
        AUSGBUCH.DB_STATUS, AUSGBUCH.adr_lnr

FROM ausgbuch
   Left outer join BUCHKONT on (AUSGBUCH.LNR_BUCHKONT = BUCHKONT.LNR)
   left outer join fakt_erloese on (buchkont.lnr = fakt_erloese.lnr_buchkont and (FAKT_ERLOESE.tag_abs<=0) and (FAKT_ERLOESE.zahlungsart=9999)
   and (FAKT_ERLOESE.TA_STATUS < 1000))
   left outer JOIN LEISTSTA ON (ausgbuch.leist_lnr = LEISTSTA.LNR)
   left outer JOIN WARENGRU ON (LEISTSTA.WG = WARENGRU.LNR)
   left outer join kontstam on (kontstam.kontonr = leiststa.kontonr)
   left outer join gastkont on (gastkont.lnr = fakt_erloese.belegnr) 
   left outer join zimmstam on (zimmstam.lnr = gastkont.lnr_zinr)
   left outer join adressen on (adressen.lnr = ausgbuch.adr_lnr)
where ausgbuch.umsatz > 0.000 or ausgbuch.umsatz < 0.000;

/* View: VIEW_PREISLISTE_NACH_SAISONNR, Owner: SYSDBA */
CREATE VIEW VIEW_PREISLISTE_NACH_SAISONNR (PCBEZEICHN, PPREISTYP, PMATCHC, PBEZEICHN, PPREISLIST_LNR, PSAISON, LBEZEICHN, PBETRAG, PZIMMERPREIS, PPAUSCHALE, PLNR, PMAND_NR, S_BEMERK, P_VON, P_BIS) AS

select DISTINCT preiscode.bezeichn, preislist.preistyp,preislist.matchc, preislist.bezeichung ,
       preislist.preislist_lnr,preislist.saison,
       leiststa.bezeichn, preislist.betrag, preislist.zimmerpreis, preislist.pauschale, preislist.lnr,
       preislist.mand_nr, saisstam.bemerk, preislist.von, preislist.bis

FROM PREISLIST
   LEFT OUTER JOIN SAISSTAM ON (PREISLIST.SAISON = SAISSTAM.saison and saisstam.ta_status<1000)
   LEFT OUTER JOIN PREISCODE ON (PREISLIST.PRCODE_LNR = PREISCODE.LNR)
   LEFT OUTER JOIN LEISTSTA ON (PREISLIST.LEIST_LNR = LEISTSTA.LNR)
WHERE 
      (PREISLIST.TA_STATUS < 1000);

/* View: VIEW_GASTKONT_WEBPLAN, Owner: SYSDBA */
CREATE VIEW VIEW_GASTKONT_WEBPLAN (LNR, NAME1, NAME2, STRASSE, PLZ, ORT, TELE1, E_MAIL, BEGLEIT_V, BEGLEIT, K1, K2, K3, K4, ANREDE, GASTKONT_LNR, VON, BIS) AS

SELECT distinct a.LNR, a.NAME1, a.NAME2, a.STRASSE, a.PLZ, a.ORT, a.TELE1, a.E_MAIL, a.BEGLEIT_V, a.BEGLEIT, a.K1, a.K2, a.K3, a.K4, a.ANREDE, view_gastkont.lnr, b.von, b.bis
FROM view_gastkont
inner join gastkont on gastkont.lnr = view_gastkont.lnr
inner join adressen a on a.lnr = gastkont.gastnr_1
inner join buchkont b on b.gk_lnr = gastkont.lnr
where a.ta_status < 1000 
and gastkont.ta_status <1000 and gastkont.ci_status <2
and char_length(a.name1) > 0 order by a.name1;

/* View: VIEW_GASTKONT_2, Owner: SYSDBA */
CREATE VIEW VIEW_GASTKONT_2 (NAME1, NAME2, STRASSE, LAND, PLZ, ORT, ANREISE, ABREISE, ZINR, KATEGORIE, MAND_NR, BUCH_STATUS, CI_STATUS, LNR, GASTNR_1, BELEGUNGSART) AS

select a.name1, a.name2,a.strasse,a.land,a.plz,a.ort,
       gk.vonaufh, gk.bisaufh, z.zinr, k.kategorie,
       gk.mand_nr,gk.buch_status,gk.ci_status,gk.lnr, gk.gastnr_1 ,
       gk.BELEGUNGSART

from gastkont gk
    inner join adressen a on (gk.gastnr_1  = a.lnr and gk.ta_status <500)
    left outer join zimmstam z on (z.lnr = gk.lnr_zinr)
    left outer join katestam k  on (k.lnr = z.lnr_kate);

/* View: VIEW_ADRESSEN_ERW, Owner: SYSDBA */
CREATE VIEW VIEW_ADRESSEN_ERW (LNR, ANREDE, TITEL, NAME1, NAME2, STRASSE, LAND, PLZ, ORT, TELE1, TELE2, TELE3, E_MAIL, ANREDEBRF, GEBDAT, GESCHLECHT, SPRACHE) AS
select a.lnr, a.anrede, a.titel, a.name1, a.name2,a.strasse,a.land,a.plz,a.ort,
       a.tele1, a.tele2, a.tele3, a.e_mail, a.anredebrf, a.gebdat, a.geschlecht, a.sprache
from  adressen a;

/* View: VIEW_GASTKONT, Owner: SYSDBA */
CREATE VIEW VIEW_GASTKONT (NAME1, NAME2, STRASSE, LAND, PLZ, ORT, ANREISE, ABREISE, ZINR, KATEGORIE, MAND_NR, BUCH_STATUS, CI_STATUS, LNR, PARTY_NR) AS
select a.name1, a.name2,a.strasse,a.land,a.plz,a.ort,
       gk.vonaufh, gk.bisaufh, z.zinr, k.kategorie,
       gk.mand_nr,gk.buch_status,gk.ci_status,gk.lnr, gk.party_nr
from adressen a
    inner join gastkont gk on (gk.gastnr_1  = a.lnr)
    left outer join zimmstam z on (z.lnr = gk.lnr_zinr)
    left outer join katestam k  on (k.lnr = z.lnr_kate)
where gk.ta_status <500;

/* View: VIEW_ZI_KATE, Owner: SYSDBA */
CREATE VIEW VIEW_ZI_KATE (LNR, ZINR, MAND_NR, STOCK, BETTZAHL, TA_STATUS, KATE_NR, OBJEKT_NR, KATEGORIE, OBJEKT_BEZ, MAND_BEZ, LNR_KATE, GARAGE, HAUSTIER, RAUCHER, T_OPERATER, ZIMMERART, VERMIETJN, MANDZINR, AUSSTATTUNG, BEZEICHN, ZWEITES_ZIM) AS

select z.lnr, z.zinr,z.mand_nr,z.stock,z.bettzahl,z.ta_status,
       z.lnr_kate,z.objekt_nr, k.kategorie, o.bezeichn,m.bezeichn,z.lnr_kate,
       z.garage,z.haustier,z.raucher,z.to_operator,z.zimmerart,z.vermietjn,z.mand_nr,
       z.ausstatung, z.bezeichn, z.zweites_zim

from zimmstam z
     LEFT OUTER join katestam k on z.lnr_kate = k.lnr
     LEFT OUTER join objekt   o on z.objekt_nr=o.lnr
     LEFT OUTER join mandant  m on z.mand_nr = m.lnr
     where z.ta_status<1000;

/* View: VIEW_HOUSEKEEPING, Owner: SYSDBA */
CREATE VIEW VIEW_HOUSEKEEPING (DATUM, VONAUFH, BISAUFH, SORTIERUNG, MAN_SORTIERUNG, LNR, GK_LNR, TEXT_BEMERK, TA_STATUS, REIN_STATUS, VORGEREIN, VORGEREIN_MA, GEREINIGT, GEREINIGT_MA, KONTROLLIERT, KONTROLLIERT_MA, ZINR, STOCK, PUTZ_LNR, NAME1, NAME2, GASTNACHNAME, GASTVORNAME) AS

select 
    housekeeping.datum,
    gastkont.vonaufh,
    gastkont.bisaufh,
    housekeeping.sortierung,
    housekeeping.man_sortierung,
    housekeeping.lnr,
    housekeeping.gk_lnr,
    housekeeping.text_bemerk,
    housekeeping.ta_status,
    housekeeping.rein_status,
    housekeeping.vorgerein,
    housekeeping.vorgerein_ma,
    housekeeping.gereinigt,
    housekeeping.gereinigt_ma,
    housekeeping.kontrolliert,
    housekeeping.kontrolliert_ma,
    zimmstam.zinr,
    zimmstam.stock,
    zimmstam.putz_lnr,
    adressen.name1,
    adressen.name2,
    a2.name1 as Gastnachname,
    a2.name2 as Gastvorname


from housekeeping


   inner join gastkont on (gastkont.lnr = housekeeping.gk_lnr)
   inner join zimmstam on (zimmstam.lnr = gastkont.lnr_zinr)
   inner join adressen on (adressen.lnr = zimmstam.putz_lnr)
   left outer join adressen a2 on (a2.lnr = gastkont.gastnr_1);

/* View: VIEW_ADR_ANSPRECHP_VERB, Owner: SYSDBA */
CREATE VIEW VIEW_ADR_ANSPRECHP_VERB (LNR, ANREDE, TITEL, NAME1, NAME2, STRASSE, LAND, PLZ, ORT, TELE1, TELE2, TELE3, DEBI_NR, BEZEICHN, ANSP_NAME, ANSP_TATK, ANSP_EMAIL, ANSP_TELE1) AS

SELECT ADRESSEN.LNR, ADRESSEN.ANREDE, ADRESSEN.TITEL, ADRESSEN.NAME1, ADRESSEN.NAME2, ADRESSEN.STRASSE, ADRESSEN.LAND,
       ADRESSEN.PLZ, ADRESSEN.ORT, ADRESSEN.TELE1, ADRESSEN.TELE2, ADRESSEN.TELE3, ADRESSEN.DEBI_NR,
       ADR_AUSWAHL.BEZEICHN,
       ANSPRECHP.ANSP_NAME, ANSPRECHP.ANSP_TATK, ANSPRECHP.E_MAIL ANSPRECHP_EMAIL, ANSPRECHP.TELE1 ANSPRECHP_TELE1
FROM ADRESSEN
   LEFT OUTER JOIN ADR_AUSWAHL ON (ADRESSEN.ADR_WAHL = ADR_AUSWAHL.ADR_WAHL)
   LEFT OUTER JOIN ANSPRECHP ON (ADRESSEN.LNR = ANSPRECHP.ADR_LNR)

   where adressen.ta_status<1000;

/* View: VIEW_ADRESSEN, Owner: SYSDBA */
CREATE VIEW VIEW_ADRESSEN (ANREDE, NAME1, NAME2, STRASSE, LAND, PLZ, ORT, TELE1) AS

select a.anrede, a.name1, a.name2,a.strasse,a.land,a.plz,a.ort,a.tele1
from  adressen a
where a.ta_status<1000;

/* View: VIEW_BUCHUNGEN, Owner: SYSDBA */
CREATE VIEW VIEW_BUCHUNGEN (LNR, LNR_ZINR, LNR_GK, ANREISE, ABREISE, FARBE, ANZ_ZI, NAME1, NAME2) AS

select b.lnr, b.lnr_zinr,b.lnr_gk, b.anreise, b.abreise, b.farbe, b.anz_zi,
       a.name1,a.name2
from belegung b, adressen a, gastkont gk
where b.ta_status<1000 and
      gk.lnr = b.lnr_gk and
      a.lnr  = gk.gastnr_1;

/* View: VIEW_GET_REGK_VERB, Owner: SYSDBA */
CREATE VIEW VIEW_GET_REGK_VERB (BELEGNR, ANREISE, ABREISE, ZINR, NAME1, NAME2, BEMERK, ONLINE_CI) AS

SELECT distinct GASTKONT.LNR, BELEGUNG.ANREISE, BELEGUNG.ABREISE, ZIMMSTAM.ZINR,
                A_1.name1  AS NAME1, ADRESSEN.NAME1 || ' ' || ADRESSEN.NAME2 AS NAME2,
                    GASTKONT.BEMERK,
                    ONLINE_VERBUND.CI_STATUS as online_ci
           FROM BELEGUNG
                INNER JOIN GASTKONT ON (BELEGUNG.LNR_GK = GASTKONT.LNR)
                LEFT OUTER JOIN ADRESSEN ON (GASTKONT.GASTNR_1 = ADRESSEN.LNR)
                LEFT OUTER JOIN ZIMMSTAM ON (BELEGUNG.LNR_ZINR = ZIMMSTAM.LNR)
                LEFT OUTER JOIN ADRESSEN  a_1 ON (GASTKONT.GASTNR_2 = a_1.LNR)
                LEFT OUTER JOIN ONLINE_VERBUND ON (GASTKONT.LNR = ONLINE_VERBUND.GK_LNR)
     WHERE
     (
        (gastkont.ci_status = 1) and
        (gastkont.ta_status<500) and
        (current_date between gastkont.vonaufh and gastkont.bisaufh)
     );

/* View: VIEW_PREISLISTE, Owner: SYSDBA */
CREATE VIEW VIEW_PREISLISTE (PCBEZEICHN, PPREISTYP, PMATCHC, PBEZEICHN, PPREISLIST_LNR, PSAISON, LBEZEICHN, PBETRAG, PZIMMERPREIS, PPAUSCHALE, PLNR, PMAND_NR, S_VON, S_BIS, P_VON, P_BIS) AS

select preiscode.bezeichn, preislist.preistyp,preislist.matchc, preislist.bezeichung ,
       preislist.preislist_lnr,preislist.saison,
       leiststa.bezeichn, preislist.betrag, preislist.zimmerpreis, preislist.pauschale, preislist.lnr,
       preislist.mand_nr,
       saisstam.von, saisstam.bis, preislist.von, preislist.bis

FROM PREISLIST
   LEFT OUTER JOIN SAISSTAM ON (PREISLIST.SAISON = SAISSTAM.LNR)
   LEFT OUTER JOIN PREISCODE ON (PREISLIST.PRCODE_LNR = PREISCODE.LNR)
   LEFT OUTER JOIN LEISTSTA ON (PREISLIST.LEIST_LNR = LEISTSTA.LNR)
WHERE 
      (PREISLIST.TA_STATUS < 1000);

/* View: AUSGBUCH_ADR_OHNE_VERBUCHEN, Owner: SYSDBA */
CREATE VIEW AUSGBUCH_ADR_OHNE_VERBUCHEN (LNR, MAND_NR, ADR_LNR, RECHNR, RE_LAUF, RECH_DAT, LNR_ZINR, GBVON, GBBIS, LEIST_LNR, MENGE, EPREIS, UMSATZ, BELEGNR, STEUERSATZ, DB_STATUS, NAME1, NAME2, PLZ, ORT, BEZEICHN, LNR_CO, G_NAME1, G_NAME2) AS

select AUSGBUCH.LNR, AUSGBUCH.MAND_NR, AUSGBUCH.ADR_LNR, AUSGBUCH.RECHNR, AUSGBUCH.RE_LAUF,
       AUSGBUCH.RECH_DAT, AUSGBUCH.LNR_ZINR, AUSGBUCH.GBVON, AUSGBUCH.GBBIS, AUSGBUCH.LEIST_LNR,
       AUSGBUCH.MENGE, AUSGBUCH.EPREIS, AUSGBUCH.UMSATZ,
       AUSGBUCH.BELEGNR, AUSGBUCH.STEUERSATZ, AUSGBUCH.DB_STATUS,
       ADRESSEN.NAME1, ADRESSEN.NAME2, ADRESSEN.PLZ, ADRESSEN.ORT,
       AUSGBUCH.BEZEICHN,ausgbuch.lnr_co,
       a2.name1 as g_name1 ,a2.name2 as g_name2
from AUSGBUCH
    inner join ADRESSEN on (AUSGBUCH.ADR_LNR = ADRESSEN.LNR)
    Left outer join BUCHKONT on (AUSGBUCH.LNR_BUCHKONT = BUCHKONT.LNR)
    left outer join gastkont on (gastkont.lnr = ausgbuch.belegnr)
    left outer join adressen a2 on (gastkont.gastnr_2 = a2.lnr and gastkont.gastnr_2>0);

/* View: VIEW_ADRESSEN_ERW_KOR_MANAGER, Owner: SYSDBA */
CREATE VIEW VIEW_ADRESSEN_ERW_KOR_MANAGER (LNR, ANREDE, TITEL, NAME1, NAME2, STRASSE, LAND, PLZ, ORT, TELE1, TELE2, TELE3, E_MAIL, ANREDEBRF, GEBDAT, GESCHLECHT, ISO_ZEICHEN, LANGUAGE, ISO_KORR_MAN_VERW) AS
select a.lnr, a.anrede, a.titel, a.name1, a.name2,a.strasse,a.land,a.plz,a.ort,
       a.tele1, a.tele2, a.tele3, a.e_mail, a.anredebrf, a.gebdat, a.geschlecht, sprache.iso_zeichen, sprache.iso_zeichen as language , sprache.iso_korr_man_verw
from  adressen a
   left outer join sprache on (sprache.lnr = a.sprache);

/* View: VIEW_BUCHUNG_GK_BELEGUNG, Owner: SYSDBA */
CREATE VIEW VIEW_BUCHUNG_GK_BELEGUNG (BUCHNR, VONAUFH, BISAUFH, GASTNR_1, GASTNR_2, GASTNR_3, BEMERK, TISCH, GARAGE, BU_ST_OPTION, RESVBDAT, PERSZAHL, ANZJUGEND, ANZKINDER, ANZKINDER2, ANZKLEINKIND, BEGLEITOK, KIND1OK, KIND2OK, KIND3OK, KIND4OK, BUCH_STATUS, SHARE_NR, CI_STATUS, ANREISE, ABREISE, KATEGORIE, ZINR, BEZEICHN) AS
select gastkont.lnr as buchnr, gastkont.vonaufh, gastkont.bisaufh,
gastkont.gastnr_1, gastkont.gastnr_2, gastkont.gastnr_3,
gastkont.bemerk, gastkont.tisch, gastkont.garage, gastkont.bu_st_option, gastkont.resvbdat,
gastkont.perszahl, gastkont.anzjugend, gastkont.anzkinder, gastkont.anzkinder2, gastkont.anzkleinkind,
gastkont.begleitok, gastkont.kind1ok, gastkont.kind2ok, gastkont.kind3ok, gastkont.kind4ok,
gastkont.buch_status, gastkont.share_nr, gastkont.ci_status,
belegung.anreise, belegung.abreise,
katestam.kategorie, zimmstam.zinr, zimmstam.bezeichn

from belegung
  inner join gastkont on (gastkont.lnr = belegung.lnr_gk and belegung.ta_status <1000)
  left outer join katestam on (katestam.lnr = belegung.lnr_kate)
  left outer join zimmstam on (zimmstam.lnr = belegung.lnr_zinr);

/* View: VIEW_GASTKONT_SUCHE, Owner: SYSDBA */
CREATE VIEW VIEW_GASTKONT_SUCHE (NAME1, NAME2, SUCHNAME, STRASSE, LAND, PLZ, ORT, ANREISE, ABREISE, ZINR, KATEGORIE, MAND_NR, BUCH_STATUS, CI_STATUS, LNR, GASTNR_1, BELEGUNGSART) AS
select a.name1, a.name2,a.suchname ,a.strasse,a.land,a.plz,a.ort,
       gk.vonaufh, gk.bisaufh, z.zinr, k.kategorie,
       gk.mand_nr,gk.buch_status,gk.ci_status,gk.lnr, gk.gastnr_1 ,
       gk.BELEGUNGSART

from gastkont gk
    inner join adressen a on (gk.gastnr_1  = a.lnr and gk.ta_status <500)
    left outer join zimmstam z on (z.lnr = gk.lnr_zinr)
    left outer join katestam k  on (k.lnr = z.lnr_kate);

/* View: AUSGBUCH_ADR_OHNE_VERBUCHEN_ERW, Owner: SYSDBA */
CREATE VIEW AUSGBUCH_ADR_OHNE_VERBUCHEN_ERW (LNR, MAND_NR, ADR_LNR, RECHNR, RE_LAUF, RECH_DAT, LNR_ZINR, GBVON, GBBIS, LEIST_LNR, MENGE, EPREIS, UMSATZ, BELEGNR, STEUERSATZ, DB_STATUS, NAME1, NAME2, PLZ, ORT, BEZEICHN, LNR_CO, G_NAME1, G_NAME2, ZA_BAR, ZA_UNBAR, ZINR) AS
select AUSGBUCH.LNR, AUSGBUCH.MAND_NR, AUSGBUCH.ADR_LNR, AUSGBUCH.RECHNR, AUSGBUCH.RE_LAUF,
       AUSGBUCH.RECH_DAT, AUSGBUCH.LNR_ZINR, AUSGBUCH.GBVON, AUSGBUCH.GBBIS, AUSGBUCH.LEIST_LNR,
       AUSGBUCH.MENGE, AUSGBUCH.EPREIS, AUSGBUCH.UMSATZ,
       AUSGBUCH.BELEGNR, AUSGBUCH.STEUERSATZ, AUSGBUCH.DB_STATUS,
       ADRESSEN.NAME1, ADRESSEN.NAME2, ADRESSEN.PLZ, ADRESSEN.ORT,
       AUSGBUCH.BEZEICHN,ausgbuch.lnr_co,
       a2.name1 as g_name1 ,a2.name2 as g_name2,
       (select coalesce(  sum(zahlungen.betrag),0) as za_bar from zahlungen
            inner join devisen on (devisen.lnr = zahlungen.lnr_devi and devisen.zahlungsart = 0 and
                                        zahlungen.lnr_co = ausgbuch.lnr_co and zahlungen.ta_status<1000))
        ,
        (select coalesce(  sum(zahlungen.betrag),0) as za_unbar from zahlungen
            inner join devisen on (devisen.lnr = zahlungen.lnr_devi and devisen.zahlungsart > 0 and
                                        zahlungen.lnr_co = ausgbuch.lnr_co and zahlungen.ta_status<1000)),
        zimmstam.zinr


from AUSGBUCH
    inner join ADRESSEN on (AUSGBUCH.ADR_LNR = ADRESSEN.LNR)
    Left outer join BUCHKONT on (AUSGBUCH.LNR_BUCHKONT = BUCHKONT.LNR)
    left outer join gastkont on (gastkont.lnr = ausgbuch.belegnr)
    left outer join adressen a2 on (gastkont.gastnr_2 = a2.lnr and gastkont.gastnr_2>0)
    left outer join zimmstam on (zimmstam.lnr = ausgbuch.lnr_zinr);

COMMIT WORK;
SET AUTODDL OFF;
SET TERM ^ ;

/* Stored procedures bodies */

ALTER PROCEDURE ANZ_NACHTE_PRO_ZINR (JAHR INTEGER)
RETURNS (ZI_LNR INTEGER,
TAGE INTEGER)
AS 
begin
  /* Procedure Text */
  for
    SELECT belegung.lnr_zinr, SUM(belegung.abreise - belegung.anreise) AS TAGE
      FROM belegung
           WHERE (belegung.ta_status < 1000) AND
           EXTRACT(YEAR from belegung.anreise) = :"JAHR"

       GROUP BY lnr_zinr
       ORDER BY lnr_zinr
       into :"ZI_LNR", :"TAGE"


  do
  suspend;
end ^

ALTER PROCEDURE BUCH_N_DATUM_DELETE (DATUM DATE)
AS 
declare variable BUCHNR integer;
begin
  /* Procedure Text */
  for
    select gastkont.lnr
    from gastkont
      where gastkont.bisaufh< :Datum
      into :"BUCHNR"
  do
 -- suspend;
  if (buchnr>0) then
  begin
    delete from buchkont where buchkont.gk_lnr = :buchnr;
    delete from belegung where belegung.lnr_gk = :buchnr;
    delete from gastkont where gastkont.lnr = :buchnr;
  end
  --suspend;

end ^

ALTER PROCEDURE CO_GK_BELEG (GK_LNR INTEGER)
AS 
begin
  /* Procedure Text */
   update gastkont set ta_status = 500, ci_status = 2, gastkont.tgabsdatum = bisaufh
     where lnr = :gk_lnr and ta_status<500;

   update belegung set ta_status = 500
     where lnr_gk = :gk_lnr and ta_status<500;
   update buchkont set ta_status = 500
     where gk_lnr = :gk_lnr and ta_status<500;

end ^

ALTER PROCEDURE DEL_PREISSPLITTING (LNROLD INTEGER)
AS 
begin
  /* Procedure Text */
  update preissplitting set ta_status = ta_status+1000
  where lnr = :lnrold;

end ^

ALTER PROCEDURE DRUCK_ANR_ABR_UMZUG RETURNS (GK_LNR INTEGER,
UMZUG_AM DATE,
UMZUG_ZI VARCHAR(10) CHARACTER SET NONE)
AS 
declare variable anz_beleg integer;
declare variable zinr varchar(10) character set none;
declare variable abreise date;
declare variable lauf integer;
declare variable anreise date;
declare variable belegnr integer;
begin
  /* Procedure Text */
  ANZ_BELEG = 0;
  LAUF = 0;
  for
    SELECT GASTKONT.LNR
    FROM GASTKONT
    WHERE GASTKONT.TA_STATUS < 1000
    INTO :BELEGNR
  do
  begin
    for
        select count(*) from belegung
             LEFT OUTER JOIN ZIMMSTAM ON (BELEGUNG.LNR_ZINR = ZIMMSTAM.LNR)
        WHERE (BELEGUNG.LNR_GK = :BELEGNR) AND (BELEGUNG.TA_STATUS < 1000)
        into :ANZ_BELEG
    do
    begin
        LAUF = 0;
        if(ANZ_BELEG > 1) THEN
        BEGIN
            for
                SELECT BELEGUNG.ANREISE, BELEGUNG.ABREISE, ZIMMSTAM.ZINR
                FROM BELEGUNG
                    LEFT OUTER JOIN ZIMMSTAM ON (BELEGUNG.LNR_ZINR = ZIMMSTAM.LNR)
                WHERE (BELEGUNG.LNR_GK = :BELEGNR) AND (BELEGUNG.TA_STATUS < 1000)
                INTO :ANREISE, :ABREISE, :ZINR
            do
            begin
                LAUF = LAUF +1;
                if(LAUF = 2) THEN
                begin
                    UMZUG_AM = :ANREISE;
                    UMZUG_ZI = :ZINR;
                    GK_LNR = :BELEGNR;
                    LAUF = 0;
                    suspend;
                end
            end
        end
    end
  end
end ^

ALTER PROCEDURE DRUCK_ANR_ABR_UMZUG_NEU (GKLNR INTEGER)
RETURNS (GK_LNR INTEGER,
UMZUG_AM DATE,
UMZUG_ZI VARCHAR(10) CHARACTER SET NONE)
