  for
    SELECT GASTKONT.LNR
    FROM GASTKONT
    WHERE GASTKONT.LNR = :gklnr
         and GASTKONT.TA_STATUS < 1000
    INTO :BELEGNR
  do
  begin
    for
        select count(*) from belegung
             LEFT OUTER JOIN ZIMMSTAM ON (BELEGUNG.LNR_ZINR = ZIMMSTAM.LNR)
        WHERE (BELEGUNG.LNR_GK = :BELEGNR) AND (BELEGUNG.TA_STATUS < 1000)
        into :ANZ_BELEG
    do
    begin
        LAUF = 0;
        if(ANZ_BELEG > 1) THEN
        BEGIN
            for
                SELECT BELEGUNG.ANREISE, BELEGUNG.ABREISE, ZIMMSTAM.ZINR
                FROM BELEGUNG
                    LEFT OUTER JOIN ZIMMSTAM ON (BELEGUNG.LNR_ZINR = ZIMMSTAM.LNR)
                WHERE (BELEGUNG.LNR_GK = :BELEGNR) AND (BELEGUNG.TA_STATUS < 1000)
                INTO :ANREISE, :ABREISE, :ZINR
            do
            begin
                LAUF = LAUF +1;
                if(LAUF = 2) THEN
                begin
                    UMZUG_AM = :ANREISE;
                    UMZUG_ZI = :ZINR;
                    GK_LNR = :BELEGNR;
                    LAUF = 0;
                    suspend;
                end
            end
        end
    end
  end
end ^

ALTER PROCEDURE DRUCK_BELEGUNG RETURNS (ANREDE VARCHAR(30) CHARACTER SET NONE,
NAME1 VARCHAR(60) CHARACTER SET NONE,
NAME2 VARCHAR(60) CHARACTER SET NONE,
STRASSE VARCHAR(60) CHARACTER SET NONE,
PLZ VARCHAR(10) CHARACTER SET NONE,
ORT VARCHAR(50) CHARACTER SET NONE,
VONAUFH DATE,
BISAUFH DATE,
CI_STATUS INTEGER,
BEMERK VARCHAR(100) CHARACTER SET NONE,
MAND_NR INTEGER,
MAND_BEZEICHN VARCHAR(50) CHARACTER SET NONE,
ZINR VARCHAR(10) CHARACTER SET NONE,
NACHT INTEGER,
TAG INTEGER,
WASSER INTEGER,
TELEF INTEGER,
W_WASSER INTEGER,
GAS INTEGER,
LAND VARCHAR(5) CHARACTER SET NONE,
GASTNR INTEGER,
PERSZAHL INTEGER,
ANZKINDER INTEGER,
LNR INTEGER,
ANZJUGEND INTEGER,
VERMIET_GASTNR INTEGER,
BUCHNR INTEGER,
ZI_BEZEICHN VARCHAR(100) CHARACTER SET NONE,
ZI_BEMERK1 VARCHAR(255) CHARACTER SET NONE,
BELEGUNGSART INTEGER)
AS 
begin
  /* Procedure Text */
  for
   SELECT ADRESSEN.ANREDE, ADRESSEN.NAME1, ADRESSEN.NAME2, ADRESSEN.STRASSE, ADRESSEN.PLZ, ADRESSEN.ORT,
          adressen.land, adressen.lnr as gastnr,
          GASTKONT.VONAUFH, GASTKONT.BISAUFH, GASTKONT.CI_STATUS, GASTKONT.BEMERK, GASTKONT.MAND_NR, gastkont.perszahl, gastkont.anzkinder, gastkont.anzjugend, gastkont.lnr,
          MANDANT.BEZEICHN,
          ZIMMSTAM.ZINR, ZIMMSTAM.NACHT, ZIMMSTAM.TAG, ZIMMSTAM.WASSER, ZIMMSTAM.TELEF, ZIMMSTAM.W_WASSER, ZIMMSTAM.GAS ,
          zimmstam.adr_lnr as vermiet_gastnr, gastkont.lnr as buchnr,
          zimmstam.bezeichn, zimmstam.bemerk1 ,
          gastkont.belegungsart

   FROM GASTKONT
     INNER JOIN ADRESSEN ON (GASTKONT.GASTNR_1 = ADRESSEN.LNR)
     INNER JOIN ZIMMSTAM ON (GASTKONT.LNR_ZINR = ZIMMSTAM.LNR)
     INNER JOIN MANDANT ON (GASTKONT.MAND_NR = MANDANT.LNR)



     where gastkont.ta_status<1000
     /*and
           gastkont.gastnr_1 = adressen.lnr */

     into :"ANREDE", :"NAME1", :"NAME2", :"STRASSE", :"PLZ", :"ORT", :"LAND", :"GASTNR",
          :"VONAUFH", :"BISAUFH", :"CI_STATUS", :"BEMERK", :"MAND_NR", :"PERSZAHL", :"ANZKINDER", :"ANZJUGEND", :"LNR",
          :"MAND_BEZEICHN", :"ZINR", :"NACHT", :"TAG", :"WASSER", :"TELEF", :"W_WASSER", :"GAS",
          :"VERMIET_GASTNR", :"BUCHNR", :"ZI_BEZEICHN" , :"ZI_BEMERK1" , :"BELEGUNGSART"




  do
  suspend;
end ^

ALTER PROCEDURE DRUCK_CI RETURNS (ANREDE VARCHAR(30) CHARACTER SET NONE,
LNR_ZINR INTEGER,
NAME1 VARCHAR(60) CHARACTER SET NONE,
NAME2 VARCHAR(60) CHARACTER SET NONE,
STRASSE VARCHAR(60) CHARACTER SET NONE,
PLZ VARCHAR(10) CHARACTER SET NONE,
ORT VARCHAR(50) CHARACTER SET NONE,
VONAUFH DATE,
BISAUFH DATE,
CI_STATUS INTEGER,
BEMERK VARCHAR(100) CHARACTER SET NONE,
MAND_NR INTEGER,
MAND_BEZEICHN VARCHAR(50) CHARACTER SET NONE,
ZINR VARCHAR(10) CHARACTER SET NONE,
NACHT INTEGER,
TAG INTEGER,
WASSER INTEGER,
TELEF INTEGER,
W_WASSER INTEGER,
GAS INTEGER,
LAND VARCHAR(5) CHARACTER SET NONE,
PERSZAHL INTEGER,
ANZKINDER INTEGER,
LNR INTEGER,
ANZJUGEND INTEGER,
ADR_LNR INTEGER)
AS 
begin
  /* Procedure Text */
  for
   SELECT ADRESSEN.ANREDE, ADRESSEN.NAME1, ADRESSEN.NAME2, ADRESSEN.STRASSE, ADRESSEN.PLZ, ADRESSEN.ORT, adressen.land,
          GASTKONT.VONAUFH, GASTKONT.BISAUFH, GASTKONT.CI_STATUS, GASTKONT.BEMERK, GASTKONT.MAND_NR, gastkont.perszahl, gastkont.anzkinder, gastkont.anzjugend, gastkont.lnr,
          MANDANT.BEZEICHN,
          Zimmstam.lnr, zimmstam.zinr, ZIMMSTAM.NACHT, ZIMMSTAM.TAG, ZIMMSTAM.WASSER, ZIMMSTAM.TELEF, ZIMMSTAM.W_WASSER, ZIMMSTAM.GAS,
          Adressen.lnr

   FROM GASTKONT
     INNER JOIN ADRESSEN ON (GASTKONT.GASTNR_1 = ADRESSEN.LNR)
     INNER JOIN ZIMMSTAM ON (GASTKONT.LNR_ZINR = ZIMMSTAM.LNR)
     INNER JOIN MANDANT ON (GASTKONT.MAND_NR = MANDANT.LNR)

     where gastkont.ta_status<1000 and
           gastkont.ci_status=1
     into :"ANREDE", :"NAME1", :"NAME2", :"STRASSE", :"PLZ", :"ORT", :"LAND",
          :"VONAUFH", :"BISAUFH", :"CI_STATUS", :"BEMERK", :"MAND_NR", :"PERSZAHL", :"ANZKINDER", :"ANZJUGEND", :"LNR",
          :"MAND_BEZEICHN",:"LNR_ZINR", :"ZINR", :"NACHT", :"TAG", :"WASSER", :"TELEF", :"W_WASSER", :"GAS",
          :"ADR_LNR"




  do
  suspend;
end ^

ALTER PROCEDURE DRUCK_FAKT_ERLOESE (VONDATUM DATE,
BISDATUM DATE,
STATUS INTEGER,
MAND_NR INTEGER)
RETURNS (BUDAT DATE,
BELEGNR INTEGER,
BEZEICHN VARCHAR(100) CHARACTER SET NONE,
BETRAG NUMERIC(12, 3),
RECHNR INTEGER,
RE_LAUF INTEGER,
VON DATE,
BIS DATE,
NAME1 VARCHAR(80) CHARACTER SET NONE,
NAME2 VARCHAR(80) CHARACTER SET NONE,
PLZ VARCHAR(10) CHARACTER SET NONE,
ORT VARCHAR(50) CHARACTER SET NONE,
STSATZ NUMERIC(12, 3),
KONTONR VARCHAR(10) CHARACTER SET NONE,
MANUELL INTEGER,
LNR INTEGER)
AS 
begin
  /* Procedure Text */
  for
    SELECT FAKT_ERLOESE.BUDAT, FAKT_ERLOESE.BELEGNR, FAKT_ERLOESE.BEZEICHN,
           FAKT_ERLOESE.BETRAG, FAKT_ERLOESE.RECHNR, FAKT_ERLOESE.RE_LAUF,
           FAKT_ERLOESE.VOND, FAKT_ERLOESE.BISD,
           ADRESSEN.NAME1, ADRESSEN.NAME2, ADRESSEN.PLZ, ADRESSEN.ORT,
           Steustam.stsatz,
           LEISTSTA.KONTONR,
           fakt_erloese.manuell,fakt_erloese.lnr

    FROM FAKT_ERLOESE
         INNER JOIN LEISTSTA ON (FAKT_ERLOESE.LNR_LEIST = LEISTSTA.LNR)
         LEFT OUTER JOIN STEUSTAM ON (FAKT_ERLOESE.ST_SCHL = STEUSTAM.LNR)
         left outer JOIN ADRESSEN ON (FAKT_ERLOESE.ADR_LNR = ADRESSEN.LNR)
         where  (fakt_erloese.lnr>=0) and
                (FAKT_ERLOESE.BUDAT>=:VONDATUM) and
                (fakt_erloese.budat<=:BISDATUM) and
                (fakt_erloese.mand_nr = :MAND_NR) and
                (fakt_erloese.ta_status<=:STATUS)

         into
           :"BUDAT", :"BELEGNR", :"BEZEICHN",
           :"BETRAG", :"RECHNR", :"RE_LAUF",
           :"VON", :"BIS",
           :"NAME1", :"NAME2", :"PLZ", :"ORT",
           :"STSATZ",:"KONTONR", :"MANUELL", :"LNR"



  do
  suspend;
end ^

ALTER PROCEDURE DRUCK_GEBURTSTAGE (VONDATUM DATE,
BISDATUM DATE,
HACKEN INTEGER)
RETURNS (VONAUFH DATE,
BISAUFH DATE,
BEGLEITOK INTEGER,
KIND1OK INTEGER,
KIND2OK INTEGER,
KIND3OK INTEGER,
KIND4OK INTEGER,
KIND5OK INTEGER,
ZINR VARCHAR(10) CHARACTER SET NONE,
LNR INTEGER,
ANREDE VARCHAR(30) CHARACTER SET NONE,
TITEL VARCHAR(30) CHARACTER SET NONE,
NAME1 VARCHAR(60) CHARACTER SET NONE,
NAME2 VARCHAR(60) CHARACTER SET NONE,
GEBDAT DATE,
ANREDE_B VARCHAR(30) CHARACTER SET NONE,
BEGLEIT VARCHAR(60) CHARACTER SET NONE,
BEGLEIT_V VARCHAR(60) CHARACTER SET NONE,
BEGLEIT_G DATE,
K1 VARCHAR(60) CHARACTER SET NONE,
K1_GEB DATE,
K2 VARCHAR(60) CHARACTER SET NONE,
K2_GEB DATE,
K3 VARCHAR(60) CHARACTER SET NONE,
K3_GEB DATE,
K4 VARCHAR(60) CHARACTER SET NONE,
K4_GEB DATE,
K5 VARCHAR(60) CHARACTER SET NONE,
K5_GEB DATE,
G2_ANREDE VARCHAR(30) CHARACTER SET NONE,
G2_TITEL VARCHAR(30) CHARACTER SET NONE,
G2_NAME1 VARCHAR(60) CHARACTER SET NONE,
G2_NAME2 VARCHAR(60) CHARACTER SET NONE,
G2_GEBDAT DATE,
G2_ANREDE_B VARCHAR(30) CHARACTER SET NONE,
G2_BEGLEIT VARCHAR(60) CHARACTER SET NONE,
G2_BEGLEIT_V VARCHAR(60) CHARACTER SET NONE,
G2_BEGLEIT_G DATE,
G2_K1 VARCHAR(60) CHARACTER SET NONE,
G2_K1_GEB DATE,
G2_K2 VARCHAR(60) CHARACTER SET NONE,
G2_K2_GEB DATE,
G2_K3 VARCHAR(60) CHARACTER SET NONE,
G2_K3_GEB DATE,
G2_K4 VARCHAR(60) CHARACTER SET NONE,
G2_K4_GEB DATE,
G2_K5 VARCHAR(60) CHARACTER SET NONE,
G2_K5_GEB DATE,
G3_ANREDE VARCHAR(30) CHARACTER SET NONE,
G3_TITEL VARCHAR(30) CHARACTER SET NONE,
G3_NAME1 VARCHAR(60) CHARACTER SET NONE,
G3_NAME2 VARCHAR(60) CHARACTER SET NONE,
G3_GEBDAT DATE,
G3_ANREDE_B VARCHAR(30) CHARACTER SET NONE,
G3_BEGLEIT VARCHAR(60) CHARACTER SET NONE,
G3_BEGLEIT_V VARCHAR(60) CHARACTER SET NONE,
G3_BEGLEIT_G DATE,
G3_K1 VARCHAR(60) CHARACTER SET NONE,
G3_K1_GEB DATE,
G3_K2 VARCHAR(60) CHARACTER SET NONE,
G3_K2_GEB DATE,
G3_K3 VARCHAR(60) CHARACTER SET NONE,
G3_K3_GEB DATE,
G3_K4 VARCHAR(60) CHARACTER SET NONE,
G3_K4_GEB DATE,
G3_K5 VARCHAR(60) CHARACTER SET NONE,
G3_K5_GEB DATE)
AS 
declare variable COUNT_YEARS integer;
declare variable VON date;
declare variable BIS date;
declare variable WEITER smallint;
BEGIN
  :WEITER = 1;
  --if (extract(day from :BISDATUM) = '29' and extract(month from :BISDATUM) = '02') then WEITER=0;
  if (extract(day from :VONDATUM) = '29' and extract(month from :VONDATUM) = '02') then WEITER=0;

  if (:WEITER=1) then
  begin

      COUNT_YEARS = 0;
      if(extract(year from :VONDATUM) < extract(year from :BISDATUM)) THEN
      BEGIN
        VON = VONDATUM;
        BIS = CAST(('01.01.' || extract(year from :BISDATUM)) AS DATE) -1;
        COUNT_YEARS = extract(year from :BISDATUM) - extract(year from :VONDATUM);
      END
      ELSE
      BEGIN
        VON = VONDATUM;
        BIS = BISDATUM;
      END
      if(HACKEN = 0 AND COUNT_YEARS <= 1) THEN
      BEGIN
        FOR
        SELECT GASTKONT.VONAUFH, GASTKONT.BISAUFH, GASTKONT.BEGLEITOK, GASTKONT.KIND1OK,GASTKONT.KIND2OK,
            GASTKONT.KIND3OK, GASTKONT.KIND4OK, GASTKONT.KIND5OK, ZIMMSTAM.ZINR, GASTKONT.LNR,
            A_1.ANREDE, A_1.TITEL, A_1.NAME1, A_1.NAME2, A_1.GEBDAT,
            A_1.ANREDE_B, A_1.BEGLEIT, A_1.BEGLEIT_V, A_1.BEGLEIT_G,
            A_1.K1, A_1.K1_GEB, A_1.K2, A_1.K2_GEB,
            A_1.K3, A_1.K3_GEB, A_1.K4, A_1.K4_GEB,
            A_1.K5, A_1.K5_GEB,
    
            A_2.ANREDE as G2_ANREDE, A_2.TITEL as G2_TITEL, A_2.NAME1 as G2_NAME1,
            A_2.NAME2 as G2_NAME2, A_2.GEBDAT as G2_GEBDAT, A_2.ANREDE_B as G2_ANREDE_B,
            A_2.BEGLEIT as G2_BEGLEIT, A_2.BEGLEIT_V as G2_BEGLEIT_V, A_2.BEGLEIT_G as G2_BEGLEIT_G,
            A_2.K1 as G2_K1, A_2.K1_GEB as G2_K1_GEB, A_2.K2 as G2_K2, A_2.K2_GEB as G2_K2_GEB,
            A_2.K3 as G2_K3, A_2.K3_GEB as G2_K3_GEB, A_2.K4 as G2_K4, A_2.K4_GEB as G2_K4_GEB,
            A_2.K5 as G2_K5, A_1.K5_GEB as G2_K5_GEB,
    
            A_3.ANREDE as G3_ANREDE, A_3.TITEL as G3_TITEL, A_3.NAME1 as G3_NAME1,
            A_3.NAME2 as G3_NAME2, A_3.GEBDAT as G3_GEBDAT, A_3.ANREDE_B as G3_ANREDE_B,
            A_3.BEGLEIT as G3_BEGLEIT, A_3.BEGLEIT_V as G3_BEGLEIT_V, A_3.BEGLEIT_G as G3_BEGLEIT_G,
            A_3.K1 as G3_K1, A_3.K1_GEB as G3_K1_GEB, A_3.K2 as G3_K2, A_3.K2_GEB as G3_K2_GEB,
            A_3.K3 as G3_K3, A_3.K3_GEB as G3_K3_GEB, A_3.K4 as G3_K4, A_3.K4_GEB as G3_K4_GEB,
            A_3.K5 as G3_K5, A_3.K5_GEB as G3_K5_GEB
    
    
        FROM GASTKONT
    
            LEFT OUTER JOIN ADRESSEN A_1 ON (A_1.LNR = GASTKONT.GASTNR_1)
            LEFT OUTER JOIN ADRESSEN A_2 ON (A_2.LNR = GASTKONT.GASTNR_2)
            LEFT OUTER JOIN ADRESSEN A_3 ON (A_3.LNR = GASTKONT.GASTNR_3 )
    
            LEFT OUTER JOIN ZIMMSTAM ON (GASTKONT.LNR_ZINR = ZIMMSTAM.LNR)
    
        where gastkont.lnr >0 and gastkont.ci_status < 2 and A_1.ta_status < 1000
          and gastkont.ta_status < 1000 and zimmstam.ta_status < 1000
          and
          (
              (gastkont.vonaufh>= :VONDATUM and gastkont.vonaufh<=:BISDATUM) or
              (gastkont.bisaufh>= :VONDATUM and gastkont.bisaufh<=:BISDATUM) or
              (gastkont.vonaufh<  :VONDATUM and gastkont.bisaufh> :BISDATUM)
          )
         and
          (
            (
               (
               A_1.gebdat BETWEEN
               extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_1.gebdat)
               AND
               extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_1.gebdat)
               )
            )
            OR
            (
               A_2.gebdat BETWEEN
               extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_2.gebdat)
               AND
               extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_2.gebdat)
            )
            OR
            (
               A_3.gebdat BETWEEN
               extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_3.gebdat)
               AND
               extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_3.gebdat)
            )
            OR
            (
               (
                 A_1.begleit_g BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_1.begleit_g)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_1.begleit_g)
               )
            )
            OR
            (
               (
                 A_2.begleit_g BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_2.begleit_g)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_2.begleit_g)
               )
            )
            OR
            (
               (
                 A_3.begleit_g BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_3.begleit_g)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_3.begleit_g)
               )
            )
            OR
            (
               (
                 A_1.k1_geb BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_1.k1_geb)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_1.k1_geb)
               )
            )
            OR
            (
               (
                 A_2.k1_geb BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_2.k1_geb)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_2.k1_geb)
               )
            )
            OR
            (
               (
                 A_3.k1_geb BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_3.k1_geb)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_3.k1_geb)
               )
            )
            OR
            (
               (
                 A_1.k2_geb BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_1.k2_geb)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_1.k2_geb)
               )
            )
            OR
            (
               (
                 A_2.k2_geb BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_2.k2_geb)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_2.k2_geb)
               )
            )
            OR
            (
               (
                 A_3.k2_geb BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_3.k2_geb)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_3.k2_geb)
               )
            )
            OR
            (
               (
                 A_1.k3_geb BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_1.k3_geb)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_1.k3_geb)
               )
            )
            OR
            (
               (
                 A_2.k3_geb BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_2.k3_geb)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_2.k3_geb)
               )
            )
            OR
            (
               (
                 A_3.k3_geb BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_3.k3_geb)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_3.k3_geb)
               )
            )
            OR
            (
               (
                 A_1.k4_geb BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_1.k4_geb)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_1.k4_geb)
               )
            )
            OR
            (
               (
                 A_2.k4_geb BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_2.k4_geb)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_2.k4_geb)
               )
            )
            OR
            (
               (
                 A_3.k4_geb BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_3.k4_geb)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_3.k4_geb)
               )
            )
            OR
            (
               (
                 A_1.k5_geb BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_1.k5_geb)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_1.k5_geb)
               )
            )
            OR
            (
               (
                 A_2.k5_geb BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_2.k5_geb)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_2.k5_geb)
               )
            )
            OR
            (
               (
                 A_3.k5_geb BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_3.k5_geb)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_3.k5_geb)
               )
            )
          )
          order by ZIMMSTAM.ZINR
          INTO :VONAUFH, :BISAUFH, :BEGLEITOK, :KIND1OK,:KIND2OK,
            :KIND3OK, :KIND4OK, :KIND5OK, :ZINR, :LNR,
            :ANREDE, :TITEL, :NAME1, :NAME2, :GEBDAT,
            :ANREDE_B, :BEGLEIT, :BEGLEIT_V, :BEGLEIT_G,
            :K1, :K1_GEB, :K2, :K2_GEB,
            :K3, :K3_GEB, :K4, :K4_GEB,
            :K5, :K5_GEB,
    
            :G2_ANREDE, :G2_TITEL, :G2_NAME1,
            :G2_NAME2, :G2_GEBDAT, :G2_ANREDE_B,
            :G2_BEGLEIT, :G2_BEGLEIT_V, :G2_BEGLEIT_G,
            :G2_K1, :G2_K1_GEB,:G2_K2, :G2_K2_GEB,
            :G2_K3, :G2_K3_GEB, :G2_K4, :G2_K4_GEB,
            :G2_K5, :G2_K5_GEB,
    
            :G3_ANREDE, :G3_TITEL, :G3_NAME1,
            :G3_NAME2, :G3_GEBDAT, :G3_ANREDE_B,
            :G3_BEGLEIT, :G3_BEGLEIT_V, :G3_BEGLEIT_G,
            :G3_K1, :G3_K1_GEB, :G3_K2, :G3_K2_GEB,
            :G3_K3, :G3_K3_GEB,:G3_K4, :G3_K4_GEB,
            :G3_K5, :G3_K5_GEB
        DO
        suspend;
        
        IF(count_years = 1) THEN
        BEGIN
            VON = CAST(('01.01.' || extract(year from :BISDATUM)) AS DATE);
            BIS = BISDATUM;
            FOR
            SELECT GASTKONT.VONAUFH, GASTKONT.BISAUFH, GASTKONT.BEGLEITOK, GASTKONT.KIND1OK,GASTKONT.KIND2OK,
                GASTKONT.KIND3OK, GASTKONT.KIND4OK, GASTKONT.KIND5OK, ZIMMSTAM.ZINR, GASTKONT.LNR,
                A_1.ANREDE, A_1.TITEL, A_1.NAME1, A_1.NAME2, A_1.GEBDAT,
                A_1.ANREDE_B, A_1.BEGLEIT, A_1.BEGLEIT_V, A_1.BEGLEIT_G,
                A_1.K1, A_1.K1_GEB, A_1.K2, A_1.K2_GEB,
                A_1.K3, A_1.K3_GEB, A_1.K4, A_1.K4_GEB,
                A_1.K5, A_1.K5_GEB,
    
                A_2.ANREDE as G2_ANREDE, A_2.TITEL as G2_TITEL, A_2.NAME1 as G2_NAME1,
                A_2.NAME2 as G2_NAME2, A_2.GEBDAT as G2_GEBDAT, A_2.ANREDE_B as G2_ANREDE_B,
                A_2.BEGLEIT as G2_BEGLEIT, A_2.BEGLEIT_V as G2_BEGLEIT_V, A_2.BEGLEIT_G as G2_BEGLEIT_G,
                A_2.K1 as G2_K1, A_2.K1_GEB as G2_K1_GEB, A_2.K2 as G2_K2, A_2.K2_GEB as G2_K2_GEB,
                A_2.K3 as G2_K3, A_2.K3_GEB as G2_K3_GEB, A_2.K4 as G2_K4, A_2.K4_GEB as G2_K4_GEB,
                A_2.K5 as G2_K5, A_2.K5_GEB as G2_K5_GEB,
        
                A_3.ANREDE as G3_ANREDE, A_3.TITEL as G3_TITEL, A_3.NAME1 as G3_NAME1,
                A_3.NAME2 as G3_NAME2, A_3.GEBDAT as G3_GEBDAT, A_3.ANREDE_B as G3_ANREDE_B,
                A_3.BEGLEIT as G3_BEGLEIT, A_3.BEGLEIT_V as G3_BEGLEIT_V, A_3.BEGLEIT_G as G3_BEGLEIT_G,
                A_3.K1 as G3_K1, A_3.K1_GEB as G3_K1_GEB, A_3.K2 as G3_K2, A_3.K2_GEB as G3_K2_GEB,
                A_3.K3 as G3_K3, A_3.K3_GEB as G3_K3_GEB, A_3.K4 as G3_K4, A_3.K4_GEB as G3_K4_GEB,
                A_3.K5 as G3_K5, A_3.K5_GEB as G3_K5_GEB
        
        
            FROM GASTKONT
        
                LEFT OUTER JOIN ADRESSEN A_1 ON (A_1.LNR = GASTKONT.GASTNR_1)
                LEFT OUTER JOIN ADRESSEN A_2 ON (A_2.LNR = GASTKONT.GASTNR_2)
                LEFT OUTER JOIN ADRESSEN A_3 ON (A_3.LNR = GASTKONT.GASTNR_3 )
        
                LEFT OUTER JOIN ZIMMSTAM ON (GASTKONT.LNR_ZINR = ZIMMSTAM.LNR)
        
            where gastkont.lnr >0 and gastkont.ci_status < 2 and A_1.ta_status < 1000
              and gastkont.ta_status < 1000 and zimmstam.ta_status < 1000
              and
              (
                  (gastkont.vonaufh>= :VONDATUM and gastkont.vonaufh<=:BISDATUM) or
                  (gastkont.bisaufh>= :VONDATUM and gastkont.bisaufh<=:BISDATUM) or
                  (gastkont.vonaufh<  :VONDATUM and gastkont.bisaufh> :BISDATUM)
              )
             and
              (
                (
                   (
                   A_1.gebdat BETWEEN
                   extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_1.gebdat)
                   AND
                   extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_1.gebdat)
                   )
                )
                OR
                (
                   A_2.gebdat BETWEEN
                   extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_2.gebdat)
                   AND
                   extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_2.gebdat)
                )
                OR
                (
                   A_3.gebdat BETWEEN
                   extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_3.gebdat)
                   AND
                   extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_3.gebdat)
                )
                OR
                (
                   (
                     A_1.begleit_g BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_1.begleit_g)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_1.begleit_g)
                   )
                )
                OR
                (
                   (
                     A_2.begleit_g BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_2.begleit_g)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_2.begleit_g)
                   )
                )
                OR
                (
                   (
                     A_3.begleit_g BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_3.begleit_g)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_3.begleit_g)
                   )
                )
                OR
                (
                   (
                     A_1.k1_geb BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_1.k1_geb)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_1.k1_geb)
                   )
                )
                OR
                (
                   (
                     A_2.k1_geb BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_2.k1_geb)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_2.k1_geb)
                   )
                )
                OR
                (
                   (
                     A_3.k1_geb BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_3.k1_geb)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_3.k1_geb)
                   )
                )
                OR
                (
                   (
                     A_1.k2_geb BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_1.k2_geb)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_1.k2_geb)
                   )
                )
                OR
                (
                   (
                     A_2.k2_geb BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_2.k2_geb)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_2.k2_geb)
                   )
                )
                OR
                (
                   (
                     A_3.k2_geb BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_3.k2_geb)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_3.k2_geb)
                   )
                )
                OR
                (
                   (
                     A_1.k3_geb BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_1.k3_geb)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_1.k3_geb)
                   )
                )
                OR
                (
                   (
                     A_2.k3_geb BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_2.k3_geb)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_2.k3_geb)
                   )
                )
                OR
                (
                   (
                     A_3.k3_geb BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_3.k3_geb)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_3.k3_geb)
                   )
                )
                OR
                (
                   (
                     A_1.k4_geb BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_1.k4_geb)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_1.k4_geb)
                   )
                )
                OR
                (
                   (
                     A_2.k4_geb BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_2.k4_geb)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_2.k4_geb)
                   )
                )
                OR
                (
                   (
                     A_3.k4_geb BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_3.k4_geb)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_3.k4_geb)
                   )
                )
                OR
                (
                   (
                     A_1.k5_geb BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_1.k5_geb)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_1.k5_geb)
                   )
                )
                OR
                (
                   (
                     A_2.k5_geb BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_2.k5_geb)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_2.k5_geb)
                   )
                )
                OR
                (
                   (
                     A_3.k5_geb BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_3.k5_geb)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_3.k5_geb)
                   )
                )
              )
              order by ZIMMSTAM.ZINR
              INTO :VONAUFH, :BISAUFH, :BEGLEITOK, :KIND1OK,:KIND2OK,
                :KIND3OK, :KIND4OK, :KIND4OK, :ZINR, :LNR,
                :ANREDE, :TITEL, :NAME1, :NAME2, :GEBDAT,
                :ANREDE_B, :BEGLEIT, :BEGLEIT_V, :BEGLEIT_G,
                :K1, :K1_GEB, :K2, :K2_GEB,
                :K3, :K3_GEB, :K4, :K4_GEB,
                :K5, :K5_GEB,
        
                :G2_ANREDE, :G2_TITEL, :G2_NAME1,
                :G2_NAME2, :G2_GEBDAT, :G2_ANREDE_B,
                :G2_BEGLEIT, :G2_BEGLEIT_V, :G2_BEGLEIT_G,
                :G2_K1, :G2_K1_GEB,:G2_K2, :G2_K2_GEB,
                :G2_K3, :G2_K3_GEB, :G2_K4, :G2_K4_GEB,
                :G2_K5, :G2_K5_GEB,
        
                :G3_ANREDE, :G3_TITEL, :G3_NAME1,
                :G3_NAME2, :G3_GEBDAT, :G3_ANREDE_B,
                :G3_BEGLEIT, :G3_BEGLEIT_V, :G3_BEGLEIT_G,
                :G3_K1, :G3_K1_GEB, :G3_K2, :G3_K2_GEB,
                :G3_K3, :G3_K3_GEB, :G3_K4, :G3_K4_GEB,
                :G3_K5, :G3_K5_GEB
          DO
          suspend;
        END
      END
      ELSE IF(HACKEN = 1 AND COUNT_YEARS <= 1) THEN
      BEGIN
      FOR
        SELECT GASTKONT.VONAUFH, GASTKONT.BISAUFH, GASTKONT.BEGLEITOK, GASTKONT.KIND1OK,GASTKONT.KIND2OK,
            GASTKONT.KIND3OK, GASTKONT.KIND4OK, GASTKONT.KIND5OK, ZIMMSTAM.ZINR, GASTKONT.LNR,
            A_1.ANREDE, A_1.TITEL, A_1.NAME1, A_1.NAME2, A_1.GEBDAT,
            A_1.ANREDE_B, A_1.BEGLEIT, A_1.BEGLEIT_V, A_1.BEGLEIT_G,
            A_1.K1, A_1.K1_GEB, A_1.K2, A_1.K2_GEB,
            A_1.K3, A_1.K3_GEB, A_1.K4, A_1.K4_GEB,
            A_1.K5, A_1.K5_GEB,
    
            A_2.ANREDE as G2_ANREDE, A_2.TITEL as G2_TITEL, A_2.NAME1 as G2_NAME1,
            A_2.NAME2 as G2_NAME2, A_2.GEBDAT as G2_GEBDAT, A_2.ANREDE_B as G2_ANREDE_B,
            A_2.BEGLEIT as G2_BEGLEIT, A_2.BEGLEIT_V as G2_BEGLEIT_V, A_2.BEGLEIT_G as G2_BEGLEIT_G,
            A_2.K1 as G2_K1, A_2.K1_GEB as G2_K1_GEB, A_2.K2 as G2_K2, A_2.K2_GEB as G2_K2_GEB,
            A_2.K3 as G2_K3, A_2.K3_GEB as G2_K3_GEB, A_2.K4 as G2_K4, A_2.K4_GEB as G2_K4_GEB,
            A_2.K5 as G2_K5, A_2.K5_GEB as G2_K5_GEB,
    
            A_3.ANREDE as G3_ANREDE, A_3.TITEL as G3_TITEL, A_3.NAME1 as G3_NAME1,
            A_3.NAME2 as G3_NAME2, A_3.GEBDAT as G3_GEBDAT, A_3.ANREDE_B as G3_ANREDE_B,
            A_3.BEGLEIT as G3_BEGLEIT, A_3.BEGLEIT_V as G3_BEGLEIT_V, A_3.BEGLEIT_G as G3_BEGLEIT_G,
            A_3.K1 as G3_K1, A_3.K1_GEB as G3_K1_GEB, A_3.K2 as G3_K2, A_3.K2_GEB as G3_K2_GEB,
            A_3.K3 as G3_K3, A_3.K3_GEB as G3_K3_GEB, A_3.K4 as G3_K4, A_3.K4_GEB as G3_K4_GEB,
            A_3.K5 as G3_K5, A_3.K5_GEB as G3_K5_GEB
    
    
        FROM GASTKONT
    
            LEFT OUTER JOIN ADRESSEN A_1 ON (A_1.LNR = GASTKONT.GASTNR_1)
            LEFT OUTER JOIN ADRESSEN A_2 ON (A_2.LNR = GASTKONT.GASTNR_2)
            LEFT OUTER JOIN ADRESSEN A_3 ON (A_3.LNR = GASTKONT.GASTNR_3 )
    
            LEFT OUTER JOIN ZIMMSTAM ON (GASTKONT.LNR_ZINR = ZIMMSTAM.LNR)
    
        where gastkont.lnr >0 and gastkont.ci_status < 2 and A_1.ta_status < 1000
          and gastkont.ta_status < 1000 and zimmstam.ta_status < 1000
          and
          (
              (gastkont.vonaufh>= :VONDATUM and gastkont.vonaufh<=:BISDATUM) or
              (gastkont.bisaufh>= :VONDATUM and gastkont.bisaufh<=:BISDATUM) or
              (gastkont.vonaufh<  :VONDATUM and gastkont.bisaufh> :BISDATUM)
          )
         and
          (
            (
               (
               A_1.gebdat BETWEEN
               extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_1.gebdat)
               AND
               extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_1.gebdat)
               )
            )
            OR
            (
               A_2.gebdat BETWEEN
               extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_2.gebdat)
               AND
               extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_2.gebdat)
            )
            OR
            (
               A_3.gebdat BETWEEN
               extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_3.gebdat)
               AND
               extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_3.gebdat)
            )
            OR
            (
               (
                 A_1.begleit_g BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_1.begleit_g)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_1.begleit_g)
               )
               AND
               (
                 gastkont.begleitok = 1
               )
            )
            OR
            (
               (
                 A_2.begleit_g BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_2.begleit_g)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_2.begleit_g)
               )
               AND
               (
                 gastkont.begleitok = 1
               )
            )
            OR
            (
               (
                 A_3.begleit_g BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_3.begleit_g)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_3.begleit_g)
               )
               AND
               (
                 gastkont.begleitok = 1
               )
            )
            OR
            (
               (
                 A_1.k1_geb BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_1.k1_geb)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_1.k1_geb)
               )
               AND
               (
                 gastkont.kind1ok = 1
               )
            )
            OR
            (
               (
                 A_2.k1_geb BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_2.k1_geb)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_2.k1_geb)
               )
               AND
               (
                 gastkont.kind1ok = 1
               )
            )
            OR
            (
               (
                 A_3.k1_geb BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_3.k1_geb)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_3.k1_geb)
               )
               AND
               (
                 gastkont.kind1ok = 1
               )
            )
            OR
            (
               (
                 A_1.k2_geb BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_1.k2_geb)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_1.k2_geb)
               )
            )
            OR
            (
               (
                 A_2.k2_geb BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_2.k2_geb)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_2.k2_geb)
               )
               AND
               (
                 gastkont.kind2ok = 1
               )
            )
            OR
            (
               (
                 A_3.k2_geb BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_3.k2_geb)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_3.k2_geb)
               )
               AND
               (
                 gastkont.kind2ok = 1
               )
            )
            OR
            (
               (
                 A_1.k3_geb BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_1.k3_geb)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_1.k3_geb)
               )
               AND
               (
                 gastkont.kind3ok = 1
               )
            )
            OR
            (
               (
                 A_2.k3_geb BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_2.k3_geb)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_2.k3_geb)
               )
               AND
               (
                 gastkont.kind3ok = 1
               )
            )
            OR
            (
               (
                 A_3.k3_geb BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_3.k3_geb)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_3.k3_geb)
               )
               AND
               (
                 gastkont.kind3ok = 1
               )
            )
            OR
            (
               (
                 A_1.k4_geb BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_1.k4_geb)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_1.k4_geb)
               )
               AND
               (
                 gastkont.kind4ok = 1
               )
            )
            OR
            (
               (
                 A_2.k4_geb BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_2.k4_geb)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_2.k4_geb)
               )
               AND
               (
                 gastkont.kind4ok = 1
               )
            )
            OR
            (
               (
                 A_3.k4_geb BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_3.k4_geb)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_3.k4_geb)
               )
               AND
               (
                 gastkont.kind4ok = 1
               )
            )
            OR
            (
               (
                 A_1.k5_geb BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_1.k5_geb)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_1.k5_geb)
               )
               AND
               (
                 gastkont.kind5ok = 1
               )
            )
            OR
            (
               (
                 A_2.k5_geb BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_2.k5_geb)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_2.k5_geb)
               )
               AND
               (
                 gastkont.kind5ok = 1
               )
            )
            OR
            (
               (
                 A_3.k5_geb BETWEEN
                 extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_3.k5_geb)
                 AND
                 extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_3.k5_geb)
               )
               AND
               (
                 gastkont.kind5ok = 1
               )
            )
          )
          order by ZIMMSTAM.ZINR
          INTO :VONAUFH, :BISAUFH, :BEGLEITOK, :KIND1OK,:KIND2OK,
            :KIND3OK, :KIND4OK, :KIND5OK, :ZINR, :LNR,
            :ANREDE, :TITEL, :NAME1, :NAME2, :GEBDAT,
            :ANREDE_B, :BEGLEIT, :BEGLEIT_V, :BEGLEIT_G,
            :K1, :K1_GEB, :K2, :K2_GEB,
            :K3, :K3_GEB, :K4, :K4_GEB,
            :K5, :K5_GEB,
    
            :G2_ANREDE, :G2_TITEL, :G2_NAME1,
            :G2_NAME2, :G2_GEBDAT, :G2_ANREDE_B,
            :G2_BEGLEIT, :G2_BEGLEIT_V, :G2_BEGLEIT_G,
            :G2_K1, :G2_K1_GEB,:G2_K2, :G2_K2_GEB,
            :G2_K3, :G2_K3_GEB, :G2_K4, :G2_K4_GEB,
            :G2_K5, :G2_K5_GEB,
    
            :G3_ANREDE, :G3_TITEL, :G3_NAME1,
            :G3_NAME2, :G3_GEBDAT, :G3_ANREDE_B,
            :G3_BEGLEIT, :G3_BEGLEIT_V, :G3_BEGLEIT_G,
            :G3_K1, :G3_K1_GEB, :G3_K2, :G3_K2_GEB,
            :G3_K3, :G3_K3_GEB,:G3_K4, :G3_K4_GEB,
            :G2_K5, :G2_K5_GEB
        DO
        suspend;
        
        IF( count_years = 1) THEN
        BEGIN
            VON = CAST(('01.01.' || extract(year from :BISDATUM)) AS DATE);
            BIS = BISDATUM;
            FOR
            SELECT GASTKONT.VONAUFH, GASTKONT.BISAUFH, GASTKONT.BEGLEITOK, GASTKONT.KIND1OK,GASTKONT.KIND2OK,
                GASTKONT.KIND3OK, GASTKONT.KIND4OK, GASTKONT.KIND5OK, ZIMMSTAM.ZINR, GASTKONT.LNR,
                A_1.ANREDE, A_1.TITEL, A_1.NAME1, A_1.NAME2, A_1.GEBDAT,
                A_1.ANREDE_B, A_1.BEGLEIT, A_1.BEGLEIT_V, A_1.BEGLEIT_G,
                A_1.K1, A_1.K1_GEB, A_1.K2, A_1.K2_GEB,
                A_1.K3, A_1.K3_GEB, A_1.K4, A_1.K4_GEB,
                A_1.K5, A_1.K5_GEB,
        
                A_2.ANREDE as G2_ANREDE, A_2.TITEL as G2_TITEL, A_2.NAME1 as G2_NAME1,
                A_2.NAME2 as G2_NAME2, A_2.GEBDAT as G2_GEBDAT, A_2.ANREDE_B as G2_ANREDE_B,
                A_2.BEGLEIT as G2_BEGLEIT, A_2.BEGLEIT_V as G2_BEGLEIT_V, A_2.BEGLEIT_G as G2_BEGLEIT_G,
                A_2.K1 as G2_K1, A_2.K1_GEB as G2_K1_GEB, A_2.K2 as G2_K2, A_2.K2_GEB as G2_K2_GEB,
                A_2.K3 as G2_K3, A_2.K3_GEB as G2_K3_GEB, A_2.K4 as G2_K4, A_2.K4_GEB as G2_K4_GEB,
                A_2.K5 as G2_K5, A_2.K5_GEB as G2_K5_GEB,
    
                A_3.ANREDE as G3_ANREDE, A_3.TITEL as G3_TITEL, A_3.NAME1 as G3_NAME1,
                A_3.NAME2 as G3_NAME2, A_3.GEBDAT as G3_GEBDAT, A_3.ANREDE_B as G3_ANREDE_B,
                A_3.BEGLEIT as G3_BEGLEIT, A_3.BEGLEIT_V as G3_BEGLEIT_V, A_3.BEGLEIT_G as G3_BEGLEIT_G,
                A_3.K1 as G3_K1, A_3.K1_GEB as G3_K1_GEB, A_3.K2 as G3_K2, A_3.K2_GEB as G3_K2_GEB,
                A_3.K3 as G3_K3, A_3.K3_GEB as G3_K3_GEB, A_3.K4 as G3_K4, A_3.K4_GEB as G3_K4_GEB,
                A_3.K5 as G3_K5, A_3.K5_GEB as G3_K5_GEB
        
        
            FROM GASTKONT
        
                LEFT OUTER JOIN ADRESSEN A_1 ON (A_1.LNR = GASTKONT.GASTNR_1)
                LEFT OUTER JOIN ADRESSEN A_2 ON (A_2.LNR = GASTKONT.GASTNR_2)
                LEFT OUTER JOIN ADRESSEN A_3 ON (A_3.LNR = GASTKONT.GASTNR_3 )
        
                LEFT OUTER JOIN ZIMMSTAM ON (GASTKONT.LNR_ZINR = ZIMMSTAM.LNR)
        
            where gastkont.lnr >0 and gastkont.ci_status < 2 and A_1.ta_status < 1000
              and gastkont.ta_status < 1000 and zimmstam.ta_status < 1000
              and
              (
                  (gastkont.vonaufh>= :VONDATUM and gastkont.vonaufh<=:BISDATUM) or
                  (gastkont.bisaufh>= :VONDATUM and gastkont.bisaufh<=:BISDATUM) or
                  (gastkont.vonaufh<  :VONDATUM and gastkont.bisaufh> :BISDATUM)
              )
             and
              (
                (
                   (
                   A_1.gebdat BETWEEN
                   extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_1.gebdat)
                   AND
                   extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_1.gebdat)
                   )
                )
                OR
                (
                   A_2.gebdat BETWEEN
                   extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_2.gebdat)
                   AND
                   extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_2.gebdat)
                )
                OR
                (
                   A_3.gebdat BETWEEN
                   extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_3.gebdat)
                   AND
                   extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_3.gebdat)
                )
                OR
                (
                   (
                     A_1.begleit_g BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_1.begleit_g)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_1.begleit_g)
                   )
                   AND
                   (
                     gastkont.begleitok = 1
                   )
                )
                OR
                (
                   (
                     A_2.begleit_g BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_2.begleit_g)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_2.begleit_g)
                   )
                   AND
                   (
                     gastkont.begleitok = 1
                   )
                )
                OR
                (
                   (
                     A_3.begleit_g BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_3.begleit_g)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_3.begleit_g)
                   )
                   AND
                   (
                     gastkont.begleitok = 1
                   )
                )
                OR
                (
                   (
                     A_1.k1_geb BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_1.k1_geb)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_1.k1_geb)
                   )
                   AND
                   (
                     gastkont.kind1ok = 1
                   )
                )
                OR
                (
                   (
                     A_2.k1_geb BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_2.k1_geb)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_2.k1_geb)
                   )
                   AND
                   (
                     gastkont.kind1ok = 1
                   )
                )
                OR
                (
                   (
                     A_3.k1_geb BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_3.k1_geb)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_3.k1_geb)
                   )
                   AND
                   (
                     gastkont.kind1ok = 1
                   )
                )
                OR
                (
                   (
                     A_1.k2_geb BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_1.k2_geb)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_1.k2_geb)
                   )
                )
                OR
                (
                   (
                     A_2.k2_geb BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_2.k2_geb)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_2.k2_geb)
                   )
                   AND
                   (
                     gastkont.kind2ok = 1
                   )
                )
                OR
                (
                   (
                     A_3.k2_geb BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_3.k2_geb)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_3.k2_geb)
                   )
                   AND
                   (
                     gastkont.kind2ok = 1
                   )
                )
                OR
                (
                   (
                     A_1.k3_geb BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_1.k3_geb)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_1.k3_geb)
                   )
                   AND
                   (
                     gastkont.kind3ok = 1
                   )
                )
                OR
                (
                   (
                     A_2.k3_geb BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_2.k3_geb)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_2.k3_geb)
                   )
                   AND
                   (
                     gastkont.kind3ok = 1
                   )
                )
                OR
                (
                   (
                     A_3.k3_geb BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_3.k3_geb)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_3.k3_geb)
                   )
                   AND
                   (
                     gastkont.kind3ok = 1
                   )
                )
                OR
                (
                   (
                     A_1.k4_geb BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_1.k4_geb)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_1.k4_geb)
                   )
                   AND
                   (
                     gastkont.kind4ok = 1
                   )
                )
                OR
                (
                   (
                     A_2.k4_geb BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_2.k4_geb)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_2.k4_geb)
                   )
                   AND
                   (
                     gastkont.kind4ok = 1
                   )
                )
                OR
                (
                   (
                     A_3.k4_geb BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_3.k4_geb)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_3.k4_geb)
                   )
                   AND
                   (
                     gastkont.kind4ok = 1
                   )
                )
                OR
                (
                   (
                     A_1.k5_geb BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_1.k5_geb)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_1.k5_geb)
                   )
                   AND
                   (
                     gastkont.kind5ok = 1
                   )
                )
                OR
                (
                   (
                     A_2.k5_geb BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_2.k5_geb)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_2.k5_geb)
                   )
                   AND
                   (
                     gastkont.kind5ok = 1
                   )
                )
                OR
                (
                   (
                     A_3.k5_geb BETWEEN
                     extract(day from :VON) || '.' || extract(month from :VON) || '.' || extract(year from A_3.k5_geb)
                     AND
                     extract(day from :BIS) || '.' || extract(month from :BIS) || '.' || extract(year from A_3.k5_geb)
                   )
                   AND
                   (
                     gastkont.kind5ok = 1
                   )
                )
              )
              order by ZIMMSTAM.ZINR
              INTO :VONAUFH, :BISAUFH, :BEGLEITOK, :KIND1OK,:KIND2OK,
                :KIND3OK, :KIND4OK, :KIND5OK, :ZINR, :LNR,
                :ANREDE, :TITEL, :NAME1, :NAME2, :GEBDAT,
                :ANREDE_B, :BEGLEIT, :BEGLEIT_V, :BEGLEIT_G,
                :K1, :K1_GEB, :K2, :K2_GEB,
                :K3, :K3_GEB, :K4, :K4_GEB,
                :K5, :K5_GEB,
        
                :G2_ANREDE, :G2_TITEL, :G2_NAME1,
                :G2_NAME2, :G2_GEBDAT, :G2_ANREDE_B,
                :G2_BEGLEIT, :G2_BEGLEIT_V, :G2_BEGLEIT_G,
                :G2_K1, :G2_K1_GEB,:G2_K2, :G2_K2_GEB,
                :G2_K3, :G2_K3_GEB, :G2_K4, :G2_K4_GEB,
                :G2_K5, :G2_K5_GEB,
        
                :G3_ANREDE, :G3_TITEL, :G3_NAME1,
                :G3_NAME2, :G3_GEBDAT, :G3_ANREDE_B,
                :G3_BEGLEIT, :G3_BEGLEIT_V, :G3_BEGLEIT_G,
                :G3_K1, :G3_K1_GEB, :G3_K2, :G3_K2_GEB,
                :G3_K3, :G3_K3_GEB,:G3_K4, :G3_K4_GEB,
                :G3_K5, :G3_K5_GEB
          DO
          suspend;
        END
      END
   END
END ^

ALTER PROCEDURE DRUCK_GK RETURNS (ANREDE VARCHAR(30) CHARACTER SET NONE,
LNR_ZINR INTEGER,
NAME1 VARCHAR(60) CHARACTER SET NONE,
NAME2 VARCHAR(60) CHARACTER SET NONE,
STRASSE VARCHAR(60) CHARACTER SET NONE,
PLZ VARCHAR(10) CHARACTER SET NONE,
ORT VARCHAR(50) CHARACTER SET NONE,
VONAUFH DATE,
BISAUFH DATE,
CI_STATUS INTEGER,
BEMERK VARCHAR(100) CHARACTER SET NONE,
MAND_NR INTEGER,
MAND_BEZEICHN VARCHAR(50) CHARACTER SET NONE,
ZINR VARCHAR(10) CHARACTER SET NONE,
NACHT INTEGER,
TAG INTEGER,
WASSER INTEGER,
TELEF INTEGER,
W_WASSER INTEGER,
GAS INTEGER,
LAND VARCHAR(5) CHARACTER SET NONE,
PERSZAHL INTEGER,
ANZKINDER INTEGER,
LNR INTEGER,
ANZJUGEND INTEGER,
ADR_LNR INTEGER)
AS 
begin
  /* Procedure Text */
  for
   SELECT ADRESSEN.ANREDE, ADRESSEN.NAME1, ADRESSEN.NAME2, ADRESSEN.STRASSE, ADRESSEN.PLZ, ADRESSEN.ORT, adressen.land,
          GASTKONT.VONAUFH, GASTKONT.BISAUFH, GASTKONT.CI_STATUS, GASTKONT.BEMERK, GASTKONT.MAND_NR, gastkont.perszahl, gastkont.anzkinder, gastkont.anzjugend, gastkont.lnr,
          MANDANT.BEZEICHN,
          Zimmstam.lnr, zimmstam.zinr, ZIMMSTAM.NACHT, ZIMMSTAM.TAG, ZIMMSTAM.WASSER, ZIMMSTAM.TELEF, ZIMMSTAM.W_WASSER, ZIMMSTAM.GAS,
          Adressen.lnr

   FROM GASTKONT
     INNER JOIN ADRESSEN ON (GASTKONT.GASTNR_1 = ADRESSEN.LNR)
     INNER JOIN ZIMMSTAM ON (GASTKONT.LNR_ZINR = ZIMMSTAM.LNR)
     INNER JOIN MANDANT ON (GASTKONT.MAND_NR = MANDANT.LNR)

     where gastkont.ta_status<1000 and
           gastkont.ci_status<=1
     into :"ANREDE", :"NAME1", :"NAME2", :"STRASSE", :"PLZ", :"ORT", :"LAND",
          :"VONAUFH", :"BISAUFH", :"CI_STATUS", :"BEMERK", :"MAND_NR", :"PERSZAHL", :"ANZKINDER", :"ANZJUGEND", :"LNR",
          :"MAND_BEZEICHN",:"LNR_ZINR", :"ZINR", :"NACHT", :"TAG", :"WASSER", :"TELEF", :"W_WASSER", :"GAS",
          :"ADR_LNR"




  do
  suspend;
end ^

ALTER PROCEDURE DRUCK_HAUSDAMEN (VONDATUM DATE,
BISDATUM DATE,
REINIGTAG INTEGER)
RETURNS (SCHL_GEN INTEGER,
ABR DATE,
ANR DATE,
ZI VARCHAR(10) CHARACTER SET NONE,
UMZUG_ZI VARCHAR(10) CHARACTER SET NONE,
UMZUG_AM DATE,
GK_LNR INTEGER,
SELEDAT DATE,
STATUS INTEGER)
AS 
declare variable anreise date;
declare variable lauf integer;
declare variable abreise date;
declare variable datum date;
declare variable belegnr integer;
declare variable zinr varchar(10) character set none;
declare variable anz_beleg integer;
declare variable reinlauf date;
declare variable belg_abr date;
begin
  /* Procedure Text */
  ANZ_BELEG = 0;
  LAUF = 0;
  DATUM = VONDATUM;
  STATUS = 0;
  WHILE(DATUM < BISDATUM+1)
  do
    begin
    for
        SELECT GASTKONT.LNR
        FROM GASTKONT
        WHERE GASTKONT.TA_STATUS < 1000 and
            ((GASTKONT.vonaufh>=:DATUM and GASTKONT.vonaufh<=:DATUM) or
            (GASTKONT.bisaufh>= :DATUM and GASTKONT.bisaufh<=:DATUM) or
            (GASTKONT.vonaufh<:DATUM  and GASTKONT.bisaufh>:DATUM)) AND (GASTKONT.vonaufh != :DATUM)
        INTO :BELEGNR
    do
    begin
        for
            SELECT COUNT(*) FROM BELEGUNG
                LEFT OUTER JOIN ZIMMSTAM ON (BELEGUNG.LNR_ZINR = ZIMMSTAM.LNR)
            WHERE (BELEGUNG.LNR_GK = :BELEGNR) AND (BELEGUNG.TA_STATUS < 1000)
            into :ANZ_BELEG
        do
        begin
            if(ANZ_BELEG > 1) THEN
            BEGIN
                for
                    SELECT GASTKONT.VONAUFH, GASTKONT.BISAUFH, ZIMMSTAM.ZINR, ZIMMSTAM.SCHL_GEN, BELEGUNG.ABREISE
                    FROM BELEGUNG
                        LEFT OUTER JOIN GASTKONT ON (GASTKONT.LNR = BELEGUNG.LNR_GK)
                        LEFT OUTER JOIN ZIMMSTAM ON (BELEGUNG.LNR_ZINR = ZIMMSTAM.LNR)
                    WHERE (BELEGUNG.LNR_GK = :BELEGNR) AND (BELEGUNG.TA_STATUS < 1000)
                    INTO :ANREISE, :ABREISE, :ZINR, :SCHL_GEN , BELG_ABR
                do
                begin
                    if(LAUF = 0 AND BELG_ABR = DATUM) THEN
                    begin
                        UMZUG_AM = :BELG_ABR;
                        UMZUG_ZI = :ZINR;
                        ZI = :ZINR;
                        ANR = :ANREISE;
                        ABR = :ABREISE;
                        GK_LNR = :BELEGNR;
                        LAUF = LAUF + 1;
                        SELEDAT = :DATUM;
                        if(UMZUG_AM = ABR) then
                        begin
                          STATUS = 0;
                        end 
                        else
                        begin
                          STATUS = 2;
                        end
                        suspend;
                    end
                end
            end
            else
            begin
                for
                    SELECT BELEGUNG.ANREISE, BELEGUNG.ABREISE, ZIMMSTAM.ZINR, ZIMMSTAM.SCHL_GEN
                    FROM BELEGUNG
                        LEFT OUTER JOIN ZIMMSTAM ON (BELEGUNG.LNR_ZINR = ZIMMSTAM.LNR)
                    WHERE (BELEGUNG.LNR_GK = :BELEGNR) AND (BELEGUNG.TA_STATUS < 1000)
                    INTO :ANREISE, :ABREISE, :ZINR, :SCHL_GEN
                do
                begin
                    REINLAUF = :ANREISE;
                    if(ABREISE = DATUM) THEN
                    begin
                        ANR = :ANREISE;
                        ABR = :ABREISE;
                        ZI = :ZINR;
                        UMZUG_ZI = 0;
                        UMZUG_AM = null;
                        GK_LNR = :BELEGNR;
                        SELEDAT = :DATUM;
                        STATUS = 1;
                        suspend;
                    end
                    while(REINLAUF < DATUM)
                    do
                    begin
                        REINLAUF = REINLAUF + REINIGTAG;
                        if(REINLAUF = DATUM  AND ABREISE != DATUM) THEN
                        begin
                            ANR = :ANREISE;
                            ABR = :ABREISE;
                            ZI = :ZINR;
                            UMZUG_ZI = 0;
                            UMZUG_AM = null;
                            GK_LNR = :BELEGNR;
                            SELEDAT = :DATUM;
                            STATUS = 0;
                            suspend;
                        end
                    end
                end
            end
            LAUF = 0;
        end
    end
    DATUM = DATUM +1;
    STATUS = 0;
  end
end ^

ALTER PROCEDURE DRUCK_HAUSDAMEN_INKL_ANR (VONDATUM DATE,
BISDATUM DATE,
REINIGTAG INTEGER)
RETURNS (SCHL_GEN INTEGER,
ABR DATE,
ANR DATE,
ZI VARCHAR(10) CHARACTER SET NONE,
UMZUG_ZI VARCHAR(10) CHARACTER SET NONE,
UMZUG_AM DATE,
GK_LNR INTEGER,
SELEDAT DATE,
STATUS INTEGER)
AS 
declare variable ANREISE date;
declare variable LAUF integer;
declare variable ABREISE date;
declare variable DATUM date;
declare variable BELEGNR integer;
declare variable ZINR varchar(10);
declare variable ANZ_BELEG integer;
declare variable REINLAUF date;
declare variable BELG_ABR date;
begin
  /* Procedure Text */
  ANZ_BELEG = 0;
  LAUF = 0;
  DATUM = VONDATUM;
  STATUS = 0;
  WHILE(DATUM < BISDATUM+1)
  do
    begin
    for
        SELECT GASTKONT.LNR
        FROM GASTKONT
        WHERE GASTKONT.TA_STATUS < 1000 and
            ((GASTKONT.vonaufh>=:DATUM and GASTKONT.vonaufh<=:DATUM) or
            (GASTKONT.bisaufh>= :DATUM and GASTKONT.bisaufh<=:DATUM) or
            (GASTKONT.vonaufh<:DATUM  and GASTKONT.bisaufh>:DATUM))
        INTO :BELEGNR
    do
    begin
        for
            SELECT COUNT(*) FROM BELEGUNG
                LEFT OUTER JOIN ZIMMSTAM ON (BELEGUNG.LNR_ZINR = ZIMMSTAM.LNR)
            WHERE (BELEGUNG.LNR_GK = :BELEGNR) AND (BELEGUNG.TA_STATUS < 1000)
            into :ANZ_BELEG
        do
        begin
            if(ANZ_BELEG > 1) THEN
            BEGIN
                for
                    SELECT GASTKONT.VONAUFH, GASTKONT.BISAUFH, ZIMMSTAM.ZINR, ZIMMSTAM.SCHL_GEN, BELEGUNG.ABREISE
                    FROM BELEGUNG
                        LEFT OUTER JOIN GASTKONT ON (GASTKONT.LNR = BELEGUNG.LNR_GK)
                        LEFT OUTER JOIN ZIMMSTAM ON (BELEGUNG.LNR_ZINR = ZIMMSTAM.LNR)
                    WHERE (BELEGUNG.LNR_GK = :BELEGNR) AND (BELEGUNG.TA_STATUS < 1000)
                    INTO :ANREISE, :ABREISE, :ZINR, :SCHL_GEN , BELG_ABR
                do
                begin
                    if(LAUF = 0 AND BELG_ABR = DATUM) THEN
                    begin
                        UMZUG_AM = :BELG_ABR;
                        UMZUG_ZI = :ZINR;
                        ZI = :ZINR;
                        ANR = :ANREISE;
                        ABR = :ABREISE;
                        GK_LNR = :BELEGNR;
                        LAUF = LAUF + 1;
                        SELEDAT = :DATUM;
                        if(UMZUG_AM = ABR) then
                        begin
                          STATUS = 0;
                        end 
                        else
                        begin
                          STATUS = 2;
                        end
                        suspend;
                    end
                end
            end
            else
            begin
                for
                    SELECT BELEGUNG.ANREISE, BELEGUNG.ABREISE, ZIMMSTAM.ZINR, ZIMMSTAM.SCHL_GEN
                    FROM BELEGUNG
                        LEFT OUTER JOIN ZIMMSTAM ON (BELEGUNG.LNR_ZINR = ZIMMSTAM.LNR)
                    WHERE (BELEGUNG.LNR_GK = :BELEGNR) AND (BELEGUNG.TA_STATUS < 1000)
                    INTO :ANREISE, :ABREISE, :ZINR, :SCHL_GEN
                do
                begin

                    REINLAUF = :ANREISE;
                    if(ABREISE = DATUM) THEN
                    begin
                        ANR = :ANREISE;
                        ABR = :ABREISE;
                        ZI = :ZINR;
                        UMZUG_ZI = 0;
                        UMZUG_AM = null;
                        GK_LNR = :BELEGNR;
                        SELEDAT = :DATUM;
                        STATUS = 1;
                        suspend;
                    end
                    if(ANREISE = DATUM) THEN
                    begin

                        ANR = :ANREISE;
                        ABR = :ABREISE;
                        ZI = :ZINR;
                        UMZUG_ZI = 0;
                        UMZUG_AM = null;
                        GK_LNR = :BELEGNR;
                        SELEDAT = :DATUM;
                        STATUS = 10;
                        suspend;
                    end
                    while(REINLAUF < DATUM)
                    do
                    begin
                        REINLAUF = REINLAUF + REINIGTAG;
                        if(REINLAUF = DATUM  AND ABREISE != DATUM) THEN
                        begin
                            ANR = :ANREISE;
                            ABR = :ABREISE;
                            ZI = :ZINR;
                            UMZUG_ZI = 0;
                            UMZUG_AM = null;
                            GK_LNR = :BELEGNR;
                            SELEDAT = :DATUM;
                            STATUS = 0;
                            suspend;
                        end
                    end

                    /*suspend; */
                end
            end
            LAUF = 0;
        end
    end
    DATUM = DATUM +1;
    STATUS = 0;
  end
end ^

ALTER PROCEDURE DRUCK_SELEKTION_ADRESSEN RETURNS (LNR INTEGER,
ANREDE VARCHAR(50) CHARACTER SET NONE,
TITEL VARCHAR(50) CHARACTER SET NONE,
NAME1 VARCHAR(100) CHARACTER SET NONE,
NAME2 VARCHAR(100) CHARACTER SET NONE,
STRASSE VARCHAR(60) CHARACTER SET NONE,
LAND VARCHAR(10) CHARACTER SET NONE,
PLZ VARCHAR(10) CHARACTER SET NONE,
ORT VARCHAR(80) CHARACTER SET NONE,
TELE1 VARCHAR(30) CHARACTER SET NONE,
TELE2 VARCHAR(30) CHARACTER SET NONE,
TELE3 VARCHAR(30) CHARACTER SET NONE,
TELEFAX VARCHAR(30) CHARACTER SET NONE,
GEBDAT DATE,
ANREDEBRF VARCHAR(80) CHARACTER SET NONE,
ANREDE_B VARCHAR(30) CHARACTER SET NONE,
BEGLEIT VARCHAR(60) CHARACTER SET NONE,
BEGLEIT_V VARCHAR(60) CHARACTER SET NONE,
BEGLEIT_G DATE,
B_STRASSE VARCHAR(50) CHARACTER SET NONE,
