BANK VARCHAR(50) CHARACTER SET NONE,
BLZ VARCHAR(30) CHARACTER SET NONE,
KONTONR VARCHAR(30) CHARACTER SET NONE,
K1 VARCHAR(60) CHARACTER SET NONE,
K1_GEB DATE,
K2 VARCHAR(60) CHARACTER SET NONE,
K2_GEB DATE,
K3 VARCHAR(60) CHARACTER SET NONE,
K3_GEB DATE,
K4 VARCHAR(60) CHARACTER SET NONE,
K4_GEB DATE,
K5 VARCHAR(60) CHARACTER SET NONE,
K5_GEB DATE,
WELCHEPERSON INTEGER,
NAMENSZUSATZ VARCHAR(60) CHARACTER SET NONE,
BERUF VARCHAR(30) CHARACTER SET NONE,
ZUSATZ1 VARCHAR(100) CHARACTER SET NONE,
ZUSATZ2 VARCHAR(100) CHARACTER SET NONE,
ZUSATZ3 VARCHAR(100) CHARACTER SET NONE,
ZUSATZ4 VARCHAR(100) CHARACTER SET NONE,
K1_NNAME VARCHAR(60) CHARACTER SET NONE,
K2_NNAME VARCHAR(60) CHARACTER SET NONE,
K3_NNAME VARCHAR(60) CHARACTER SET NONE,
K4_NNAME VARCHAR(60) CHARACTER SET NONE,
K5_NNAME VARCHAR(60) CHARACTER SET NONE,
ANREDEBRF_K1 VARCHAR(60) CHARACTER SET NONE,
ANREDEBRF_K2 VARCHAR(60) CHARACTER SET NONE,
ANREDEBRF_K3 VARCHAR(60) CHARACTER SET NONE,
ANREDEBRF_K4 VARCHAR(60) CHARACTER SET NONE,
ANREDEBRF_K5 VARCHAR(60) CHARACTER SET NONE)
AS 
begin
  /* Procedure Text */
  for
    SELECT ADRESSEN.LNR, ADRESSEN.ANREDE, ADRESSEN.TITEL, ADRESSEN.NAME1, ADRESSEN.NAME2, ADRESSEN.STRASSE,
           ADRESSEN.LAND, ADRESSEN.PLZ, ADRESSEN.ORT, ADRESSEN.TELE1, ADRESSEN.TELE2, ADRESSEN.TELE3,
           ADRESSEN.TELEFAX,
           ADRESSEN.GEBDAT, ADRESSEN.ANREDEBRF, ADRESSEN.ANREDE_B, ADRESSEN.BEGLEIT,
           ADRESSEN.BEGLEIT_V, ADRESSEN.BEGLEIT_G, ADRESSEN.B_STRASSE, ADRESSEN.B_LAND, ADRESSEN.B_PLZ,
           ADRESSEN.B_ORT, ADRESSEN.ANREDEBRF_B, ADRESSEN.E_MAIL, ADRESSEN.BANK, ADRESSEN.BLZ, ADRESSEN.KONTONR,
           ADRESSEN.k1, ADRESSEN.k1_geb,
           ADRESSEN.k2, ADRESSEN.k2_geb,
           ADRESSEN.k3, ADRESSEN.k3_geb,
           ADRESSEN.k4, ADRESSEN.k4_geb,
           ADRESSEN.k5, ADRESSEN.k5_geb,
           Selektion_temp.welcheperson,adressen.namenzus, adressen.beruf,
           adressen.zusatz1, adressen.zusatz2, adressen.zusatz3, adressen.zusatz4,
           ADRESSEN.K1_NNAME, ADRESSEN.K2_NNAME,ADRESSEN.K3_NNAME,ADRESSEN.K4_NNAME,ADRESSEN.K5_NNAME,
           ADRESSEN.ANREDEBRF_K1, ADRESSEN.ANREDEBRF_K2, ADRESSEN.ANREDEBRF_K3, ADRESSEN.ANREDEBRF_K4, ADRESSEN.ANREDEBRF_K5

    FROM ADRESSEN
     INNER JOIN SELEKTION_TEMP ON (ADRESSEN.LNR = SELEKTION_TEMP.ADR_LNR)
         where SELEKTION_TEMP.ADR_LNR>0

     into  :"LNR", :"ANREDE", :"TITEL", :"NAME1", :"NAME2", :"STRASSE",
           :"LAND", :"PLZ", :"ORT", :"TELE1", :"TELE2", :"TELE3",
           :"TELEFAX",
           :"GEBDAT", :"ANREDEBRF", :"ANREDE_B", :"BEGLEIT",
           :"BEGLEIT_V", :"BEGLEIT_G", :"B_STRASSE", :"B_LAND", :"B_PLZ",
           :"B_ORT", :"ANREDEBRF_B", :"E_MAIL", :"BANK", :"BLZ", :"KONTONR",
           :"K1", :"K1_GEB",
           :"K2", :"K2_GEB",
           :"K3", :"K3_GEB",
           :"K4", :"K4_GEB",
           :"K5", :"K5_GEB",
           :"WELCHEPERSON", :"NAMENSZUSATZ" , :"BERUF",
           :"ZUSATZ1", :"ZUSATZ2", :"ZUSATZ3", :"ZUSATZ4",
           :"K1_NNAME", :"K2_NNAME", :"K3_NNAME", :"K4_NNAME", :"K5_NNAME",
           :"ANREDEBRF_K1", :"ANREDEBRF_K2", :"ANREDEBRF_K3", :"ANREDEBRF_K4", :"ANREDEBRF_K5"






  do
  suspend;
end ^

