ALTER PROCEDURE DRUCK_SELEKTION_ADR_HISTORY RETURNS (LNR INTEGER,
ANREDE VARCHAR(50) CHARACTER SET NONE,
TITEL VARCHAR(50) CHARACTER SET NONE,
NAME1 VARCHAR(100) CHARACTER SET NONE,
NAME2 VARCHAR(100) CHARACTER SET NONE,
STRASSE VARCHAR(60) CHARACTER SET NONE,
LAND VARCHAR(10) CHARACTER SET NONE,
PLZ VARCHAR(10) CHARACTER SET NONE,
ORT VARCHAR(80) CHARACTER SET NONE,
TELE1 VARCHAR(30) CHARACTER SET NONE,
TELEFAX VARCHAR(30) CHARACTER SET NONE,
GEBDAT DATE,
ANREDEBRF VARCHAR(80) CHARACTER SET NONE,
ANREDE_B VARCHAR(30) CHARACTER SET NONE,
BEGLEIT VARCHAR(60) CHARACTER SET NONE,
BEGLEIT_V VARCHAR(60) CHARACTER SET NONE,
BEGLEIT_G DATE,
B_STRASSE VARCHAR(60) CHARACTER SET NONE,
B_LAND VARCHAR(10) CHARACTER SET NONE,
B_PLZ VARCHAR(10) CHARACTER SET NONE,
B_ORT VARCHAR(50) CHARACTER SET NONE,
E_MAIL VARCHAR(100) CHARACTER SET NONE,
BANK VARCHAR(50) CHARACTER SET NONE,
BLZ VARCHAR(30) CHARACTER SET NONE,
KONTONR VARCHAR(30) CHARACTER SET NONE,
VONDATUM DATE,
BISDATUM DATE,
TAGE INTEGER,
ZINR VARCHAR(10) CHARACTER SET NONE,
PERSONEN INTEGER)
AS 
begin
  /* Procedure Text */
  for
    SELECT ADRESSEN.LNR, ADRESSEN.ANREDE, ADRESSEN.TITEL, ADRESSEN.NAME1, ADRESSEN.NAME2, ADRESSEN.STRASSE,
           ADRESSEN.LAND, ADRESSEN.PLZ, ADRESSEN.ORT, ADRESSEN.TELE1,ADRESSEN.TELEFAX,
           ADRESSEN.GEBDAT, ADRESSEN.ANREDEBRF, ADRESSEN.ANREDE_B, ADRESSEN.BEGLEIT,
           ADRESSEN.BEGLEIT_V, ADRESSEN.BEGLEIT_G, ADRESSEN.B_STRASSE, ADRESSEN.B_LAND, ADRESSEN.B_PLZ,
           ADRESSEN.B_ORT, ADRESSEN.E_MAIL, ADRESSEN.BANK, ADRESSEN.BLZ, ADRESSEN.KONTONR,
           GASTHIST.vondatum, GASTHIST.bisdatum, GASTHIST.tage, GASTHIST.zinr, GASTHIST.personen

    FROM ADRESSEN
     INNER JOIN SELEKTION_TEMP ON (ADRESSEN.LNR = SELEKTION_TEMP.ADR_LNR)
