ALTER PROCEDURE DRUCK_ST_DEVISEN (MANDNR INTEGER)
RETURNS (LNR INTEGER,
MAND_NR INTEGER,
KURZBEZ VARCHAR(5) CHARACTER SET NONE,
BEZEICHN VARCHAR(50) CHARACTER SET NONE,
KURS_FAKT NUMERIC(18, 6),
VERMINDER INTEGER,
M_OP_MAHN INTEGER,
M_DEPITOR INTEGER,
M_DEBIRECHN INTEGER,
M_EINER INTEGER,
KONTONR VARCHAR(10) CHARACTER SET NONE,
BEZRECHN VARCHAR(255) CHARACTER SET NONE,
WG INTEGER,
ZAHLUNGSART INTEGER,
AKTIVE INTEGER,
ERF_DATUM DATE,
ERF_USERID INTEGER,
KOR_DATUM DATE,
KOR_ZEIT TIME,
KOR_USERID INTEGER,
TA_STATUS INTEGER,
ERF_ZEIT TIME,
KS_ZANR INTEGER,
SORT_NR INTEGER)
AS 
begin
  /* Procedure Text */
  for
    SELECT DEVISEN.LNR, DEVISEN.MAND_NR, DEVISEN.KURZBEZ, DEVISEN.BEZEICHN,
            DEVISEN.KURS_FAKT, DEVISEN.VERMINDER, DEVISEN.M_OP_MAHN, DEVISEN.M_DEPITOR,
            DEVISEN.M_DEBIRECHN, DEVISEN.M_EINER, DEVISEN.KONTONR, DEVISEN.BEZRECHN,
            DEVISEN.WG, DEVISEN.ZAHLUNGSART, DEVISEN.AKTIVE, DEVISEN.ERF_DATUM,
            DEVISEN.ERF_USERID, DEVISEN.KOR_DATUM, DEVISEN.KOR_ZEIT, DEVISEN.KOR_USERID,
            DEVISEN.TA_STATUS, DEVISEN.ERF_ZEIT, DEVISEN.KS_ZANR, DEVISEN.SORT_NR
    FROM DEVISEN
    WHERE DEVISEN.TA_STATUS < 1000 AND DEVISEN.mand_nr = :"MANDNR"
    into  :"LNR", :"MAND_NR", :"KURZBEZ", :"BEZEICHN",
            :"KURS_FAKT", :"VERMINDER", :"M_OP_MAHN", :"M_DEPITOR",
            :"M_DEBIRECHN", :"M_EINER", :"KONTONR", :"BEZRECHN",
            :"WG", :"ZAHLUNGSART", :"AKTIVE", :"ERF_DATUM",
            :"ERF_USERID", :"KOR_DATUM", :"KOR_ZEIT", :"KOR_USERID",
            :"TA_STATUS", :"ERF_ZEIT", :"KS_ZANR", :"SORT_NR"
  do
  suspend;
end ^

