ALTER PROCEDURE DRUCK_ST_GLOBLEIST (MANDNR INTEGER)
RETURNS (LNR INTEGER,
LEISTUNG_LNR INTEGER,
BETRAG NUMERIC(12, 3),
MENGE INTEGER,
EINMALIG INTEGER,
EINM_STATUS INTEGER,
DATUM INTEGER,
TAEGLICH INTEGER,
PROPERSON INTEGER,
PA_ANREISE DATE,
PA_ABREISE DATE,
PA_DATUM DATE,
TA_STATUS INTEGER,
ERF_DATUM DATE,
ERF_USERID INTEGER,
KOR_DATUM DATE,
KOR_ZEIT TIME,
KOR_USERID INTEGER,
ERF_ZEIT TIME,
ABTAGE INTEGER,
BISTAGE INTEGER,
MAND_NR INTEGER,
BEZEICHN VARCHAR(200) CHARACTER SET NONE)
AS 
begin
  /* Procedure Text */
  for
    SELECT GLOB_LEISTUNG.LNR, GLOB_LEISTUNG.LEISTUNG_LNR, GLOB_LEISTUNG.BETRAG,
           GLOB_LEISTUNG.MENGE, GLOB_LEISTUNG.EINMALIG, GLOB_LEISTUNG.EINM_STATUS,
           GLOB_LEISTUNG.DATUM, GLOB_LEISTUNG.TAEGLICH, GLOB_LEISTUNG.PROPERSON,
           GLOB_LEISTUNG.PA_ANREISE, GLOB_LEISTUNG.PA_ABREISE, GLOB_LEISTUNG.PA_DATUM,
           GLOB_LEISTUNG.TA_STATUS, GLOB_LEISTUNG.ERF_DATUM, GLOB_LEISTUNG.ERF_USERID,
           GLOB_LEISTUNG.KOR_DATUM, GLOB_LEISTUNG.KOR_ZEIT, GLOB_LEISTUNG.KOR_USERID,
           GLOB_LEISTUNG.ERF_ZEIT, GLOB_LEISTUNG.ABTAGE, GLOB_LEISTUNG.BISTAGE,
           GLOB_LEISTUNG.MAND_NR, leiststa.bezeichn
    FROM GLOB_LEISTUNG
         INNER JOIN leiststa on (GLOB_LEISTUNG.TA_STATUS < 1000
                                 AND GLOB_LEISTUNG.mand_nr = :"MANDNR"
                                 AND GLOB_LEISTUNG.leistung_lnr = leiststa.lnr)
    into   :"LNR", :"LEISTUNG_LNR", :"BETRAG",
           :"MENGE", :"EINMALIG", :"EINM_STATUS",
           :"DATUM", :"TAEGLICH", :"PROPERSON",
