           :"KOR_DATUM", :"KOR_ZEIT", :"KOR_USERID",
           :"ERF_ZEIT", :"ABTAGE", :"BISTAGE",
           :"MAND_NR", :"BEZEICHN"
  do
  suspend;
end ^

