ALTER PROCEDURE DRUCK_ST_KATELEIST (MANDNR INTEGER)
RETURNS (LNR INTEGER,
KATE_LNR INTEGER,
LEISTUNG_LNR INTEGER,
BETRAG NUMERIC(12, 3),
MENGE INTEGER,
EINMALIG INTEGER,
EINM_STATUS INTEGER,
DATUM INTEGER,
TAEGLICH INTEGER,
PROPERSON INTEGER,
PA_ANREISE DATE,
PA_ABREISE DATE,
PA_DATUM DATE,
TA_STATUS INTEGER,
ERF_DATUM DATE,
ERF_USERID INTEGER,
KOR_DATUM DATE,
KOR_ZEIT TIME,
KOR_USERID INTEGER,
ERF_ZEIT TIME,
ABTAGE INTEGER,
BISTAGE INTEGER,
MAND_NR INTEGER,
KATEGORIE VARCHAR(10) CHARACTER SET NONE,
BEZEICHN VARCHAR(200) CHARACTER SET NONE)
AS 
begin
  /* Procedure Text */
  for
    SELECT KATESTAM_LEISTUNG.LNR, KATESTAM_LEISTUNG.KATE_LNR, KATESTAM_LEISTUNG.LEISTUNG_LNR,
           KATESTAM_LEISTUNG.BETRAG, KATESTAM_LEISTUNG.MENGE, KATESTAM_LEISTUNG.EINMALIG,
           KATESTAM_LEISTUNG.EINM_STATUS, KATESTAM_LEISTUNG.DATUM, KATESTAM_LEISTUNG.TAEGLICH,
           KATESTAM_LEISTUNG.PROPERSON, KATESTAM_LEISTUNG.PA_ANREISE, KATESTAM_LEISTUNG.PA_ABREISE,
           KATESTAM_LEISTUNG.PA_DATUM, KATESTAM_LEISTUNG.TA_STATUS, KATESTAM_LEISTUNG.ERF_DATUM,
           KATESTAM_LEISTUNG.ERF_USERID, KATESTAM_LEISTUNG.KOR_DATUM, KATESTAM_LEISTUNG.KOR_ZEIT,
           KATESTAM_LEISTUNG.KOR_USERID, KATESTAM_LEISTUNG.ERF_ZEIT, KATESTAM_LEISTUNG.ABTAGE,
           KATESTAM_LEISTUNG.BISTAGE, KATESTAM_LEISTUNG.MAND_NR, katestam.kategorie, leiststa.bezeichn
    FROM KATESTAM_LEISTUNG
          INNER JOIN KATESTAM ON (KATESTAM_LEISTUNG.kate_lnr = KATESTAM.LNR
