    SELECT ZIMMSTAM.LNR, ZIMMSTAM.MAND_NR, ZIMMSTAM.OBJEKT_NR, ZIMMSTAM.ZINR,
           ZIMMSTAM.LNR_KATE, ZIMMSTAM.AUSSTATUNG, ZIMMSTAM.BEZEICHN, ZIMMSTAM.GESPERRT,
           ZIMMSTAM.GESP_VON, ZIMMSTAM.GESP_BIS, ZIMMSTAM.BETTZAHL, ZIMMSTAM.PREISLIST,
           ZIMMSTAM.TELE_NR1, ZIMMSTAM.TELE_NR2, ZIMMSTAM.TELE_NR3, ZIMMSTAM.TELE_NR4,
           ZIMMSTAM.CLEAN_ST, ZIMMSTAM.BEMERK1, ZIMMSTAM.BEMERK2, ZIMMSTAM.BEMERK3,
           ZIMMSTAM.BEMERK4, ZIMMSTAM.FEWO, ZIMMSTAM.SCHEINZ, ZIMMSTAM.MEMO, ZIMMSTAM.STOCK,
           ZIMMSTAM.FARBE, ZIMMSTAM.VA_SPERR, ZIMMSTAM.VA_ZINR, ZIMMSTAM.VA_KATE,
           ZIMMSTAM.ERF_DATUM, ZIMMSTAM.ERF_USERID, ZIMMSTAM.KOR_DATUM, ZIMMSTAM.KOR_ZEIT,
           ZIMMSTAM.KOR_USERID, ZIMMSTAM.TA_STATUS, ZIMMSTAM.ERF_ZEIT, ZIMMSTAM.PFAD,
           ZIMMSTAM.ORT, ZIMMSTAM.LINK, ZIMMSTAM.TAG, ZIMMSTAM.NACHT, ZIMMSTAM.WASSER,
           ZIMMSTAM.TELEF, ZIMMSTAM.W_WASSER, ZIMMSTAM.GAS, ZIMMSTAM.ZUSATZ1,
           ZIMMSTAM.ZUSATZ2, ZIMMSTAM.ZUSATZ3, ZIMMSTAM.ZUSATZ4, ZIMMSTAM.VERMIETJN,
           ZIMMSTAM.ZIMMERART, ZIMMSTAM.ABRTYP, ZIMMSTAM.GARAGE, ZIMMSTAM.HAUSTIER,
           ZIMMSTAM.RAUCHER, ZIMMSTAM.TO_OPERATOR, ZIMMSTAM.EIGT_PROZ, ZIMMSTAM.ADR_LNR,
           ZIMMSTAM.ANZ_SCHLAFZ, ZIMMSTAM.FLAECHE, ZIMMSTAM.INET_ID, katestam.kategorie
    FROM ZIMMSTAM
       INNER JOIN KATESTAM ON (zimmstam.lnr_kate = KATESTAM.LNR and
                  zimmstam.TA_STATUS < 1000 AND zimmstam.mand_nr = :"MANDNR")

    into   :"LNR", :"MAND_NR", :"OBJEKT_NR", :"ZINR",
           :"LNR_KATE", :"AUSSTATUNG", :"BEZEICHN", :"GESPERRT",
           :"GESP_VON", :"GESP_BIS", :"BETTZAHL", :"PREISLIST",
           :"TELE_NR1", :"TELE_NR2", :"TELE_NR3", :"TELE_NR4",
           :"CLEAN_ST", :"BEMERK1", :"BEMERK2", :"BEMERK3",
           :"BEMERK4", :"FEWO", :"SCHEINZ", :"MEMO",
           :"STOCK", :"FARBE", :"VA_SPERR", :"VA_ZINR",
           :"VA_KATE", :"ERF_DATUM", :"ERF_USERID", :"KOR_DATUM",
           :"KOR_ZEIT", :"KOR_USERID", :"TA_STATUS", :"ERF_ZEIT",
           :"PFAD", :"ORT", :"LINK", :"TAG", :"NACHT",
           :"WASSER", :"TELEF", :"W_WASSER", :"GAS",
           :"ZUSATZ1", :"ZUSATZ2", :"ZUSATZ3", :"ZUSATZ4",
           :"VERMIETJN", :"ZIMMERART", :"ABRTYP", :"GARAGE",
           :"HAUSTIER", :"RAUCHER", :"TO_OPERATOR", :"EIGT_PROZ",
           :"ADR_LNR", :"ANZ_SCHLAFZ", :"FLAECHE", :"INET_ID",:"KATEGORIE"
  do
  suspend;
end ^

ALTER PROCEDURE DRUCK_TGABS_BENDEF1 (VONDATUM DATE,
BISDATUM DATE,
MAND_NR INTEGER,
VONZINR VARCHAR(10) CHARACTER SET NONE,
BISZINR VARCHAR(10) CHARACTER SET NONE)
RETURNS (VONAUFH DATE,
BISAUFH DATE,
ERW INTEGER,
KINDER INTEGER,
JUGEND INTEGER,
BUCH_STATUS INTEGER,
CI_STATUS INTEGER,
BU_OPTION INTEGER,
BEMERK VARCHAR(100) CHARACTER SET NONE,
NAME1 VARCHAR(100) CHARACTER SET NONE,
NAME2 VARCHAR(100) CHARACTER SET NONE,
ZINR VARCHAR(10) CHARACTER SET NONE,
KATEGORIE VARCHAR(20) CHARACTER SET NONE,
GK_MANDNR INTEGER,
MAND_BEZ VARCHAR(50) CHARACTER SET NONE,
MAND_NAME VARCHAR(100) CHARACTER SET NONE,
GASTNR1 INTEGER,
ZIMMERART INTEGER,
GK_LNR INTEGER,
LNR_ZINR INTEGER,
GAST_GR INTEGER,
STRASSE VARCHAR(80) CHARACTER SET NONE,
PLZ VARCHAR(10) CHARACTER SET NONE,
ORT VARCHAR(80) CHARACTER SET NONE,
G2_NAME1 VARCHAR(100) CHARACTER SET NONE,
G2_NAME2 VARCHAR(100) CHARACTER SET NONE,
G2_KFZ_KENNZ VARCHAR(30) CHARACTER SET NONE,
G3_NAME1 VARCHAR(100) CHARACTER SET NONE,
G3_NAME2 VARCHAR(100) CHARACTER SET NONE,
G3_KFZ_KENNZ VARCHAR(30) CHARACTER SET NONE,
KFZ_KENNZ VARCHAR(30) CHARACTER SET NONE,
GARAGE VARCHAR(20) CHARACTER SET NONE,
NAMEN_ZUSATZ VARCHAR(80) CHARACTER SET NONE,
ANREDE VARCHAR(50) CHARACTER SET NONE,
TITEL VARCHAR(50) CHARACTER SET NONE,
UMZUG VARCHAR(10) CHARACTER SET NONE,
TISCHNR VARCHAR(10) CHARACTER SET NONE,
GEBDATUM DATE,
ANZKLEINKIND INTEGER,
PM INTEGER,
INET_ID INTEGER,
ZUSATZ1 VARCHAR(100) CHARACTER SET NONE,
ZUSATZ2 VARCHAR(100) CHARACTER SET NONE,
ZUSATZ3 VARCHAR(100) CHARACTER SET NONE,
ZUSATZ4 VARCHAR(100) CHARACTER SET NONE,
KK INTEGER,
REINIGUNG_JA_NEIN INTEGER,
ADR_WAHL INTEGER,
GASTNR_1 INTEGER,
GASTNR_2 INTEGER,
ADR_TRACE_LNR INTEGER,
VERK_NR INTEGER,
PARTY_NR INTEGER,
RESV_KATE_LNR INTEGER,
PRECHECKIN_DONE INTEGER,
BEGLEIT VARCHAR(80) CHARACTER SET NONE,
BEGLEIT_V VARCHAR(80) CHARACTER SET NONE,
G2_BEGLEITUNG VARCHAR(80) CHARACTER SET NONE,
G2_VORNAMEBEGLEITUNG VARCHAR(80) CHARACTER SET NONE,
VIP VARCHAR(100) CHARACTER SET NONE,
GAST2BEMERK BLOB CHARACTER SET NONE,
GASTBEMERK BLOB CHARACTER SET NONE,
ANZAHL INTEGER,
TODO_LNR INTEGER,
ABT_TEXT VARCHAR(100) CHARACTER SET NONE,
ERLED_BISDATE DATE,
INFOTEXT VARCHAR(255) CHARACTER SET NONE,
BEREICH VARCHAR(100) CHARACTER SET NONE,
ERLEDIGT_STATUS INTEGER,
TODO_ADD_LNR INTEGER,
TODOLIST_BELEGNR INTEGER,
BEDIENERNAME VARCHAR(50) CHARACTER SET NONE,
K1_GEB DATE,
K1 VARCHAR(80) CHARACTER SET NONE,
K2_GEB DATE,
K2 VARCHAR(80) CHARACTER SET NONE,
K3_GEB DATE,
K3 VARCHAR(80) CHARACTER SET NONE,
K4_GEB DATE,
K4 VARCHAR(80) CHARACTER SET NONE,
K5_GEB DATE,
K5 VARCHAR(80) CHARACTER SET NONE,
KIND1OK INTEGER,
KIND2OK INTEGER,
KIND3OK INTEGER,
KIND4OK INTEGER,
KIND5OK INTEGER,
BUSEGMENT VARCHAR(50) CHARACTER SET NONE,
KATERESV VARCHAR(30) CHARACTER SET NONE,
A_1_ANZAHL INTEGER,
A_2_ANZAHL INTEGER,
A_3_ANZAHL INTEGER,
PARTYMASTER VARCHAR(200) CHARACTER SET NONE,
ANZKINDER2 INTEGER,
TISCH VARCHAR(20) CHARACTER SET NONE,
G2_TISCH VARCHAR(20) CHARACTER SET NONE)
AS 
begin
 /* Procedure Text */
  for
    select DRUCK_TG_LIST.*

    ,ADRESSEN.ADR_WAHL, GASTKONT.GASTNR_1, GASTKONT.GASTNR_2,
       (case when ADRESSEN.ADR_WAHL > 0 then gastkont.gastnr_2 else gastkont.gastnr_1 END) as ADR_TRACE_LNR,
       GASTKONT.VERK_NR, GASTKONT.PARTY_NR, GASTKONT.RESV_KATE_LNR,
       GASTKREF.PRECHECKIN_DONE, ADRESSEN.BEGLEIT, ADRESSEN.BEGLEIT_V, A_2.BEGLEIT as G2_BEGLEITUNG,
       A_2.BEGLEIT_V as G2_VORNAMEBEGLEITUNG, TEXTE.BEZEICHN as VIP, A_2.BEMERK as GAST2BEMERK,
       ADRESSEN.BEMERK as GASTBEMERK
       , T1.* ,


        iif(ADRESSEN.ADR_WAHL > 0, A_2.K1_GEB, ADRESSEN.K1_GEB) as K1_GEB,
        iif(ADRESSEN.ADR_WAHL > 0, A_2.K1, ADRESSEN.K1) as K1,
        iif(ADRESSEN.ADR_WAHL > 0, A_2.K2_GEB, ADRESSEN.K2_GEB) as K2_GEB,
        iif(ADRESSEN.ADR_WAHL > 0, A_2.K2, ADRESSEN.K2) as K2,
        iif(ADRESSEN.ADR_WAHL > 0, A_2.K3_GEB, ADRESSEN.K3_GEB) as K3_GEB,
        iif(ADRESSEN.ADR_WAHL > 0, A_2.K3, ADRESSEN.K3) as K3,
        iif(ADRESSEN.ADR_WAHL > 0, A_2.K4_GEB, ADRESSEN.K4_GEB) as K4_GEB,
        iif(ADRESSEN.ADR_WAHL > 0, A_2.K4, ADRESSEN.K4) as K4,
        iif(ADRESSEN.ADR_WAHL > 0, A_2.K5_GEB, ADRESSEN.K5_GEB) as K5_GEB,
        iif(ADRESSEN.ADR_WAHL > 0, A_2.K5, ADRESSEN.K5) as K5,

        iif(ADRESSEN.ADR_WAHL > 0, GASTKONT.A2_KIND1OK, GASTKONT.KIND1OK) as KIND1OK,
        iif(ADRESSEN.ADR_WAHL > 0, GASTKONT.A2_KIND2OK, GASTKONT.KIND2OK) as KIND2OK,
        iif(ADRESSEN.ADR_WAHL > 0, GASTKONT.A2_KIND3OK, GASTKONT.KIND3OK) as KIND3OK,
        iif(ADRESSEN.ADR_WAHL > 0, GASTKONT.A2_KIND4OK, GASTKONT.KIND4OK) as KIND4OK,
        iif(ADRESSEN.ADR_WAHL > 0, GASTKONT.A2_KIND5OK, GASTKONT.KIND5OK) as KIND5OK
      

       ,SEGMSTAM.BEZEICHN as BUSEGMENT,
       KATEABWEICHEND.KATEGORIE as KATERESV,
       H1.ANZ_AUFENTH as A_1_ANZAHL, H2.ANZ_AUFENTH as A_2_ANZAHL, H3.ANZ_AUFENTH as A_3_ANZAHL, 

       (select iif(partyadr1.adr_wahl = 1, partyadr2.NAME2 || ' ' || partyadr2.NAME1, partyadr1.NAME2 || ' ' || partyadr1.NAME1)
        from gastkont gparty
        inner join ADRESSEN partyadr1 on (partyadr1.lnr = gparty.gastnr_1)
        left outer join ADRESSEN partyadr2 on (partyadr2.lnr = gparty.gastnr_2)
        where gparty.lnr = GASTKONT.party_nr) AS partymaster, gastkont.anzkinder2, ADRESSEN.tisch, A_2.tisch as G2_TISCH

        from DRUCK_TG_LIST(:VONDATUM, :BISDATUM, :MAND_NR)
        
        inner join GASTKONT on (DRUCK_TG_LIST.GK_LNR = GASTKONT.LNR)
        inner join ADRESSEN on (GASTKONT.GASTNR_1 = ADRESSEN.LNR)
        inner join SEGMSTAM on (druck_tg_list.gast_gr = segmstam.segmcode and segmstam.ta_status < 1000)
        left outer join zimmstam on (druck_tg_list.lnr_zinr = zimmstam.lnr)
        left outer join KATESTAM KATEABWEICHEND on (KATEABWEICHEND.LNR = GASTKONT.RESV_KATE_LNR)
        left outer join GASTKREF on (GASTKREF.GK_LNR = GASTKONT.LNR and gastkref.ta_status < 1000)
        left outer join ADRESSEN A_2 on (GASTKONT.GASTNR_2 = A_2.LNR)
        left outer join ADRESSEN A_3 on (GASTKONT.GASTNR_3 = A_3.LNR)
        left outer join TEXTE on ( (case when ADRESSEN.ADR_WAHL > 0 then A_2.texte_lnr1 else ADRESSEN.TEXTE_LNR1 END) = TEXTE.LNR)
        left outer join PROC_GET_ANZ_HIST_2(ADRESSEN.LNR) H1 on (1 = 1)
        left outer join PROC_GET_ANZ_HIST_2(A_2.LNR) H2 on (1 = 1)
        left outer join PROC_GET_ANZ_HIST_2(A_3.LNR) H3 on (1 = 1)
        left outer join PROC_GET_TRACING(GASTKONT.LNR, (case when ADRESSEN.ADR_WAHL > 0 then gastkont.gastnr_2 else gastkont.gastnr_1 END), 421) T1
        on ((t1.erled_bisdate = :VONDATUM or (t1.erled_bisdate is null)) and  ((t1.erledigt_status <1) or (t1.erledigt_status is null)))
        
        where (GASTKONT.PM = 0 or (GASTKONT.PM is null)) and druck_tg_list.ci_status = 0 and (druck_tg_list.zinr>=:VONZINR and druck_tg_list.zinr<=:BISZINR)
        and zimmstam.objekt_nr < 5

        into  :VONAUFH, :BISAUFH, :ERW, :KINDER, :JUGEND, :BUCH_STATUS,
              :CI_STATUS, :BU_OPTION, :BEMERK, :NAME1, :NAME2, :ZINR, :KATEGORIE, :GK_MANDNR, :MAND_BEZ, :MAND_NAME, :GASTNR1,
              :ZIMMERART, :GK_LNR, :LNR_ZINR, :GAST_GR, :STRASSE, :PLZ, :ORT, :G2_NAME1, :G2_NAME2, :G2_KFZ_KENNZ, :G3_NAME1, :G3_NAME2, :G3_KFZ_KENNZ, :KFZ_KENNZ,
              :GARAGE, :NAMEN_ZUSATZ, :ANREDE, :TITEL, :UMZUG, :TISCHNR, :GEBDATUM, :ANZKLEINKIND, :PM, :INET_ID,
              :ZUSATZ1, :ZUSATZ2, :ZUSATZ3, :ZUSATZ4, :KK, :REINIGUNG_JA_NEIN
              , :ADR_WAHL, :GASTNR_1, :GASTNR_2, :ADR_TRACE_LNR,
              :VERK_NR, :PARTY_NR, :RESV_KATE_LNR, :PRECHECKIN_DONE, :BEGLEIT, :BEGLEIT_V, :G2_BEGLEITUNG, :G2_VORNAMEBEGLEITUNG,
              :VIP, :GAST2BEMERK, :GASTBEMERK

              ,:ANZAHL, :TODO_LNR, :ABT_TEXT, :ERLED_BISDATE, :INFOTEXT, :BEREICH, :ERLEDIGT_STATUS, :TODO_ADD_LNR, :TODOLIST_BELEGNR,
              :BEDIENERNAME

              , :K1_GEB, :K1, :K2_GEB, :K2, :K3_GEB, :K3, :K4_GEB, :K4, :K5_GEB, :K5, :KIND1OK,
              :KIND2OK, :KIND3OK, :KIND4OK, :KIND5OK

              , :BUSEGMENT, :KATERESV, :A_1_ANZAHL, :A_2_ANZAHL, :A_3_ANZAHL,
              :PARTYMASTER, :ANZKINDER2, :TISCH, :G2_TISCH


  do
  suspend;
end ^

ALTER PROCEDURE DRUCK_TG_LIST (VONDATUM DATE,
BISDATUM DATE,
MAND_NR INTEGER)
RETURNS (VONAUFH DATE,
BISAUFH DATE,
ERW INTEGER,
KINDER INTEGER,
JUGEND INTEGER,
BUCH_STATUS INTEGER,
CI_STATUS INTEGER,
BU_OPTION INTEGER,
BEMERK VARCHAR(100) CHARACTER SET NONE,
NAME1 VARCHAR(80) CHARACTER SET NONE,
NAME2 VARCHAR(80) CHARACTER SET NONE,
ZINR VARCHAR(10) CHARACTER SET NONE,
KATEGORIE VARCHAR(20) CHARACTER SET NONE,
GK_MANDNR INTEGER,
MAND_BEZ VARCHAR(30) CHARACTER SET NONE,
MAND_NAME VARCHAR(50) CHARACTER SET NONE,
GASTNR1 INTEGER,
ZIMMERART INTEGER,
GK_LNR INTEGER,
LNR_ZINR INTEGER,
GAST_GR INTEGER,
STRASSE VARCHAR(60) CHARACTER SET NONE,
PLZ VARCHAR(10) CHARACTER SET NONE,
ORT VARCHAR(50) CHARACTER SET NONE,
G2_NAME1 VARCHAR(80) CHARACTER SET NONE,
G2_NAME2 VARCHAR(80) CHARACTER SET NONE,
G2_KFZ_KENNZ VARCHAR(30) CHARACTER SET NONE,
G3_NAME1 VARCHAR(80) CHARACTER SET NONE,
G3_NAME2 VARCHAR(80) CHARACTER SET NONE,
G3_KFZ_KENNZ VARCHAR(30) CHARACTER SET NONE,
KFZ_KENNZ VARCHAR(30) CHARACTER SET NONE,
GARAGE VARCHAR(50) CHARACTER SET NONE,
NAMEN_ZUSATZ VARCHAR(50) CHARACTER SET NONE,
ANREDE VARCHAR(30) CHARACTER SET NONE,
TITEL VARCHAR(30) CHARACTER SET NONE,
UMZUG VARCHAR(10) CHARACTER SET NONE,
TISCHNR VARCHAR(10) CHARACTER SET NONE,
GEBDATUM DATE,
ANZKLEINKIND INTEGER,
PM INTEGER,
INET_ID INTEGER,
ZUSATZ1 VARCHAR(100) CHARACTER SET NONE,
ZUSATZ2 VARCHAR(100) CHARACTER SET NONE,
ZUSATZ3 VARCHAR(100) CHARACTER SET NONE,
ZUSATZ4 VARCHAR(100) CHARACTER SET NONE,
KK INTEGER,
REINIGUNG_JA_NEIN INTEGER,
GASTBEMERK BLOB CHARACTER SET NONE)
AS 
begin
  /* Procedure Text */

  if (mand_nr>0) then
  begin
    for
     SELECT GASTKONT.VONAUFH, GASTKONT.BISAUFH, GASTKONT.PERSZAHL, coalesce(GASTKONT.ANZKINDER,0) + coalesce(gastkont.anzkinder2,0) as anzkinder, GASTKONT.ANZJUGEND,
            GASTKONT.BUCH_STATUS, GASTKONT.CI_STATUS,GASTKONT.BU_ST_OPTION, GASTKONT.bemerk,
            a_1.NAME1, a_1.NAME2, ZIMMSTAM.ZINR, KATESTAM.KATEGORIE,GASTKONT.mand_nr,
            MANDANT.bezeichn, MANDANT.name1,gastkont.gastnr_1,ZIMMSTAM.zimmerart,GASTKONT.lnr,gastkont.lnr_zinr,
            GASTKONT.gast_gr, gastkont.garage, gastkont.umzug_zinr,gastkont.tisch,
            a_1.strasse, a_1.plz, a_1.ort,
            a_2.name1 as g2_name1 , a_2.name2 as g2_name2, a_2.kfz_kennz as g2_kfz_kennz,
            a_3.name1 as g3_name1 , a_3.name2 as g3_name2, a_3.kfz_kennz as g3_kfz_kennz,
            a_1.kfz_kennz,gastkont.namen_zusatz, a_1.anrede, a_1.titel,a_1.gebdat,
            gastkont.ANZKLEINKIND, gastkont.pm, zimmstam.inet_id,
            a_1.zusatz1, a_1.zusatz2, a_1.zusatz3, a_1.zusatz4,
            GASTKONT.ANZKLEINKIND,GASTKONT.REINIGUNG_JA_NEIN



     FROM KATESTAM
        INNER JOIN GASTKONT ON (KATESTAM.LNR = GASTKONT.LNR_KATE and
        (
        ((GASTKONT.vonaufh>=:"VONDATUM" and GASTKONT.vonaufh<=:"BISDATUM") or
         (GASTKONT.bisaufh>= :"VONDATUM" and GASTKONT.bisaufh<=:"BISDATUM") or
         (GASTKONT.vonaufh<:"VONDATUM"  and GASTKONT.bisaufh>:"BISDATUM"))))
        INNER JOIN ADRESSEN a_1 ON (GASTKONT.GASTNR_1 = a_1.LNR)
        INNER JOIN MANDANT ON (GASTKONT.MAND_NR = MANDANT.LNR)
        LEFT OUTER JOIN ZIMMSTAM ON (GASTKONT.LNR_ZINR = ZIMMSTAM.LNR)
        LEFT OUTER JOIN adressen a_2 on (gastkont.gastnr_2 = a_2.lnr)
        LEFT OUTER JOIN adressen a_3 on (gastkont.gastnr_3 = a_3.lnr)


        where (gastkont.ta_status<1000) and (GASTKONT.mand_nr = :"MAND_NR")

         order by GASTKONT.vonaufh

       into :"VONAUFH", :"BISAUFH", :"ERW",:"KINDER",:"JUGEND",:"BUCH_STATUS",:"CI_STATUS",:"BU_OPTION",:"BEMERK",
            :"NAME1" , :"NAME2" , :"ZINR", :"KATEGORIE",:"GK_MANDNR",:"MAND_BEZ",:"MAND_NAME",:"GASTNR1",
            :"ZIMMERART", :"GK_LNR" , :"LNR_ZINR",
            :"GAST_GR", :"GARAGE", :"UMZUG", :"TISCHNR",
            :"STRASSE", :"PLZ", :"ORT",
            :"G2_NAME1", :"G2_NAME2", :"G2_KFZ_KENNZ",
            :"G3_NAME1", :"G3_NAME2", :"G3_KFZ_KENNZ",
            :"KFZ_KENNZ", :"NAMEN_ZUSATZ", :"ANREDE", :"TITEL", :"GEBDATUM", :"ANZKLEINKIND", :"PM", :"INET_ID",
            :"ZUSATZ1", :"ZUSATZ2", :"ZUSATZ3", :"ZUSATZ4" , :"KK", :"REINIGUNG_JA_NEIN"
   do
   suspend;
  end
  if (mand_nr<=0) then
  begin
    for
     SELECT GASTKONT.VONAUFH, GASTKONT.BISAUFH, GASTKONT.PERSZAHL, coalesce(GASTKONT.ANZKINDER,0) + coalesce(gastkont.anzkinder2,0) as anzkinder, GASTKONT.ANZJUGEND,
            GASTKONT.BUCH_STATUS, GASTKONT.CI_STATUS,GASTKONT.BU_ST_OPTION, GASTKONT.bemerk,gastkont.garage,
            a_1.NAME1, a_1.NAME2, ZIMMSTAM.ZINR, KATESTAM.KATEGORIE,GASTKONT.mand_nr,
            MANDANT.bezeichn, MANDANT.name1,gastkont.gastnr_1,ZIMMSTAM.zimmerart,GASTKONT.lnr,gastkont.lnr_zinr, gastkont.umzug_zinr,gastkont.tisch,
            a_2.name1 as g2_name1 , a_2.name2 as g2_name2, a_2.kfz_kennz as g2_kfz_kennz,
            a_3.name1 as g3_name1 , a_3.name1 as g3_name2, a_3.kfz_kennz as g3_kfz_kennz,
            a_1.kfz_kennz, gastkont.namen_zusatz, a_1.anrede, a_1.titel, a_1.gebdat,
            gastkont.ANZKLEINKIND, gastkont.pm, zimmstam.inet_id,
            a_1.zusatz1, a_1.zusatz2, a_1.zusatz3, a_1.zusatz4,
            GASTKONT.ANZKLEINKIND, GASTKONT.REINIGUNG_JA_NEIN

     FROM KATESTAM
        INNER JOIN GASTKONT ON (KATESTAM.LNR = GASTKONT.LNR_KATE and (
        ((GASTKONT.vonaufh>=:"VONDATUM" and GASTKONT.vonaufh<=:"BISDATUM") or
         (GASTKONT.bisaufh>= :"VONDATUM" and GASTKONT.bisaufh<=:"BISDATUM") or
         (GASTKONT.vonaufh<:"VONDATUM"  and GASTKONT.bisaufh>:"BISDATUM"))
        ))
        INNER JOIN ADRESSEN a_1 ON (GASTKONT.GASTNR_1 = a_1.LNR)
        INNER JOIN MANDANT ON (GASTKONT.MAND_NR = MANDANT.LNR)
        LEFT JOIN ZIMMSTAM ON (GASTKONT.LNR_ZINR = ZIMMSTAM.LNR)
        LEFT OUTER JOIN adressen a_2 on (gastkont.gastnr_2 = a_2.lnr)
        LEFT OUTER JOIN adressen a_3 on (gastkont.gastnr_3 = a_3.lnr)

        where (gastkont.ta_status<1000)

         order by GASTKONT.vonaufh

       into :"VONAUFH", :"BISAUFH", :"ERW",:"KINDER",:"JUGEND",:"BUCH_STATUS",:"CI_STATUS",:"BU_OPTION",:"BEMERK", :"GARAGE",
            :"NAME1" , :"NAME2" , :"ZINR", :"KATEGORIE",:"GK_MANDNR",:"MAND_BEZ",:"MAND_NAME", :"GASTNR1",
            :"ZIMMERART", :"GK_LNR", :"LNR_ZINR", :"UMZUG", :"TISCHNR",
            :"G2_NAME1", :"G2_NAME2", :"G2_KFZ_KENNZ",
            :"G3_NAME1", :"G3_NAME2", :"G3_KFZ_KENNZ",
            :"KFZ_KENNZ", :"NAMEN_ZUSATZ", :"ANREDE", :"TITEL", :"GEBDATUM", :"ANZKLEINKIND", :"PM", :"INET_ID",
            :"ZUSATZ1", :"ZUSATZ2", :"ZUSATZ3", :"ZUSATZ4", :"KK", :"REINIGUNG_JA_NEIN"
    do
    suspend;
  end

end ^

ALTER PROCEDURE DRUCK_TG_LIST_BELEGUNG (VONDATUM DATE,
BISDATUM DATE,
MAND_NR INTEGER)
RETURNS (VONAUFH DATE,
BISAUFH DATE,
ERW INTEGER,
KINDER INTEGER,
JUGEND INTEGER,
BUCH_STATUS INTEGER,
CI_STATUS INTEGER,
BU_OPTION INTEGER,
BEMERK VARCHAR(100) CHARACTER SET NONE,
NAME1 VARCHAR(80) CHARACTER SET NONE,
NAME2 VARCHAR(80) CHARACTER SET NONE,
ZINR VARCHAR(10) CHARACTER SET NONE,
KATEGORIE VARCHAR(20) CHARACTER SET NONE,
GK_MANDNR INTEGER,
MAND_BEZ VARCHAR(30) CHARACTER SET NONE,
MAND_NAME VARCHAR(50) CHARACTER SET NONE,
GASTNR1 INTEGER,
ZIMMERART INTEGER,
GK_LNR INTEGER,
LNR_ZINR INTEGER,
GAST_GR INTEGER,
STRASSE VARCHAR(60) CHARACTER SET NONE,
PLZ VARCHAR(10) CHARACTER SET NONE,
ORT VARCHAR(50) CHARACTER SET NONE,
G2_NAME1 VARCHAR(80) CHARACTER SET NONE,
G2_NAME2 VARCHAR(80) CHARACTER SET NONE,
G2_KFZ_KENNZ VARCHAR(30) CHARACTER SET NONE,
G3_NAME1 VARCHAR(80) CHARACTER SET NONE,
G3_NAME2 VARCHAR(80) CHARACTER SET NONE,
G3_KFZ_KENNZ VARCHAR(30) CHARACTER SET NONE,
KFZ_KENNZ VARCHAR(30) CHARACTER SET NONE,
GARAGE VARCHAR(50) CHARACTER SET NONE,
NAMEN_ZUSATZ VARCHAR(50) CHARACTER SET NONE,
ANREDE VARCHAR(30) CHARACTER SET NONE,
TITEL VARCHAR(30) CHARACTER SET NONE,
UMZUG VARCHAR(10) CHARACTER SET NONE,
TISCHNR VARCHAR(10) CHARACTER SET NONE,
GEBDATUM DATE,
ANZKLEINKIND INTEGER,
PM INTEGER,
INET_ID INTEGER,
ZUSATZ1 VARCHAR(100) CHARACTER SET NONE,
ZUSATZ2 VARCHAR(100) CHARACTER SET NONE,
STOCK INTEGER,
ZUSATZ3 VARCHAR(100) CHARACTER SET NONE,
VERMIETJN SMALLINT,
BELEGUNG_ABREISE DATE,
BELEGUNG_ANREISE DATE,
ZUSATZ4 VARCHAR(100) CHARACTER SET NONE,
KK INTEGER)
AS 
begin
  /* Procedure Text */

  if (mand_nr>0) then
  begin
    for
     SELECT GASTKONT.VONAUFH, GASTKONT.BISAUFH, GASTKONT.PERSZAHL, GASTKONT.ANZKINDER, GASTKONT.ANZJUGEND,
            GASTKONT.BUCH_STATUS, GASTKONT.CI_STATUS,GASTKONT.BU_ST_OPTION, GASTKONT.bemerk,
            a_1.NAME1, a_1.NAME2, ZIMMSTAM.ZINR, KATESTAM.KATEGORIE,GASTKONT.mand_nr,
            MANDANT.bezeichn, MANDANT.name1,gastkont.gastnr_1,ZIMMSTAM.zimmerart,GASTKONT.lnr,gastkont.lnr_zinr,
            GASTKONT.gast_gr, gastkont.garage, gastkont.umzug_zinr,gastkont.tisch,
            a_1.strasse, a_1.plz, a_1.ort,
            a_2.name1 as g2_name1 , a_2.name2 as g2_name2, a_2.kfz_kennz as g2_kfz_kennz,
            a_3.name1 as g3_name1 , a_3.name1 as g3_name2, a_3.kfz_kennz as g3_kfz_kennz,
            a_1.kfz_kennz,gastkont.namen_zusatz, a_1.anrede, a_1.titel,a_1.gebdat,
            gastkont.ANZKLEINKIND, gastkont.pm, zimmstam.inet_id,
            a_1.zusatz1, a_1.zusatz2, a_1.zusatz3, a_1.zusatz4,
            GASTKONT.ANZKLEINKIND, belegung.anreise, belegung.abreise, zimmstam.vermietjn, zimmstam.stock


     FROM KATESTAM
         INNER JOIN GASTKONT ON (KATESTAM.LNR = GASTKONT.LNR_KATE and
        (
        ((GASTKONT.vonaufh>=:"VONDATUM" and GASTKONT.vonaufh<=:"BISDATUM") or
         (GASTKONT.bisaufh>= :"VONDATUM" and GASTKONT.bisaufh<=:"BISDATUM") or
         (GASTKONT.vonaufh<:"VONDATUM"  and GASTKONT.bisaufh>:"BISDATUM"))))

        INNER JOIN BELEGUNG ON (gastkont.lnr = belegung.lnr_gk and belegung.ta_status <1000)

        INNER JOIN ADRESSEN a_1 ON (GASTKONT.GASTNR_1 = a_1.LNR)
        INNER JOIN MANDANT ON (GASTKONT.MAND_NR = MANDANT.LNR)
        LEFT OUTER JOIN ZIMMSTAM ON (belegung.lnr_zinr = ZIMMSTAM.LNR)
        LEFT OUTER JOIN adressen a_2 on (gastkont.gastnr_2 = a_2.lnr)
        LEFT OUTER JOIN adressen a_3 on (gastkont.gastnr_3 = a_3.lnr)


        where (gastkont.ta_status<1000) and (GASTKONT.mand_nr = :"MAND_NR")

         order by GASTKONT.vonaufh

       into :"VONAUFH", :"BISAUFH", :"ERW",:"KINDER",:"JUGEND",:"BUCH_STATUS",:"CI_STATUS",:"BU_OPTION",:"BEMERK",
            :"NAME1" , :"NAME2" , :"ZINR", :"KATEGORIE",:"GK_MANDNR",:"MAND_BEZ",:"MAND_NAME",:"GASTNR1",
            :"ZIMMERART", :"GK_LNR" , :"LNR_ZINR",
            :"GAST_GR", :"GARAGE", :"UMZUG", :"TISCHNR",
            :"STRASSE", :"PLZ", :"ORT",
            :"G2_NAME1", :"G2_NAME2", :"G2_KFZ_KENNZ",
            :"G3_NAME1", :"G3_NAME2", :"G3_KFZ_KENNZ",
            :"KFZ_KENNZ", :"NAMEN_ZUSATZ", :"ANREDE", :"TITEL", :"GEBDATUM", :"ANZKLEINKIND", :"PM", :"INET_ID",
            :"ZUSATZ1", :"ZUSATZ2", :"ZUSATZ3", :"ZUSATZ4" , :"KK", :"BELEGUNG_ANREISE", :"BELEGUNG_ABREISE", :"VERMIETJN", :"STOCK"
   do
   suspend;
  end
  if (mand_nr<=0) then
  begin
    for
     SELECT GASTKONT.VONAUFH, GASTKONT.BISAUFH, GASTKONT.PERSZAHL, GASTKONT.ANZKINDER, GASTKONT.ANZJUGEND,
            GASTKONT.BUCH_STATUS, GASTKONT.CI_STATUS,GASTKONT.BU_ST_OPTION, GASTKONT.bemerk,gastkont.garage,
            a_1.NAME1, a_1.NAME2, ZIMMSTAM.ZINR, KATESTAM.KATEGORIE,GASTKONT.mand_nr,
            MANDANT.bezeichn, MANDANT.name1,gastkont.gastnr_1,ZIMMSTAM.zimmerart,GASTKONT.lnr,gastkont.lnr_zinr, gastkont.umzug_zinr,gastkont.tisch,
            a_2.name1 as g2_name1 , a_2.name2 as g2_name2, a_2.kfz_kennz as g2_kfz_kennz,
            a_3.name1 as g3_name1 , a_3.name1 as g3_name2, a_3.kfz_kennz as g3_kfz_kennz,
            a_1.kfz_kennz, gastkont.namen_zusatz, a_1.anrede, a_1.titel, a_1.gebdat,
            gastkont.ANZKLEINKIND, gastkont.pm, zimmstam.inet_id,
            a_1.zusatz1, a_1.zusatz2, a_1.zusatz3, a_1.zusatz4,
            GASTKONT.ANZKLEINKIND, belegung.anreise, belegung.abreise, zimmstam.vermietjn, zimmstam.stock

     FROM KATESTAM
        INNER JOIN GASTKONT ON (KATESTAM.LNR = GASTKONT.LNR_KATE and (
        ((GASTKONT.vonaufh>=:"VONDATUM" and GASTKONT.vonaufh<=:"BISDATUM") or
         (GASTKONT.bisaufh>= :"VONDATUM" and GASTKONT.bisaufh<=:"BISDATUM") or
         (GASTKONT.vonaufh<:"VONDATUM"  and GASTKONT.bisaufh>:"BISDATUM"))
        ))
        INNER JOIN BELEGUNG ON (gastkont.lnr = belegung.lnr_gk and belegung.ta_status <1000)
        INNER JOIN ADRESSEN a_1 ON (GASTKONT.GASTNR_1 = a_1.LNR)
        INNER JOIN MANDANT ON (GASTKONT.MAND_NR = MANDANT.LNR)
        LEFT JOIN ZIMMSTAM ON (belegung.lnr_zinr = ZIMMSTAM.LNR)
        LEFT OUTER JOIN adressen a_2 on (gastkont.gastnr_2 = a_2.lnr)
        LEFT OUTER JOIN adressen a_3 on (gastkont.gastnr_3 = a_3.lnr)

        where (gastkont.ta_status<1000)

         order by GASTKONT.vonaufh

       into :"VONAUFH", :"BISAUFH", :"ERW",:"KINDER",:"JUGEND",:"BUCH_STATUS",:"CI_STATUS",:"BU_OPTION",:"BEMERK", :"GARAGE",
            :"NAME1" , :"NAME2" , :"ZINR", :"KATEGORIE",:"GK_MANDNR",:"MAND_BEZ",:"MAND_NAME", :"GASTNR1",
            :"ZIMMERART", :"GK_LNR", :"LNR_ZINR", :"UMZUG", :"TISCHNR",
            :"G2_NAME1", :"G2_NAME2", :"G2_KFZ_KENNZ",
            :"G3_NAME1", :"G3_NAME2", :"G3_KFZ_KENNZ",
            :"KFZ_KENNZ", :"NAMEN_ZUSATZ", :"ANREDE", :"TITEL", :"GEBDATUM", :"ANZKLEINKIND", :"PM", :"INET_ID",
            :"ZUSATZ1", :"ZUSATZ2", :"ZUSATZ3", :"ZUSATZ4", :"KK", :"BELEGUNG_ANREISE", :"BELEGUNG_ABREISE", :"VERMIETJN", :"STOCK"
    do
    suspend;
  end

end ^

ALTER PROCEDURE DRUCK_VORSCHAULISTE (VONDATUM TIMESTAMP,
BISDATUM TIMESTAMP,
MAND_NR INTEGER)
RETURNS (TAGDATUM DATE,
ANREISEN INTEGER,
ABREISEN INTEGER,
GESAMT INTEGER,
ANR_ERW INTEGER,
ANR_JUG INTEGER,
ANR_KIN INTEGER,
ANR_KK INTEGER,
ABR_ERW INTEGER,
ABR_JUG INTEGER,
ABR_KIN INTEGER,
ABR_KK INTEGER,
BLEIB_E INTEGER,
BLEIB_J INTEGER,
BLEIB_K INTEGER,
BLEIB_KK INTEGER,
ANR_ANZ_Z INTEGER,
ABR_ANZ_Z INTEGER,
BL_ANZ_Z INTEGER)
AS 
declare variable KIND integer;
declare variable JUG integer;
declare variable ERW integer;
declare variable GAESTE_IM_HAUS integer;
declare variable DATUM date;
declare variable KK integer;
begin
  /* Procedure Text */
  DATUM = vondatum;
  ANREISEN = 0;
  ABREISEN = 0;
  GESAMT = 0;
  GAESTE_IM_HAUS = 0;
  ANR_ERW = 0;
  ANR_JUG = 0;
  ANR_KIN = 0;
  ABR_ERW = 0;
  ABR_JUG = 0;
  ABR_KIN = 0;
  BLEIB_E = 0;
  BLEIB_J = 0;
  BLEIB_K = 0;
  while(:datum < bisdatum+1)
  do
  begin
    if(mand_nr > 0) then
    begin
         for
           SELECT SUM( GASTKONT.PERSZAHL ) SUMERW,  SUM( GASTKONT.ANZJUGEND ) SUMJUGEND, SUM( GASTKONT.ANZKINDER+ coalesce( GASTKONT.ANZKINDER2,0)) SUMKINDER , SUM( GASTKONT.anzkleinkind ) SUMKLEINKINDER , count(*) SUM_ZINR
           FROM GASTKONT
           LEFT OUTER JOIN ZIMMSTAM ON (GASTKONT.LNR_ZINR = ZIMMSTAM.LNR)
           WHERE
                GASTKONT.VONAUFH = :datum AND GASTKONT.TA_STATUS < 1000 AND ZIMMSTAM.ZINR not between '9000' and '9999'
                and zimmstam.mand_nr = :mand_nr
           INTO :ERW, :JUG, :KIND, :KK, :ANR_ANZ_Z
         do
         begin
            ANREISEN = :KIND + :JUG + :ERW;
            ANR_ERW = :ERW;
            ANR_JUG = :JUG;
            ANR_KIN = :KIND;
            ANR_KK = :KK;
            if(ANREISEN IS NULL) then
            begin
              ANREISEN = 0;
            end 
            if(ANR_ERW IS NULL) then
            begin
              ANR_ERW = 0;
            end 
            if(ANR_JUG IS NULL) then
            begin
              ANR_JUG = 0;
            end 
            if(ANR_KIN IS NULL) then
            begin
              ANR_KIN = 0;
            end 
            if(ANR_KK IS NULL) then
            begin
              ANR_KK = 0;
            end 
         end
         for
           SELECT SUM( GASTKONT.PERSZAHL ) SUMERW, SUM( GASTKONT.ANZJUGEND ) SUMJUGEND, SUM( GASTKONT.ANZKINDER+ coalesce( GASTKONT.ANZKINDER2,0) ) SUMKINDER, SUM( GASTKONT.anzkleinkind ) SUMKLEINKINDER , count(*) SUM_ZINR
           FROM GASTKONT
           LEFT OUTER JOIN ZIMMSTAM ON (GASTKONT.LNR_ZINR = ZIMMSTAM.LNR)
           WHERE
                GASTKONT.BISAUFH = :datum AND GASTKONT.TA_STATUS < 1000 AND ZIMMSTAM.ZINR not between '9000' and '9999'
                and zimmstam.mand_nr = :mand_nr
           INTO :ERW, :JUG, :KIND, :KK, :ABR_ANZ_Z
         do
         begin
            ABREISEN = :KIND + :JUG + :ERW;
            ABR_ERW = :ERW;
            ABR_JUG = :JUG;
            ABR_KIN = :KIND;
            ABR_KK = :KK;
            if(ABREISEN IS NULL) then
            begin
              ABREISEN = 0;
            end 
            if(ABR_ERW IS NULL) then
            begin
              ABR_ERW = 0;
            end 
            if(ABR_JUG IS NULL) then
            begin
              ABR_JUG = 0;
            end 
            if(ABR_KIN IS NULL) then
            begin
              ABR_KIN = 0;
            end 
            if(ABR_KK IS NULL) then
            begin
              ABR_KK = 0;
            end 
         end
         for
           SELECT SUM( GASTKONT.PERSZAHL ) SUMERW,  SUM( GASTKONT.ANZJUGEND ) SUMJUGEND, SUM( GASTKONT.ANZKINDER+ coalesce( GASTKONT.ANZKINDER2,0) ) SUMKINDER, SUM( GASTKONT.anzkleinkind ) SUMKLEINKINDER , count(*) SUM_ZINR
           FROM GASTKONT
           LEFT OUTER JOIN ZIMMSTAM ON (GASTKONT.LNR_ZINR = ZIMMSTAM.LNR)
           WHERE
                GASTKONT.VONAUFH < :datum AND GASTKONT.BISAUFH > :datum
                    AND GASTKONT.TA_STATUS < 1000
                    AND ZIMMSTAM.ZINR < '9000'
                and zimmstam.mand_nr = :mand_nr
           into :ERW, :JUG, :KIND, :KK, :BL_ANZ_Z
         do
         begin
            GAESTE_IM_HAUS = :KIND + :JUG + :ERW;
            BLEIB_E = :ERW;
            BLEIB_J = :JUG;
            BLEIB_K = :KIND;
            BLEIB_KK = :KK;
    
            if(BLEIB_E IS NULL) then
            begin
              BLEIB_E = 0;
            end 
            if(BLEIB_J IS NULL) then
            begin
              BLEIB_J = 0;
            end 
            if(BLEIB_K IS NULL) then
            begin
              BLEIB_K = 0;
            end
            if(BLEIB_KK IS NULL) then
            begin
              BLEIB_KK = 0;
            end
            TAGDATUM = DATUM;
            if(GAESTE_IM_HAUS is null) then
            begin
               GAESTE_IM_HAUS = 0;
            end
            GESAMT = ANREISEN + GAESTE_IM_HAUS;
         end
         suspend;
         datum = datum +1;
         GESAMT = 0;
    end
    else
    begin
        for
           SELECT SUM( GASTKONT.PERSZAHL ) SUMERW,  SUM( GASTKONT.ANZJUGEND ) SUMJUGEND, SUM( GASTKONT.ANZKINDER+ coalesce( GASTKONT.ANZKINDER2,0) ) SUMKINDER , SUM( GASTKONT.anzkleinkind ) SUMKLEINKINDER , count(*) SUM_ZINR
           FROM GASTKONT
           LEFT OUTER JOIN ZIMMSTAM ON (GASTKONT.LNR_ZINR = ZIMMSTAM.LNR)
           WHERE
                GASTKONT.VONAUFH = :datum AND GASTKONT.TA_STATUS < 1000 AND ZIMMSTAM.ZINR not between '9000' and '9999'
           INTO :ERW, :JUG, :KIND, :KK, :ANR_ANZ_Z
         do
         begin
            ANREISEN = :KIND + :JUG + :ERW;
            ANR_ERW = :ERW;
            ANR_JUG = :JUG;
            ANR_KIN = :KIND;
            ANR_KK = :KK;
            if(ANREISEN IS NULL) then
            begin
              ANREISEN = 0;
            end 
            if(ANR_ERW IS NULL) then
            begin
              ANR_ERW = 0;
            end 
            if(ANR_JUG IS NULL) then
            begin
              ANR_JUG = 0;
            end 
            if(ANR_KIN IS NULL) then
            begin
              ANR_KIN = 0;
            end 
            if(ANR_KK IS NULL) then
            begin
              ANR_KK = 0;
            end 
         end
         for
           SELECT SUM( GASTKONT.PERSZAHL ) SUMERW, SUM( GASTKONT.ANZJUGEND ) SUMJUGEND, SUM( GASTKONT.ANZKINDER+ coalesce( GASTKONT.ANZKINDER2,0) ) SUMKINDER, SUM( GASTKONT.anzkleinkind ) SUMKLEINKINDER , count(*) SUM_ZINR
           FROM GASTKONT
           LEFT OUTER JOIN ZIMMSTAM ON (GASTKONT.LNR_ZINR = ZIMMSTAM.LNR)
           WHERE
                GASTKONT.BISAUFH = :datum AND GASTKONT.TA_STATUS < 1000 AND ZIMMSTAM.ZINR not between '9000' and '9999'
           INTO :ERW, :JUG, :KIND, :KK, :ABR_ANZ_Z
         do
         begin
            ABREISEN = :KIND + :JUG + :ERW;
            ABR_ERW = :ERW;
            ABR_JUG = :JUG;
            ABR_KIN = :KIND;
            ABR_KK = :KK;
            if(ABREISEN IS NULL) then
            begin
              ABREISEN = 0;
            end 
            if(ABR_ERW IS NULL) then
            begin
              ABR_ERW = 0;
            end 
            if(ABR_JUG IS NULL) then
            begin
              ABR_JUG = 0;
            end 
            if(ABR_KIN IS NULL) then
            begin
              ABR_KIN = 0;
            end 
            if(ABR_KK IS NULL) then
            begin
              ABR_KK = 0;
            end 
         end
         for
           SELECT SUM( GASTKONT.PERSZAHL ) SUMERW,  SUM( GASTKONT.ANZJUGEND ) SUMJUGEND, SUM( GASTKONT.ANZKINDER+ coalesce( GASTKONT.ANZKINDER2,0) ) SUMKINDER, SUM( GASTKONT.anzkleinkind ) SUMKLEINKINDER , count(*) SUM_ZINR
           FROM GASTKONT
           LEFT OUTER JOIN ZIMMSTAM ON (GASTKONT.LNR_ZINR = ZIMMSTAM.LNR)
           WHERE
                GASTKONT.VONAUFH < :datum AND GASTKONT.BISAUFH > :datum
                    AND GASTKONT.TA_STATUS < 1000
                    AND ZIMMSTAM.ZINR not between '9000' and '9999'
           into :ERW, :JUG, :KIND, :KK, :BL_ANZ_Z
         do
         begin
            GAESTE_IM_HAUS = :KIND + :JUG + :ERW;
            BLEIB_E = :ERW;
            BLEIB_J = :JUG;
            BLEIB_K = :KIND;
            BLEIB_KK = :KK;
    
            if(BLEIB_E IS NULL) then
            begin
              BLEIB_E = 0;
            end 
            if(BLEIB_J IS NULL) then
            begin
              BLEIB_J = 0;
            end 
            if(BLEIB_K IS NULL) then
            begin
              BLEIB_K = 0;
            end
            if(BLEIB_KK IS NULL) then
            begin
              BLEIB_KK = 0;
            end
            TAGDATUM = DATUM;
            if(GAESTE_IM_HAUS is null) then
            begin
               GAESTE_IM_HAUS = 0;
            end
            GESAMT = ANREISEN + GAESTE_IM_HAUS;
         end
         suspend;
         datum = datum +1;
         GESAMT = 0;
    end
  end
