ALTER PROCEDURE DRUCK_VORSCHAULISTE_ZIART_ABRUF (VONDATUM TIMESTAMP,
BISDATUM TIMESTAMP,
MAND_NR INTEGER)
RETURNS (TAGDATUM DATE,
ANREISEN INTEGER,
ABREISEN INTEGER,
GESAMT INTEGER,
ANR_ERW INTEGER,
ANR_JUG INTEGER,
ANR_KIN INTEGER,
ANR_KK INTEGER,
ABR_ERW INTEGER,
ABR_JUG INTEGER,
ABR_KIN INTEGER,
ABR_KK INTEGER,
BLEIB_E INTEGER,
BLEIB_J INTEGER,
BLEIB_K INTEGER,
BLEIB_KK INTEGER,
ANR_ANZ_Z INTEGER,
ABR_ANZ_Z INTEGER,
BL_ANZ_Z INTEGER,
ZIMMERART INTEGER)
AS 
declare variable KIND integer;
declare variable JUG integer;
declare variable ERW integer;
declare variable GAESTE_IM_HAUS integer;
declare variable DATUM date;
declare variable KK integer;
begin
   -- hier f?r jede zimmerart einen Aufruf starten ....
   datum = vondatum;

   while(:datum < bisdatum+1)
   do
   begin
     zimmerart = 0;
     while (zimmerart <3)
     do
     begin

         select * from DRUCK_VORSCHAULISTE_ZIART(:datum,:datum,:mand_nr,:zimmerart)
            into :TAGDATUM, :ANREISEN, :ABREISEN, :GESAMT, :ANR_ERW, :ANR_JUG,
                 :ANR_KIN, :ANR_KK, :ABR_ERW, :ABR_JUG, :ABR_KIN, :ABR_KK,
                 :BLEIB_E, :BLEIB_J, :BLEIB_K, :BLEIB_KK, :ANR_ANZ_Z,
                 :ABR_ANZ_Z, BL_ANZ_Z;

         zimmerart = zimmerart+1;

         suspend;
     end
     datum = datum +1;

   end

end ^

