"USER" INTEGER,
NAME1 VARCHAR(80) CHARACTER SET NONE,
NAME2 VARCHAR(80) CHARACTER SET NONE,
VONAUFH DATE,
BISAUFH DATE,
BEDIENERNAME VARCHAR(50) CHARACTER SET NONE,
LNR_DEVI INTEGER,
LNR_GK INTEGER,
TG_ABS INTEGER,
ZINR VARCHAR(10) CHARACTER SET NONE,
GASTNAME2 VARCHAR(200) CHARACTER SET NONE,
TA_STATUS INTEGER)
AS 
begin
  /* Procedure Text */
  if (mand_nr>0) then
  begin
    for

    SELECT ZAHLUNGEN.LNR, ZAHLUNGEN.BUDAT, ZAHLUNGEN.UHRZEIT,
           ZAHLUNGEN.BEZEICHN, ZAHLUNGEN.BETRAG, ZAHLUNGEN.GASTNR_1,
           ZAHLUNGEN.AUFPERS, ZAHLUNGEN.RE_NR, ZAHLUNGEN.TATIGK,
           ZAHLUNGEN.KURS_FAKT, ZAHLUNGEN.RE_LAUF,
           ZAHLUNGEN.USERID,
           ADRESSEN.NAME1, ADRESSEN.NAME2,
           GASTKONT.VONAUFH, GASTKONT.BISAUFH,
           BEDIENER.NAME,ZAHLUNGEN.LNR_DEVI,
           ZAHLUNGEN.lnr_gk,
           ZAHLUNGEN.tg_abs,
           ZIMMSTAM.zinr,
           A_1.NAME1 || ' ' || A_1.NAME2,
           Zahlungen.ta_status

       FROM ZAHLUNGEN
         LEFT OUTER JOIN GASTKONT ON (ZAHLUNGEN.LNR_GK = GASTKONT.LNR)
         LEFT OUTER JOIN ADRESSEN ON (ZAHLUNGEN.GASTNR_1 = ADRESSEN.LNR)
         LEFT OUTER JOIN BEDIENER ON (ZAHLUNGEN.USERID = BEDIENER.LNR)
         LEFT OUTER JOIN ZIMMSTAM ON (GASTKONT.lnr_zinr = ZIMMSTAM.lnr)
         LEFT OUTER JOIN ADRESSEN A_1 ON (GASTKONT.GASTNR_2 = A_1.LNR)
          where  zahlungen.mand_nr=:"MAND_NR"
        into :"LNR", :"BUDAT",:"UHRZEIT", :"BEZEICHN", :"BETRAG", :"GASTNR", :"AUFPERS", :"RE_NR", :"TATIGK",
             :"KURS_FAKTOR",:"RE_LAUF",:"USER", :"NAME1", :"NAME2", :"VONAUFH", :"BISAUFH", :"BEDIENERNAME",
             :"LNR_DEVI", :"LNR_GK", :"TG_ABS", :"ZINR", :"GASTNAME2", :"TA_STATUS"
     do
     suspend;
  end
  else
  begin
    for
    SELECT ZAHLUNGEN.LNR, ZAHLUNGEN.BUDAT, ZAHLUNGEN.UHRZEIT,
           ZAHLUNGEN.BEZEICHN, ZAHLUNGEN.BETRAG, ZAHLUNGEN.GASTNR_1,
           ZAHLUNGEN.AUFPERS, ZAHLUNGEN.RE_NR, ZAHLUNGEN.TATIGK,
           ZAHLUNGEN.KURS_FAKT, ZAHLUNGEN.RE_LAUF,
           ZAHLUNGEN.USERID,
           ADRESSEN.NAME1, ADRESSEN.NAME2,
           GASTKONT.VONAUFH, GASTKONT.BISAUFH,
           BEDIENER.NAME,ZAHLUNGEN.LNR_DEVI,
           ZAHLUNGEN.lnr_gk,
           ZAHLUNGEN.tg_abs,
           ZIMMSTAM.zinr,
           A_1.NAME1 || ' ' || A_1.NAME2,
           Zahlungen.ta_status

       FROM ZAHLUNGEN
         LEFT OUTER JOIN GASTKONT ON (ZAHLUNGEN.LNR_GK = GASTKONT.LNR)
         LEFT OUTER JOIN ADRESSEN ON (ZAHLUNGEN.GASTNR_1 = ADRESSEN.LNR)
         LEFT OUTER JOIN BEDIENER ON (ZAHLUNGEN.USERID = BEDIENER.LNR)
         LEFT OUTER JOIN ZIMMSTAM ON (GASTKONT.lnr_zinr = ZIMMSTAM.lnr)
         LEFT OUTER JOIN ADRESSEN A_1 ON (GASTKONT.GASTNR_2 = A_1.LNR)

        into :"LNR", :"BUDAT",:"UHRZEIT", :"BEZEICHN", :"BETRAG", :"GASTNR", :"AUFPERS", :"RE_NR", :"TATIGK",
             :"KURS_FAKTOR",:"RE_LAUF",:"USER", :"NAME1", :"NAME2", :"VONAUFH", :"BISAUFH", :"BEDIENERNAME",
             :"LNR_DEVI", :"LNR_GK", :"TG_ABS", :"ZINR", :"GASTNAME2", :"TA_STATUS"

    do
    suspend;
  end

end ^

ALTER PROCEDURE DRUCK_ZIMBELEG_LIST (VONDATUM DATE,
BISDATUM DATE,
MAND_NR INTEGER)
RETURNS (ZINR VARCHAR(10) CHARACTER SET NONE,
ZI_MANDNR INTEGER,
NAME1 VARCHAR(80) CHARACTER SET NONE,
NAME2 VARCHAR(80) CHARACTER SET NONE,
VONAUFH DATE,
BISAUFH DATE,
ERW INTEGER,
KINDER INTEGER,
JUGEND INTEGER,
BEMERK VARCHAR(100) CHARACTER SET NONE,
MAND_BEZ VARCHAR(30) CHARACTER SET NONE,
MAND_NAME VARCHAR(50) CHARACTER SET NONE,
TISCH VARCHAR(10) CHARACTER SET NONE)
AS 
begin
  /* Procedure Text */
  if (mand_nr>0) then
  begin
   for
     SELECT ZIMMSTAM.ZINR, zimmstam.mand_nr, adressen.NAME1, ADRESSEN.NAME2,
            BELEGUNG.ANREISE, BELEGUNG.ABREISE, GASTKONT.PERSZAHL, GASTKONT.ANZJUGEND,
            GASTKONT.ANZKINDER, GASTKONT.BEMERK, GASTKONT.TISCH,
            MANDANT.bezeichn, MANDANT.name1
     FROM ZIMMSTAM
        LEFT OUTER JOIN BELEGUNG ON (ZIMMSTAM.LNR = BELEGUNG.LNR_ZINR)
        LEFT OUTER JOIN GASTKONT ON (BELEGUNG.LNR_GK = GASTKONT.LNR)
        LEFT OUTER JOIN ADRESSEN ON (GASTKONT.GASTNR_1 = ADRESSEN.LNR)
        INNER JOIN MANDANT  ON (zimmstam.mand_nr = MANDANT.LNR)
     WHERE 
     (
      (ZIMMSTAM.TA_STATUS < 1000)
      and 
      (
         (
            (zimmstam.MAND_NR = :"MAND_NR" )
         and 
            (BELEGUNG.TA_STATUS < 1000)
         and 
            (
               (
                  (BELEGUNG.ANREISE >= :"VONDATUM")
               and 
                  (BELEGUNG.ANREISE <= :"BISDATUM")
               )
            or 
               (
                  (BELEGUNG.ABREISE >= :"VONDATUM")
               and 
                  (BELEGUNG.ABREISE <= :"BISDATUM")
               )
            or 
               (
                  (BELEGUNG.ANREISE < :"VONDATUM")
               and 
                  (BELEGUNG.ABREISE > :"BISDATUM")
               )
            )
         )
      or 
         (BELEGUNG.TA_STATUS IS NULL )
      )
     )
     ORDER BY ZIMMSTAM.ZINR,belegung.anreise

     into :"ZINR",:"ZI_MANDNR", :"NAME1" , :"NAME2" , :"VONAUFH", :"BISAUFH",
      :"ERW" , :"KINDER" , :"JUGEND" , :"BEMERK", :"TISCH", :"MAND_BEZ", :"MAND_NAME"

   do
   suspend;
   end
   if (mand_nr<=0) then
   begin
    for
      SELECT ZIMMSTAM.ZINR, zimmstam.mand_nr, ADRESSEN.NAME1, ADRESSEN.NAME2,
            BELEGUNG.ANREISE, BELEGUNG.ABREISE, GASTKONT.PERSZAHL, GASTKONT.ANZJUGEND,
            GASTKONT.ANZKINDER, GASTKONT.BEMERK, GASTKONT.TISCH,
            MANDANT.bezeichn, MANDANT.name1
      FROM ZIMMSTAM
        LEFT OUTER JOIN BELEGUNG ON (ZIMMSTAM.LNR = BELEGUNG.LNR_ZINR)
        LEFT OUTER JOIN GASTKONT ON (BELEGUNG.LNR_GK = GASTKONT.LNR)
        LEFT OUTER JOIN ADRESSEN ON (GASTKONT.GASTNR_1 = ADRESSEN.LNR)
        INNER JOIN MANDANT  ON (Zimmstam.mand_nr = MANDANT.LNR)
      WHERE
      (
       (ZIMMSTAM.TA_STATUS < 1000)
       and
       (
         (
            (BELEGUNG.TA_STATUS < 1000)
         and 
            (
               (
                  (BELEGUNG.ANREISE >= :"VONDATUM")
               and 
                  (BELEGUNG.ANREISE <= :"BISDATUM")
               )
            or 
               (
                  (BELEGUNG.ABREISE >= :"VONDATUM")
               and 
                  (BELEGUNG.ABREISE <= :"BISDATUM")
               )
            or 
               (
                  (BELEGUNG.ANREISE < :"VONDATUM")
               and 
                  (BELEGUNG.ABREISE > :"BISDATUM")
               )
            )
         )
       or
         (BELEGUNG.TA_STATUS IS NULL )
       )
      )
      ORDER BY ZIMMSTAM.ZINR,belegung.anreise

      into :"ZINR", :"ZI_MANDNR",:"NAME1" , :"NAME2" , :"VONAUFH", :"BISAUFH",
       :"ERW" , :"KINDER" , :"JUGEND" , :"BEMERK", :"TISCH", :"MAND_BEZ", :"MAND_NAME"

    do
    suspend;
  end
end ^

