ALTER PROCEDURE FLEXCOM_GET_TELEFON_BUCHNR_NS (NS VARCHAR(10) CHARACTER SET NONE)
RETURNS (BUCHNR INTEGER)
AS 
begin
BUCHNR = 0;
  /* Procedure Text */
  for
   SELECT GASTKONT.LNR

   FROM GASTKONT
    LEFT OUTER JOIN ZIMMSTAM ON (GASTKONT.lnr_zinr = ZIMMSTAM.lnr)

   WHERE GASTKONT.CI_STATUS = 1 AND
            (ZIMMSTAM.tele_nr1 = :ns OR ZIMMSTAM.TELE_NR2 = :NS
            or ZIMMSTAM.tele_nr3 = :NS or ZIMMSTAM.tele_nr4 = :NS)

   INTO :"BUCHNR"

  do
  suspend;
end ^

ALTER PROCEDURE FLEXCOM_GET_TELEFON_CI_CO RETURNS (ANREDE VARCHAR(30) CHARACTER SET NONE,
NAME1 VARCHAR(60) CHARACTER SET NONE,
NAME2 VARCHAR(60) CHARACTER SET NONE,
SPRACHE INTEGER,
BUCHNR INTEGER,
VONAUFH DATE,
BISAUFH DATE,
LNR INTEGER,
TELEFON INTEGER,
CI_STATUS INTEGER,
WECKZEIT VARCHAR(5) CHARACTER SET NONE,
WECKSTATUS INTEGER,
NS1 INTEGER,
NS2 INTEGER,
NS3 INTEGER,
NS4 INTEGER,
NS5 INTEGER,
NOTIZ VARCHAR(100) CHARACTER SET NONE)
AS 
begin
  /* Procedure Text */
  for
   SELECT ADRESSEN.ANREDE, ADRESSEN.NAME1, ADRESSEN.NAME2, ADRESSEN.SPRACHE,
          GASTKONT.LNR AS BUCHNR, GASTKONT.VONAUFH, GASTKONT.BISAUFH,
          ONLINE_VERBUND.LNR, ONLINE_VERBUND.TELEFON, ONLINE_VERBUND.CI_STATUS, ONLINE_VERBUND.WECKZEIT,
          ONLINE_VERBUND.WECKSTATUS,
          ZIMMSTAM.TELE_NR1 AS NS1, ZIMMSTAM.TELE_NR2 AS NS2, ZIMMSTAM.TELE_NR3 AS NS3, ZIMMSTAM.TELE_NR4 AS NS4,
          ONLINE_VERBUND.nebenst AS NS4, ONLINE_VERBUND.NAME

   FROM ONLINE_VERBUND
     LEFT OUTER JOIN GASTKONT ON (ONLINE_VERBUND.GK_LNR = GASTKONT.LNR)
     LEFT OUTER JOIN ADRESSEN ON (GASTKONT.GASTNR_1 = ADRESSEN.LNR)
     LEFT OUTER JOIN ZIMMSTAM ON (GASTKONT.LNR_ZINR = ZIMMSTAM.LNR)

   WHERE ONLINE_VERBUND.TELEFON = 0

   INTO :"ANREDE", :"NAME1", :"NAME2", :"SPRACHE",
        :"BUCHNR", :"VONAUFH", :"BISAUFH",
        :"LNR", :"TELEFON", :"CI_STATUS", :"WECKZEIT", :"WECKSTATUS",
        :"NS1", :"NS2", :"NS3", :"NS4", :"NS5", :"NOTIZ"

  do
  suspend;
end ^

ALTER PROCEDURE FLEXCOM_INS_TELEFON (GK_LNR INTEGER,
NS VARCHAR(10) CHARACTER SET NONE,
DATUM DATE,
ZEIT VARCHAR(10) CHARACTER SET NONE,
AMTSL INTEGER,
EINHEITEN INTEGER,
RUFNUMMER VARCHAR(30) CHARACTER SET NONE,
DAUER VARCHAR(10) CHARACTER SET NONE)
AS 
begin
  /* Procedure Text */
  INSERT INTO TELEFON(GK_LNR,NEBENST,DATUM,ZEIT,AMTSL,EINHEITEN,RUFNUMMER,DAUER,BETRAG,AUFPERS,TA_STATUS,ABR_STATUS,SYSDATUM)
      VALUES(:"GK_LNR",:"NS",:"DATUM",:"ZEIT",:"AMTSL",:"EINHEITEN",:"RUFNUMMER",:"DAUER",0,0,0,0,CURRENT_TIMESTAMP);
  suspend;
end ^

ALTER PROCEDURE FLEXCOM_UPD_ONLINE_VERBUND (LNROLD INTEGER)
AS 
begin
  /* Procedure Text */
  UPDATE ONLINE_VERBUND SET ONLINE_VERBUND.TELEFON = 1
     WHERE ONLINE_VERBUND.LNR = :LNROLD;
  suspend;
end ^

ALTER PROCEDURE GASTHIST_UMS_ST ("adr_lnr" INTEGER)
RETURNS ("Logis" NUMERIC(15, 2),
"Sonstiger" NUMERIC(15, 2),
"Storno" NUMERIC(15, 2))
AS 
begin
  /* Procedure Text */

  for select sum(logium) , sum(sonstum) , sum(sto_betrag)
  from gasthist  where adr_lnr=:"adr_lnr"  and gasthist.ta_status <1000
  into :"Logis", :"Sonstiger", :"Storno"
  do

  suspend;
end ^

ALTER PROCEDURE GAST_BUCH_ZUKUNFT (ADR_LNR INTEGER)
RETURNS (ANREISE DATE,
ABREISE DATE,
ZINR VARCHAR(10) CHARACTER SET NONE,
KATEGORIE VARCHAR(20) CHARACTER SET NONE,
PERSZAHL INTEGER,
ANZKINDER INTEGER,
ANZJUGEND INTEGER,
BUCHNR INTEGER,
SUM_LEISTUNG FLOAT,
BEZAHLT FLOAT)
AS 
begin
  /* Procedure Text */
  for
    select gk.vonaufh, gk.bisaufh, z.zinr, k.kategorie,gk.perszahl, gk.anzkinder, gk.anzjugend, gk.lnr,
       GET_GK_REBETRAG_BK.sum_leistung, GET_ZAHLBETRAG.bezahlt

     from gastkont gk

     left outer join zimmstam z on (gk.lnr_zinr = z.lnr)
     left outer join katestam k on (gk.lnr_kate = k.lnr)
     left outer join GET_GK_REBETRAG_BK(gk.lnr) on (1 = 1)
     left outer join GET_ZAHLBETRAG(gk.lnr) on (1 = 1)

  where (gk.gastnr_1 = :"ADR_LNR" or
         gk.gastnr_2 = :"ADR_LNR" or
         gk.gastnr_3 = :"ADR_LNR")
         and (gk.ta_status<500)

  into :"ANREISE", :"ABREISE", :"ZINR", :"KATEGORIE", :"PERSZAHL", :"ANZKINDER" ,:"ANZJUGEND" , :"BUCHNR", :"SUM_LEISTUNG" ,
    :"BEZAHLT"

  do

  suspend;
end ^

ALTER PROCEDURE GETINTEGERLIST (AINTEGERLIST VARCHAR(32000) CHARACTER SET NONE,
TRENNER VARCHAR(1) CHARACTER SET NONE)
RETURNS (ID INTEGER)
AS 
declare variable INTEGERLIST varchar(32000);
declare variable COMMAPOS integer;
declare variable INTEGERVAL varchar(10);
begin

  INTEGERLIST = AINTEGERLIST || ' ';
  COMMAPOS = position(:TRENNER, INTEGERLIST);

  while (COMMAPOS > 0) do
  begin
    INTEGERVAL = trim(substring(INTEGERLIST from 1 for COMMAPOS - 1));

    if (char_length(INTEGERVAL) > 0) then
    begin
      if (INTEGERVAL similar to '[0-9]*') then
      begin
        ID = cast(INTEGERVAL as integer);
        suspend;
      end
    end

    if (char_length(INTEGERLIST) > COMMAPOS) then
      INTEGERLIST = substring(INTEGERLIST from COMMAPOS + 1);
    else
      INTEGERLIST = '';

    COMMAPOS = position(:TRENNER, INTEGERLIST);
  end

  INTEGERLIST = trim(INTEGERLIST);

  if (char_length(INTEGERLIST) > 0) then
  begin
    if (INTEGERLIST similar to '[0-9]*') then
    begin
      ID = cast(INTEGERLIST as integer);
      suspend;
    end
  end
end ^

ALTER PROCEDURE GET_ADRLNR_ALLE_AUS_GK (BELEGNR INTEGER)
RETURNS (GASTNR1 INTEGER,
GASTNR2 INTEGER,
GASTNR3 INTEGER)
AS 
