ALTER PROCEDURE GET_ANGEBOT_ANZA_KATE (ANG_LNR INTEGER)
RETURNS (ANZAHL INTEGER)
AS 
begin
  /* Procedure Text */
  for
    select count(*) as anzahl      from ang_leistung 
     where ang_leistung.ang_lnr = :ANG_LNR
     group by ang_leistung.kate_lnr
       into :ANZAHL
  do
  suspend;
end ^

ALTER PROCEDURE GET_ANGEBOT_BETRAG (ANG_LNR INTEGER,
ANG_LAUF INTEGER)
RETURNS (OUT_ANG_LAUF INTEGER,
OUT_BETRAG DECIMAL(12, 4))
AS 
begin
  /* Procedure Text */
  if (:ang_lauf>0) then
  begin
     for
        select ang_leistung.ang_lauf   , sum(ang_leistung.gbetrag)
           from ang_leistung where ang_leistung.ang_lnr = :ANG_LNR
               and ang_leistung.ta_status <1000
               and ang_leistung.ang_lauf = :ang_lauf
              group by ang_leistung.ang_lauf
              into :OUT_ANG_LAUF, :out_betrag
     do
     suspend;
  end
  else
  begin

    select sum(ang_leistung.gbetrag)
           from ang_leistung where ang_leistung.ang_lnr = :ANG_LNR
               and ang_leistung.ta_status <1000
              into  :out_betrag;
    suspend;
  end




end ^

ALTER PROCEDURE GET_ANG_ANZU_PERS_PRO_ALTERSK (ANG_LNR INTEGER,
INP_ALTERSKREIS INTEGER)
RETURNS (ANG_KATE_ZI_LNR INTEGER,
ALTERSKREIS INTEGER,
PERSZAHL INTEGER)
AS 
begin
  /* Procedure Text */
   for
    select
    
    ang_leistung.ang_kate_zi_lnr ,
    preislist.alterskreis,
    sum(erw) as perszahl
    
    
     from ang_leistung
        inner join preislist on (preislist.lnr = ang_leistung.prl_lnr)
    
     where  ang_leistung.ang_lnr = :ang_lnr and ang_leistung.ta_status <1000 and ang_leistung.prl_lnr >0
    
     group by ang_leistung.ang_kate_zi_lnr, preislist.alterskreis
       into :ang_kate_zi_lnr, :alterskreis, :perszahl

--     if (:INP_ALTERSKREIS=-1) then suspend;
--        else
--          if (:INP_ALTERSKREIS=:alterskreis) suspend;

  do
  if (:INP_ALTERSKREIS=-1) then suspend;
   else
        if (:INP_ALTERSKREIS=:alterskreis) then suspend;
end ^

ALTER PROCEDURE GET_ANZA_ZAHLBETRAG (DATUM DATE)
RETURNS (BELEGNR INTEGER,
BETRAG NUMERIC(12, 2))
AS 
begin
  /* Procedure Text */
  FOR
    SELECT gastkont.lnr
    FROM gastkont
      where gastkont.ta_status<500 and gastkont.anza_datum <= :DATUM
         into :BELEGNR
  do
  if (belegnr>0) then
  begin
  for
       select sum(get_zahlbetrag.bezahlt)
         from get_zahlbetrag(:belegnr)
        into :BETRAG
  do
  suspend;
  end


end ^

ALTER PROCEDURE GET_ANZ_FREIE_ZIMMER (VONDATUM DATE,
TAGE INTEGER,
MANDANT INTEGER,
OBJEKT INTEGER)
RETURNS (TAG DATE,
FREIEZIMMER INTEGER)
AS 
declare variable BELEGT integer;
declare variable MAXZI integer;
declare variable MAXDATE date;
declare variable CURRDATE date;
declare variable SPERRE integer;
declare variable SPERRDATE date;
begin

    CURRDATE = VONDATUM;
    MAXDATE = VONDATUM + TAGE;
    MAXZI = 0;
    BELEGT = 0;
    SPERRE = 0;
    SPERRDATE = CURRDATE - 1;

    select sum(KS.ANZ_KATE)
    from KATESTAM KS
    where KS.TA_STATUS < 1000 and
          KS.PSEUDO = 0 and
          KS.ONLINE_VERFUGBAR = 1 and
          KS.MAND_NR = :MANDANT and
          (KS.OBJEKT_NR = :OBJEKT or :OBJEKT = 0)
    into :MAXZI;

    if (:MAXZI = 0 or :MAXZI is null) then
    begin
        select count(ZIMMSTAM.LNR)
        from ZIMMSTAM
        inner join KATESTAM on (KATESTAM.LNR = ZIMMSTAM.LNR_KATE and
              KATESTAM.TA_STATUS < 1000 and
              KATESTAM.PSEUDO = 0)
        where ZIMMSTAM.TA_STATUS < 1000 and
              ZIMMSTAM.VERMIETJN = 1 and
              ZIMMSTAM.ONLINE_VERFUGBAR = 1 and
              ZIMMSTAM.MAND_NR = :MANDANT and
              (ZIMMSTAM.OBJEKT_NR = :OBJEKT or :OBJEKT = 0)
        into :MAXZI;
    end

    while (CURRDATE < MAXDATE) do
    begin

        SPERRE = 0;
        if (CURRDATE >= SPERRDATE) then
        begin
            select first 1 SPERRZEIT.LNR, SPERRZEIT.BISDATUM
            from SPERRZEIT
            where :CURRDATE between SPERRZEIT.VONDATUM and SPERRZEIT.BISDATUM and
                  SPERRZEIT.TA_STATUS < 1000 and
                  SPERRZEIT.OPTISCHE_SPERRE_WEBMX = 0 and
                  SPERRZEIT.PROVIDER_NR = 0
            into :SPERRE, :SPERRDATE;
        end

        :FREIEZIMMER = 0;

        if (:SPERRE = 0 and
            SPERRDATE < CURRDATE) then
        begin
            select count(BELEGUNG.LNR)
            from BELEGUNG

            inner join KATESTAM on (KATESTAM.TA_STATUS < 1000 and
                  KATESTAM.PSEUDO = 0 and
                  KATESTAM.LNR = BELEGUNG.LNR_KATE)
            inner join GASTKONT on (GASTKONT.LNR = BELEGUNG.LNR_GK and
                  coalesce(GASTKONT.SHARE_NR, 0) = 0)
            left outer join ZIMMSTAM on (ZIMMSTAM.TA_STATUS < 1000 and
                  ZIMMSTAM.LNR = BELEGUNG.LNR_ZINR)

            where (KATESTAM.ONLINE_VERFUGBAR = 1 or ZIMMSTAM.ONLINE_VERFUGBAR = 1) and
                  (ZIMMSTAM.VERMIETJN = 1 or ZIMMSTAM.VERMIETJN is null) and
                  (BELEGUNG.TA_STATUS < 1000) and
                  (:CURRDATE >= BELEGUNG.ANREISE and
                  :CURRDATE < BELEGUNG.ABREISE) and
                  KATESTAM.MAND_NR = :MANDANT and
                  (KATESTAM.OBJEKT_NR = :OBJEKT or :OBJEKT = 0)
            into :BELEGT;

            FREIEZIMMER = MAXZI - BELEGT;
        end
        TAG = CURRDATE;
        CURRDATE = CURRDATE + 1;

        suspend;
    end
end ^

ALTER PROCEDURE GET_ANZ_VERKNR (VERK_NR INTEGER)
RETURNS (ANZ_BUCHUNGEN INTEGER)
AS 
begin
  /* Procedure Text */
  for
    SELECT count(GASTKONT.VERK_NR)
      FROM GASTKONT
        where gastkont.verk_nr = :VERK_NR
           and ta_status<500
         into :"ANZ_BUCHUNGEN"

  do
  suspend;
end ^

ALTER PROCEDURE GET_ANZ_VERKNR_GASTNR (GASTNR INTEGER,
VERK_NR INTEGER)
RETURNS (ANZ_BUCHUNGEN INTEGER,
ANZ_GAESTE INTEGER)
AS 
declare variable GAST1 integer;
declare variable GAST2 integer;
declare variable GAST3 integer;
declare variable AKTIV1 integer;
declare variable AKTIV2 integer;
declare variable AKTIV3 integer;
begin
    :ANZ_BUCHUNGEN = 0;
    :ANZ_GAESTE = 0;
    /* Procedure Text */
    for select GASTKONT.GASTNR_1, GASTKONT.GASTNR_2, GASTKONT.GASTNR_3
        from GASTKONT
        where (GASTKONT.VERK_NR = :VERK_NR or GASTKONT.LNR = :VERK_NR) and
              GASTKONT.TA_STATUS < 500 --and
              --(:GASTNR = 0 or :GASTNR in (GASTKONT.GASTNR_1, GASTKONT.GASTNR_2, GASTKONT.GASTNR_3))
        into :GAST1, :GAST2, :GAST3
    do
    begin
        :ANZ_BUCHUNGEN = :ANZ_BUCHUNGEN + 1;
        if (:GAST1 > 0) then
        begin
            select ADR_AUSWAHL.ONLINETOOLS_NICHT_AKTIV
            from ADRESSEN
            inner join ADR_AUSWAHL on ADR_AUSWAHL.LNR = ADRESSEN.ADR_WAHL
            where ADRESSEN.LNR = :GAST1 and
                  ADRESSEN.TA_STATUS < 1000
            into :AKTIV1;

            if (:AKTIV1 = 0) then
                :ANZ_GAESTE = :ANZ_GAESTE + 1;
        end
        if (:GAST2 > 0) then
        begin
            select ADR_AUSWAHL.ONLINETOOLS_NICHT_AKTIV
            from ADRESSEN
            inner join ADR_AUSWAHL on ADR_AUSWAHL.LNR = ADRESSEN.ADR_WAHL
            where ADRESSEN.LNR = :GAST2 and
                  ADRESSEN.TA_STATUS < 1000
            into :AKTIV2;

            if (:AKTIV2 = 0) then
                :ANZ_GAESTE = :ANZ_GAESTE + 1;
        end
        if (:GAST3 > 0) then
        begin
            select ADR_AUSWAHL.ONLINETOOLS_NICHT_AKTIV
            from ADRESSEN
            inner join ADR_AUSWAHL on ADR_AUSWAHL.LNR = ADRESSEN.ADR_WAHL
            where ADRESSEN.LNR = :GAST3 and
                  ADRESSEN.TA_STATUS < 1000
            into :AKTIV3;

            if (:AKTIV3 = 0) then
                :ANZ_GAESTE = :ANZ_GAESTE + 1;
        end

    end
    suspend;
end ^

ALTER PROCEDURE GET_BELEGUNG_STAT_BELG (BUCHNR INTEGER)
RETURNS (PERSZAHL INTEGER,
ANZKINDER INTEGER,
ANZJUGEND INTEGER,
ANREISE DATE,
ABREISE DATE,
TGABSDATUM TIMESTAMP)
AS 
begin
  for
    select perszahl,anzkinder,anzjugend,vonaufh,bisaufh,TGABSDATUM
    from gastkont
    where lnr=:"BUCHNR" and ta_status<1000
    into   :"PERSZAHL",:"ANZKINDER", :"ANZJUGEND","ANREISE",:"ABREISE",:"TGABSDATUM"
  do
  suspend;
end ^

ALTER PROCEDURE GET_BUCH_PRO_GK (GK_LNR INTEGER)
RETURNS (ANREISE DATE,
ABREISE DATE,
KATEGORIE VARCHAR(20) CHARACTER SET NONE,
ZINR VARCHAR(10) CHARACTER SET NONE,
KATE_PREISLIST INTEGER,
ZIMM_PREISLIST INTEGER,
OBJEKT_KURZBEZ VARCHAR(10) CHARACTER SET NONE)
AS 
begin
  /* Procedure Text */
  for
   SELECT BELEGUNG.ANREISE, BELEGUNG.ABREISE, KATESTAM.KATEGORIE, KATESTAM.PREISLIST as Kate_preisliste,
          ZIMMSTAM.ZINR, ZIMMSTAM.preislist as Zimm_preislist, objekt.kurzbez as OBJEKT_KURZBEZ
     FROM BELEGUNG
       LEFT OUTER JOIN KATESTAM ON (BELEGUNG.LNR_KATE = KATESTAM.LNR)
       LEFT OUTER JOIN ZIMMSTAM ON (BELEGUNG.LNR_ZINR = ZIMMSTAM.LNR)
       LEFT OUTER JOIN OBJEKT   on (objekt.lnr = zimmstam.objekt_nr)
       WHERE
       (
           (BELEGUNG.lnr_gk = :"GK_LNR")
           and (belegung.ta_status<1000)
       )
       into :"ANREISE", :"ABREISE", :"KATEGORIE", :"KATE_PREISLIST", :"ZINR", :"ZIMM_PREISLIST", :"OBJEKT_KURZBEZ"

  do
  suspend;
end ^

ALTER PROCEDURE GET_BUCH_REGK_VERB RETURNS (BELEGNR INTEGER,
ANREISE TIMESTAMP,
ABREISE TIMESTAMP,
ZINR VARCHAR(10) CHARACTER SET NONE,
NAME1 VARCHAR(40) CHARACTER SET NONE,
NAME2 VARCHAR(40) CHARACTER SET NONE,
BEMERK VARCHAR(100) CHARACTER SET NONE,
ONLINE_CI INTEGER,
AUFP INTEGER)
AS 
declare variable N1 varchar(60);
declare variable N2 varchar(60);
begin
  /* Procedure Text */
  AUFP = 0;

  FOR
    SELECT DISTINCT GASTKONT.LNR, BELEGUNG.ANREISE, BELEGUNG.ABREISE, ZIMMSTAM.ZINR,
                    ADRESSEN.NAME1, ADRESSEN.NAME2,
                    GASTKONT.BEMERK,
                    ONLINE_VERBUND.CI_STATUS AS ONLINE_CI
           FROM BELEGUNG
                INNER JOIN GASTKONT ON (BELEGUNG.LNR_GK = GASTKONT.LNR and gastkont.lnr_zinr = belegung.lnr_zinr)
                INNER JOIN ADRESSEN ON (GASTKONT.GASTNR_1 = ADRESSEN.LNR)
                LEFT OUTER JOIN ZIMMSTAM ON (ZIMMSTAM.LNR = GASTKONT.lnr_zinr)
                LEFT OUTER JOIN ONLINE_VERBUND ON (BELEGUNG.LNR_GK = ONLINE_VERBUND.GK_LNR)
     WHERE
     (
        (ONLINE_VERBUND.CI_STATUS = 1) AND
        (gastkont.TA_STATUS<500) AND (gastkont.ci_status = 1) AND
        (GASTKONT.GASTNR_1 > 0) AND ((gastkont.pm < 1) or (gastkont.pm is null) )
     )
     ORDER BY ZIMMSTAM.ZINR
     INTO
     :BELEGNR, :ANREISE, :ABREISE, :ZINR, :N1, :N2, :BEMERK, :ONLINE_CI
  do
  FOR
    SELECT PROC_SUBSTRING.RESULT FROM PROC_SUBSTRING
        (:N1, 1, 40 )
    INTO :name1
  DO
  FOR
    SELECT PROC_SUBSTRING.RESULT FROM PROC_SUBSTRING
        (:N2, 1, 40 )
    INTO :name2
  DO
  suspend;
  AUFP = 1;
  FOR
    SELECT DISTINCT GASTKONT.LNR, BELEGUNG.ANREISE, BELEGUNG.ABREISE, ZIMMSTAM.ZINR, ADRESSEN.NAME1,ADRESSEN.NAME2,
                    GASTKONT.BEMERK,
                    ONLINE_VERBUND.CI_STATUS AS ONLINE_CI
           FROM BELEGUNG
                INNER JOIN GASTKONT ON (BELEGUNG.LNR_GK = GASTKONT.LNR)
                INNER JOIN ADRESSEN ON (GASTKONT.GASTNR_2 = ADRESSEN.LNR)
                LEFT OUTER JOIN ZIMMSTAM ON (ZIMMSTAM.LNR = GASTKONT.LNR_ZINR)
                LEFT OUTER JOIN ONLINE_VERBUND ON (BELEGUNG.LNR_GK = ONLINE_VERBUND.GK_LNR)
     WHERE
     (
        (ONLINE_VERBUND.CI_STATUS = 1) AND
        (gastkont.TA_STATUS<500) AND (gastkont.ci_status = 1) AND
        (GASTKONT.GASTNR_2 > 0)  AND ((gastkont.pm < 1) or (gastkont.pm is null) )
     )
     ORDER BY ZIMMSTAM.ZINR
     INTO
     :BELEGNR, :ANREISE, :ABREISE, :ZINR, :N1, :N2, :BEMERK, :ONLINE_CI
  do
  FOR
    SELECT PROC_SUBSTRING.RESULT FROM PROC_SUBSTRING
        (:N1, 1, 40 )
    INTO :name1
  DO
  FOR
    SELECT PROC_SUBSTRING.RESULT FROM PROC_SUBSTRING
        (:N2, 1, 40 )
    INTO :name2
  DO
  suspend;
  AUFP = 2;
  FOR
    SELECT DISTINCT GASTKONT.LNR, BELEGUNG.ANREISE, BELEGUNG.ABREISE, ZIMMSTAM.ZINR, ADRESSEN.NAME1,ADRESSEN.NAME2,
                    GASTKONT.BEMERK,
                    ONLINE_VERBUND.CI_STATUS AS ONLINE_CI
           FROM BELEGUNG
                INNER JOIN GASTKONT ON (BELEGUNG.LNR_GK = GASTKONT.LNR)
                INNER JOIN ADRESSEN ON (GASTKONT.GASTNR_3 = ADRESSEN.LNR)
                LEFT OUTER JOIN ZIMMSTAM ON (ZIMMSTAM.LNR = GASTKONT.LNR_ZINR)
                LEFT OUTER JOIN ONLINE_VERBUND ON (BELEGUNG.LNR_GK = ONLINE_VERBUND.GK_LNR)
     WHERE
     (
        (ONLINE_VERBUND.CI_STATUS = 1) AND
        (gastkont.TA_STATUS<500) AND (gastkont.ci_status = 1) AND
        (GASTKONT.GASTNR_3 > 0) AND ((gastkont.pm < 1)or (gastkont.pm is null) )
     )
     ORDER BY ZIMMSTAM.ZINR
     INTO
     :BELEGNR, :ANREISE, :ABREISE, :ZINR, :N1, :N2, :BEMERK, :ONLINE_CI
  do
  FOR
    SELECT PROC_SUBSTRING.RESULT FROM PROC_SUBSTRING
        (:N1, 1, 40 )
    INTO :name1
  DO
  FOR
    SELECT PROC_SUBSTRING.RESULT FROM PROC_SUBSTRING
        (:N2, 1, 40 )
    INTO :name2
  DO
  suspend;
end ^

ALTER PROCEDURE GET_DASHBOARD_MARKTING (VONDATUM DATE,
BISDATUM DATE)
RETURNS (COUNT_OFFER INTEGER,
COUNT_RESERV INTEGER,
COUNT_OFFER_RESERV INTEGER,
BOOKING_CODE INTEGER,
BOOKING_TEXT VARCHAR(50) CHARACTER SET NONE,
BOOKING_COUNT INTEGER)
AS 
begin
  /* Procedure Text */
  select count(*) as anzahl
      from angebot where   cast ( angebot.erf_datum as date) between :vondatum and :bisdatum
        into :count_offer;

  select count(*) as anzahl
      from gastkont where erf_datum between :vondatum and :bisdatum and gastkont.ta_status <1000
        into :count_reserv;



  
    select count(*) as anzahl
       from gastkont where erf_datum between :vondatum and :bisdatum and gastkont.ta_status <1000
         and gastkont.ang_lnr >0
           into :count_offer_reserv;


    for
      select gastkont.gast_gr, segmstam.bezeichn
               ,count(*) as anzahl
            from gastkont
              left outer join segmstam on (gastkont.gast_gr = segmstam.SEGMCODE and gastkont.mand_nr = segmstam.mand_nr)
            where gastkont.erf_datum between :vondatum and :bisdatum and gastkont.ta_status <1000
            group by gastkont.gast_gr, segmstam.bezeichn
              into :booking_code, :booking_text, :booking_count


    do




  suspend;
end ^

ALTER PROCEDURE GET_DASHBOARD_PERSON (VONDATUM DATE,
BISDATUM DATE)
RETURNS (ARRIVAL_ROOMS INTEGER,
ARRIVAL_ADULT INTEGER,
ARRIVAL_YOUNGP INTEGER,
ARRIVAL_CHILD INTEGER,
ARRIVAL_BABY INTEGER,
DEPART_ROOMS INTEGER,
DEPART_ADULT INTEGER,
DEPART_YOUNGP INTEGER,
DEPART_CHILD INTEGER,
DEPART_BABY INTEGER,
STAY_ROOMS INTEGER,
STAY_ADULT INTEGER,
STAY_YOUNGP INTEGER,
STAY_CHILD INTEGER,
STAY_BABY INTEGER,
SELECTDATE DATE,
LOGIS_SALES NUMERIC(12, 2),
FB_SALES NUMERIC(12, 2),
HEALTH_SALES NUMERIC(12, 2),
VARIOUS_SALES NUMERIC(12, 2),
OFFER_COUNT INTEGER,
RESERVATION_COUNT INTEGER,
OFFER_TO_BOOK INTEGER,
LOGIS_INVOICE NUMERIC(12, 2),
FB_INVOICE NUMERIC(15, 2),
HEALTH_INVOICE NUMERIC(15, 2),
VARIOUS_INVOICE NUMERIC(15, 2))
AS 
declare variable DATUM date;
declare variable TEMPBETRAG numeric(12,2) = 0;
begin
  /* Procedure Text */
  -- als erstes die Anreisen....
  :datum = :VONDATUM;

  while (:datum <= :bisdatum) do
  begin
      :selectdate = :datum;
    
      select count(*) as arrival_rooms, sum(gastkont.perszahl) arrival_adult, sum(gastkont.anzjugend) as arrival_youngp,
        sum(  coalesce(gastkont.anzkinder,0)+ coalesce(gastkont.anzkinder2,0)) as arrival_child,
        sum (coalesce(gastkont.anzkleinkind,0)) as arrival_baby
        from
        gastkont
         inner join katestam on (gastkont.lnr_kate = katestam.lnr and katestam.pseudo =0)
        
         where gastkont.vonaufh = :DATUM
         and gastkont.ta_status <1000
         and gastkont.buch_status <10000
    
           into :arrival_rooms, :arrival_adult, :arrival_youngp, :arrival_child, :arrival_baby;
    
      -- als zweites die abreisen
    
      select count(*) as depart_rooms, sum(gastkont.perszahl) depart_adult, sum(gastkont.anzjugend) as depart_youngp,
        sum(  coalesce(gastkont.anzkinder,0)+ coalesce(gastkont.anzkinder2,0)) as depart_child,
        sum (coalesce(gastkont.anzkleinkind,0)) as depart_baby
        
        
        from
        gastkont
         inner join katestam on (gastkont.lnr_kate = katestam.lnr and katestam.pseudo =0)
        
         where gastkont.bisaufh = :DATUM
         and gastkont.ta_status <1000
         and gastkont.buch_status <10000
           into :depart_rooms, :depart_adult, :depart_youngp, :depart_child, :depart_baby;
    
    
       --- als drittes noch die bleiben....
    
       select count(*) as stay_rooms, sum(gastkont.perszahl) stay_adult, sum(gastkont.anzjugend) as stay_youngp,
            sum(  coalesce(gastkont.anzkinder,0)+ coalesce(gastkont.anzkinder2,0)) as stay_child,
            sum (coalesce(gastkont.anzkleinkind,0)) as stay_baby
            
            
            from
            gastkont
             inner join katestam on (gastkont.lnr_kate = katestam.lnr and katestam.pseudo =0)
            
             where :DATUM between gastkont.vonaufh+1 and gastkont.bisaufh -1
             and gastkont.ta_status <1000
             and gastkont.buch_status <10000
             into :stay_rooms, :stay_adult, :stay_youngp, :stay_child, :stay_baby;
    
    
        :logis_sales = 0;
        :fb_sales = 0;
        :health_sales = 0;
        :various_sales = 0;

        -- hier noch den umsatz f?r diesen tag berechnen ......
        select coalesce( sum(TEMP_STAT_UMS_DASHBOARD.tag_betrag*TEMP_STAT_UMS_DASHBOARD.me),0)
          from TEMP_STAT_UMS_DASHBOARD
           inner join warengru on (warengru.wgnr = TEMP_STAT_UMS_DASHBOARD.wgnr)
            where TEMP_STAT_UMS_DASHBOARD.datum = :datum and warengru.durchl = 0
               into :logis_sales;
    
        -- hier noch den umsatz f&B
        select coalesce( sum(TEMP_STAT_UMS_DASHBOARD.tag_betrag*TEMP_STAT_UMS_DASHBOARD.me),0)
          from TEMP_STAT_UMS_DASHBOARD
           inner join warengru on (warengru.wgnr = TEMP_STAT_UMS_DASHBOARD.wgnr)
            where TEMP_STAT_UMS_DASHBOARD.datum = :datum and warengru.durchl = 1
               into :fb_sales;
    
        -- hier noch den umsatz gesundheit
        select coalesce( sum(TEMP_STAT_UMS_DASHBOARD.tag_betrag*TEMP_STAT_UMS_DASHBOARD.me),0)
          from TEMP_STAT_UMS_DASHBOARD
           inner join warengru on (warengru.wgnr = TEMP_STAT_UMS_DASHBOARD.wgnr)
            where TEMP_STAT_UMS_DASHBOARD.datum = :datum and warengru.durchl = 2
               into :health_sales;

        -- hier noch den umsatz divers
        select coalesce( sum(TEMP_STAT_UMS_DASHBOARD.tag_betrag*TEMP_STAT_UMS_DASHBOARD.me),0)
          from TEMP_STAT_UMS_DASHBOARD
           inner join warengru on (warengru.wgnr = TEMP_STAT_UMS_DASHBOARD.wgnr)
            where TEMP_STAT_UMS_DASHBOARD.datum = :datum and warengru.durchl = 2
               into :various_sales;

    
       --jetzt noch den stat_umsatz mit abfragen
       :tempbetrag = 0;
       select coalesce( sum(stat_umsatz.tag_betrag*stat_umsatz.me),0)
          from stat_umsatz
           inner join leiststa on (leiststa.lnr = stat_umsatz.leist_lnr)
           inner join warengru on (warengru.lnr = leiststa.wg)
            where stat_umsatz.ldatum = :datum and warengru.durchl = 0
               into :tempbetrag;

       :logis_sales = :logis_sales + :tempbetrag;

       :tempbetrag = 0;
       select coalesce( sum(stat_umsatz.tag_betrag*stat_umsatz.me),0)
          from stat_umsatz
           inner join leiststa on (leiststa.lnr = stat_umsatz.leist_lnr)
           inner join warengru on (warengru.lnr = leiststa.wg)
            where stat_umsatz.ldatum = :datum and warengru.durchl = 1
               into :tempbetrag;
        :fb_sales = :fb_sales + :tempbetrag;

       :tempbetrag = 0;
       select coalesce( sum(stat_umsatz.tag_betrag*stat_umsatz.me),0)
          from stat_umsatz
           inner join leiststa on (leiststa.lnr = stat_umsatz.leist_lnr)
           inner join warengru on (warengru.lnr = leiststa.wg)
            where stat_umsatz.ldatum = :datum and warengru.durchl = 2
               into :tempbetrag;
        :health_sales = :health_sales + :tempbetrag;

       :tempbetrag = 0;
       select coalesce( sum(stat_umsatz.tag_betrag*stat_umsatz.me),0)
          from stat_umsatz
           inner join leiststa on (leiststa.lnr = stat_umsatz.leist_lnr)
           inner join warengru on (warengru.lnr = leiststa.wg)
            where stat_umsatz.ldatum = :datum and warengru.durchl = 3
               into :tempbetrag;
        :various_sales = :various_sales + :tempbetrag;



       -- hier noch den fakt_erloese abfragen.....

       :logis_invoice = 0;
       :fb_invoice = 0;
       :health_invoice = 0;
       :various_invoice = 0;
       select  sum(fakt_erloese.betrag) as umsatz
             from fakt_erloese
             inner join leiststa on (leiststa.lnr = fakt_erloese.lnr_leist)
             left outer join warengru on (warengru.lnr = leiststa.wg)
             where   fakt_erloese.budat = :datum 
             and fakt_erloese.zahlungsart = 9999
             and warengru.durchl=0
               into :logis_invoice;


       select  sum(fakt_erloese.betrag) as umsatz
             from fakt_erloese
             inner join leiststa on (leiststa.lnr = fakt_erloese.lnr_leist)
             left outer join warengru on (warengru.lnr = leiststa.wg)
             where   fakt_erloese.budat = :datum
             and fakt_erloese.zahlungsart = 9999
             and warengru.durchl=1
               into :fb_invoice;

       select  sum(fakt_erloese.betrag) as umsatz
             from fakt_erloese
             inner join leiststa on (leiststa.lnr = fakt_erloese.lnr_leist)
             left outer join warengru on (warengru.lnr = leiststa.wg)
             where   fakt_erloese.budat = :datum
             and fakt_erloese.zahlungsart = 9999
             and warengru.durchl=2
               into :health_invoice;

       select  sum(fakt_erloese.betrag) as umsatz
             from fakt_erloese
             inner join leiststa on (leiststa.lnr = fakt_erloese.lnr_leist)
             left outer join warengru on (warengru.lnr = leiststa.wg)
             where   fakt_erloese.budat = :datum
             and fakt_erloese.zahlungsart = 9999
             and warengru.durchl=3
               into :various_invoice;





       -- anz erf angebot

       select count(*) from angebot where cast ( angebot.erf_datum as date) = :datum
          into :offer_count;

       -- anz erf_buchungen
       select count(*) from gastkont where gastkont.erf_datum = :datum
          into :reservation_count;

       select count(*) from gastkont where gastkont.erf_datum = :datum and gastkont.ang_lnr >0
          into :offer_to_book;



       suspend; -- nur zum schluss, damit wir einen ds bekommen ....
       :datum = datum+1;
    end
end ^

ALTER PROCEDURE GET_DASHBOARD_TODOS (VONDATUM DATE,
BISDATUM DATE)
RETURNS (TODO_LNR INTEGER,
FINISH_DATE DATE,
ACT_STATUS INTEGER,
MEMO VARCHAR(1099) CHARACTER SET NONE,
NAME1 VARCHAR(100) CHARACTER SET NONE,
NAME2 VARCHAR(100) CHARACTER SET NONE,
STREET VARCHAR(60) CHARACTER SET NONE,
COUNTY VARCHAR(10) CHARACTER SET NONE,
PLZ VARCHAR(20) CHARACTER SET NONE,
CITY VARCHAR(60) CHARACTER SET NONE,
ARRIVAL DATE,
DEPART DATE,
BOOKING_NO INTEGER,
ROOMNO VARCHAR(20) CHARACTER SET NONE)
AS 
declare variable TEMPINT integer;
declare variable TEMPINT2 integer;
begin
  /* Procedure Text */


  for
     select todolist.lnr, todolist.erled_bisdate
     , todolist.memo , todolist.akt_status,  adressen.name1, adressen.name2, adressen.strasse, adressen.land, adressen.plz,  adressen.ort,
         gastkont.vonaufh, gastkont.bisaufh, gastkont.lnr as buchnr,
         (select zimmstam.zinr from zimmstam where gastkont.lnr_zinr = zimmstam.lnr) as zinr
         from todolist
         inner join gastkont on (gastkont.lnr = todolist.gk_lnr  and todolist.gk_lnr>0)
