               and todolist.adr_lnr > 0
               order by todolist.ERLED_BISDATE, adressen.suchname

         into :todo_lnr, :finish_date,:memo, :act_status, :name1, :name2, :street, :county, :plz, :city,
         :arrival, :depart, :booking_no, :roomno



    do
    suspend;
    -- jetzt noch die optionen mit einbinden .....


    for
      select -1 , gastkont.termindat, gastkont.bemerk , 0,
         adressen.name1, adressen.name2, adressen.strasse, adressen.land, adressen.plz,  adressen.ort,
         gastkont.vonaufh, gastkont.bisaufh, gastkont.lnr as buchnr,
         (select zimmstam.zinr from zimmstam where gastkont.lnr_zinr = zimmstam.lnr) as zinr
         from gastkont
         inner join adressen on (adressen.lnr = gastkont.gastnr_1)

         where
         gastkont.ta_status <1000
         and gastkont.bu_st_option>=10000
         and    gastkont.termindat between :vondatum and :bisdatum

           order by gastkont.termindat, adressen.suchname

         into :todo_lnr, :finish_date,:memo, :act_status, :name1, :name2, :street, :county, :plz, :city,
         :arrival, :depart, :booking_no, :roomno


    do
    suspend;

    -- jetzt noch die geb_tage anzeigen.....
    :tempint = extract (month from :vondatum);
    :tempint2 = extract (month from :bisdatum);


     for
      select -2 , adressen.gebdat, gastkont.bemerk , 0,
         adressen.name1, adressen.name2, adressen.strasse, adressen.land, adressen.plz,  adressen.ort,
         gastkont.vonaufh, gastkont.bisaufh, gastkont.lnr as buchnr,
         (select zimmstam.zinr from zimmstam where gastkont.lnr_zinr = zimmstam.lnr) as zinr
         from gastkont
         inner join adressen on (adressen.lnr = gastkont.gastnr_1)

         where
           (    (gastkont.vonaufh between :vondatum and :bisdatum)
             or (gastkont.bisaufh between :vondatum and :bisdatum)
             or (gastkont.vonaufh < :vondatum and gastkont.bisaufh > :bisdatum)
             )

           and gastkont.ta_status <1000
           and
           ( extract(month from gebdat) between :tempint and :tempint2)

           order by adressen.suchname

         into :todo_lnr, :finish_date,:memo, :act_status, :name1, :name2, :street, :county, :plz, :city,
         :arrival, :depart, :booking_no, :roomno


    do
    suspend;
    
    -- jetzt noch die hochzeitstage anzeigen.....

     for
      select -3 , adressen.hochzeitstag, gastkont.bemerk , 0,
         adressen.name1, adressen.name2, adressen.strasse, adressen.land, adressen.plz,  adressen.ort,
         gastkont.vonaufh, gastkont.bisaufh, gastkont.lnr as buchnr,
         (select zimmstam.zinr from zimmstam where gastkont.lnr_zinr = zimmstam.lnr) as zinr
         from gastkont
         inner join adressen on (adressen.lnr = gastkont.gastnr_1)

         where
           (    (gastkont.vonaufh between :vondatum and :bisdatum)
             or (gastkont.bisaufh between :vondatum and :bisdatum)
             or (gastkont.vonaufh < :vondatum and gastkont.bisaufh > :bisdatum)
             )

           and gastkont.ta_status <1000
           and
           ( extract(month from hochzeitstag) between :tempint and :tempint2)

           order by adressen.suchname

         into :todo_lnr, :finish_date,:memo, :act_status, :name1, :name2, :street, :county, :plz, :city,
         :arrival, :depart, :booking_no, :roomno

    do
    suspend;

end ^

ALTER PROCEDURE GET_EIGENTUEMER RETURNS (NAME1 VARCHAR(60) CHARACTER SET NONE,
NAME2 VARCHAR(60) CHARACTER SET NONE,
STRASSE VARCHAR(60) CHARACTER SET NONE,
LANDKENN VARCHAR(10) CHARACTER SET NONE,
LAND VARCHAR(5) CHARACTER SET NONE,
PLZ VARCHAR(10) CHARACTER SET NONE,
ORT VARCHAR(50) CHARACTER SET NONE,
ANREDE VARCHAR(30) CHARACTER SET NONE,
ZINR VARCHAR(10) CHARACTER SET NONE,
ADR_LNR INTEGER,
LNR_ZINR INTEGER,
MAND_NR INTEGER,
MANDANT VARCHAR(30) CHARACTER SET NONE,
VERMIET_JN INTEGER)
AS 
begin
  /* Procedure Text */
  for
   SELECT ADRESSEN.NAME1, ADRESSEN.NAME2, ADRESSEN.STRASSE, ADRESSEN.LANDKENN,
          ADRESSEN.LAND, ADRESSEN.PLZ, ADRESSEN.ORT, ADRESSEN.ANREDE, Adressen.lnr,
          ZIMMSTAM.ZINR, ZIMMSTAM.lnr, ZIMMSTAM.mand_nr, mandant.bezeichn, ZIMMSTAM.vermietjn

   FROM ZIMMSTAM
     INNER JOIN ADRESSEN ON (ZIMMSTAM.ADR_LNR = ADRESSEN.LNR)
     INNER JOIN MANDANT  ON (ZIMMSTAM.mand_nr = MANDANT.lnr)

   where adressen.ta_status < 1000 and zimmstam.ta_status < 1000

     into :"NAME1", :"NAME2", :"STRASSE", :"LANDKENN",
          :"LAND", :"PLZ", :"ORT", :"ANREDE",:"ADR_LNR",
          :"ZINR", :"LNR_ZINR", :"MAND_NR", :"MANDANT", :"VERMIET_JN"
  do
  suspend;
end ^

ALTER PROCEDURE GET_EIGENTUEMER_BELASTUNG RETURNS (EBETRAG NUMERIC(12, 3),
GBETRAG NUMERIC(12, 3),
ME INTEGER,
LNR INTEGER,
MAND_NR INTEGER,
VON DATE,
BIS DATE,
TAGE INTEGER,
ADR_LNR INTEGER,
NAME1 VARCHAR(60) CHARACTER SET NONE,
NAME2 VARCHAR(60) CHARACTER SET NONE,
STRASSE VARCHAR(60) CHARACTER SET NONE,
LANDKENN VARCHAR(10) CHARACTER SET NONE,
LAND VARCHAR(5) CHARACTER SET NONE,
PLZ VARCHAR(10) CHARACTER SET NONE,
ORT VARCHAR(50) CHARACTER SET NONE,
ANREDE VARCHAR(30) CHARACTER SET NONE,
ZINR VARCHAR(10) CHARACTER SET NONE,
MAND_BEZEICHN VARCHAR(30) CHARACTER SET NONE)
AS 
begin
  /* Procedure Text */
  for
   SELECT EIGT_KTO.EBETRAG, EIGT_KTO.GBETRAG, EIGT_KTO.ME,EIGT_KTO.LNR, EIGT_KTO.MAND_NR,
          EIGT_KTO.VON, EIGT_KTO.BIS, EIGT_KTO.TAGE, EIGT_KTO.adr_lnr,
          ADRESSEN.NAME1, ADRESSEN.NAME2, ADRESSEN.STRASSE, ADRESSEN.LANDKENN,
          ADRESSEN.LAND, ADRESSEN.PLZ, ADRESSEN.ORT, ADRESSEN.ANREDE,
          ZIMMSTAM.ZINR,
          MANDANT.BEZEICHN
   FROM EIGT_KTO
     INNER JOIN ADRESSEN ON (EIGT_KTO.adr_lnr = ADRESSEN.LNR)
     INNER JOIN ZIMMSTAM ON (EIGT_KTO.ZI_LNR = ZIMMSTAM.LNR)
     INNER JOIN MANDANT ON (EIGT_KTO.MAND_NR = MANDANT.LNR)

     where eigt_kto.ta_status < 1000 and
           zimmstam.ta_status < 1000
     into :"EBETRAG", :"GBETRAG", :"ME", :"LNR", :"MAND_NR",
          :"VON", :"BIS", :"TAGE", :"ADR_LNR",
          :"NAME1", :"NAME2", :"STRASSE", :"LANDKENN",
          :"LAND", :"PLZ", :"ORT", :"ANREDE", :"ZINR", :"MAND_BEZEICHN"
  do
  suspend;
end ^

ALTER PROCEDURE GET_FAKT_AKT_SALDO_VAR2 (VONDATUM DATE,
BISDATUM DATE)
RETURNS (AKT_SALDO_EINGANG NUMERIC(12, 2),
AKT_SALDO_AUSGANG NUMERIC(12, 2),
AKT_SALDO_BARE NUMERIC(12, 2),
AKT_SALDO_BANKA NUMERIC(12, 2),
AKT_SALDO_BARA NUMERIC(12, 2),
AKT_SALDO_BAR_SONST NUMERIC(12, 2),
AKT_SALDO_UNBAR_O_BNR NUMERIC(12, 2))
AS 
begin
  /* alle erlöse summieren eingang */
  select sum(fakt_erloese.betrag)  as saldobetrag
   from fakt_erloese
      where budat between :vondatum and :bisdatum
            and ta_status <1000 and betrag >0
      into :akt_saldo_eingang;

  /* alle erlöse summieren ausgang */
  select sum(fakt_erloese.betrag)  as saldobetrag
   from fakt_erloese
      where budat between :vondatum and :bisdatum
            and ta_status <1000 and betrag <0
      into :akt_saldo_ausgang;

   /* alle baranzahlungen eingang in diesem monat aufbuchen ...... für abreisen ab der folgezeit*/
   select sum(zahlungen.betrag)
   from zahlungen 
     inner join devisen on (zahlungen.lnr_devi = devisen.lnr and devisen.FAKT_AUSW_VAR2=1 and devisen.ta_status<1000) 
     inner join gastkont on (gastkont.lnr = zahlungen.lnr_gk and (gastkont.vonaufh >=:vondatum))
   where (zahlungen.lnr>0 and zahlungen.budat between  :vondatum and :bisdatum)
         and (zahlungen.ta_status<1000) and (zahlungen.lnr_gk>0)
         into :akt_saldo_bare;


   /*  alle baranzahlungen vor diesemzeitraum mit der abreise in diesem Zeitraum */
   select sum(zahlungen.betrag)*-1
   from zahlungen 
     inner join devisen on (zahlungen.lnr_devi = devisen.lnr and devisen.FAKT_AUSW_VAR2=1 and devisen.ta_status<1000) 
     inner join gastkont on (gastkont.lnr = zahlungen.lnr_gk and (gastkont.bisaufh between  :vondatum  and :bisdatum ))
   where (zahlungen.lnr>0 and zahlungen.budat <=:bisdatum)
        and (zahlungen.ta_status<1000 and zahlungen.re_nr >0) 
        into :akt_saldo_bara;

   /* alle baranzahlungen eingang in diesem monat aufbuchen ohne zuordnung einer gastkonto - nr wg. gutschein z. b. */
   select sum(zahlungen.betrag)
   from zahlungen 
     inner join devisen on (zahlungen.lnr_devi = devisen.lnr and devisen.FAKT_AUSW_VAR2=1 and devisen.ta_status<1000) 
   where (zahlungen.lnr>0 and zahlungen.budat between  :vondatum  and :bisdatum)
        and (zahlungen.ta_status<1000) and (zahlungen.lnr_gk=0)
        into :akt_saldo_bar_sonst;

   /* alle bankanzahlungen */
   select sum(pro_lesen_fakt_var2.betrag)*-1
   from pro_lesen_fakt_var2(:vondatum,:bisdatum,2)
     where ci_status>=0
     into :akt_saldo_banka;

  /* alle unbaren zahlungen belegnr = 0 */

  select sum(zahlungen.betrag)*-1 as saldo_unbar_o_bnr
      from zahlungen 
      inner join  devisen on (zahlungen.lnr_devi = devisen.lnr ) 
      where (zahlungen.lnr>0 and zahlungen.lnr_gk<=0 and zahlungen.lnr_co = 0 and zahlungen.budat >= '01.10.2007')
            and (devisen.FAKT_AUSW_VAR2=2) 
            and (zahlungen.ta_status<1000) 
            and (devisen.ta_status<1000) and (devisen.ZAHLUNGSART!=0)
        into :AKT_SALDO_UNBAR_O_BNR;

  if (akt_saldo_ausgang is null) then akt_saldo_ausgang = 0;
  if (akt_saldo_eingang is null) then akt_saldo_eingang = 0;
  if (akt_saldo_bare is null) then akt_saldo_bare = 0;
  if (akt_saldo_banka is null) then akt_saldo_banka = 0;
  if (akt_saldo_bar_sonst is null ) then akt_saldo_bar_sonst = 0;
  if (akt_saldo_bara is null ) then akt_saldo_bara = 0;
  if (AKT_SALDO_UNBAR_O_BNR is null) then AKT_SALDO_UNBAR_O_BNR = 0;

  suspend;
end ^

ALTER PROCEDURE GET_FREIE_ZIMMER_LISTE (VONDATUM DATE,
BISDATUM DATE)
RETURNS (LNR_ZINR INTEGER)
AS 
declare variable MAXZI integer;
declare variable BELEGT integer;
begin
  /* Procedure Text */

  for
    select zimmstam.lnr, 1 as einz
      from zimmstam
      where zimmstam.TA_STATUS < 1000 and
          zimmstam.scheinz = 0 and
          zimmstam.vermietjn = 1

      into :LNR_ZINR , :MAXZI
   do
   begin
          :belegt = 0;
    
          select count(*)
             from  BELEGUNG
    
               inner join GASTKONT on (GASTKONT.LNR = BELEGUNG.LNR_GK and  GASTKONT.SHARE_NR=0)
    
                where
                belegung.lnr_zinr = :LNR_ZINR
                and (belegung.ta_status <1000)
                and
                      ((:vondatum >= BELEGUNG.ANREISE and :vondatum < BELEGUNG.ABREISE)
                      or
                       (:bisdatum >= BELEGUNG.ANREISE and :bisdatum < BELEGUNG.ABREISE)
                      or ((:vondatum < BELEGUNG.ANREISE and :bisdatum > BELEGUNG.ABREISE))
                       )

          

                into :BELEGT;
    
                :MAXZI = :MAXZI - :BELEGT;

          if (:maxzi>0) then suspend;
   end
    



end ^

ALTER PROCEDURE GET_FREIE_ZIMMER_LISTE_NEU (VONDATUM DATE,
BISDATUM DATE)
RETURNS (LNR_ZINR INTEGER,
ZINR TV10,
KATEGORIE TV10)
AS 
declare variable MAXZI integer;
declare variable BELEGT integer;
begin
  /* Procedure Text */

  for
    select zimmstam.lnr, 1 as einz, zimmstam.zinr, katestam.kategorie
      from zimmstam
         inner join katestam on (katestam.lnr = zimmstam.lnr_kate and coalesce(katestam.pseudo,0)=0)
      where zimmstam.TA_STATUS < 1000 and
          zimmstam.scheinz = 0 and
          zimmstam.vermietjn = 1

      into :LNR_ZINR , :MAXZI, :ZINR, :kategorie
   do
   if(:lnr_zinr > 0) then
   begin
          :belegt = 0;
    

          select count(*)
             from  BELEGUNG
    
               inner join GASTKONT on (GASTKONT.LNR = BELEGUNG.LNR_GK and  GASTKONT.SHARE_NR=0 )
    
                where
                (belegung.ta_status <1000)
                and belegung.lnr_zinr = :LNR_ZINR
                and  :vondatum < BELEGUNG.ABREISE
                and  :bisdatum > BELEGUNG.ANREISE



                into :BELEGT;

                :MAXZI = :MAXZI - :BELEGT;

          if (:maxzi>0) then suspend;
   end
    



end ^

ALTER PROCEDURE GET_FREIZIMMER_PRO_KATE (ANREISE DATE,
ABREISE DATE,
BUCH_STATUS INTEGER,
IMP_KATELNR INTEGER)
RETURNS (VON DATE,
BIS DATE,
LNR_ZINR INTEGER,
KATEGORIE VARCHAR(10) CHARACTER SET NONE,
ZINR VARCHAR(10) CHARACTER SET NONE,
PRL_LNR INTEGER,
MAND_NR INTEGER)
AS 
declare variable INT_TEMP integer;
begin
  /* Procedure Text */

  int_temp = -1;
  for
    select katestam.kategorie, zimmstam.lnr as lnr_zinr, zimmstam.zinr, zimmstam.preislist,
    zimmstam.mand_nr
       from katestam
         inner join zimmstam on (zimmstam.lnr_kate = katestam.lnr and zimmstam.ta_status <1000)
       where katestam.lnr >0 and katestam.pseudo = 0 and katestam.ta_status <1000 and (:IMP_KATELNR = 0 or katestam.lnr = :IMP_KATELNR)
       order by zimmstam.inet_id, zimmstam.zinr
       into :kategorie, :LNR_ZINR, :ZINR, :PRL_LNR, :MAND_NR
  DO
  BEGIN

    for
     select  count(*)
        from belegung
          left outer join gastkont on (gastkont.lnr = belegung.lnr_gk --and gastkont.buch_status <= :buch_status
          )


        where (belegung.lnr_zinr = :lnr_zinr) and (belegung.ta_status<1000)
        and gastkont.buch_status <= :buch_status
        and
        (
        (anreise>=:anreise and anreise<:abreise) or
        (abreise>:anreise and abreise<=:abreise) or
        (anreise<:anreise  and abreise>:abreise)
       )
       -- group by belegung.lnr_zinr

       into   :int_temp



     do
     if (:int_temp=0) then
     begin
       --saison holen

       von = :anreise;
       bis = :abreise;
       --int_saison = 0;


       suspend;
     end



   END

end ^

ALTER PROCEDURE GET_GAST_INFO_UMSATZ RETURNS (GASTNR INTEGER,
ANREDE VARCHAR(30) CHARACTER SET NONE,
TITEL VARCHAR(30) CHARACTER SET NONE,
NAME1 VARCHAR(60) CHARACTER SET NONE,
NAME2 VARCHAR(60) CHARACTER SET NONE,
NAMENZUS VARCHAR(60) CHARACTER SET NONE,
STRASSE VARCHAR(60) CHARACTER SET NONE,
LAND VARCHAR(10) CHARACTER SET NONE,
PLZ VARCHAR(10) CHARACTER SET NONE,
ORT VARCHAR(50) CHARACTER SET NONE,
TELE1 VARCHAR(30) CHARACTER SET NONE,
TELE2 VARCHAR(30) CHARACTER SET NONE,
TELE3 VARCHAR(30) CHARACTER SET NONE,
E_MAIL VARCHAR(100) CHARACTER SET NONE,
GESCHLECHT VARCHAR(1) CHARACTER SET NONE,
LOGISUMS NUMERIC(12, 2),
FBUMS NUMERIC(12, 2),
HEALTHUMS NUMERIC(12, 2),
SONSTUMS NUMERIC(12, 2),
DEBITORSUMME NUMERIC(12, 2),
OFF_DEBITORSUMME NUMERIC(12, 2),
