AS 
begin
  /* Procedure Text */


   for
    SELECT ADRESSEN.lnr as GASTNR, ADRESSEN.anrede, ADRESSEN.titel, ADRESSEN.name1,
       ADRESSEN.name2, ADRESSEN.namenzus,
       ADRESSEN.strasse, ADRESSEN.land, ADRESSEN.plz,
       ADRESSEN.ort, ADRESSEN.tele1, ADRESSEN.tele2, ADRESSEN.tele3,
       ADRESSEN.e_mail, ADRESSEN.geschlecht,
         gasthist.lnr_co , EXTRACT (YEAR from gasthist.bisdatum ) as ja


    FROM ADRESSEN
       inner join gasthist on (gasthist.adr_lnr = adressen.lnr and gasthist.ta_status<1000)

    WHERE ADRESSEN.ta_status<1000

       INTO   :"GASTNR", :"ANREDE", :"TITEL",:"NAME1",
           :"NAME2",:"NAMENZUS",
           :"STRASSE", :"LAND", :"PLZ",
           :"ORT", :"TELE1", :"TELE2", :"TELE3",
           :"E_MAIL", :"GESCHLECHT" , :"VORGANG", :"JAHR"




  do


  begin
    for
      select sum(fakt_erloese.betrag)
         from fakt_erloese
            inner join leiststa on (leiststa.lnr = fakt_erloese.lnr_leist)
            inner join warengru on (warengru.lnr = leiststa.wg and warengru.durchl = 0)
          where fakt_erloese.lnr_co = :vorgang and fakt_erloese.zahlungsart=9999

            into  :"LOGISUMS"

    do
    for
      select sum(fakt_erloese.betrag)
         from fakt_erloese
            inner join leiststa on (leiststa.lnr = fakt_erloese.lnr_leist)
            inner join warengru on (warengru.lnr = leiststa.wg and warengru.durchl = 1)
          where fakt_erloese.lnr_co = :vorgang and fakt_erloese.zahlungsart=9999

            into  :"FBUMS"


    do
    for
      select sum(fakt_erloese.betrag)
         from fakt_erloese
            inner join leiststa on (leiststa.lnr = fakt_erloese.lnr_leist)
            inner join warengru on (warengru.lnr = leiststa.wg and warengru.durchl = 2)
          where fakt_erloese.lnr_co = :vorgang and fakt_erloese.zahlungsart=9999

            into  :"HEALTHUMS"


    do
    for
      select sum(fakt_erloese.betrag)
         from fakt_erloese
            inner join leiststa on (leiststa.lnr = fakt_erloese.lnr_leist)
            inner join warengru on (warengru.lnr = leiststa.wg and warengru.durchl = 3)
          where fakt_erloese.lnr_co = :vorgang and fakt_erloese.zahlungsart=9999

            into  :"SONSTUMS"


    do
    for
        select sum(betrag)
    
     from zahlungen
        inner join devisen on (devisen.lnr = zahlungen.lnr_devi and devisen.zahlungsart = 2)
      where zahlungen.ta_status<1000
        and zahlungen.lnr_co = :vorgang

        INTO :"DEBITORSUMME"


    do
    
    for
        select sum(betrag) - sum(zahlungen.debi_bez_betr)
    
     from zahlungen
        inner join devisen on (devisen.lnr = zahlungen.lnr_devi and devisen.zahlungsart = 2)
      where zahlungen.ta_status<1000
        and zahlungen.lnr_co = :vorgang

        INTO :"OFF_DEBITORSUMME"


    do
    

    suspend;
  end

end ^

ALTER PROCEDURE GET_GKFIND_BUCHNR (BUCHNR INTEGER)
RETURNS (NAME1 VARCHAR(100) CHARACTER SET NONE,
NAME2 VARCHAR(100) CHARACTER SET NONE,
STRASSE VARCHAR(60) CHARACTER SET NONE,
LAND VARCHAR(10) CHARACTER SET NONE,
PLZ VARCHAR(10) CHARACTER SET NONE,
ORT VARCHAR(50) CHARACTER SET NONE,
VONAUFH DATE,
BISAUFH DATE,
GK_LNR INTEGER,
MAND_NR INTEGER,
TA_STATUS INTEGER,
ZINR VARCHAR(10) CHARACTER SET NONE,
KATEGORIE VARCHAR(20) CHARACTER SET NONE)
AS 
begin
  for
    SELECT A.NAME1, A.NAME2, A.STRASSE, A.LAND, A.PLZ, A.ORT,
           G.VONAUFH, G.BISAUFH, G.LNR, G.MAND_NR, G.TA_STATUS,
           Z.ZINR, K.KATEGORIE
     FROM GASTKONT G
     INNER JOIN ADRESSEN A ON (G.GASTNR_1 = A.LNR)
     INNER JOIN KATESTAM K ON (G.LNR_KATE = K.LNR)
     Left outer JOIN ZIMMSTAM Z ON (G.LNR_ZINR = Z.LNR)
     WHERE  g.lnr = :"BUCHNR" and
                     g.ta_status<100

        into   :"NAME1", :"NAME2", :"STRASSE", :"LAND", :"PLZ", :"ORT",
                 :"VONAUFH" ,  :"BISAUFH", :"GK_LNR", :"MAND_NR",  :"TA_STATUS",
                 :"ZINR",  :"KATEGORIE"

  do
  suspend;
end ^

ALTER PROCEDURE GET_GK_ADRESSE_EINF_RRO_LNR (GK_LNR INTEGER)
RETURNS (NAME1 VARCHAR(100) CHARACTER SET NONE,
GK_BEMERK VARCHAR(100) CHARACTER SET NONE)
AS 
