ALTER PROCEDURE GET_GK_ADRESSE_RRO_LNR (GK_LNR INTEGER)
RETURNS (GASTNR INTEGER,
NAME1 VARCHAR(100) CHARACTER SET NONE,
NAME2 VARCHAR(100) CHARACTER SET NONE,
STRASSE VARCHAR(60) CHARACTER SET NONE,
LAND VARCHAR(10) CHARACTER SET NONE,
PLZ VARCHAR(10) CHARACTER SET NONE,
ORT VARCHAR(50) CHARACTER SET NONE,
VONAUFH DATE,
BISAUFH DATE,
GK_BEMERK VARCHAR(100) CHARACTER SET NONE)
AS 
begin
  /* Procedure Text */
  for
  SELECT GASTKONT.GASTNR_1, ADRESSEN.NAME1, ADRESSEN.NAME2,
         ADRESSEN.STRASSE, ADRESSEN.LAND,ADRESSEN.PLZ,ADRESSEN.ORT,
         GASTKONT.VONAUFH, GASTKONT.BISAUFH,
         GASTKONT.BEMERK
  FROM GASTKONT
       inner join belegung on (gastkont.lnr = belegung.lnr_gk)
       INNER JOIN ADRESSEN ON (GASTKONT.GASTNR_1 = ADRESSEN.LNR)
       WHERE
       (
           (BELEGUNG.LNR = :"GK_LNR")
       )
       into :"GASTNR", :"NAME1", :"NAME2",:"STRASSE" ,:"LAND",  :"PLZ", :"ORT",

            :"VONAUFH", :"BISAUFH", :"GK_BEMERK"
  do
  suspend;
end ^

