ALTER PROCEDURE GET_GK_REBETRAG_HIST (LNR_GK INTEGER)
RETURNS (SUM_LEISTUNG FLOAT,
LNR INTEGER,
STSATZ NUMERIC(12, 2))
AS 
begin
  /* Procedure Text */
  LNR = LNR_GK;
  for
  select
      sum(fakt_erloese.betrag), steustam.stsatz
       from fakt_erloese
          inner join leiststa on (leiststa.lnr = fakt_erloese.lnr_leist and fakt_erloese.zahlungsart=9999)
          inner join steustam on (steustam.sts = leiststa.sts and steustam.ta_status<1000 and fakt_erloese.budat between steustam.von and steustam.bis)
        where fakt_erloese.belegnr = :lnr_gk
        and fakt_erloese.ta_status <1000
              group by steustam.stsatz
         into :sum_leistung,:stsatz
  do
  suspend;
end ^

