ALTER PROCEDURE GET_GK_REBETRAG_UMSATZ_PRO_GAST (LNR_GK INTEGER,
AUFPERS INTEGER)
RETURNS (SUM_LEISTUNG FLOAT)
AS 
BEGIN
  --LNR = LNR_GK;
  IF (:AUFPERS=-1) THEN

      SELECT SUM(gbetrag)
           FROM BUCHKONT
           LEFT OUTER JOIN leiststa ON (leiststa.lnr = buchkont.leist_lnr)
           LEFT OUTER JOIN warengru ON (warengru.wgnr = leiststa.wg AND warengru.ta_status <1000 AND warengru.durchl <4 )
           WHERE buchkont.gk_lnr = :LNR_GK
             AND buchkont.ta_status<1000
             INTO :sum_leistung;


  else
      SELECT SUM(gbetrag)
           FROM BUCHKONT
           LEFT OUTER JOIN leiststa ON (leiststa.lnr = buchkont.leist_lnr)
           LEFT OUTER JOIN warengru ON (warengru.wgnr = leiststa.wg AND warengru.ta_status <1000 AND warengru.durchl <4 )
           WHERE buchkont.gk_lnr = :LNR_GK
             AND buchkont.ta_status<1000 and buchkont.aufp = :AUFPERS
             INTO :sum_leistung;


  SUSPEND;
END ^

