ALTER PROCEDURE GET_GK_REBETRAG_VERK_NEU (GK_LNR INTEGER,
AUFPERS INTEGER,
VERK_NR INTEGER)
RETURNS (SUM_LEISTUNG FLOAT,
LNR INTEGER)
AS 
begin
    /* Procedure Text */
    LNR = GK_LNR;
    if (LNR = 0) then
        LNR = VERK_NR;

    for select sum(GBETRAG)
        from BUCHKONT
        inner join GASTKONT on GASTKONT.LNR = BUCHKONT.GK_LNR
        where ((:GK_LNR = 0 and
              GASTKONT.VERK_NR = :LNR) or (:VERK_NR = 0 and
              GASTKONT.LNR = :LNR)) and
              GASTKONT.TA_STATUS < 1000 and
              BUCHKONT.TA_STATUS < 1000 and
              (BUCHKONT.AUFP = :AUFPERS or :AUFPERS < 0)
        into :SUM_LEISTUNG
    do
        suspend;
end ^

