  /* Procedure Text */
  LNR = LNR_GK;
  for
  SELECT sum(buchkont.tagbetrag)
       FROM BUCHKONT where buchkont.gk_lnr = :LNR_GK
         and buchkont.ta_status<1000
         and :BISDAT between buchkont.von and buchkont.bis-1
         into :sum_leistung
  do
  suspend;
end ^

ALTER PROCEDURE GET_HOUSEKEEPING (DATUM_ABFR DATE)
RETURNS (ANREISE DATE,
ABREISE DATE,
ANREISEN INTEGER,
ABREISEN INTEGER,
LNR INTEGER,
BELEG_LNR INTEGER,
DATUM DATE,
WW INTEGER,
ZINR VARCHAR(10) CHARACTER SET NONE,
STOCK INTEGER,
PUTZ_LNR INTEGER,
PUTZNAME1 VARCHAR(60) CHARACTER SET NONE,
PUTZNAME2 VARCHAR(60) CHARACTER SET NONE,
BLEIBE INTEGER,
GASTNACHNAME VARCHAR(60) CHARACTER SET NONE,
TODO VARCHAR(100) CHARACTER SET NONE,
GASTVORNAME VARCHAR(60) CHARACTER SET NONE,
ZIM_LNR INTEGER)
AS 
BEGIN
  FOR

SELECT ANREISE,
         ABREISE,
         ANREISEN,
         ABREISEN,
         LNR,
         BELEG_LNR,
         DATUM,
         WW,
         ZINR,
         STOCK,
         PUTZ_LNR,
         PUTZNAME1,
         PUTZNAME2,
         GASTNACHNAME,
         GASTVORNAME,
         BLEIBE,
         CASE   WHEN BLEIBE = 1 AND ANREISEN = 0 AND ABREISEN = 0 AND WW = 0 then 'Bleibe'
                WHEN BLEIBE = 0 AND ANREISEN = 1 AND ABREISEN = 0 AND WW = 0 then 'Anreise'
                WHEN BLEIBE = 0 AND ANREISEN = 0 AND ABREISEN = 1 then 'Abreise'
                when WW =1          then 'Waesche'
                ELSE 'NICHTS'
         END
         AS TODO   ,
         ZIM_LNR

        FROM
        
        (
            select
                    belegung.anreise,
                    belegung.abreise,
                    case when belegung.anreise = :DATUM_ABFR then 1 else 0 end as anreisen,
                    case when (belegung.abreise <= :DATUM_ABFR and  housekeeping.datum = :DATUM_ABFR) then 1 else 0 end as abreisen,
                    housekeeping.lnr,
                    housekeeping.beleg_lnr,
                    :DATUM_ABFR as datum,      --// deakt. seit dem 20.06. - th jede buchung wird von anreise bis abreise als gleiches datum angezeigt.....
                    --housekeeping.datum as datum,
                    GET_WAESCHEWECHSEL.ww,
                    zimmstam.zinr,
                    zimmstam.stock,
                    housekeeping.putz_lnr_tag as putz_lnr,
                    COALESCE(adressen.name1, '') as Putzname1,
                    COALESCE(adressen.name2, '') as Putzname2,
                    COALESCE(a2.name1,'') as Gastnachname,
                    COALESCE(a2.name2,'') as Gastvorname,
                    case when belegung.anreise < :DATUM_ABFR and belegung.abreise > :datum_abfr then 1 else 0 end as bleibe,
                    zimmstam.lnr as ZIM_LNR

                
                from housekeeping
                
                   inner join belegung on (belegung.lnr_gk = housekeeping.gk_lnr)
                   inner join gastkont on (gastkont.lnr = housekeeping.gk_lnr)
                   inner join zimmstam on (zimmstam.lnr = gastkont.lnr_zinr)
                   inner join katestam on (zimmstam.lnr_kate = katestam.lnr)
                   inner join adressen on (adressen.lnr = housekeeping.putz_lnr_tag)
                   left outer join adressen a2 on (a2.lnr = gastkont.gastnr_1)   
                   LEFT JOIN GET_WAESCHEWECHSEL(belegung.anreise, belegung.abreise, :DATUM_ABFR)   on (1=1)
                
                 WHERE :DATUM_ABFR = housekeeping.datum
                 --:DATUM_ABFR between belegung.anreise and belegung.abreise
                 and belegung.ta_status < 1000
                 AND katestam.ta_status < 1000 AND katestam.pseudo = 0
                 --and :DATUM_ABFR = housekeeping.datum
    )

    INTO :ANREISE,
         :ABREISE,
         :ANREISEN,
         :ABREISEN,
         :LNR,
         :BELEG_LNR,
         :DATUM,
         :WW,
         :ZINR,
         :STOCK,
         :PUTZ_LNR,
         :PUTZNAME1,
         :PUTZNAME2,
         :GASTNACHNAME,
         :GASTVORNAME,
         :BLEIBE,
         :TODO,
         :ZIM_LNR

  DO
  BEGIN
    SUSPEND;
  END
END ^

