ALTER PROCEDURE GET_KATE_VAKANZ (ANREISE DATE,
ABREISE DATE,
BUCH_STATUS INTEGER)
RETURNS (VON TIMESTAMP,
BIS TIMESTAMP,
LNR_KATE INTEGER,
ANZ_ZI INTEGER,
INT_TEMP INTEGER,
KATEGORIE VARCHAR(10) CHARACTER SET NONE,
PRL_LNR INTEGER,
MAND_NR INTEGER)
AS 
declare variable INT_KATEANZ integer;
declare variable INT_KATELNR integer;
declare variable INT_SAISON integer;
begin
  /* Procedure Text */
  int_temp = 0;
  for
    select lnr, katestam.anz_kate ,katestam.kategorie, katestam.preislist, katestam.mand_nr
       from katestam where katestam.lnr >0 and katestam.pseudo = 0 and katestam.ta_status <1000
       order by katestam.sort_nr, katestam.kategorie
       into :int_katelnr, :anz_zi, :kategorie, :PRL_LNR, :MAND_NR
  DO
  BEGIN
    int_kateanz = anz_zi;
    int_temp = 0;

    for
     select  max(belegung.anz_zi)
        from belegung
          left outer join gastkont on (gastkont.lnr = belegung.lnr_gk --and gastkont.buch_status <= :buch_status
          )


        where (belegung.lnr_kate = :int_katelnr) and (belegung.ta_status<1000)
        and gastkont.buch_status <= :buch_status
        and
        (
        /*
        (anreise>=:anreise and anreise<=:abreise) or
        (abreise>=:anreise and abreise<=:abreise) or
        (anreise<:anreise  and abreise>:abreise)
        */
        (anreise>=:anreise and anreise<:abreise) or
        (abreise>:anreise and abreise<=:abreise) or
        (anreise<:anreise  and abreise>:abreise)
       )
        group by belegung.lnr_zinr

       into   :int_temp



     do

     int_kateanz = int_kateanz - int_temp;
     lnr_kate = int_katelnr;

     INT_TEMP = int_kateanz;

     if (anz_zi>0) then
     begin
      /* saison holen */

       von = :anreise;
       bis = :abreise;
       int_saison = 0;



     end

     suspend;

   END

end ^

ALTER PROCEDURE GET_KURT_ERW (MAND_NR INTEGER,
SELEVON DATE,
SELEBIS DATE)
RETURNS (VON DATE,
BIS DATE,
ERWBETR NUMERIC(12, 3),
LEISTLNR_ERW INTEGER,
KURZBEZ VARCHAR(10) CHARACTER SET NONE,
BEZEICHN VARCHAR(200) CHARACTER SET NONE,
STS INTEGER,
BETRAG NUMERIC(12, 3),
KONTONR VARCHAR(10) CHARACTER SET NONE,
BEMERKUNG VARCHAR(100) CHARACTER SET NONE,
OBJEKT_NR INTEGER)
AS 
begin
  /* Procedure Text */
  for

  SELECT KURTSTAM.VON, KURTSTAM.BIS, KURTSTAM.ERBETR, KURTSTAM.LEISTLNR_ERW,
         LEISTSTA.KURZBEZ, LEISTSTA.BEZEICHN,
         LEISTSTA.STS, LEISTSTA.BETRAG,
         LEISTSTA.KONTONR, LEISTSTA.BEMERKUNG,KURTSTAM.OBJEKT_LNR


   FROM KURTSTAM
   left outer JOIN LEISTSTA ON (KURTSTAM.LEISTLNR_ERW = LEISTSTA.LNR)

   where kurtstam.ta_status<1000 and kurtstam.mand_nr = :"MAND_NR"
         and
         (
           (kurtstam.von>=:"SELEVON" and kurtstam.von<:"SELEBIS")
           or
           (kurtstam.bis>=:"SELEVON"   and kurtstam.bis<=:"SELEBIS")
           or
           (kurtstam.von<:"SELEVON"  and kurtstam.bis>:"SELEBIS")

         )
          order by kurtstam.von

   into :"VON", :"BIS",:"ERWBETR",:"LEISTLNR_ERW", :"KURZBEZ", :"BEZEICHN", :"STS",
        :"BETRAG", :"KONTONR", :"BEMERKUNG", :"OBJEKT_NR"


  do
  suspend;
end ^

