ALTER PROCEDURE GET_LOGIUMS_BK_PRO_LNR_KATE (VON DATE,
LNR_KATE INTEGER)
RETURNS (LVON DATE,
LBIS DATE,
UMSATZ NUMERIC(12, 2))
AS 
begin
  /* Procedure Text */
  for
    select buchkont.von, buchkont.bis,  buchkont.gbetrag
     from buchkont
        inner join gastkont on (gastkont.lnr = buchkont.gk_lnr and  gastkont.ta_status<1000)
        inner join leiststa on (leiststa.lnr = buchkont.leist_lnr and leiststa.m_logi=0)
        where buchkont.ta_status <1000
          and buchkont.bis >= :von
                                and
        gastkont.lnr_kate= :lnr_kate
        into :lvon, :lbis, :umsatz



  do

  suspend;
end ^

ALTER PROCEDURE GET_LOGIUMS_BK_PRO_LNR_KATE_BA (VON DATE,
LNR_KATE INTEGER)
RETURNS (LVON DATE,
LBIS DATE,
UMSATZ NUMERIC(12, 2),
BELEGART INT0)
AS 
begin
  /* Procedure Text */
  for
    select buchkont.von, buchkont.bis,  buchkont.gbetrag,gastkont.belegungsart
     from buchkont
        inner join gastkont on (gastkont.lnr = buchkont.gk_lnr and  gastkont.ta_status<1000)
        inner join leiststa on (leiststa.lnr = buchkont.leist_lnr)-- and leiststa.m_logi=0)
        inner join warengru on (warengru.lnr = leiststa.wg and warengru.durchl <4)
        where buchkont.ta_status <1000
          and buchkont.bis >= :von
                                and
        gastkont.lnr_kate= :lnr_kate
        into :lvon, :lbis, :umsatz, :belegart



  do

  suspend;
end ^

ALTER PROCEDURE GET_LOGIUMS_BK_PRO_ZILNR (VON DATE,
LNR_ZINR INTEGER)
RETURNS (LVON DATE,
LBIS DATE,
UMSATZ NUMERIC(12, 2))
AS 
begin
  /* Procedure Text */
  for
    select buchkont.von, buchkont.bis,  buchkont.gbetrag
     from buchkont
        inner join gastkont on (gastkont.lnr = buchkont.gk_lnr and  gastkont.ta_status<1000 and gastkont.belegungsart <=1)
        inner join leiststa on (leiststa.lnr = buchkont.leist_lnr)
        -- and leiststa.m_logi=0)
        left outer join warengru on (leiststa.wg = warengru.lnr and leiststa.mand_nr = warengru.mand_nr)
        where buchkont.ta_status <1000 and (WARENGRU.DURCHL=0)
          and buchkont.bis >= :von
                                and
        gastkont.lnr_zinr= :lnr_zinr
        into :lvon, :lbis, :umsatz



  do

  suspend;
end ^

ALTER PROCEDURE GET_LOGIUMS_BK_PRO_ZILNR_PRO_MO (VON DATE,
ZILNR INTEGER)
RETURNS (JAHR SMALLINT,
MONAT SMALLINT,
MONATSUMSATZ NUMERIC(18, 2))
AS 
BEGIN
  FOR
    SELECT jahr, monat, sum(umsatz) as monatsumsatz
        FROM
        (
            select
            extract(month from get_logiums_bk_pro_zilnr.lvon)   as monat
            , extract(year from get_logiums_bk_pro_zilnr.lvon)  as jahr
            , get_logiums_bk_pro_zilnr.umsatz
            from get_logiums_bk_pro_zilnr(:VON, :ZILNR)
            where
            extract(month from get_logiums_bk_pro_zilnr.lvon)
            = extract(month from get_logiums_bk_pro_zilnr.lbis)
            AND
             extract(year from get_logiums_bk_pro_zilnr.lvon)
           = extract(year from get_logiums_bk_pro_zilnr.lbis)
        )
        as z
        group by  jahr, monat
        order by  jahr, monat
    INTO :JAHR,
         :MONAT,
         :MONATSUMSATZ
  DO
  BEGIN
    SUSPEND;
  END
END ^

ALTER PROCEDURE GET_OFFEN_ZAHLBETRAG (BELEGNR INTEGER)
RETURNS (OFFEN_BETRAG NUMERIC(12, 3))
AS 
DECLARE VARIABLE SUM_LEISTUNG NUMERIC(12,3);
DECLARE VARIABLE SUM_ZAHLUNG NUMERIC(12,3);
begin
  /* Procedure Text */
  sum_leistung = 0;
  sum_zahlung = 0;
  for
     SELECT sum(gbetrag)
       FROM BUCHKONT where buchkont.gk_lnr = :belegnr
         and buchkont.ta_status<1000
         into :sum_leistung

  do
  for

     select sum(betrag)
       from zahlungen where zahlungen.lnr_gk = :belegnr and
            zahlungen.ta_status<1000

          into :sum_zahlung
  do
  if (sum_zahlung is Null ) then  OFFEN_BETRAG = sum_leistung;
     else OFFEN_BETRAG = sum_leistung - sum_zahlung;


  suspend;
end ^

ALTER PROCEDURE GET_PARTY_ANZAHL (GASTNR INTEGER)
RETURNS (ANZAHL INTEGER)
AS 
begin
  /* Procedure Text */
  begin
  select
  count(*) as anzahl
     from gastkont

      where ((gastkont.gastnr_1 = :GASTNR) or (gastkont.gastnr_2= :GASTNR)
       or ((gastkont.gastnr_3 = :GASTNR) )  )
       and gastkont.party_nr>0
       and gastkont.ta_status <1000
       into :ANZAHL;
  end
  suspend;
end ^

ALTER PROCEDURE GET_PLAN_VON_BIS (SELEVON DATE,
SELEBIS DATE)
RETURNS (ANREISE DATE,
ABREISE DATE,
LNR_ZINR INTEGER,
LNR INTEGER,
MAND_NR INTEGER,
ZINR VARCHAR(10) CHARACTER SET NONE,
KATE_LNR INTEGER,
BEZEICHN VARCHAR(50) CHARACTER SET NONE,
OBJ_LNR INTEGER,
BETTZAHL INTEGER,
ZIMMERART INTEGER,
GARAGE INTEGER,
HAUSTIER INTEGER,
RAUCHER INTEGER,
KATEGORIE VARCHAR(20) CHARACTER SET NONE,
BELEG_TA_STATUS INTEGER,
TO_OPERATOR INTEGER,
VERMIETJN SMALLINT,
MANDZINR INTEGER)
AS 
begin
  /* Procedure Text */
  for
   SELECT BELEGUNG.ANREISE, BELEGUNG.ABREISE, zimmstam.lnr, belegung.lnr,zimmstam.mand_nr,
          ZIMMSTAM.ZINR, ZIMMSTAM.lnr_kate, ZIMMSTAM.BEZEICHN, ZIMMSTAM.objekt_nr, ZIMMSTAM.bettzahl,
          ZIMMSTAM.zimmerart, ZIMMSTAM.garage, ZIMMSTAM.haustier,ZIMMSTAM.raucher, ZIMMSTAM.to_operator,
          katestam.kategorie,belegung.ta_status,ZIMMSTAM.vermietjn,ZIMMSTAM.mand_nr

     FROM zimmstam
       left OUTER JOIN belegung ON (zimmstam.lnr = BELEGUNG.LNR_ZINR )
       inner JOIN katestam ON (zimmstam.lnr_kate = katestam.LNR )

   WHERE
      ((belegung.anreise>= :SELEVON and belegung.anreise<=:SELEBIS) or
       (belegung.abreise>= :SELEVON and belegung.abreise<=:SELEBIS) or
       (belegung.anreise<= :SELEVON and belegung.abreise>=:SELEBIS) or
       (belegung.abreise<= :SELEVON) or
       (belegung.abreise>= :SELEBIS)

       or (belegung.anreise is null))

      and
      (ZIMMSTAM.TA_STATUS < 1000)

   into :"ANREISE", :"ABREISE", :"LNR_ZINR", :"LNR",:"MAND_NR",
        :"ZINR",:"KATE_LNR", :"BEZEICHN",:"OBJ_LNR", :"BETTZAHL",
        :"ZIMMERART", :"GARAGE", :"HAUSTIER", :"RAUCHER", :"TO_OPERATOR",
        :"KATEGORIE", :"BELEG_TA_STATUS", :"VERMIETJN", :"MANDZINR"


  do
  suspend;
end ^

ALTER PROCEDURE GET_PREISLIST_P2020 (INP_VONDATUM DATE,
INP_BISDATUM DATE,
INP_PREISLIST_LNR INTEGER,
INP_MATCHC VARCHAR(20) CHARACTER SET NONE,
INP_PR_CODE INTEGER,
INP_ALTERSKREIS INTEGER,
INP_PERSZAHL INTEGER,
INP_PREISLISTONLINE INTEGER)
RETURNS (MATCHC VARCHAR(255) CHARACTER SET NONE,
BEZEICHNUNG VARCHAR(255) CHARACTER SET NONE,
TAGBETRAG NUMERIC(12, 4),
DATUM DATE,
TEMPBETRAG NUMERIC(12, 4),
MIN_TAGE INTEGER,
OUT_PAUSCHALE INTEGER,
OUT_ZIMMERPREIS INTEGER,
OUT_PREISLIST_LNR INTEGER,
OUT_DUMMY INTEGER,
DIFF_VOLLZAHLER INTEGER)
AS 
declare variable TEMP_LNR integer;
declare variable SPERRE integer;
declare variable TEMP_I date;
declare variable PRL_LNR integer;
declare variable BETRAG_VERERBUNG numeric(12,2) = 0;
declare variable BETRAG decimal(12,4) = 0;
declare variable BETRAG_PERS integer;
declare variable ZIMMERPREIS integer;
declare variable PAUSCHAL integer;
declare variable PAUFSCHLAG1 numeric(12,2) = 0;
declare variable PAUFSCHLAG2 numeric(12,2) = 0;
declare variable PAUFSCHLAG3 numeric(12,2) = 0;
declare variable PAUFSCHLAG4 numeric(12,2) = 0;
declare variable PAUFSCHLAG5 numeric(12,2) = 0;
declare variable PAUFSCHLAG6 numeric(12,2) = 0;
declare variable ALTERSKREIS integer;
declare variable MIN_VOLLZAHLER integer;
declare variable EAUFSCHLAG_OK integer;
declare variable LAUFI integer;
declare variable AUFTAGE integer;
declare variable TEMPDUMMY integer;
declare variable KATE_ANZ_BETTEN integer;
declare variable EZZUSCHLAG numeric(12,2) = 0;
declare variable SAVE_BETRAG decimal(12,4) = 0;
declare variable UTAG1 integer;
declare variable UTAG2 integer;
declare variable UTAG3 integer;
declare variable UBETRAG1 numeric(12,2) = 0;
declare variable UBETRAG2 numeric(12,2) = 0;
declare variable UBETRAG3 numeric(12,2) = 0;
declare variable SAVE_PAX integer;
declare variable UBETRAG numeric(12,2) = 0;
declare variable NULL_BETRAG_ZEIGEN integer;
declare variable TEMP_ALTERSKREIS integer;
begin
    /* Procedure Text */
    :AUFTAGE = :INP_BISDATUM - :INP_VONDATUM;
    :OUT_DUMMY = 0;
    :SPERRE = 0;
    :SAVE_PAX = :INP_PERSZAHL;
    -- Alterskreis 9999, wenn Aufruf von Preisansicht => Webtemplate wird nicht beachtet
    :TEMP_ALTERSKREIS = :INP_ALTERSKREIS;
    if (:INP_ALTERSKREIS = 9999) then
        :INP_ALTERSKREIS = 0;

    if (INP_PREISLISTONLINE = 1) then
    begin
        select count(SPERRZEIT.LNR)
        from SPERRZEIT
        where ((:INP_VONDATUM between SPERRZEIT.VONDATUM and SPERRZEIT.BISDATUM) or (:INP_BISDATUM between SPERRZEIT.VONDATUM and SPERRZEIT.BISDATUM) or (:INP_VONDATUM < SPERRZEIT.VONDATUM and
              :INP_BISDATUM > SPERRZEIT.BISDATUM)) and
              SPERRZEIT.TA_STATUS < 1000 and
              SPERRZEIT.OPTISCHE_SPERRE_WEBMX = 0 and
              SPERRZEIT.PROVIDER_NR = 0
        into :SPERRE;

        select first 1 PARAMETE_ONL_BUCH.NULL_BETRAG_ZEIGEN
        from PARAMETE_ONL_BUCH
        order by LNR
        into :NULL_BETRAG_ZEIGEN;
    end

    if (:SPERRE = 0) then
    begin
        for select PREISLIST.MATCHC

            from PREISLIST
            inner join SAISSTAM on (PREISLIST.SAISON = SAISSTAM.SAISON and
                  :INP_VONDATUM between SAISSTAM.VON and SAISSTAM.BIS + 1 and
                  SAISSTAM.TA_STATUS < 1000 and
                  (:INP_PR_CODE = 0 or PREISLIST.PRCODE_LNR = SAISSTAM.PRCODE))

            where (:INP_PREISLISTONLINE = 0 or (:INP_PREISLISTONLINE = PREISLIST.ONLINE_BUCHBAR)) and
                  PREISLIST.TA_STATUS < 1000 and
                  PREISLIST.P_AB_2020 = 1 and
                  PREISLIST.ALTERSKREIS = :INP_ALTERSKREIS and
                  ((PREISLIST.PREISLIST_LNR = :INP_PREISLIST_LNR) or (PREISLIST.PREISLIST_LNR = 9999)) and
                  (:INP_PR_CODE = 0 or (PREISLIST.PRCODE_LNR = :INP_PR_CODE)) and
                  (:INP_MATCHC = '' or (PREISLIST.MATCHC = :INP_MATCHC)) and
                  ((PREISLIST.MIN_TAGE_WEB is null) or (PREISLIST.MIN_TAGE_WEB = 0) or (:AUFTAGE >= PREISLIST.MIN_TAGE_WEB)) and
                  ((PREISLIST.MAX_TAGE_WEB is null) or (PREISLIST.MAX_TAGE_WEB = 0) or (:AUFTAGE <= PREISLIST.MAX_TAGE_WEB))
            group by PREISLIST.MATCHC
            into :INP_MATCHC
        do
        begin
            :SAVE_BETRAG = 0.00;
            TEMP_I = INP_VONDATUM;

            while (TEMP_I < INP_BISDATUM) do
            begin
                for select PREISLIST.LNR as PRL_LNR, PREISLIST.MATCHC, PREISLIST.BEZEICHUNG,
                           coalesce(PREISLIST_VERERB.AUFSCHLAG_ERW, 0) as AUFSCHLAG_ERW, PREISLIST.BETRAG,

                           PREISLIST.BETRAG_PERS, PREISLIST.ZIMMERPREIS, PREISLIST.PAUSCHALE, PREISLIST.PAUFSCHLAG1, PREISLIST.PAUFSCHLAG2,
                           PREISLIST.PAUFSCHLAG3, PREISLIST.PAUFSCHLAG4, PREISLIST.PAUFSCHLAG5, PREISLIST.PAUFSCHLAG6, PREISLIST.ALTERSKREIS,
                           PREISLIST.MIN_VOLLZAHLER, PREISLIST.EAUFSCHLAG_OK, PREISLIST.MIN_TAGE_WEB, PREISLIST.UTAG1, PREISLIST.UBETRAG1,
                           PREISLIST.UTAG2, PREISLIST.UBETRAG2, PREISLIST.UTAG3, PREISLIST.UBETRAG3,
                           (select first 1 KATESTAM.ANZ_BETTEN
                            from KATESTAM
                            where KATESTAM.PREISLIST = PREISLIST.PREISLIST_LNR and
                                  KATESTAM.TA_STATUS < 1000), coalesce(PREISLIST.EZZUSCHLAG, 0) as EZZUSCHLAG, PREISLIST.TEMPLATE_LNR

                    from PREISLIST
                    inner join SAISSTAM on (PREISLIST.SAISON = SAISSTAM.SAISON and
                          :TEMP_I >= SAISSTAM.VON and
                          :TEMP_I < SAISSTAM.BIS + 1 and
                          SAISSTAM.TA_STATUS < 1000 and
                          (:INP_PR_CODE = 0 or PREISLIST.PRCODE_LNR = SAISSTAM.PRCODE))
                    left outer join PREISLIST_VERERB on (PREISLIST_VERERB.PREISLIST_LNR = PREISLIST.PREISLIST_LNR and
                          PREISLIST_VERERB.F_DATUM = :TEMP_I and
                          PREISLIST_VERERB.MATCHC = PREISLIST.MATCHC and
                          PREISLIST_VERERB.ALTERSKREIS = PREISLIST.ALTERSKREIS and
                          PREISLIST_VERERB.P_AB_2020 = 1)

                    where (:INP_PREISLISTONLINE = 0 or (:INP_PREISLISTONLINE = PREISLIST.ONLINE_BUCHBAR)) and
                          PREISLIST.TA_STATUS < 1000 and
                          PREISLIST.P_AB_2020 = 1 and
                          PREISLIST.ALTERSKREIS = :INP_ALTERSKREIS and
                          (iif((select count(PREISLIST.LNR)
                                from PREISLIST
                                inner join SAISSTAM on (PREISLIST.SAISON = SAISSTAM.SAISON and
                                      :INP_VONDATUM between SAISSTAM.VON and SAISSTAM.BIS + 1 and
                                      SAISSTAM.TA_STATUS < 1000 and
                                      (:INP_PR_CODE = 0 or PREISLIST.PRCODE_LNR = SAISSTAM.PRCODE))
                                where (:INP_PREISLISTONLINE = 0 or (:INP_PREISLISTONLINE = PREISLIST.ONLINE_BUCHBAR)) and
                                      PREISLIST.TA_STATUS < 1000 and
                                      PREISLIST.P_AB_2020 = 1 and
                                      PREISLIST.ALTERSKREIS = :INP_ALTERSKREIS and
                                      (PREISLIST.PREISLIST_LNR = :INP_PREISLIST_LNR) and
                                      (:INP_PR_CODE = 0 or (PREISLIST.PRCODE_LNR = :INP_PR_CODE)) and
                                      (:INP_MATCHC = '' or (PREISLIST.MATCHC = :INP_MATCHC)) and
                                      ((PREISLIST.MIN_TAGE_WEB is null) or (PREISLIST.MIN_TAGE_WEB = 0) or (:AUFTAGE >= PREISLIST.MIN_TAGE_WEB)) and
                                      ((PREISLIST.MAX_TAGE_WEB is null) or (PREISLIST.MAX_TAGE_WEB = 0) or (:AUFTAGE <= PREISLIST.MAX_TAGE_WEB))) > 0, (PREISLIST.PREISLIST_LNR = :INP_PREISLIST_LNR), (PREISLIST.PREISLIST_LNR = 9999))) and
                          (:INP_PR_CODE = 0 or (PREISLIST.PRCODE_LNR = :INP_PR_CODE)) and
                          (:INP_MATCHC = '' or (PREISLIST.MATCHC = :INP_MATCHC)) and
                          ((:INP_PERSZAHL >= PREISLIST.MIN_GESAMTPERS or PREISLIST.MIN_GESAMTPERS is null or PREISLIST.MIN_GESAMTPERS = 0) and
                          (:INP_PERSZAHL <= PREISLIST.MAX_ANZ_GESAMT or PREISLIST.MAX_ANZ_GESAMT is null or PREISLIST.MAX_ANZ_GESAMT = 0))

                    into :PRL_LNR, :MATCHC, :BEZEICHNUNG, :BETRAG_VERERBUNG, :BETRAG, :BETRAG_PERS, :ZIMMERPREIS, :PAUSCHAL, :PAUFSCHLAG1,
                         :PAUFSCHLAG2, :PAUFSCHLAG3, :PAUFSCHLAG4, :PAUFSCHLAG5, :PAUFSCHLAG6, :ALTERSKREIS, :MIN_VOLLZAHLER, :EAUFSCHLAG_OK,
                         :MIN_TAGE, :UTAG1, :UBETRAG1, :UTAG2, :UBETRAG2, :UTAG3, :UBETRAG3, :KATE_ANZ_BETTEN, :EZZUSCHLAG, --:SPERRE,
                         :TEMP_LNR
                do
                begin
                    :OUT_PAUSCHALE = :PAUSCHAL;
                    :OUT_ZIMMERPREIS = :ZIMMERPREIS;
                    :OUT_PREISLIST_LNR = :PRL_LNR;
                    :DIFF_VOLLZAHLER = 0;
                    :UBETRAG = 0;
                    :INP_PERSZAHL = :SAVE_PAX;

                    if (:TEMP_ALTERSKREIS = 9999) then
                        :SPERRE = 1;

                    if (:TEMP_ALTERSKREIS < 9999) then
                    begin

                        if (:TEMP_I = :INP_VONDATUM) then
                        begin
                            select OK
                            from GET_PREISTEMPLATE(:AUFTAGE, :TEMP_I, 0, :TEMP_LNR)
                            into :SPERRE;
                        end

                        if ((:SPERRE = 1) and
                            (:TEMP_I + 1 = :INP_BISDATUM)) then
                        begin
                            select OK
                            from GET_PREISTEMPLATE(:AUFTAGE, :INP_BISDATUM, 1, :TEMP_LNR)
                            into :SPERRE;
                        end

                    end

                    if (:SPERRE = 0) then
                        continue;

                    if (:INP_PERSZAHL < :MIN_VOLLZAHLER) then
                    begin
                        :DIFF_VOLLZAHLER = :MIN_VOLLZAHLER - INP_PERSZAHL;
                        :INP_PERSZAHL = :MIN_VOLLZAHLER;
                    end

                    -- Hier UBETRAG ?berpr?fen
                    if (:AUFTAGE <= UTAG1) then
                        :UBETRAG = UBETRAG1;
                    else
                    begin
                        if (:AUFTAGE <= UTAG2) then
                            :UBETRAG = UBETRAG2;
                        else
                        if (:AUFTAGE <= UTAG3) then
                            :UBETRAG = UBETRAG3;
                    end

                    if (:PAUSCHAL = 1) then
                    begin

                        :TAGBETRAG = :BETRAG;

                        if (:AUFTAGE != 0) then
                            :TAGBETRAG = :TAGBETRAG / :AUFTAGE;

                        :TAGBETRAG = :TAGBETRAG + :BETRAG_VERERBUNG;

                        if (:EAUFSCHLAG_OK = 1) then
                        begin
                            :LAUFI = 1;
                            while (:LAUFI <= :INP_PERSZAHL - :BETRAG_PERS) do
                            begin
                                if (:LAUFI = 1) then
                                    :TAGBETRAG = :TAGBETRAG + ((:PAUFSCHLAG1 / :AUFTAGE) + :BETRAG_VERERBUNG);
                                if (:LAUFI = 2) then
                                    :TAGBETRAG = :TAGBETRAG + ((:PAUFSCHLAG2 / :AUFTAGE) + :BETRAG_VERERBUNG);
                                if (:LAUFI = 3) then
                                    :TAGBETRAG = :TAGBETRAG + ((:PAUFSCHLAG3 / :AUFTAGE) + :BETRAG_VERERBUNG);
                                if (:LAUFI = 4) then
                                    :TAGBETRAG = :TAGBETRAG + ((:PAUFSCHLAG4 / :AUFTAGE) + :BETRAG_VERERBUNG);
                                if (:LAUFI = 5) then
                                    :TAGBETRAG = :TAGBETRAG + ((:PAUFSCHLAG5 / :AUFTAGE) + :BETRAG_VERERBUNG);
                                if (:LAUFI = 6) then
                                    :TAGBETRAG = :TAGBETRAG + ((:PAUFSCHLAG6 / :AUFTAGE) + :BETRAG_VERERBUNG);
                                :LAUFI = :LAUFI + 1;
                            end
                        end
                        else
                        begin
                            if (:ZIMMERPREIS = 1) then
                                :TAGBETRAG = (:TAGBETRAG + :BETRAG_VERERBUNG);
                            else
                                :TAGBETRAG = (:TAGBETRAG + :BETRAG_VERERBUNG) * :INP_PERSZAHL;
                        end

                        -- hier noch den unterpreis bei unterbelegung addieren ....
                        if (:INP_PERSZAHL = 1 and
                            :KATE_ANZ_BETTEN > :INP_PERSZAHL) then
                            :TAGBETRAG = :TAGBETRAG + (:EZZUSCHLAG / :AUFTAGE);
                    end
                    else
                    begin

                        if (:EAUFSCHLAG_OK = 1) then
                        begin
                            if (:ZIMMERPREIS = 1) then
                            begin
                                :TAGBETRAG = (:BETRAG + :BETRAG_VERERBUNG + UBETRAG);
                            end
                            else
                            begin
                                :TAGBETRAG = :BETRAG + :BETRAG_VERERBUNG + (UBETRAG * BETRAG_PERS);
                                if (BETRAG_PERS > INP_PERSZAHL) then
                                    :TAGBETRAG = :BETRAG + :BETRAG_VERERBUNG + (UBETRAG * INP_PERSZAHL);
                            end

                            -- Hier werden die Aufschl?ge f?r weitere Erwachsene ?ber betrag_pers hinaus dazu gerechnet
                            :LAUFI = 1;
                            while (:LAUFI <= :INP_PERSZAHL - :BETRAG_PERS) do
                            begin
                                if (:LAUFI = 1) then
                                    :TAGBETRAG = :TAGBETRAG + (:PAUFSCHLAG1 + :BETRAG_VERERBUNG + UBETRAG);
                                if (:LAUFI = 2) then
                                    :TAGBETRAG = :TAGBETRAG + (:PAUFSCHLAG2 + :BETRAG_VERERBUNG + UBETRAG);
                                if (:LAUFI = 3) then
                                    :TAGBETRAG = :TAGBETRAG + (:PAUFSCHLAG3 + :BETRAG_VERERBUNG + UBETRAG);
                                if (:LAUFI = 4) then
                                    :TAGBETRAG = :TAGBETRAG + (:PAUFSCHLAG4 + :BETRAG_VERERBUNG + UBETRAG);
                                if (:LAUFI = 5) then
                                    :TAGBETRAG = :TAGBETRAG + (:PAUFSCHLAG5 + :BETRAG_VERERBUNG + UBETRAG);
                                if (:LAUFI = 6) then
                                    :TAGBETRAG = :TAGBETRAG + (:PAUFSCHLAG6 + :BETRAG_VERERBUNG + UBETRAG);
                                :LAUFI = :LAUFI + 1;
                            end
                        end
                        else
                        begin /* hier wird die anzahl personen mal dem betrag gerechnet..... end */
                            if (:ZIMMERPREIS = 1) then
                                :TAGBETRAG = (:BETRAG + :BETRAG_VERERBUNG + :UBETRAG);
                            else
                                :TAGBETRAG = (:BETRAG + :BETRAG_VERERBUNG + :UBETRAG) * :INP_PERSZAHL;
                        end

                        -- hier noch den unterpreis bei unterbelegung addieren ....
                        if (:INP_PERSZAHL = 1 and
                            :KATE_ANZ_BETTEN > :INP_PERSZAHL) then
                            :TAGBETRAG = :TAGBETRAG + :EZZUSCHLAG;
                    end
                    :DATUM = :TEMP_I;
                    :TEMPBETRAG = :BETRAG_VERERBUNG;
                    if (:SAVE_BETRAG != TAGBETRAG) then
                        :OUT_DUMMY = :OUT_DUMMY + 1;

                    :SAVE_BETRAG = :TAGBETRAG;

                    if (:TAGBETRAG != 0 or :NULL_BETRAG_ZEIGEN > 1 or (:INP_ALTERSKREIS > 0 and
                        :NULL_BETRAG_ZEIGEN > 0)) then
                        suspend;
                end

                :TEMP_I = :TEMP_I + 1;

            end
        end
    end
end ^

ALTER PROCEDURE GET_PREISLIST_P2020_GESAMT (INP_VONDATUM DATE,
INP_BISDATUM DATE,
INP_PREISLIST_LNR INTEGER,
INP_MATCHC VARCHAR(20) CHARACTER SET NONE,
INP_PR_CODE INTEGER,
INP_ALTERSKREIS INTEGER,
INP_PERSZAHL INTEGER,
INP_PREISLISTONLINE INTEGER,
INP_LNR_KATE INTEGER,
INP_LNR_ZINR INTEGER)
RETURNS (MATCHC VARCHAR(20) CHARACTER SET NONE,
BEZEICHNUNG VARCHAR(255) CHARACTER SET NONE,
BETRAG NUMERIC(12, 4),
GESAMTBETRAG DECIMAL(12, 4),
PREISLIST_LNR INTEGER,
VONDATUM DATE,
BISDATUM DATE,
WOHER INTEGER,
OUT_PAUSCHALE INTEGER,
OUT_ZIMMERPREIS INTEGER,
OUT_GRUPPE INTEGER,
SAISVON DATE,
SAISBIS DATE,
DIFF_VOLLZAHLER INTEGER)
AS 
declare variable AUFTAGE integer;
declare variable AKT_PRL integer;
declare variable TEMPINT integer;
declare variable SAIS integer;
begin
    /* Procedure Text */
    :AUFTAGE = :INP_BISDATUM - :INP_VONDATUM;

    if (:AUFTAGE = 0) then
        :AUFTAGE = 1;
    :AKT_PRL = 0;
    :OUT_GRUPPE = 0;

    --if (erw!=0) then
    for select GET_PREISLIST_P2020.MATCHC, GET_PREISLIST_P2020.BEZEICHNUNG, GET_PREISLIST_P2020.TAGBETRAG, GET_PREISLIST_P2020.OUT_PREISLIST_LNR,
               min(GET_PREISLIST_P2020.DATUM) as VONDATUM, max(GET_PREISLIST_P2020.DATUM) + 1 as BISDATUM,
               sum(GET_PREISLIST_P2020.TAGBETRAG) as GESAMTBETRAG, sum(0), min(GET_PREISLIST_P2020.OUT_PAUSCHALE),
               min(GET_PREISLIST_P2020.OUT_ZIMMERPREIS), SAISSTAM.LNR, SAISSTAM.VON, SAISSTAM.BIS + 1, max(get_preislist_p2020.diff_vollzahler)
        from GET_PREISLIST_P2020(:INP_VONDATUM, :INP_BISDATUM, :INP_PREISLIST_LNR, :INP_MATCHC, :INP_PR_CODE, :INP_ALTERSKREIS, :INP_PERSZAHL, :INP_PREISLISTONLINE)
        inner join PREISLIST on PREISLIST.LNR = GET_PREISLIST_P2020.OUT_PREISLIST_LNR
        inner join SAISSTAM on (PREISLIST.SAISON = SAISSTAM.SAISON and
              GET_PREISLIST_P2020.DATUM >= SAISSTAM.VON and
              GET_PREISLIST_P2020.DATUM < SAISSTAM.BIS + 1 and
              SAISSTAM.TA_STATUS < 1000 and (:INP_PR_CODE = 0 or preislist.prcode_lnr = saisstam.prcode))
        group by GET_PREISLIST_P2020.MATCHC, GET_PREISLIST_P2020.BEZEICHNUNG, GET_PREISLIST_P2020.TAGBETRAG, GET_PREISLIST_P2020.OUT_PREISLIST_LNR, GET_PREISLIST_P2020.OUT_DUMMY, SAISSTAM.LNR, SAISSTAM.VON, SAISSTAM.BIS, get_preislist_p2020.diff_vollzahler
        order by MATCHC, VONDATUM, OUT_PREISLIST_LNR
            --, get_preislist_p2020.bezeichnung
        into :MATCHC, :BEZEICHNUNG, :BETRAG, :PREISLIST_LNR, :VONDATUM, :BISDATUM, :GESAMTBETRAG, :WOHER, :OUT_PAUSCHALE, :OUT_ZIMMERPREIS, :SAIS,
             :SAISVON, :SAISBIS, :DIFF_VOLLZAHLER

             --, pauschal, zimmerpreis
    do
    begin
        if (SAISVON < :INP_VONDATUM) then
            :SAISVON = INP_VONDATUM;
        if (SAISBIS > :INP_BISDATUM) then
            :SAISBIS = INP_BISDATUM;
        if (:SAISBIS = :SAISVON) then
            :SAISBIS = :SAISVON + 1;

        if (WOHER = 0 and
            AKT_PRL != PREISLIST_LNR) then
        begin
            AKT_PRL = PREISLIST_LNR;
            OUT_GRUPPE = OUT_GRUPPE + 1;
        end

        suspend;

    end
end ^

ALTER PROCEDURE GET_PREISLIST_P2020_MIT_LEIST (INP_VONDATUM DATE,
INP_BISDATUM DATE,
INP_PREISLIST_LNR INTEGER,
INP_MATCHC VARCHAR(20) CHARACTER SET NONE,
INP_PR_CODE INTEGER,
INP_ALTERSKREIS INTEGER,
INP_PERSZAHL INTEGER,
INP_PREISLISTONLINE INTEGER,
INP_OBJEKT INTEGER,
INP_LNR_KATE INTEGER,
INP_LNR_ZINR INTEGER,
INP_ERW INTEGER,
INP_JUG INTEGER,
INP_KIND INTEGER)
RETURNS (MATCHC VARCHAR(20) CHARACTER SET NONE,
BEZEICHNUNG VARCHAR(255) CHARACTER SET NONE,
BETRAG NUMERIC(12, 4),
GESAMTBETRAG DECIMAL(12, 4),
PREISLIST_LNR INTEGER,
VONDATUM DATE,
BISDATUM DATE,
WOHER INTEGER,
OUT_PAUSCHALE INTEGER,
OUT_ZIMMERPREIS INTEGER,
OUT_GRUPPE INTEGER,
DIFF_VOLLZAHLER INTEGER)
AS 
declare variable TEMPINT integer;
declare variable AUFTAGE integer;
declare variable SAVE_GRUPPE integer;
declare variable SAVE_PREISLIST integer;
declare variable TEMP_GRUPPE integer;
declare variable ANZAHL_DS integer;
declare variable LAUF_DS integer;
declare variable RECHEN_DUMMY integer;
declare variable AUFPERS integer;
declare variable TEMP_PROPERS integer;
declare variable KURT_EX integer;
declare variable BISSPLIT date;
declare variable VONSPLIT date;
declare variable DATUM_OK integer;
declare variable WOCHENTAG_OK integer;
declare variable TEMP_I date;
declare variable ADD_WD integer;
declare variable EINZELBETRAG decimal(15,2);
declare variable WT_SO integer;
declare variable WT_SA integer;
declare variable WT_FR integer;
declare variable WT_DO integer;
declare variable WT_MI integer;
declare variable WT_DI integer;
declare variable WT_MO integer;
declare variable WEB2_EXKL_LEIST_AUSWAHL integer;
declare variable SAISVON date;
declare variable SAISBIS date;
declare variable TEMP_MATCH varchar(20);
declare variable SAVE_PAX integer;
declare variable BUCH_SEG integer;
declare variable MAND_NR integer;
begin
    :TEMPINT = 0;
    :AUFTAGE = :INP_BISDATUM - :INP_VONDATUM;
    :SAVE_PAX = :INP_PERSZAHL;

    select first 1 coalesce(PARAMETE_WEB.WEB2_EXKL_LEIST_AUSWAHL, 0), PARAMETE_WEB.BUCH_SEG
    from PARAMETE_WEB
    order by LNR
    into :WEB2_EXKL_LEIST_AUSWAHL, :BUCH_SEG;

    select first 1 PARAMETE.KURTEXKL
    from PARAMETE
    order by LNR
    into :KURT_EX;

    if (:INP_ALTERSKREIS > 1) then
        AUFPERS = 3;
    else
        AUFPERS = :INP_ALTERSKREIS + 1;

    select count(*)
    from GET_PREISLIST_P2020_GESAMT(:INP_VONDATUM, :INP_BISDATUM, :INP_PREISLIST_LNR, :INP_MATCHC, :INP_PR_CODE, :INP_ALTERSKREIS, :INP_PERSZAHL, :INP_PREISLISTONLINE, :INP_LNR_KATE, :INP_LNR_ZINR)
    --inner join PREISLIST on (PREISLIST.LNR = GET_PREISLIST_P2020_GESAMT.PREISLIST_LNR)
    into :ANZAHL_DS;

    :LAUF_DS = 1;
    :TEMP_MATCH = '';

    for select GET_PREISLIST_P2020_GESAMT.*, PREISLIST.MAND_NR
               --, preislist.sort_nr
        from GET_PREISLIST_P2020_GESAMT(:INP_VONDATUM, :INP_BISDATUM, :INP_PREISLIST_LNR, :INP_MATCHC, :INP_PR_CODE, :INP_ALTERSKREIS, :INP_PERSZAHL, :INP_PREISLISTONLINE, :INP_LNR_KATE, :INP_LNR_ZINR)

        inner join PREISLIST on (PREISLIST.LNR = GET_PREISLIST_P2020_GESAMT.PREISLIST_LNR)
        order by GET_PREISLIST_P2020_GESAMT.OUT_GRUPPE, PREISLIST.SORT_NR, GET_PREISLIST_P2020_GESAMT.MATCHC, GET_PREISLIST_P2020_GESAMT.VONDATUM
        into :MATCHC, :BEZEICHNUNG, :BETRAG, :GESAMTBETRAG, :PREISLIST_LNR, :VONDATUM, :BISDATUM, :WOHER, :OUT_PAUSCHALE, :OUT_ZIMMERPREIS,
             :TEMP_GRUPPE, :SAISVON, :SAISBIS, :DIFF_VOLLZAHLER, :MAND_NR
    do
    begin

        if (:TEMPINT = 0) then
        begin
            --:TEMPINT = :OUT_GRUPPE;
            :SAVE_GRUPPE = :OUT_GRUPPE;
        end
        :SAVE_PREISLIST = :PREISLIST_LNR;

        :INP_PERSZAHL = :SAVE_PAX;
        if (DIFF_VOLLZAHLER > 0) then
            :INP_PERSZAHL = :INP_PERSZAHL + DIFF_VOLLZAHLER;

        if (:TEMP_MATCH != MATCHC) then
        begin
            :LAUF_DS = 1;
            :TEMP_MATCH = MATCHC;
        end

        :OUT_GRUPPE = TEMP_GRUPPE;
        suspend;

        if (TEMPINT != :OUT_GRUPPE) then -- or (:LAUF_DS = :ANZAHL_DS) or :LAUF_DS = 1) then
        begin
            :VONDATUM = SAISVON;
            :BISDATUM = SAISBIS;

            if (WEB2_EXKL_LEIST_AUSWAHL not in (1, 1002, 1003, 1004, 9999)) then
            begin

                -- aktiven leistung aus preisliste  == zusatzbetrag  = 1
                for select LEISTSTA.KURZBEZ, LEISTSTA.BEZEICHN, PREISSPLITTING.BETRAG * PREISSPLITTING.MENGE, PREISSPLITTING.LEISTUNG_LNR,
                           PREISSPLITTING.BETRAG * PREISSPLITTING.MENGE, PREISSPLITTING.EINMALIG, PREISSPLITTING.PROPERSON,
                           coalesce(PREISSPLITTING.WOCHENTAG_OK, 0), coalesce(PREISSPLITTING.DATUM_OK, 0), PREISSPLITTING.VONDATUM, PREISSPLITTING.BISDATUM,
                           PREISSPLITTING.WOCHENTAG_MO, PREISSPLITTING.WOCHENTAG_DI, PREISSPLITTING.WOCHENTAG_MI, PREISSPLITTING.WOCHENTAG_DO,
                           PREISSPLITTING.WOCHENTAG_FR, PREISSPLITTING.WOCHENTAG_SA, PREISSPLITTING.WOCHENTAG_SO
                    from PREISSPLITTING
                    inner join LEISTSTA on (LEISTSTA.LNR = PREISSPLITTING.LEISTUNG_LNR)
                    where PREISSPLITTING.PREISLIST_LNR = :SAVE_PREISLIST and
                          PREISSPLITTING.TA_STATUS < 1000 and
                          coalesce(PREISSPLITTING.PAS_AKTIV, 0) = 0 and
                          ((coalesce(PREISSPLITTING.ABTAGE, 0) < 1 and coalesce(PREISSPLITTING.BISTAGE, 0) < 1) or 
                          (:AUFTAGE >= coalesce(PREISSPLITTING.ABTAGE, 0) and :AUFTAGE <= coalesce(PREISSPLITTING.BISTAGE, 0))) and
                          (coalesce(PREISSPLITTING.DATUM_OK, 0) = 0 or PREISSPLITTING.VONDATUM is null or PREISSPLITTING.BISDATUM is null or 
                          (:VONDATUM between PREISSPLITTING.VONDATUM and PREISSPLITTING.BISDATUM)) and
                          (coalesce(PREISSPLITTING.AUFPERSON, 0) = 0 or PREISSPLITTING.AUFPERSON = :AUFPERS)

                    into :MATCHC, :BEZEICHNUNG, :BETRAG, :PREISLIST_LNR, :GESAMTBETRAG, :OUT_PAUSCHALE, :OUT_ZIMMERPREIS, :WOCHENTAG_OK, :DATUM_OK,
                         :VONSPLIT, :BISSPLIT, :WT_MO, :WT_DI, :WT_MI, :WT_DO, :WT_FR, :WT_SA, :WT_SO
                do
                begin
                    -- preis berechnen ...
                    :WOHER = 1;
                    --if (:DATUM_OK = 0 or :DATUM_OK is null or (:DATUM_OK = 1 and :VONDATUM between :VONSPLIT and :BISSPLIT)) then
                    --begin
                        if (:WOCHENTAG_OK = 0) then
                        begin
                            :TEMPINT = :BISDATUM - :VONDATUM; --:SAISBIS - :SAISVON; --:BISDATUM - :VONDATUM;
                            if (:OUT_PAUSCHALE = 0) then -- f?r tgliche berechnung
                                GESAMTBETRAG = GESAMTBETRAG * TEMPINT;
                            --if (OUT_PAUSCHALE = 0) then -- f?r pro person
                            --  GESAMTBETRAG = GESAMTBETRAG * :INP_PERSZAHL;
                            if (:OUT_ZIMMERPREIS = 1) then
                                GESAMTBETRAG = GESAMTBETRAG * :INP_PERSZAHL;
                            --:out_gruppe = :save_gruppe;
                            if (:OUT_PAUSCHALE = 0 or (:OUT_PAUSCHALE = 1 and
                                :LAUF_DS = 1)) then
                                suspend;
                        end
                        else
                        begin
                            :EINZELBETRAG = :GESAMTBETRAG;
                            :GESAMTBETRAG = 0;
                            TEMP_I = VONDATUM; --INP_VONDATUM;
                            while (TEMP_I < BISDATUM) do
                            --INP_BISDATUM) do
                            begin
                                :ADD_WD = extract(weekday from TEMP_I);
                                if ((:ADD_WD = 0 and
                                    :WT_SO = 1) or (:ADD_WD = 1 and
                                    :WT_MO = 1) or (:ADD_WD = 2 and
                                    :WT_DI = 1) or (:ADD_WD = 3 and
                                    :WT_MI = 1) or (:ADD_WD = 4 and
                                    :WT_DO = 1) or (:ADD_WD = 5 and
                                    :WT_FR = 1) or (:ADD_WD = 6 and
                                    :WT_SA = 1)) then
                                    :ADD_WD = 1;
                                else
                                    :ADD_WD = 0;

                                if (:ADD_WD > 0) then
                                begin
                                    if (:OUT_ZIMMERPREIS = 1) then
                                        GESAMTBETRAG = GESAMTBETRAG + EINZELBETRAG * :INP_PERSZAHL;
                                    else
                                        GESAMTBETRAG = GESAMTBETRAG + EINZELBETRAG;
                                end
                                :TEMP_I = :TEMP_I + 1;
                            end
                            if (GESAMTBETRAG != 0) then
                                suspend;
                        end
                    --end
                end
            end

            if (WEB2_EXKL_LEIST_AUSWAHL not in (4, 1004, 204, 304, 9999)) then
            begin
                -- aktive leistungen aus globalen leistungen = 2
                for select LEISTSTA.KURZBEZ, LEISTSTA.BEZEICHN, GLOB_LEISTUNG.BETRAG * GLOB_LEISTUNG.MENGE, GLOB_LEISTUNG.LEISTUNG_LNR,
                           GLOB_LEISTUNG.BETRAG * GLOB_LEISTUNG.MENGE, GLOB_LEISTUNG.EINMALIG, GLOB_LEISTUNG.PROPERSON
                    from GLOB_LEISTUNG
                    inner join LEISTSTA on (LEISTSTA.LNR = GLOB_LEISTUNG.LEISTUNG_LNR)

                    where GLOB_LEISTUNG.TA_STATUS < 1000 and
                          ((coalesce(GLOB_LEISTUNG.ABTAGE, 0) < 1 and coalesce(GLOB_LEISTUNG.BISTAGE, 0) < 1) or 
                          (:AUFTAGE >= coalesce(GLOB_LEISTUNG.ABTAGE, 0) and :AUFTAGE <= coalesce(GLOB_LEISTUNG.BISTAGE, 0))) and
                          (coalesce(GLOB_LEISTUNG.ZEITRAUM_VERWENDEN, 0) = 0 or GLOB_LEISTUNG.ANREISE_VON is null or GLOB_LEISTUNG.ANREISE_BIS is null or 
                          (:INP_VONDATUM between GLOB_LEISTUNG.ANREISE_VON and GLOB_LEISTUNG.ANREISE_BIS)) and
                          (coalesce(GLOB_LEISTUNG.PROPERSON, 0) = 1 or :AUFPERS < 2)

                    into :MATCHC, :BEZEICHNUNG, :BETRAG, :PREISLIST_LNR, :GESAMTBETRAG, :OUT_PAUSCHALE, :OUT_ZIMMERPREIS
                do
                begin
                    :WOHER = 2;
                    -- preis berechnen ...
                    :TEMPINT = :BISDATUM - :VONDATUM;
                    if (:OUT_PAUSCHALE = 0) then -- f?r tgliche berechnung
                        GESAMTBETRAG = GESAMTBETRAG * TEMPINT;
                    if (:OUT_ZIMMERPREIS = 1) then -- f?r pro person
                        GESAMTBETRAG = GESAMTBETRAG * :INP_PERSZAHL;
                    --:out_gruppe = :save_gruppe;
                    if (:OUT_PAUSCHALE = 0 or (:OUT_PAUSCHALE = 1 and
                        :LAUF_DS = 1)) then
                        suspend;
                end
            end

            if (WEB2_EXKL_LEIST_AUSWAHL not in (3, 1003, 203, 304, 9999)) then
            begin

                -- aktive Leistungen aus katestamm = 3
                if (:INP_LNR_KATE > 0) then
                begin
                    for select LEISTSTA.KURZBEZ, LEISTSTA.BEZEICHN, KATESTAM_LEISTUNG.BETRAG * KATESTAM_LEISTUNG.MENGE,
                               KATESTAM_LEISTUNG.LEISTUNG_LNR, KATESTAM_LEISTUNG.BETRAG * KATESTAM_LEISTUNG.MENGE, KATESTAM_LEISTUNG.EINMALIG,
                               KATESTAM_LEISTUNG.PROPERSON
                        from KATESTAM_LEISTUNG
                        inner join LEISTSTA on (LEISTSTA.LNR = KATESTAM_LEISTUNG.LEISTUNG_LNR)

                        where KATESTAM_LEISTUNG.KATE_LNR = :INP_LNR_KATE and
                              KATESTAM_LEISTUNG.TA_STATUS < 1000 and
                              ((coalesce(KATESTAM_LEISTUNG.ABTAGE, 0) < 1 and coalesce(KATESTAM_LEISTUNG.BISTAGE, 0) < 1) or 
                              (:AUFTAGE >= KATESTAM_LEISTUNG.ABTAGE and :AUFTAGE <= KATESTAM_LEISTUNG.BISTAGE)) and
                              (KATESTAM_LEISTUNG.VON is null or KATESTAM_LEISTUNG.BIS is null or (:INP_VONDATUM between KATESTAM_LEISTUNG.VON and KATESTAM_LEISTUNG.BIS)) and
                              (coalesce(KATESTAM_LEISTUNG.PROPERSON, 0) = 1 or :AUFPERS < 2) and
                              (coalesce(KATESTAM_LEISTUNG.AUFPERS, 0) = 0 or KATESTAM_LEISTUNG.AUFPERS = :AUFPERS)
                              
                        into :MATCHC, :BEZEICHNUNG, :BETRAG, :PREISLIST_LNR, :GESAMTBETRAG, :OUT_PAUSCHALE, :OUT_ZIMMERPREIS
                    do
                    begin
                        :WOHER = 3;
                        -- preis berechnen ...
                        :TEMPINT = :BISDATUM - :VONDATUM;
                        if (OUT_PAUSCHALE = 0) then -- f?r tgliche berechnung
                            GESAMTBETRAG = GESAMTBETRAG * TEMPINT;
                        if (OUT_ZIMMERPREIS = 1) then -- f?r pro person
                            GESAMTBETRAG = GESAMTBETRAG * :INP_PERSZAHL;
                        --:out_gruppe = :save_gruppe;
                        if (:OUT_PAUSCHALE = 0 or (:OUT_PAUSCHALE = 1 and
                            :LAUF_DS = 1)) then
                            suspend;
                    end
                end
            end

            if (WEB2_EXKL_LEIST_AUSWAHL not in (2, 1002, 203, 204, 9999)) then
            begin

                -- aktive Leistungen aus zimmerstamm = 4
                if (:INP_LNR_ZINR > 0) then
                begin
                    for select LEISTSTA.KURZBEZ, LEISTSTA.BEZEICHN, ZIMMLEIST.BETRAG * ZIMMLEIST.MENGE, ZIMMLEIST.LNR_LEISTSTA,
                               ZIMMLEIST.BETRAG * ZIMMLEIST.MENGE, ZIMMLEIST.EINMALIG, ZIMMLEIST.PROPERSON
                        from ZIMMLEIST
                        inner join LEISTSTA on (LEISTSTA.LNR = ZIMMLEIST.LNR_LEISTSTA)

                        where ZIMMLEIST.LNR_ZIMMSTAM = :INP_LNR_ZINR and
                              ZIMMLEIST.TA_STATUS < 1000 and coalesce(ZIMMLEIST.PASSIV, 0) = 0 and
                              ((coalesce(ZIMMLEIST.VONTAGE, 0) < 1 and coalesce(ZIMMLEIST.BISTAGE, 0) < 1) or (:AUFTAGE >= ZIMMLEIST.VONTAGE and :AUFTAGE <= ZIMMLEIST.BISTAGE)) and
                              (coalesce(zimmleist.buch_seg_verwenden, 0) = 0 or :BUCH_SEG in (Select GETINTEGERLIST.id from GETINTEGERLIST(ZIMMLEIST.buch_seg_str, ';'))) and
                              (coalesce(ZIMMLEIST.AUFPERSON, 0) = 0 or ZIMMLEIST.AUFPERSON = :AUFPERS)

                        into :MATCHC, :BEZEICHNUNG, :BETRAG, :PREISLIST_LNR, :GESAMTBETRAG, :OUT_PAUSCHALE, :OUT_ZIMMERPREIS
                    do
                    begin
                        :WOHER = 4;
                        -- preis berechnen ...
                        :TEMPINT = :BISDATUM - :VONDATUM;
                        if (OUT_PAUSCHALE = 0) then -- f?r tgliche berechnung
                            GESAMTBETRAG = GESAMTBETRAG * TEMPINT;
                        if (OUT_ZIMMERPREIS = 1) then -- f?r pro person
                            GESAMTBETRAG = GESAMTBETRAG * :INP_PERSZAHL;
                        --:out_gruppe = :save_gruppe;
                        if (:OUT_PAUSCHALE = 0 or (:OUT_PAUSCHALE = 1 and
                            :LAUF_DS = 1)) then
                            suspend;
                    end
                end
            end

            if (:KURT_EX = 1) then
            begin
                :OUT_ZIMMERPREIS = 1;
                -- kurtaxe mit abrufen --- kurtaxenbetrag = 10
                :BETRAG = 0;
                if (:INP_ALTERSKREIS = 0 and
                    :INP_ERW != 0) then
                begin
                    select GET_KURT_ERW.KURZBEZ, GET_KURT_ERW.BEZEICHN, GET_KURT_ERW.ERWBETR, GET_KURT_ERW.LEISTLNR_ERW --, get_kurt_erw.von, get_kurt_erw.bis
                    from GET_KURT_ERW(:MAND_NR, :INP_VONDATUM, :INP_BISDATUM)
                    where (GET_KURT_ERW.OBJEKT_NR = :INP_OBJEKT or GET_KURT_ERW.OBJEKT_NR = 0)

                    into :MATCHC, :BEZEICHNUNG, :BETRAG, :PREISLIST_LNR; --:VONDATUM, :BISDATUM;
                    if (:BETRAG > 0) then
                    begin
                        :BETRAG = :BETRAG * :INP_ERW;
                        --if (vondatum<:inp_vondatum) then  vondatum = inp_vondatum;
                        --if (bisdatum>:inp_bisdatum) then  bisdatum = inp_bisdatum;

                        :RECHEN_DUMMY = :BISDATUM - :VONDATUM;
                        :GESAMTBETRAG = :BETRAG * :RECHEN_DUMMY;
                        :WOHER = 10;
                        suspend;
                    end
                end

                if ((:INP_ALTERSKREIS = 0 and
                    :INP_JUG != 0 and
                    :DIFF_VOLLZAHLER > 0) or (:INP_ALTERSKREIS = 1 and
                    :INP_JUG != 0)) then
                begin
                    select GET_KURT_JUG.KURZBEZ, GET_KURT_JUG.BEZEICHN, GET_KURT_JUG.JUGBETR, GET_KURT_JUG.LEISTLNR_JUG --, get_kurt_jug.von, get_kurt_jug.bis
                    from GET_KURT_JUG(:MAND_NR, :INP_VONDATUM, :INP_BISDATUM)
                    where (GET_KURT_JUG.OBJEKT_NR = :INP_OBJEKT or GET_KURT_JUG.OBJEKT_NR = 0)
                    into :MATCHC, :BEZEICHNUNG, :BETRAG, :PREISLIST_LNR; --:VONDATUM, :BISDATUM;
                    if (:BETRAG > 0) then
                    begin
                        :RECHEN_DUMMY = :INP_JUG;
                        if (:INP_ALTERSKREIS = 0 and
                            :DIFF_VOLLZAHLER > 0 and
                            :DIFF_VOLLZAHLER < :INP_JUG) then
                            :RECHEN_DUMMY = :DIFF_VOLLZAHLER;
                        :BETRAG = :BETRAG * :RECHEN_DUMMY;
                        --if (vondatum<:inp_vondatum) then  vondatum = inp_vondatum;
                        --if (bisdatum>:inp_bisdatum) then  bisdatum = inp_bisdatum;

                        :RECHEN_DUMMY = :BISDATUM - :VONDATUM;
                        :GESAMTBETRAG = :BETRAG * :RECHEN_DUMMY;
                        :WOHER = 11;
                        suspend;
                    end
                end

                if ((:INP_ALTERSKREIS = 0 and
                    :INP_KIND != 0 and
                    (:DIFF_VOLLZAHLER - :INP_JUG) > 0) or (:INP_ALTERSKREIS > 1 and
                    :INP_KIND != 0)) then
                begin
                    select GET_KURT_KIND.KURZBEZ, GET_KURT_KIND.BEZEICHN, GET_KURT_KIND.KINDBETR, GET_KURT_KIND.LEISTLNR_KIND --, get_kurt_kind.von, get_kurt_kind.bis
                    from GET_KURT_KIND(:MAND_NR, :INP_VONDATUM, :INP_BISDATUM)
                    where (GET_KURT_KIND.OBJEKT_NR = :INP_OBJEKT or GET_KURT_KIND.OBJEKT_NR = 0)
                    into :MATCHC, :BEZEICHNUNG, :BETRAG, :PREISLIST_LNR; --:VONDATUM, :BISDATUM;
                    if (:BETRAG > 0) then
                    begin
                        :RECHEN_DUMMY = :INP_KIND;
                        if (:INP_ALTERSKREIS = 0 and
                            :DIFF_VOLLZAHLER - :INP_JUG > 0 and
                            :DIFF_VOLLZAHLER - INP_JUG < :INP_KIND) then
                            :RECHEN_DUMMY = :DIFF_VOLLZAHLER - :INP_JUG;
                        :BETRAG = :BETRAG * :RECHEN_DUMMY;

                        --if (vondatum<:inp_vondatum) then  vondatum = inp_vondatum;
                        --if (bisdatum>:inp_bisdatum) then  bisdatum = inp_bisdatum;

                        :RECHEN_DUMMY = :BISDATUM - :VONDATUM;
                        :GESAMTBETRAG = :BETRAG * :RECHEN_DUMMY;
                        :WOHER = 12;
                        suspend;
                    end
                end
            end

        end
        TEMPINT = :OUT_GRUPPE;
        :SAVE_GRUPPE = :TEMP_GRUPPE;
        --:SAVE_PREISLIST = :PREISLIST_LNR;
        :LAUF_DS = :LAUF_DS + 1;

        --suspend;
    end
end ^

ALTER PROCEDURE GET_PREISTEMPLATE (INP_TAGE INTEGER,
INP_DATUM DATE,
INP_MODE INTEGER,
LNR_TEMPLATE INTEGER)
RETURNS (OK INTEGER)
AS 
declare variable K_AN_SO integer;
declare variable K_AN_SA integer;
declare variable K_AN_FR integer;
declare variable K_AN_DO integer;
declare variable K_AN_MI integer;
declare variable K_AN_DI integer;
declare variable K_AN_MO integer;
declare variable ADD_WD integer;
declare variable MAX_TAGE_WEB integer;
declare variable MIN_TAGE_WEB integer;
declare variable LNR integer;
begin
    :OK = 1;
    if (INP_MODE = 0) then
    begin
        for select first 1 LNR, MIN_TAGE_WEB, MAX_TAGE_WEB, K_AN_MO, K_AN_DI, K_AN_MI, K_AN_DO, K_AN_FR, K_AN_SA, K_AN_SO
            from TEMPLATE_PREISOPTION
            where TEMPLATE_PREISOPTION.TEMPLATE_LNR = :LNR_TEMPLATE and
                  TEMPLATE_PREISOPTION.TA_STATUS < 1000 and
                  :INP_DATUM between TEMPLATE_PREISOPTION.VON and TEMPLATE_PREISOPTION.BIS
            order by TEMPLATE_PREISOPTION.VON desc
            into :LNR, :MIN_TAGE_WEB, :MAX_TAGE_WEB, :K_AN_MO, :K_AN_DI, :K_AN_MI, :K_AN_DO, :K_AN_FR, :K_AN_SA, :K_AN_SO
        do
        begin
            if ((:INP_TAGE < :MIN_TAGE_WEB and :MIN_TAGE_WEB > 0) or
            (:INP_TAGE > :MAX_TAGE_WEB and :MAX_TAGE_WEB > 0)) then
                :OK = 0;

            if (:OK = 1) then
            begin
                :ADD_WD = extract(weekday from :INP_DATUM);
                if ((:ADD_WD = 0 and
                    :K_AN_SO = 1) or (:ADD_WD = 1 and
                    :K_AN_MO = 1) or (:ADD_WD = 2 and
                    :K_AN_DI = 1) or (:ADD_WD = 3 and
                    :K_AN_MI = 1) or (:ADD_WD = 4 and
                    :K_AN_DO = 1) or (:ADD_WD = 5 and
                    :K_AN_FR = 1) or (:ADD_WD = 6 and
                    :K_AN_SA = 1)) then
                    :OK = 0;
            end
        end
    end

    if (:INP_MODE = 1) then
    begin
        for select first 1 LNR, K_AB_MO, K_AB_DI, K_AB_MI, K_AB_DO, K_AB_FR, K_AB_SA, K_AB_SO
            from TEMPLATE_PREISOPTION
            where TEMPLATE_PREISOPTION.TEMPLATE_LNR = :LNR_TEMPLATE and
                  TEMPLATE_PREISOPTION.TA_STATUS < 1000 and
                  :INP_DATUM between TEMPLATE_PREISOPTION.VON and TEMPLATE_PREISOPTION.BIS
            order by TEMPLATE_PREISOPTION.BIS asc
            into :LNR, :K_AN_MO, :K_AN_DI, :K_AN_MI, :K_AN_DO, :K_AN_FR, :K_AN_SA, :K_AN_SO
        do
        begin
            :ADD_WD = extract(weekday from :INP_DATUM);
            if ((:ADD_WD = 0 and
                :K_AN_SO = 1) or (:ADD_WD = 1 and
                :K_AN_MO = 1) or (:ADD_WD = 2 and
                :K_AN_DI = 1) or (:ADD_WD = 3 and
                :K_AN_MI = 1) or (:ADD_WD = 4 and
                :K_AN_DO = 1) or (:ADD_WD = 5 and
                :K_AN_FR = 1) or (:ADD_WD = 6 and
                :K_AN_SA = 1)) then
                :OK = 0;
        end
    end
    suspend;
end ^

ALTER PROCEDURE GET_STAT_BELEGUNG (SELEVONDATUM DATE,
SELEBISDATUM DATE)
RETURNS (ANZERW INTEGER,
ANZKINDER INTEGER,
ANZJUGEND INTEGER,
DATUM DATE,
ANZZI INTEGER)
AS 
begin
  /* Procedure Text */
  for
    select sum(anzerw) as erw, sum(anzkinder) as kinder, sum(anzjugend) as jugend,count(*) as anzzimmer, datum from stat_belegung
      where datum>=:"SELEVONDATUM" and datum<=:"SELEBISDATUM"
      group by datum
        into :"ANZERW",:"ANZKINDER",:"ANZJUGEND",:"ANZZI",:"DATUM"
  do
  suspend;
end ^

ALTER PROCEDURE GET_TISCHBELEGUNG (GASTKONTO INTEGER,
VON DATE,
BIS DATE)
RETURNS (VONBELG DATE,
BISBELG DATE,
SCHICHT INTEGER)
AS 
BEGIN 
    FOR
    SELECT
    tischbelegung.VONBELG,
    tischbelegung.BISBELG,
    tischbelegung.SCHICHT
FROM
    TISCHBELEGUNG
WHERE
    tischbelegung.GK_LNR = :GASTKONTO
    AND tischbelegung.ta_status < 1000
    AND (tischbelegung.VONBELG >= :VON
        AND tischbelegung.VONBELG <= :BIS)
    AND (tischbelegung.BISBELG >= :VON
        AND tischbelegung.BISBELG <= :BIS)
INTO    
            :"VONBELG",
            :"BISBELG",
            :"SCHICHT"
            DO
    suspend;
END ^

ALTER PROCEDURE GET_TODOLIST_LNR (LNR INTEGER,
BEREICH INTEGER)
RETURNS (MEMO VARCHAR(1024) CHARACTER SET NONE)
AS 
declare variable DATUM date;
begin
  for
      select TODOLIST.MEMO
      from TODOLIST
      left outer join GASTKONT on (GASTKONT.LNR = TODOLIST.GK_LNR)
      left outer join TODOLIST_ADD on (TODOLIST_ADD.TODO_LNR = TODOLIST.LNR)
      where TODOLIST.TA_STATUS < 1000 and
            TODOLIST.ERLED_STATUS < 1 and
            GASTKONT.TA_STATUS < 1000 and
            ((TODOLIST.LNR_BEREICH = :BEREICH) or (TODOLIST_ADD.LNR_BEREICH = :BEREICH) AND TODOLIST.LNR = :LNR)

            into :"MEMO"
  do
  suspend;
end ^

ALTER PROCEDURE GET_TODOLIST_VONBIS (VONDATUM DOMDATUM,
BISDATUM DOMDATUM,
BEREICH INTEGER,
GK_LNR INTEGER)
RETURNS (LNR INTEGER,
MEMO VARCHAR(1024) CHARACTER SET NONE)
AS 
begin
  for
      select distinct TODOLIST.lnr , TODOLIST.MEMO
      from TODOLIST
      left outer join TODOLIST_ADD on (TODOLIST_ADD.TODO_LNR = TODOLIST.LNR and todolist_add.ta_status <1000)
      where
      TODOLIST.gk_lnr = :gk_lnr and
      TODOLIST.ERLED_BISDATE between :VONDATUM and :BISDATUM and
            TODOLIST.TA_STATUS < 1000 and
            TODOLIST.ERLED_STATUS < 1 and

            ((todolist.lnr_bereich = :bereich) or (TODOLIST_ADD.LNR_BEREICH = :BEREICH and TODOLIST_ADD.lnr_bereich <> todolist.lnr_bereich))
            into :"LNR", :"MEMO"
  do
  suspend;
end ^

ALTER PROCEDURE GET_WAESCHEWECHSEL (ANREISE DATE,
ABREISE DATE,
ABFRAGE_DAT DATE)
RETURNS (WW INTEGER)
AS 
declare variable P_AUFTAGE integer;
declare variable P_AUFTAGE_ABFRAGE integer;
declare variable P_AUFTAGE_BIS_ABREISE integer;
declare variable P_ANZ_ABST_TAGE integer;
declare variable P_ANZ_ABST_MIN integer;
declare variable P_RUNDEN integer;
declare variable P_TMP float;
begin

ww = 0;

    P_AUFTAGE = DATEDIFF(day,:anreise,:abreise);
    P_AUFTAGE_ABFRAGE = DATEDIFF(day,:anreise,:ABFRAGE_DAT);  
    P_AUFTAGE_BIS_ABREISE = DATEDIFF(day,:ABFRAGE_DAT, :abreise);

    SELECT waeschewechsel.anz_abst_tage, waeschewechsel.anz_abst_min, waeschewechsel.runden
    FROM waeschewechsel
    WHERE :p_auftage between waeschewechsel.von_auftag and waeschewechsel.bis_auftag
    INTO    :p_anz_abst_tage, :p_anz_abst_min, :p_runden;

    /* cast notwendig, da sonst keine Kommastellen angezeigt werden */
    P_tmp = cast(p_auftage_abfrage as float) / cast(p_anz_abst_tage as float);

    /* runden noch mit einbeziehen */
    if (:p_runden > 0) then p_tmp = round(:p_tmp);

    if ((:p_tmp = round(:p_tmp)) AND (:p_auftage_bis_abreise >= :p_anz_abst_min)) then ww = 1;
    /* Abreisetag */
    if (P_AUFTAGE_BIS_ABREISE = 0) then ww = 1;
    suspend;
end ^

ALTER PROCEDURE GET_ZAHLBETRAG (LNR_GK INTEGER)
RETURNS (BEZAHLT FLOAT,
LNR INTEGER)
AS 
begin
  /* Procedure Text */
  LNR = LNR_GK;
  for
  select sum(betrag) as bezahlt from zahlungen where lnr_gk= :"LNR_GK"
     and ta_status<1000 and (zahlungen.gastauslage is null or (zahlungen.gastauslage=0))
  into :"BEZAHLT"
  do
  suspend;
end ^

ALTER PROCEDURE GET_ZAHLBETRAG_VK (LNR_GK INTEGER,
AUFPERS INTEGER,
VERK_NR INTEGER)
RETURNS (BEZAHLT FLOAT,
LNR INTEGER)
AS 
begin
    /* Procedure Text */
    :LNR = :LNR_GK;
    if (:LNR = 0) then
        :LNR = :VERK_NR;

    for select sum(BETRAG) as BEZAHLT
        from ZAHLUNGEN
        inner join GASTKONT on GASTKONT.LNR = ZAHLUNGEN.LNR_GK
        where ((:LNR_GK = 0 and GASTKONT.VERK_NR = :LNR) or (:VERK_NR = 0 and GASTKONT.LNR = :LNR)) and
              GASTKONT.TA_STATUS < 1000 and
              (ZAHLUNGEN.AUFPERS = :AUFPERS or :AUFPERS < 0) and
              ZAHLUNGEN.TA_STATUS < 1000 and
              (ZAHLUNGEN.GASTAUSLAGE is null or (ZAHLUNGEN.GASTAUSLAGE = 0))
        into :"BEZAHLT"
    do
        suspend;
end ^

ALTER PROCEDURE GET_ZIMMERBELEGUNG (DRUCK_NR INTEGER)
RETURNS (LNR INTEGER,
MAND_NR INTEGER,
LNR_KATE INTEGER,
LNR_ZINR INTEGER,
ANREISE DATE,
ABREISE DATE,
ANZ_ZI INTEGER,
TA_STATUS INTEGER,
STATUS INTEGER,
BEZEICHN VARCHAR(50) CHARACTER SET NONE,
ZINR VARCHAR(10) CHARACTER SET NONE,
NAME1 VARCHAR(60) CHARACTER SET NONE,
NAME2 VARCHAR(60) CHARACTER SET NONE,
ORT VARCHAR(50) CHARACTER SET NONE,
BU_ST_OPTION INTEGER,
BUCH_STATUS INTEGER,
PERSZAHL INTEGER,
GK_LNR INTEGER,
ANZKINDER INTEGER,
ANZJUGEND INTEGER,
BEMERK VARCHAR(100) CHARACTER SET NONE,
BELEGUNGSART INTEGER,
ZI_LNR INTEGER,
MIETE FLOAT,
TISCH VARCHAR(10) CHARACTER SET NONE)
AS 
begin
  /* Procedure Text */
  for
   SELECT BELEGUNG.LNR, BELEGUNG.MAND_NR, BELEGUNG.LNR_KATE, BELEGUNG.LNR_ZINR, BELEGUNG.ANREISE,
       BELEGUNG.ABREISE, BELEGUNG.ANZ_ZI, BELEGUNG.TA_STATUS, BELEGUNG.STATUS, ZIMMSTAM.BEZEICHN, 
       ZIMMSTAM.ZINR, ADRESSEN.NAME1, ADRESSEN.NAME2, ADRESSEN.ORT, GASTKONT.BU_ST_OPTION,GASTKONT.BUCH_STATUS, GASTKONT.PERSZAHL, GASTKONT.LNR,
       GASTKONT.ANZKINDER, GASTKONT.ANZJUGEND, GASTKONT.BEMERK, GASTKONT.BELEGUNGSART, GASTKONT.TISCH, ZIMMSTAM.LNR
    FROM TEMPDRUCKEN
       INNER JOIN BELEGUNG ON (TEMPDRUCKEN.TEMP_LNR = BELEGUNG.LNR_GK)
       INNER JOIN ZIMMSTAM ON (BELEGUNG.LNR_ZINR = ZIMMSTAM.LNR)
       INNER JOIN GASTKONT ON (BELEGUNG.LNR_GK = GASTKONT.LNR)
       INNER JOIN ADRESSEN ON (GASTKONT.GASTNR_1 = ADRESSEN.LNR)
    WHERE TEMPDRUCKEN.DRUCKNR = :DRUCK_NR
    INTO  :"LNR", :"MAND_NR", :"LNR_KATE", :"LNR_ZINR", :"ANREISE",
       :"ABREISE", :"ANZ_ZI", :"TA_STATUS", :"STATUS", :"BEZEICHN",
       :"ZINR", :"NAME1", :"NAME2", :"ORT", :"BU_ST_OPTION",:"BUCH_STATUS", :"PERSZAHL", :"GK_LNR",
       :"ANZKINDER", :"ANZJUGEND", :"BEMERK", :"BELEGUNGSART", :"TISCH",:"ZI_LNR"

   do
   if(:"GK_LNR" > 0) then
   begin
   for
       select sum_leistung from GET_GK_MIETBETRAG(:GK_LNR)
       into:"MIETE"

   do
   suspend;
   end
end ^

ALTER PROCEDURE GRUP_AUFENH_VERKNR (GASTNR_1 INTEGER)
RETURNS (VERK_NR INTEGER)
AS 
begin
  /* Procedure Text */
  for
  select verk_nr
     from gastkont
         where ta_status<1000 and gastnr_1 = :gastnr_1
           group by verk_nr

  into :"VERK_NR"
  do
  suspend;
end ^

ALTER PROCEDURE GRUP_BUCHUNG_PRO_VERKNR (VERK_NR INTEGER)
RETURNS (BELEGNR INTEGER,
VONDATUM DATE,
BISDATUM DATE,
ZINR VARCHAR(10) CHARACTER SET NONE,
ERW INTEGER,
JUG INTEGER,
KIND INTEGER,
KK INTEGER,
BEMERKUNG VARCHAR(100) CHARACTER SET NONE,
PM INTEGER)
AS 
begin
  /* Procedure Text */
  for
    select gastkont.lnr, gastkont.vonaufh, gastkont.bisaufh,
           gastkont.perszahl, gastkont.anzjugend, gastkont.anzkinder, gastkont.anzkleinkind,gastkont.bemerk, gastkont.pm ,

           zimmstam.zinr
      from gastkont
          left outer join zimmstam on (gastkont.lnr_zinr = zimmstam.lnr)
          where gastkont.verk_nr = :verk_nr and gastkont.ta_status<1000
            order by zimmstam.zinr

     into :"BELEGNR", :"VONDATUM", :"BISDATUM", :"ERW", :"JUG", :"KIND", :"KK", :"BEMERKUNG", :"PM",

     :"ZINR"
  do
  suspend;



end ^

ALTER PROCEDURE GRUP_BUCH_VERKNR RETURNS (VERK_NR INTEGER,
GASTNR_1 INTEGER)
AS 
begin
  /* Procedure Text */
  for
  select verk_nr, gastnr_1
     from gastkont
         where ta_status<1000
           group by verk_nr, gastnr_1

  into :"VERK_NR", :"GASTNR_1"

  do
  suspend;
end ^

ALTER PROCEDURE G_ADR_E (ADR_LNR INTEGER)
