ALTER PROCEDURE INS_STAT_UMSATZ (GK_LNR INTEGER,
LEIST_LNR INTEGER,
TAG_BETRAG NUMERIC(12, 3),
ME INTEGER,
TAGVON INTEGER,
TAGBIS INTEGER,
LNR_CO INTEGER,
TAG_ABS_LNR INTEGER,
LNR_BUCHKONT INTEGER,
MAX_BISTAG TYPE OF INT0,
KONTONR VARCHAR(6) CHARACTER SET NONE,
STEUERSATZ NUMERIC(12, 2) = 0)
AS 
declare variable TAG integer;
declare variable TEMPTAG type of INT0;
declare variable TGABS_ZWANG integer;
declare variable LIZ_TGABS_ZW integer;
begin
   tgabs_zwang = 0;

   select TABS_ZWANG
      from
         paramete where lnr = 1
           into :tgabs_zwang;


    select param_lizenz.LIZ_TGABS_ZWANG
      from
         param_lizenz where lnr = 1
           into :liz_tgabs_zw;

  /* Procedure Text */
  tag = :"TAGVON";
  while (tag<:"TAGBIS") do
  begin
    TEMPTAG = TAG;
    if (tgabs_zwang=1 and ((liz_tgabs_zw=0) or (liz_tgabs_zw is null)) ) then
    begin
       if (TEMPTAG > MAX_BISTAG)
         then TEMPTAG = MAX_BISTAG;
    end
    insert into stat_umsatz (GK_LNR,LEIST_LNR,TAG_BETRAG,ME,DATUM,LNR_CO,TAG_ABS_LNR,LNR_BUCHKONT,KONTONR,STEUERSATZ)
                    Values(:"GK_LNR",:"LEIST_LNR",:"TAG_BETRAG",:"ME",:TEMPTAG, :"LNR_CO",:"TAG_ABS_LNR",:"LNR_BUCHKONT", :"KONTONR", :"STEUERSATZ");
    tag = tag+1;
  end
  suspend;
end ^

ALTER PROCEDURE INS_STAT_UMSATZ_LIZ_TGABS (GK_LNR INTEGER,
LEIST_LNR INTEGER,
TAG_BETRAG NUMERIC(12, 3),
ME INTEGER,
TAGVON INTEGER,
TAGBIS INTEGER,
LNR_CO INTEGER,
TAG_ABS_LNR INTEGER,
LNR_BUCHKONT INTEGER,
MAX_BISTAG INTEGER,
TGABS_INT INTEGER,
TGABS_DATE DATE,
KONTONR VARCHAR(6) CHARACTER SET NONE,
STEUERSATZ NUMERIC(12, 2) = 0)
AS 
declare variable TAG integer;
declare variable TEMPTAG type of INT0;
begin

  /* Procedure Text */
  tag = :"TAGVON";
  while (tag<:"TAGBIS") do
  begin
    TEMPTAG = TAG;
    if (TEMPTAG > MAX_BISTAG)
         then TEMPTAG = MAX_BISTAG;

    if (temptag>TGABS_INT) then
       temptag = TGABS_INT;

    if (temptag<TGABS_INT) then
       temptag = TGABS_INT;



    insert into stat_umsatz (GK_LNR,LEIST_LNR,TAG_BETRAG,ME,DATUM,LNR_CO,TAG_ABS_LNR,LNR_BUCHKONT,LDATUM,KONTONR,STEUERSATZ)
                    Values(:"GK_LNR",:"LEIST_LNR",:"TAG_BETRAG",:"ME",:TEMPTAG, :"LNR_CO",:"TAG_ABS_LNR",:"LNR_BUCHKONT",:TGABS_DATE, :"KONTONR",:"STEUERSATZ");
    tag = tag+1;
  end
  suspend;
end ^

