ALTER PROCEDURE KOR_BU_ZEIT_ZIMMER (BUCHNR INTEGER,
ALTVON DATE,
ALTBIS DATE,
ALTZILFD INTEGER,
NEUVON DATE,
NEUBIS DATE,
NEUZILFD INTEGER,
USERID INTEGER,
MAND_NR INTEGER,
LNR_BELEGUNG INTEGER)
AS 
declare variable TEMPSTATUS integer;
declare variable LAUF integer;
declare variable TABS_ZWANG integer;
begin
  /* Procedure Text */
  tempstatus = 0;



  for
    select gastkont.ta_status from gastkont
             where gastkont.lnr = :"BUCHNR"
             into :tempstatus
  do

  if (tempstatus<100) then
  begin
     /*  belegung date korrigieren  */

     update belegung set belegung.anreise = :"NEUVON",
                         belegung.abreise = :"NEUBIS",
                         belegung.lnr_zinr = :"NEUZILFD",
                         belegung.kor_datum = current_date,
                         belegung.kor_zeit  = current_time,
                         belegung.kor_userid = :"USERID",
                         belegung.mand_nr = :"MAND_NR"

       where belegung.lnr= :"LNR_BELEGUNG";


     /*  leistungen korrigiern fixleistungen  */
     update buchkont set buchkont.von = :"NEUVON",
                         buchkont.bis = :"NEUBIS",
                         buchkont.kor_datum = current_date,
                         buchkont.kor_zeit = current_time,
                         buchkont.kor_userid = :"USERID"
        where buchkont.gk_lnr = :"BUCHNR" and
              buchkont.von = :"ALTVON" and
              buchkont.bis = :"ALTBIS"
              and buchkont.ta_status < 400;



     /*  leistungen korrigiern  anreisedatei gleich */
     update buchkont set buchkont.von = :"NEUVON",
                         buchkont.kor_datum = current_date,
                         buchkont.kor_zeit = current_time,
                         buchkont.kor_userid = :"USERID"


        where buchkont.gk_lnr = :"BUCHNR" and
              buchkont.von = :"ALTVON" and
              buchkont.bis <> :"ALTBIS" and
              (buchkont.bis - buchkont.von)>=1
              and buchkont.ta_status < 400;


     /*  leistungen korrigiern  abreisedatei gleich */
     update buchkont set buchkont.bis = :"NEUBIS",
                         buchkont.kor_datum = current_date,
                         buchkont.kor_zeit  = current_time,
                         buchkont.kor_userid = :"USERID"

        where buchkont.gk_lnr = :"BUCHNR" and
              buchkont.bis = :"ALTBIS" and
              buchkont.von <> :"ALTVON" and
              (buchkont.bis - buchkont.von)>=1
              and buchkont.ta_status < 300;


     /*  leistungen korrigiern  leistung am nur anreise  */
     update buchkont set buchkont.von = :"NEUVON",
                         buchkont.bis = :"NEUVON",
                         buchkont.kor_datum = current_date,
                         buchkont.kor_zeit  = current_time,
                         buchkont.kor_userid = :"USERID"

        where buchkont.gk_lnr = :"BUCHNR" and
              buchkont.von = :"ALTVON" and
              buchkont.bis = :"ALTVON"
              and buchkont.ta_status < 300;



      /*  leistungen korrigiern  leistung am nur abreise  */
     update buchkont set buchkont.von = :"NEUBIS",
                         buchkont.bis = :"NEUBIS",
                         buchkont.kor_datum = current_date,
                         buchkont.kor_zeit  = current_time,
                         buchkont.kor_userid = :"USERID"

        where buchkont.gk_lnr = :"BUCHNR" and
              buchkont.von = :"ALTBIS" and
              buchkont.bis = :"ALTBIS"  and
              buchkont.erf_datum < buchkont.von and
              buchkont.ta_status < 400;



      /*    update leistung bei tagesabschlusszwang */

      select paramete.tabs_zwang  from paramete
          where lnr = 1
             into :TABS_ZWANG;

      if (tabs_zwang>0) then
      begin
         update buchkont set buchkont.von = :neuvon,
                             buchkont.bis = :neuvon + buchkont.tage

         where buchkont.gk_lnr = :"BUCHNR"
               and (buchkont.bis - buchkont.von)>=1
               and buchkont.ta_status =300
               and buchkont.von < :neuvon;

      end




      /* *********************************************** ende buchungskonto ************** */

      /* gastkont korrigieren */
      update gastkont set gastkont.lnr_zinr = :"NEUZILFD",
                          gastkont.vonaufh = :"NEUVON",
                          gastkont.bisaufh = :"NEUBIS",
                          gastkont.auftage = :"NEUBIS" - :"NEUVON",
                          gastkont.kor_datum = current_date,
                          gastkont.kor_zeit  = current_time,
                          gastkont.kor_userid = :"USERID",
                          gastkont.mand_nr = :"MAND_NR"
         where gastkont.lnr = :"BUCHNR" and
               gastkont.vonaufh = :"ALTVON" and
               gastkont.bisaufh = :"ALTBIS";

      lauf = -1;
      if (:neuzilfd>0) then
      begin
          for
            select zimmstam.lnr_kate from zimmstam where zimmstam.lnr = :"NEUZILFD"
                 into :lauf
    
          do
          if (lauf>0) then
          begin
             update gastkont set gastkont.lnr_kate = :lauf
                 where gastkont.lnr = :"BUCHNR";
    
             update belegung set belegung.lnr_kate = :lauf
                 where belegung.lnr= :"LNR_BELEGUNG";
    
          end
          for
             select count(*) from belegung
                where belegung.lnr_gk = :buchnr and belegung.ta_status<1000
                  into :lauf
          do
          if (lauf>1) then
          begin
             /* umzugsreservierung aktuelle kategorie in gk schreiben ..... */
             lauf = 0;
             for
                select zimmstam.lnr_kate
                  from zimmstam
                  where  zimmstam.lnr = :"NEUZILFD"
                  into :lauf
            do
            if (lauf>0) then
            begin
               update gastkont set gastkont.lnr_kate = :lauf
                  where gastkont.lnr = :buchnr;
            end
          end
      end
      /*  Update todolist ---- wenn ERLED_BISDATE = anreise oder abreisedatum ist ..... */

      update todolist set todolist.erled_bisdate = :"NEUVON"

        where todolist.gk_lnr = :"BUCHNR" and
              todolist.erled_bisdate = :"ALTVON"
              and todolist.ta_status < 400
              and todolist.erled_status !=1;

      update todolist set todolist.erled_bisdate = :"NEUBIS"

        where todolist.gk_lnr = :"BUCHNR" and
              todolist.erled_bisdate = :"ALTBIS"
              and todolist.ta_status < 400
              and todolist.erled_status !=1;



  end
 -- suspend;

end ^

ALTER PROCEDURE PRC_CHECKIN (GKNR INTEGER,
CISTATUS INTEGER)
RETURNS (RETWERT INTEGER)
AS 
DECLARE VARIABLE CI INTEGER;
begin
  /* Procedure Text */
  RETWERT = 9999;
  select buch_status,ci_status from gastkont where lnr=:"GKNR"
    into :RETWERT, :CI;


  if (RETWERT<100) then
  begin
    RETWERT = 9998;
    /*if (CI<=0) then*/
    begin
      update gastkont set ci_status = :CISTATUS where lnr=:"GKNR";
      RETWERT = 0;
    end
  end


end ^

