ALTER PROCEDURE PROC_ANZ_NAECHTE_PLUS_ZI (JAHR INTEGER)
RETURNS (LNR INTEGER,
ZINR VARCHAR(10) CHARACTER SET NONE,
MAND_NR INTEGER,
STOCK INTEGER,
BETTZAHL INTEGER,
TA_STATUS INTEGER,
LNR_KATE INTEGER,
OBJEKT_NR INTEGER,
KATEGORIE VARCHAR(10) CHARACTER SET NONE,
O_BEZEICHN VARCHAR(30) CHARACTER SET NONE,
M_BEZEICHN VARCHAR(30) CHARACTER SET NONE,
GARAGE SMALLINT,
HAUSTIER SMALLINT,
RAUCHER SMALLINT,
TO_OPERATOR SMALLINT,
ZIMMERART INTEGER,
VERMIETJN SMALLINT,
TAGE INTEGER,
FARBE INTEGER,
AUSSTATTUNG VARCHAR(50) CHARACTER SET NONE,
BEMERK1 VARCHAR(255) CHARACTER SET NONE,
ZIMMERBEZEICHN VARCHAR(50) CHARACTER SET NONE,
OB_KURZBEZ VARCHAR(10) CHARACTER SET NONE)
AS 
declare variable i integer;
begin
  /* Procedure Text */
  for
    SELECT zimmstam.LNR, zimmstam.ZINR, zimmstam.MAND_NR, zimmstam.STOCK, zimmstam.BETTZAHL,
           zimmstam.TA_STATUS, zimmstam.LNR_KATE, zimmstam.OBJEKT_NR, katestam.KATEGORIE,
           objekt.BEZEICHN, mandant.BEZEICHN, zimmstam.GARAGE, zimmstam.HAUSTIER,
           zimmstam.RAUCHER, zimmstam.TO_OPERATOR, zimmstam.ZIMMERART, zimmstam.VERMIETJN,zimmstam.farbe,
           zimmstam.ausstatung, zimmstam.bemerk1,zimmstam.bezeichn,objekt.kurzbez
    FROM ZIMMSTAM
      LEFT OUTER JOIN KATESTAM ON (ZIMMSTAM.LNR_KATE = KATESTAM.LNR)
      LEFT OUTER JOIN OBJEKT ON (ZIMMSTAM.OBJEKT_NR = OBJEKT.LNR)
      LEFT OUTER JOIN MANDANT ON (ZIMMSTAM.MAND_NR = MANDANT.LNR)
    WHERE  (zimmstam.TA_STATUS < 500)
    into   :"LNR", :"ZINR", :"MAND_NR", :"STOCK", :"BETTZAHL", :"TA_STATUS", :"LNR_KATE",
           :"OBJEKT_NR", :"KATEGORIE", :"O_BEZEICHN", :"M_BEZEICHN", :"GARAGE",
           :"HAUSTIER",  :"RAUCHER", :"TO_OPERATOR", :"ZIMMERART", :"VERMIETJN", :"FARBE", :"AUSSTATTUNG", :"BEMERK1",
           :"ZIMMERBEZEICHN", :"OB_KURZBEZ"
  do
  begin
     execute procedure PROC_ZI_BELEGUNG :"LNR", :"JAHR"
           returning_values :TAGE;
     if(:TAGE is null)
     then
       TAGE = 0;
     suspend;
  end

    /*suspend; */

end ^

ALTER PROCEDURE PROC_CREATE_STAT_UMS_BELEG (DRUCKNR INTEGER,
VONDATUM DATE,
BISDATUM DATE)
AS 
begin
  /* Procedure Text */
  delete from TEMP_STAT_UMS_BELEG where TEMP_STAT_UMS_BELEG.drucknr= :drucknr;

  insert into TEMP_STAT_UMS_BELEG (DRUCKNR, UMS_BELEG, GK_LNR, LEIST_LNR, WGR_NR, HG_NR, TAG_BETRAG, ME, ERW, JUGEND,
                                  KIND, KK, DATUM, LNR_CO, TAG_ABS_LNR, TGABS_DATE, LNR_BUCHKONT,MAND_NR)
   select :drucknr, 100, stat_umsatz.gk_lnr, stat_umsatz.leist_lnr, leiststa.wg, warengru.durchl,
      stat_umsatz.tag_betrag, stat_umsatz.ME, 0,0,0,0,stat_umsatz.ldatum , stat_umsatz.lnr_co,
                                      stat_umsatz.TAG_ABS_LNR, stat_umsatz.TGABS_DATE, stat_umsatz.lnr_buchkont,
                                      gastkont.mand_nr
                               from stat_umsatz
                                  left outer join leiststa on (leiststa.lnr = stat_umsatz.leist_lnr)
                                  left outer join warengru on (warengru.lnr = leiststa.wg)
                                  left outer join gastkont on (gastkont.lnr = stat_umsatz.gk_lnr)

                                  where stat_umsatz.ldatum between :vondatum and :bisdatum;



  insert into TEMP_STAT_UMS_BELEG (DRUCKNR, UMS_BELEG, GK_LNR, LEIST_LNR, WGR_NR, HG_NR, TAG_BETRAG, ME, ERW, JUGEND,
                                  KIND, KK, DATUM, LNR_CO, TAG_ABS_LNR, TGABS_DATE, LNR_BUCHKONT,MAND_NR)
   select :drucknr, 1, stat_belegung.gk_lnr, 0, 0, 0, 0, 0, stat_belegung.anzerw,stat_belegung.anzjugend,stat_belegung.anzkinder,0,stat_belegung.datum , stat_belegung.lnr_co,
                                      0, NULL, 0, gastkont.mand_nr
                               from stat_belegung

                                  left outer join gastkont on (gastkont.lnr = stat_belegung.gk_lnr)
                                  where stat_belegung.datum between :vondatum and :bisdatum;





end ^

ALTER PROCEDURE PROC_DEL_ADR (GASTNR INTEGER)
RETURNS (LAUF INTEGER)
AS 
begin
  /* Procedure Text */
  LAUF = 0;

      select count(*)
        from gastkont
          where ((gastkont.gastnr_1 = :"GASTNR") or
                 (gastkont.gastnr_2 = :"GASTNR") or
                 (gastkont.gastnr_3 = :"GASTNR"))
                 and (gastkont.ci_status <2)
                 and (gastkont.ta_status<100)
      into :"LAUF";


      if (:"LAUF" = 0 or (:"LAUF" is Null ) ) then
      begin
        update dokument set dokument.ta_status = 1000 where adr_lnr = :"GASTNR";
        update gasthist set gasthist.ta_status = 1000 where adr_lnr = :"GASTNR";
        update adr_sele set adr_sele.ta_status = 1000 where adr_lnr = :"GASTNR";
        update adressen set adressen.ta_status = 1000 where lnr = :"GASTNR";
      end

  suspend;
end ^

ALTER PROCEDURE PROC_DEL_TEMP_ZIMMER_BELEG (ANREISE DATE,
ABREISE DATE,
LNR_KATE INTEGER,
BELEGNR INTEGER)
AS 
declare variable TAG date;
declare variable BELEGT_ALT integer = 0;
declare variable SHARER integer = 0;
begin
  tag = anreise;

  select gastkont.share_nr from gastkont where lnr = :belegnr
     into :sharer;

  if (sharer>0) then
  begin
  end
  else
  begin
      while (tag< abreise)
      do
      begin
        belegt_alt = 0;
        select belegt-1 from TEMP_BELEGTE_ZIMMER
        where TEMP_BELEGTE_ZIMMER.tag = :tag and TEMP_BELEGTE_ZIMMER.lnr_kate = :lnr_kate
          into :belegt_alt;
    
        if (belegt_alt<0) then belegt_alt = 0;
        update or insert into TEMP_BELEGTE_ZIMMER (TAG, BELEGT, LNR_KATE)
                                 values (:tag,:belegt_alt,:lnr_kate)
                                 matching (TAG, LNR_KATE);
    
        tag = tag+1;
      end
   end
end ^

ALTER PROCEDURE PROC_DRUCK_ZIM_ABRECH (GK_LNR INTEGER)
RETURNS (ANREDE VARCHAR(30) CHARACTER SET NONE,
TITEL VARCHAR(30) CHARACTER SET NONE,
NAME1 VARCHAR(60) CHARACTER SET NONE,
NAME2 VARCHAR(60) CHARACTER SET NONE,
STRASSE VARCHAR(60) CHARACTER SET NONE,
LAND VARCHAR(5) CHARACTER SET NONE,
PLZ VARCHAR(10) CHARACTER SET NONE,
ORT VARCHAR(50) CHARACTER SET NONE,
ZINR VARCHAR(10) CHARACTER SET NONE,
ADR_LNR INTEGER,
BEMERK1 VARCHAR(255) CHARACTER SET NONE,
BEMERK2 VARCHAR(255) CHARACTER SET NONE,
BEMERK3 VARCHAR(255) CHARACTER SET NONE,
BEMERK4 VARCHAR(255) CHARACTER SET NONE,
BUDAT DATE,
BETRAG NUMERIC(12, 3),
RECHNR INTEGER,
VOND DATE,
BISD DATE,
BELEGNR INTEGER,
GASTNAME VARCHAR(60) CHARACTER SET NONE,
GASTVORN VARCHAR(60) CHARACTER SET NONE,
AUFTAGE INTEGER,
PERSZAHL INTEGER,
ANZKINDER INTEGER,
ANZJUGEND INTEGER,
LNR_ZINR INTEGER,
GASTNR_1 INTEGER,
ANFANG NUMERIC(12, 3),
ENDE NUMERIC(12, 3),
E_PREIS NUMERIC(12, 3),
CI_STATUS INTEGER,
VON DATE,
BIS DATE,
TAGBETRAG NUMERIC(12, 3),
GBETRAG NUMERIC(12, 3),
BEZEICHN VARCHAR(255) CHARACTER SET NONE,
ME INTEGER,
TAGE INTEGER,
EIGT_ABR INTEGER,
LEIST_LNR INTEGER,
FAKT_EIGT_LFD INTEGER)
AS 
begin
  /* Procedure Text */
  for
   SELECT a1.ANREDE, a1.TITEL, a1.NAME1, a1.NAME2,
          a1.STRASSE, a1.LAND, a1.PLZ, a1.ORT, ZIMMSTAM.ZINR,
          ZIMMSTAM.ADR_LNR, ZIMMSTAM.BEMERK1, ZIMMSTAM.BEMERK2, ZIMMSTAM.BEMERK3, ZIMMSTAM.BEMERK4,
          FAKT_ERLOESE.BUDAT, FAKT_ERLOESE.BETRAG, FAKT_ERLOESE.RECHNR, FAKT_ERLOESE.VOND,
          FAKT_ERLOESE.BISD, FAKT_ERLOESE.belegnr, 
          a2.name1, a2.name2,
          GASTKONT.AUFTAGE, GASTKONT.PERSZAHL, GASTKONT.ANZKINDER, GASTKONT.ANZJUGEND,
          GASTKONT.LNR_ZINR, GASTKONT.gastnr_1,
          BUCHKONT.ANFANG, BUCHKONT.ENDE, BUCHKONT.E_PREIS, GASTKONT.CI_STATUS,
          BUCHKONT.VON, BUCHKONT.BIS, BUCHKONT.TAGBETRAG, BUCHKONT.GBETRAG,
          BUCHKONT.BEZEICHN, BUCHKONT.ME, BUCHKONT.TAGE,
          LEISTSTA.eigt_abr,LEISTSTA.lnr,
           fakt_erloese.eigt_lfd as fakt_eigt_lfd


    FROM GASTKONT
       INNER JOIN FAKT_ERLOESE ON (GASTKONT.LNR = FAKT_ERLOESE.BELEGNR)
       INNER JOIN BUCHKONT ON (FAKT_ERLOESE.LNR_BUCHKONT = BUCHKONT.LNR and FAKT_ERLOESE.lnr_leist = BUCHKONT.leist_lnr)
       INNER JOIN ZIMMSTAM ON (GASTKONT.LNR_ZINR = ZIMMSTAM.LNR)
       INNER JOIN ADRESSEN a1 ON (ZIMMSTAM.ADR_LNR  = a1.LNR)
       INNER JOIN ADRESSEN a2 ON (GASTKONT.gastnr_1 = a2.lnr)
       INNER JOIN LEISTSTA ON (BUCHKONT.leist_lnr = LEISTSTA.lnr)

    where GASTKONT.lnr = :"GK_LNR"

    into :"ANREDE", :"TITEL", :"NAME1", :"NAME2",
         :"STRASSE", :"LAND", :"PLZ", :"ORT", :"ZINR",
         :"ADR_LNR", :"BEMERK1", :"BEMERK2", :"BEMERK3", :"BEMERK4",
         :"BUDAT", :"BETRAG",:"RECHNR", :"VOND", :"BISD", :"BELEGNR",
         :"GASTNAME", :"GASTVORN",
         :"AUFTAGE", :"PERSZAHL", :"ANZKINDER", :"ANZJUGEND",:"LNR_ZINR", :"GASTNR_1",
         :"ANFANG", :"ENDE", :"E_PREIS", :"CI_STATUS", :"VON", :"BIS",
         :"TAGBETRAG", :"GBETRAG", :"BEZEICHN", :"ME", :"TAGE",
         :"EIGT_ABR", :"LEIST_LNR", :"FAKT_EIGT_LFD"

   do
   suspend;
end ^

ALTER PROCEDURE PROC_EXISTS_ZIMLEIST (LNR INTEGER)
RETURNS (LNR_ZIMLEIST INTEGER)
AS 
begin
  /* Procedure Text */
  for
     SELECT ZIMMLEIST.LNR_ZIMMSTAM
        FROM LEISTSTA
        INNER JOIN ZIMMLEIST ON (LEISTSTA.LNR = ZIMMLEIST.LNR_LEISTSTA)
        where zimmleist.lnr_zimmstam = :"LNR" and leiststa.ta_status < 1000
                and zimmleist.ta_status < 1000
     into :"LNR_ZIMLEIST"
  do
  suspend;
end ^

ALTER PROCEDURE PROC_FAIRMAS_SEGMCODE (DRUCKNR INTEGER,
MAND_NR INTEGER,
ABREISE DATE,
ANREISE DATE)
RETURNS (SEGM_TYP VARCHAR(10) CHARACTER SET NONE,
SEGM_OUT_OF_ORDER INTEGER,
SEGM_SUM_ANREISE INTEGER,
SEGM_SUM_ABREISE INTEGER,
SEGM_SUM_ABREISE_GES INTEGER,
SEGM_ZIMMERZAHL INTEGER,
SEGM_PERSZAHL INTEGER,
SEGM_SUM_ANREISE_GAST INTEGER,
SEGM_NAME VARCHAR(100) CHARACTER SET NONE,
SEGM_ID VARCHAR(10) CHARACTER SET NONE,
SEGM_DATUM DATE,
SEGM_TAGBETRAG_LOGI NUMERIC(12, 2),
SEGM_TAGBETRAG_FB NUMERIC(12, 2),
SEGM_TAGBETRAG_HEALTH NUMERIC(12, 2),
SEGM_TAGBETRAG_SONSTIGES NUMERIC(12, 2))
AS 
declare variable P_TMPDATUM date;
begin

  P_TMPDATUM = ANREISE - 1;

  while (ABREISE > P_TMPDATUM) do
  begin
    P_TMPDATUM = P_TMPDATUM + 1;

    for select :P_TMPDATUM as SEGM_DATUM, '0' as SEGM_ID, 'FAMILIE' as SEGM_NAME,
               iif(GA.BUCH_STATUS = 100, 'TEN', 'DEF') as SEGM_TYP,
               sum(GA.PERSZAHL + GA.ANZKINDER + GA.ANZJUGEND + GA.ANZKLEINKIND) as SEGM_PERSZAHL,
               count(GA.LNR) as SEGM_SUM_ZIM, sum(iif(GA.VONAUFH = :P_TMPDATUM, 1, 0)) as SEGM_SUM_ANREISE,

               /* Anzahl Zimmer die frei werden in diesem Segment */
               (select count(*)
                from BELEGUNG
                inner join GASTKONT on (GASTKONT.LNR = BELEGUNG.LNR_GK)
                inner join ADRESSEN on (ADRESSEN.LNR = GASTKONT.GASTNR_1)
                where BELEGUNG.ABREISE = :P_TMPDATUM and
                      BELEGUNG.MAND_NR = 1 and
                      upper(ADRESSEN.ANREDE) = 'FAMILIE') as SEGM_SUM_ABREISE,

               /* Anzahl Zimmer die frei werden Gesamt */
               (select count(*)
                from BELEGUNG
                inner join GASTKONT on (GASTKONT.LNR = BELEGUNG.LNR_GK)
                inner join ADRESSEN on (ADRESSEN.LNR = GASTKONT.GASTNR_1)
                where BELEGUNG.ABREISE = :P_TMPDATUM and
                      BELEGUNG.MAND_NR = 1) as SEGM_SUM_ABREISE_GES,

               sum(iif(GA.VONAUFH = :P_TMPDATUM, GA.PERSZAHL + GA.ANZKINDER + GA.ANZJUGEND + GA.ANZKLEINKIND, 0)) as SEGM_SUM_ANREISE_GAST,

               /*Nur hier, naechste 2 abfrage mit 0 Wert !!!!*/
               (select count(G.LNR)
                from GASTKONT G
                inner join ADRESSEN ADR on (G.GASTNR_1 = ADR.LNR)
                inner join KATESTAM K on (G.LNR_KATE = K.LNR)
                where ((G.VONAUFH <= :P_TMPDATUM) and
                      (G.BISAUFH > :P_TMPDATUM)) and
                      G.TA_STATUS < 1000 and
                      G.BELEGUNGSART >= 3) as SEGM_OUT_OF_ORDER,

               /* Umsatz Logi */
               (select iif(sum(B_TAG) is null, 0, sum(B_TAG))
                from TEMP_STAT_MANAG
                left outer join GASTKONT on (TEMP_STAT_MANAG.GR_NR = GASTKONT.LNR)
                left outer join SEGMSTAM on (GASTKONT.GAST_GR = SEGMSTAM.SEGMCODE and
                      GASTKONT.MAND_NR = SEGMSTAM.MAND_NR)
                left outer join LEISTSTA on (TEMP_STAT_MANAG.LEIST_LNR = LEISTSTA.LNR)
                left outer join WARENGRU on (LEISTSTA.WG = WARENGRU.LNR)
                inner join ADRESSEN on (ADRESSEN.LNR = GASTKONT.GASTNR_1)
                where ((TEMP_STAT_MANAG.DRUCKNR = :DRUCKNR))

                      and
                      upper(ADRESSEN.ANREDE) = 'FAMILIE' and
                      WARENGRU.DURCHL = 0 --Logi
                      --and WARENGRU.DURCHL = 1 --F&B
                      --and WARENGRU.DURCHL = 2 --Health
                      --and WARENGRU.DURCHL = 3 --Sonstiges

                      and
                      GASTKONT.MAND_NR = :MAND_NR and
                      TEMP_STAT_MANAG.MONAT = extract(month from :P_TMPDATUM) and
                      TEMP_STAT_MANAG.TAG = extract(day from :P_TMPDATUM)) as SEGM_TAGBETRAG_LOGI,

               /* Umsatz F&B */
               (select iif(sum(B_TAG) is null, 0, sum(B_TAG))
                       --               (select sum(B_TAG)
                from TEMP_STAT_MANAG
                left outer join GASTKONT on (TEMP_STAT_MANAG.GR_NR = GASTKONT.LNR)
                left outer join SEGMSTAM on (GASTKONT.GAST_GR = SEGMSTAM.SEGMCODE and
                      GASTKONT.MAND_NR = SEGMSTAM.MAND_NR)
                left outer join LEISTSTA on (TEMP_STAT_MANAG.LEIST_LNR = LEISTSTA.LNR)
                left outer join WARENGRU on (LEISTSTA.WG = WARENGRU.LNR)
                inner join ADRESSEN on (ADRESSEN.LNR = GASTKONT.GASTNR_1)

                where ((TEMP_STAT_MANAG.DRUCKNR = :DRUCKNR))

                      and
                      upper(ADRESSEN.ANREDE) = 'FAMILIE'

                      and
                      WARENGRU.DURCHL = 1 --F&B
                      and
                      TEMP_STAT_MANAG.MONAT = extract(month from :P_TMPDATUM) and
                      TEMP_STAT_MANAG.TAG = extract(day from :P_TMPDATUM)) as SEGM_TAGBETRAG_FB,

               /* Umsatz Health */
               (select iif(sum(B_TAG) is null, 0, sum(B_TAG))
                       --               (select sum(B_TAG)
                from TEMP_STAT_MANAG
                left outer join GASTKONT on (TEMP_STAT_MANAG.GR_NR = GASTKONT.LNR)
                left outer join SEGMSTAM on (GASTKONT.GAST_GR = SEGMSTAM.SEGMCODE and
                      GASTKONT.MAND_NR = SEGMSTAM.MAND_NR)
                left outer join LEISTSTA on (TEMP_STAT_MANAG.LEIST_LNR = LEISTSTA.LNR)
                left outer join WARENGRU on (LEISTSTA.WG = WARENGRU.LNR)
                inner join ADRESSEN on (ADRESSEN.LNR = GASTKONT.GASTNR_1)

                where ((TEMP_STAT_MANAG.DRUCKNR = :DRUCKNR))

                      and
                      upper(ADRESSEN.ANREDE) = 'FAMILIE'

                      and
                      WARENGRU.DURCHL = 2 --Health
                      and
                      GASTKONT.MAND_NR = :MAND_NR and
                      TEMP_STAT_MANAG.MONAT = extract(month from :P_TMPDATUM) and
                      TEMP_STAT_MANAG.TAG = extract(day from :P_TMPDATUM)) as SEGM_TAGBETRAG_HEALTH,

               /* Umsatz Sonstiges */
               --               (select sum(B_TAG)
               (select iif(sum(B_TAG) is null, 0, sum(B_TAG))
                from TEMP_STAT_MANAG
                left outer join GASTKONT on (TEMP_STAT_MANAG.GR_NR = GASTKONT.LNR)
                left outer join SEGMSTAM on (GASTKONT.GAST_GR = SEGMSTAM.SEGMCODE and
                      GASTKONT.MAND_NR = SEGMSTAM.MAND_NR)
                left outer join LEISTSTA on (TEMP_STAT_MANAG.LEIST_LNR = LEISTSTA.LNR)
                left outer join WARENGRU on (LEISTSTA.WG = WARENGRU.LNR)
                inner join ADRESSEN on (ADRESSEN.LNR = GASTKONT.GASTNR_1)

                where ((TEMP_STAT_MANAG.DRUCKNR = :DRUCKNR))

                      and
--                      WARENGRU.DURCHL = 3 --Sonstiges
                      WARENGRU.DURCHL in (3,4,5 ) --Sonstiges

                      and
                      GASTKONT.MAND_NR = :MAND_NR and
                      TEMP_STAT_MANAG.MONAT = extract(month from :P_TMPDATUM) and
                      TEMP_STAT_MANAG.TAG = extract(day from :P_TMPDATUM)) as SEGM_TAGBETRAG_SONSTIGES

        from GASTKONT GA
        inner join ADRESSEN AD on (GA.GASTNR_1 = AD.LNR)
        where AD.ADR_WAHL = 0 and
              (upper(AD.ANREDE) = 'FAMILIE') and
              ((GA.VONAUFH >= :P_TMPDATUM and
              GA.VONAUFH <= :P_TMPDATUM) or (GA.BISAUFH > :P_TMPDATUM and
              GA.BISAUFH <= :P_TMPDATUM) or (GA.VONAUFH < :P_TMPDATUM and
              GA.BISAUFH > :P_TMPDATUM)) and
              --              GA.TA_STATUS < 1000 and
              GA.CI_STATUS < 2 and
              GA.BELEGUNGSART < 3 and
              GA.MAND_NR = :MAND_NR
        group by GA.BUCH_STATUS

        union

        select :P_TMPDATUM as SEGM_DATUM, '1' as SEGM_ID, 'FREIZEITGAST' as SEGM_NAME,
               iif(GA.BUCH_STATUS = 100, 'TEN', 'DEF') as SEGM_TYP,
               sum(GA.PERSZAHL + GA.ANZKINDER + GA.ANZJUGEND + GA.ANZKLEINKIND) as SEGM_PERSZAHL,
               count(GA.LNR) as SEGM_SUM_ZIM, sum(iif(GA.VONAUFH = :P_TMPDATUM, 1, 0)) as SEGM_SUM_ANREISE,

               /* Anzahl Zimmer die frei werden in diesem Segment */
               (select count(*)
                from BELEGUNG
                inner join GASTKONT on (GASTKONT.LNR = BELEGUNG.LNR_GK)
                inner join ADRESSEN on (ADRESSEN.LNR = GASTKONT.GASTNR_1)
                where BELEGUNG.ABREISE = :P_TMPDATUM and
                      BELEGUNG.MAND_NR = 1 and
                      ((upper(ADRESSEN.ANREDE) <> 'FIRMA') and
                      (upper(ADRESSEN.ANREDE) <> 'FAMILIE'))) as SEGM_SUM_ABREISE,

               /* Anzahl Zimmer die frei werden Gesamt */
               (select count(*)
                from BELEGUNG
                inner join GASTKONT on (GASTKONT.LNR = BELEGUNG.LNR_GK)
                inner join ADRESSEN on (ADRESSEN.LNR = GASTKONT.GASTNR_1)
                where BELEGUNG.ABREISE = :P_TMPDATUM and
                      BELEGUNG.MAND_NR = 1) as SEGM_SUM_ABREISE_GES,

               sum(iif(GA.VONAUFH = :P_TMPDATUM, GA.PERSZAHL + GA.ANZKINDER + GA.ANZJUGEND + GA.ANZKLEINKIND, 0)) as SEGM_SUM_ANREISE_GAST,
               '0' as SEGM_OUT_OF_ORDER,

               /* Umsatz Logi */
               (select iif(sum(B_TAG) is null, 0, sum(B_TAG))
                       --               (select sum(B_TAG)
                from TEMP_STAT_MANAG
                left outer join GASTKONT on (TEMP_STAT_MANAG.GR_NR = GASTKONT.LNR)
                left outer join SEGMSTAM on (GASTKONT.GAST_GR = SEGMSTAM.SEGMCODE and
                      GASTKONT.MAND_NR = SEGMSTAM.MAND_NR)
                left outer join LEISTSTA on (TEMP_STAT_MANAG.LEIST_LNR = LEISTSTA.LNR)
                left outer join WARENGRU on (LEISTSTA.WG = WARENGRU.LNR)
                inner join ADRESSEN on (ADRESSEN.LNR = GASTKONT.GASTNR_1)
                where ((TEMP_STAT_MANAG.DRUCKNR = :DRUCKNR))

                      and
                      ((upper(ADRESSEN.ANREDE) <> 'FIRMA') and
                      (upper(ADRESSEN.ANREDE) <> 'FAMILIE'))

                      and
                      WARENGRU.DURCHL = 0 --Logi
                      --and WARENGRU.DURCHL = 1 --F&B
                      --and WARENGRU.DURCHL = 2 --Health
                      --and WARENGRU.DURCHL = 3 --Sonstiges

                      and
                      GASTKONT.MAND_NR = :MAND_NR and
                      TEMP_STAT_MANAG.MONAT = extract(month from :P_TMPDATUM) and
                      TEMP_STAT_MANAG.TAG = extract(day from :P_TMPDATUM)) as SEGM_TAGBETRAG_LOGI,

               /* Umsatz F&B */
               (select iif(sum(B_TAG) is null, 0, sum(B_TAG))
                       --               (select sum(B_TAG)
                from TEMP_STAT_MANAG
                left outer join GASTKONT on (TEMP_STAT_MANAG.GR_NR = GASTKONT.LNR)
                left outer join SEGMSTAM on (GASTKONT.GAST_GR = SEGMSTAM.SEGMCODE and
                      GASTKONT.MAND_NR = SEGMSTAM.MAND_NR)
                left outer join LEISTSTA on (TEMP_STAT_MANAG.LEIST_LNR = LEISTSTA.LNR)
                left outer join WARENGRU on (LEISTSTA.WG = WARENGRU.LNR)
                inner join ADRESSEN on (ADRESSEN.LNR = GASTKONT.GASTNR_1)
                where ((TEMP_STAT_MANAG.DRUCKNR = :DRUCKNR))

                      and
                      ((upper(ADRESSEN.ANREDE) <> 'FIRMA') and
                      (upper(ADRESSEN.ANREDE) <> 'FAMILIE'))

                      and
                      WARENGRU.DURCHL = 1 --F&B
                      --and GASTKONT.MAND_NR = :MAND_NR
                      and
                      TEMP_STAT_MANAG.MONAT = extract(month from :P_TMPDATUM) and
                      TEMP_STAT_MANAG.TAG = extract(day from :P_TMPDATUM)) as SEGM_TAGBETRAG_FB,

               /* Umsatz Health */
               (select iif(sum(B_TAG) is null, 0, sum(B_TAG))
                       --               (select sum(B_TAG)
                from TEMP_STAT_MANAG
                left outer join GASTKONT on (TEMP_STAT_MANAG.GR_NR = GASTKONT.LNR)
                left outer join SEGMSTAM on (GASTKONT.GAST_GR = SEGMSTAM.SEGMCODE and
                      GASTKONT.MAND_NR = SEGMSTAM.MAND_NR)
                left outer join LEISTSTA on (TEMP_STAT_MANAG.LEIST_LNR = LEISTSTA.LNR)
                left outer join WARENGRU on (LEISTSTA.WG = WARENGRU.LNR)
                inner join ADRESSEN on (ADRESSEN.LNR = GASTKONT.GASTNR_1)
                where ((TEMP_STAT_MANAG.DRUCKNR = :DRUCKNR))

                      and
                      ((upper(ADRESSEN.ANREDE) <> 'FIRMA') and
                      (upper(ADRESSEN.ANREDE) <> 'FAMILIE'))

                      and
                      WARENGRU.DURCHL = 2 --Health
                      and
                      GASTKONT.MAND_NR = :MAND_NR and
                      TEMP_STAT_MANAG.MONAT = extract(month from :P_TMPDATUM) and
                      TEMP_STAT_MANAG.TAG = extract(day from :P_TMPDATUM)) as SEGM_TAGBETRAG_HEALTH,

               /* Umsatz Sonstiges */
               (select iif(sum(B_TAG) is null, 0, sum(B_TAG))
                       --               (select sum(B_TAG)
                from TEMP_STAT_MANAG
                left outer join GASTKONT on (TEMP_STAT_MANAG.GR_NR = GASTKONT.LNR)
                left outer join SEGMSTAM on (GASTKONT.GAST_GR = SEGMSTAM.SEGMCODE and
                      GASTKONT.MAND_NR = SEGMSTAM.MAND_NR)
                left outer join LEISTSTA on (TEMP_STAT_MANAG.LEIST_LNR = LEISTSTA.LNR)
                left outer join WARENGRU on (LEISTSTA.WG = WARENGRU.LNR)
                inner join ADRESSEN on (ADRESSEN.LNR = GASTKONT.GASTNR_1)
                where ((TEMP_STAT_MANAG.DRUCKNR = :DRUCKNR)) and
                      upper(ADRESSEN.ANREDE) <> 'FIRMA' and
                      upper(ADRESSEN.ANREDE) <> 'FAMILIE'

                      and
--                      WARENGRU.DURCHL = 3 --Sonstiges
                      WARENGRU.DURCHL in (3,4,5) --Sonstiges

                      and
                      GASTKONT.MAND_NR = :MAND_NR and
                      TEMP_STAT_MANAG.MONAT = extract(month from :P_TMPDATUM) and
                      TEMP_STAT_MANAG.TAG = extract(day from :P_TMPDATUM)) as SEGM_TAGBETRAG_SONSTIGES

        from GASTKONT GA
        inner join ADRESSEN AD1 on (GA.GASTNR_1 = AD1.LNR)
        where AD1.ADR_WAHL = 0 and
              (upper(AD1.ANREDE) <> 'FIRMA' and
              (upper(AD1.ANREDE) <> 'FAMILIE')) and
              ((GA.VONAUFH >= :P_TMPDATUM and
              GA.VONAUFH <= :P_TMPDATUM) or (GA.BISAUFH > :P_TMPDATUM and
              GA.BISAUFH <= :P_TMPDATUM) or (GA.VONAUFH < :P_TMPDATUM and
              GA.BISAUFH > :P_TMPDATUM)) and
              --              GA.TA_STATUS < 1000 and
              GA.CI_STATUS < 2 and
              GA.BELEGUNGSART < 3 and
              GA.MAND_NR = :MAND_NR
        group by GA.BUCH_STATUS

        union
        select :P_TMPDATUM as SEGM_DATUM, '2' as SEGM_ID, 'FIRMA' as SEGM_NAME,
               iif(GA.BUCH_STATUS = 100, 'TEN', 'DEF') as SEGM_TYP,
               sum(GA.PERSZAHL + GA.ANZKINDER + GA.ANZJUGEND + GA.ANZKLEINKIND) as SEGM_PERSZAHL,
               count(GA.LNR) as SEGM_SUM_ZIM, sum(iif(GA.VONAUFH = :P_TMPDATUM, 1, 0)) as SEGM_SUM_ANREISE,

               /* Anzahl Zimmer die frei werden in diesem Segment */
               (select count(*)
                from BELEGUNG
                inner join GASTKONT on (GASTKONT.LNR = BELEGUNG.LNR_GK)
                inner join ADRESSEN on (ADRESSEN.LNR = GASTKONT.GASTNR_1)
                where BELEGUNG.ABREISE = :P_TMPDATUM and
                      BELEGUNG.MAND_NR = 1 and
                      upper(ADRESSEN.ANREDE) = 'FIRMA') as SEGM_SUM_ABREISE,

               /* Anzahl Zimmer die frei werden Gesamt */
               (select count(*)
                from BELEGUNG
                inner join GASTKONT on (GASTKONT.LNR = BELEGUNG.LNR_GK)
                inner join ADRESSEN on (ADRESSEN.LNR = GASTKONT.GASTNR_1)
                where BELEGUNG.ABREISE = :P_TMPDATUM and
                      BELEGUNG.MAND_NR = 1) as SEGM_SUM_ABREISE_GES,

               sum(iif(GA.VONAUFH = :P_TMPDATUM, GA.PERSZAHL + GA.ANZKINDER + GA.ANZJUGEND + GA.ANZKLEINKIND, 0)) as SEGM_SUM_ANREISE_GAST,
               '0' as SEGM_OUT_OF_ORDER,

               /* Umsatz Logi */
               (select iif(sum(B_TAG) is null, 0, sum(B_TAG))
                       --               (select sum(B_TAG)
                from TEMP_STAT_MANAG
                left outer join GASTKONT on (TEMP_STAT_MANAG.GR_NR = GASTKONT.LNR)
                left outer join SEGMSTAM on (GASTKONT.GAST_GR = SEGMSTAM.SEGMCODE and
                      GASTKONT.MAND_NR = SEGMSTAM.MAND_NR)
                left outer join LEISTSTA on (TEMP_STAT_MANAG.LEIST_LNR = LEISTSTA.LNR)
                left outer join WARENGRU on (LEISTSTA.WG = WARENGRU.LNR)
                inner join ADRESSEN on (ADRESSEN.LNR = GASTKONT.GASTNR_1)

                where ((TEMP_STAT_MANAG.DRUCKNR = :DRUCKNR))

                      and
                      upper(ADRESSEN.ANREDE) = 'FIRMA' and

                      WARENGRU.DURCHL = 0 --Logi
                      --and WARENGRU.DURCHL = 1 --F&B
                      --and WARENGRU.DURCHL = 2 --Health
                      --and WARENGRU.DURCHL = 3 --Sonstiges

                      and
                      GASTKONT.MAND_NR = :MAND_NR and
                      TEMP_STAT_MANAG.MONAT = extract(month from :P_TMPDATUM) and
                      TEMP_STAT_MANAG.TAG = extract(day from :P_TMPDATUM)) as SEGM_TAGBETRAG_LOGI,

               /* Umsatz F&B */
               (select iif(sum(B_TAG) is null, 0, sum(B_TAG))
                       --               (select sum(B_TAG)
                from TEMP_STAT_MANAG
                left outer join GASTKONT on (TEMP_STAT_MANAG.GR_NR = GASTKONT.LNR)
                left outer join SEGMSTAM on (GASTKONT.GAST_GR = SEGMSTAM.SEGMCODE and
                      GASTKONT.MAND_NR = SEGMSTAM.MAND_NR)
                left outer join LEISTSTA on (TEMP_STAT_MANAG.LEIST_LNR = LEISTSTA.LNR)
                left outer join WARENGRU on (LEISTSTA.WG = WARENGRU.LNR)
                inner join ADRESSEN on (ADRESSEN.LNR = GASTKONT.GASTNR_1)

                where ((TEMP_STAT_MANAG.DRUCKNR = :DRUCKNR)) and
                      upper(ADRESSEN.ANREDE) = 'FIRMA'

                      and
                      WARENGRU.DURCHL = 1 --F&B
                      and
                      GASTKONT.MAND_NR = :MAND_NR and
                      TEMP_STAT_MANAG.MONAT = extract(month from :P_TMPDATUM) and
                      TEMP_STAT_MANAG.TAG = extract(day from :P_TMPDATUM)) as SEGM_TAGBETRAG_FB,

               /* Umsatz Health */
               (select iif(sum(B_TAG) is null, 0, sum(B_TAG))
                       --               (select sum(B_TAG)
                from TEMP_STAT_MANAG
                left outer join GASTKONT on (TEMP_STAT_MANAG.GR_NR = GASTKONT.LNR)
                left outer join SEGMSTAM on (GASTKONT.GAST_GR = SEGMSTAM.SEGMCODE and
                      GASTKONT.MAND_NR = SEGMSTAM.MAND_NR)
                left outer join LEISTSTA on (TEMP_STAT_MANAG.LEIST_LNR = LEISTSTA.LNR)
                left outer join WARENGRU on (LEISTSTA.WG = WARENGRU.LNR)
                inner join ADRESSEN on (ADRESSEN.LNR = GASTKONT.GASTNR_1)

                where ((TEMP_STAT_MANAG.DRUCKNR = :DRUCKNR))

                      and
                      upper(ADRESSEN.ANREDE) = 'FIRMA' and
                      WARENGRU.DURCHL = 2 --Health
                      and
                      GASTKONT.MAND_NR = :MAND_NR and
                      TEMP_STAT_MANAG.MONAT = extract(month from :P_TMPDATUM) and
                      TEMP_STAT_MANAG.TAG = extract(day from :P_TMPDATUM)) as SEGM_TAGBETRAG_HEALTH,

               /* Umsatz Sonstiges */
               (select iif(sum(B_TAG) is null, 0, sum(B_TAG))
                       --               (select sum(B_TAG)
                from TEMP_STAT_MANAG
                left outer join GASTKONT on (TEMP_STAT_MANAG.GR_NR = GASTKONT.LNR)
                left outer join SEGMSTAM on (GASTKONT.GAST_GR = SEGMSTAM.SEGMCODE and
                      GASTKONT.MAND_NR = SEGMSTAM.MAND_NR)
                left outer join LEISTSTA on (TEMP_STAT_MANAG.LEIST_LNR = LEISTSTA.LNR)
                left outer join WARENGRU on (LEISTSTA.WG = WARENGRU.LNR)
                inner join ADRESSEN on (ADRESSEN.LNR = GASTKONT.GASTNR_1)

                where ((TEMP_STAT_MANAG.DRUCKNR = :DRUCKNR))

                      and
                      upper(ADRESSEN.ANREDE) = 'FIRMA' and
--                      WARENGRU.DURCHL = 3 --Sonstiges
                      WARENGRU.DURCHL in (3,4,5) --Sonstiges

                      and
                      GASTKONT.MAND_NR = :MAND_NR and
                      TEMP_STAT_MANAG.MONAT = extract(month from :P_TMPDATUM) and
                      TEMP_STAT_MANAG.TAG = extract(day from :P_TMPDATUM)) as SEGM_TAGBETRAG_SONSTIGES

        from GASTKONT GA
        inner join ADRESSEN AD2 on (GA.GASTNR_1 = AD2.LNR)
        where (AD2.ADR_WAHL = 1 or upper(AD2.ANREDE) = 'FIRMA') and
              ((GA.VONAUFH >= :P_TMPDATUM and
              GA.VONAUFH <= :P_TMPDATUM) or (GA.BISAUFH > :P_TMPDATUM and
              GA.BISAUFH <= :P_TMPDATUM) or (GA.VONAUFH < :P_TMPDATUM and
              GA.BISAUFH > :P_TMPDATUM)) and
              --              GA.TA_STATUS < 1000 and
              GA.CI_STATUS < 2 and
              GA.BELEGUNGSART < 3 and
              GA.MAND_NR = :MAND_NR
        group by GA.BUCH_STATUS

        into :"SEGM_DATUM", :"SEGM_ID", :"SEGM_NAME", :"SEGM_TYP", :"SEGM_PERSZAHL", :"SEGM_ZIMMERZAHL",
             :"SEGM_SUM_ANREISE", :"SEGM_SUM_ABREISE", :SEGM_SUM_ABREISE_GES, :"SEGM_SUM_ANREISE_GAST",
             :"SEGM_OUT_OF_ORDER", :"SEGM_TAGBETRAG_LOGI", :"SEGM_TAGBETRAG_FB", :"SEGM_TAGBETRAG_HEALTH", :"SEGM_TAGBETRAG_SONSTIGES"

    do
    begin
      suspend;
    end

  end

end ^

ALTER PROCEDURE PROC_FAIRMAS_SEG_GESBETRAG (DRUCKNR INTEGER,
MAND_NR INTEGER,
ABREISE DATE,
ANREISE DATE)
RETURNS (SEGM_NAME VARCHAR(100) CHARACTER SET NONE,
SEGM_ID VARCHAR(10) CHARACTER SET NONE,
SEGM_DATUM DATE,
SEGM_TAGBETRAG_LOGI NUMERIC(12, 2),
SEGM_TAGBETRAG_FB NUMERIC(12, 2),
SEGM_TAGBETRAG_HEALTH NUMERIC(12, 2),
SEGM_TAGBETRAG_SONSTIGES NUMERIC(12, 2))
AS 
declare variable P_TMPDATUM date;
begin

  P_TMPDATUM = ANREISE - 1;

  while (ABREISE > P_TMPDATUM) do
  begin
    P_TMPDATUM = P_TMPDATUM + 1;

    for select :P_TMPDATUM as SEGM_DATUM, '0' as SEGM_ID, 'FAMILIE' as SEGM_NAME,

               /* Umsatz Logi */
               (select iif(sum(B_TAG) is Null, 0, sum(B_TAG))
                from TEMP_STAT_MANAG
                left outer join GASTKONT on (TEMP_STAT_MANAG.GR_NR = GASTKONT.LNR)
                left outer join SEGMSTAM on (GASTKONT.GAST_GR = SEGMSTAM.SEGMCODE and
                      GASTKONT.MAND_NR = SEGMSTAM.MAND_NR)
                left outer join LEISTSTA on (TEMP_STAT_MANAG.LEIST_LNR = LEISTSTA.LNR)
                left outer join WARENGRU on (LEISTSTA.WG = WARENGRU.LNR)
                inner join ADRESSEN on (ADRESSEN.LNR = GASTKONT.GASTNR_1)
                where ((TEMP_STAT_MANAG.DRUCKNR = :DRUCKNR))

                      and
                      upper(ADRESSEN.ANREDE) = 'FAMILIE' and
                      WARENGRU.DURCHL = 0 --Logi
                      --and WARENGRU.DURCHL = 1 --F&B
                      --and WARENGRU.DURCHL = 2 --Health
                      --and WARENGRU.DURCHL = 3 --Sonstiges

                      and
                      TEMP_STAT_MANAG.MONAT = extract(month from :P_TMPDATUM) and
                      TEMP_STAT_MANAG.TAG = extract(day from :P_TMPDATUM)) as SEGM_TAGBETRAG_LOGI,

               /* Umsatz F&B */
               (select iif(sum(B_TAG) is Null, 0, sum(B_TAG))
                from TEMP_STAT_MANAG
                left outer join GASTKONT on (TEMP_STAT_MANAG.GR_NR = GASTKONT.LNR)
                left outer join SEGMSTAM on (GASTKONT.GAST_GR = SEGMSTAM.SEGMCODE and
                      GASTKONT.MAND_NR = SEGMSTAM.MAND_NR)
                left outer join LEISTSTA on (TEMP_STAT_MANAG.LEIST_LNR = LEISTSTA.LNR)
                left outer join WARENGRU on (LEISTSTA.WG = WARENGRU.LNR)
                inner join ADRESSEN on (ADRESSEN.LNR = GASTKONT.GASTNR_1)

                where ((TEMP_STAT_MANAG.DRUCKNR = :DRUCKNR))

                      and
                      upper(ADRESSEN.ANREDE) = 'FAMILIE'

                      and
                      WARENGRU.DURCHL = 1 --F&B
                      and
                      TEMP_STAT_MANAG.MONAT = extract(month from :P_TMPDATUM) and
                      TEMP_STAT_MANAG.TAG = extract(day from :P_TMPDATUM)) as SEGM_TAGBETRAG_FB,

               /* Umsatz Health */
               (select iif(sum(B_TAG) is Null, 0, sum(B_TAG))
                from TEMP_STAT_MANAG
                left outer join GASTKONT on (TEMP_STAT_MANAG.GR_NR = GASTKONT.LNR)
                left outer join SEGMSTAM on (GASTKONT.GAST_GR = SEGMSTAM.SEGMCODE and
                      GASTKONT.MAND_NR = SEGMSTAM.MAND_NR)
                left outer join LEISTSTA on (TEMP_STAT_MANAG.LEIST_LNR = LEISTSTA.LNR)
                left outer join WARENGRU on (LEISTSTA.WG = WARENGRU.LNR)
                inner join ADRESSEN on (ADRESSEN.LNR = GASTKONT.GASTNR_1)

                where ((TEMP_STAT_MANAG.DRUCKNR = :DRUCKNR))

                      and
                      upper(ADRESSEN.ANREDE) = 'FAMILIE'

                      and
                      WARENGRU.DURCHL = 2 --Health
                      and
                      TEMP_STAT_MANAG.MONAT = extract(month from :P_TMPDATUM) and
                      TEMP_STAT_MANAG.TAG = extract(day from :P_TMPDATUM)) as SEGM_TAGBETRAG_HEALTH,

               /* Umsatz Sonstiges */
               (select iif(sum(B_TAG) is Null, 0, sum(B_TAG))
                from TEMP_STAT_MANAG
                left outer join GASTKONT on (TEMP_STAT_MANAG.GR_NR = GASTKONT.LNR)
                left outer join SEGMSTAM on (GASTKONT.GAST_GR = SEGMSTAM.SEGMCODE and
                      GASTKONT.MAND_NR = SEGMSTAM.MAND_NR)
                left outer join LEISTSTA on (TEMP_STAT_MANAG.LEIST_LNR = LEISTSTA.LNR)
                left outer join WARENGRU on (LEISTSTA.WG = WARENGRU.LNR)
                inner join ADRESSEN on (ADRESSEN.LNR = GASTKONT.GASTNR_1)

                where ((TEMP_STAT_MANAG.DRUCKNR = :DRUCKNR))

                      and
--                      WARENGRU.DURCHL = 3 --Sonstiges
                      WARENGRU.DURCHL in (3,4,5) --Sonstiges
                      and
                      TEMP_STAT_MANAG.MONAT = extract(month from :P_TMPDATUM) and
                      TEMP_STAT_MANAG.TAG = extract(day from :P_TMPDATUM)) as SEGM_TAGBETRAG_SONSTIGES

        from GASTKONT GA
        inner join ADRESSEN AD on (GA.GASTNR_1 = AD.LNR)
        where AD.ADR_WAHL = 0 and
              (upper(AD.ANREDE) = 'FAMILIE') and
              ((GA.VONAUFH >= :P_TMPDATUM and
              GA.VONAUFH <= :P_TMPDATUM) or (GA.BISAUFH > :P_TMPDATUM and
              GA.BISAUFH <= :P_TMPDATUM) or (GA.VONAUFH < :P_TMPDATUM and
              GA.BISAUFH > :P_TMPDATUM)) and
              --              GA.TA_STATUS < 1000 and
              GA.CI_STATUS < 2 and
              GA.BELEGUNGSART < 3 and
              GA.MAND_NR = MAND_NR
        group by GA.BUCH_STATUS

        union

        select :P_TMPDATUM as SEGM_DATUM, '1' as SEGM_ID, 'FREIZEITGAST' as SEGM_NAME,

               /* Umsatz Logi */
               (select iif(sum(B_TAG) is Null, 0, sum(B_TAG))
                from TEMP_STAT_MANAG
                left outer join GASTKONT on (TEMP_STAT_MANAG.GR_NR = GASTKONT.LNR)
                left outer join SEGMSTAM on (GASTKONT.GAST_GR = SEGMSTAM.SEGMCODE and
                      GASTKONT.MAND_NR = SEGMSTAM.MAND_NR)
                left outer join LEISTSTA on (TEMP_STAT_MANAG.LEIST_LNR = LEISTSTA.LNR)
                left outer join WARENGRU on (LEISTSTA.WG = WARENGRU.LNR)
                inner join ADRESSEN on (ADRESSEN.LNR = GASTKONT.GASTNR_1)
                where ((TEMP_STAT_MANAG.DRUCKNR = :DRUCKNR))

                      and
                      ((upper(ADRESSEN.ANREDE) <> 'FIRMA') and
                      (upper(ADRESSEN.ANREDE) <> 'FAMILIE'))

                      and
                      WARENGRU.DURCHL = 0 --Logi
                      --and WARENGRU.DURCHL = 1 --F&B
                      --and WARENGRU.DURCHL = 2 --Health
                      --and WARENGRU.DURCHL = 3 --Sonstiges

                      and
                      TEMP_STAT_MANAG.MONAT = extract(month from :P_TMPDATUM) and
                      TEMP_STAT_MANAG.TAG = extract(day from :P_TMPDATUM)) as SEGM_TAGBETRAG_LOGI,

               /* Umsatz F&B */
               (select iif(sum(B_TAG) is Null, 0, sum(B_TAG))
                from TEMP_STAT_MANAG
                left outer join GASTKONT on (TEMP_STAT_MANAG.GR_NR = GASTKONT.LNR)
                left outer join SEGMSTAM on (GASTKONT.GAST_GR = SEGMSTAM.SEGMCODE and
                      GASTKONT.MAND_NR = SEGMSTAM.MAND_NR)
                left outer join LEISTSTA on (TEMP_STAT_MANAG.LEIST_LNR = LEISTSTA.LNR)
                left outer join WARENGRU on (LEISTSTA.WG = WARENGRU.LNR)
                inner join ADRESSEN on (ADRESSEN.LNR = GASTKONT.GASTNR_1)
                where ((TEMP_STAT_MANAG.DRUCKNR = :DRUCKNR))

                      and
                      ((upper(ADRESSEN.ANREDE) <> 'FIRMA') and
                      (upper(ADRESSEN.ANREDE) <> 'FAMILIE'))

                      and
                      WARENGRU.DURCHL = 1 --F&B
                      and
                      TEMP_STAT_MANAG.MONAT = extract(month from :P_TMPDATUM) and
                      TEMP_STAT_MANAG.TAG = extract(day from :P_TMPDATUM)) as SEGM_TAGBETRAG_FB,

               /* Umsatz Health */
               (select iif(sum(B_TAG) is Null, 0, sum(B_TAG))
                from TEMP_STAT_MANAG
                left outer join GASTKONT on (TEMP_STAT_MANAG.GR_NR = GASTKONT.LNR)
                left outer join SEGMSTAM on (GASTKONT.GAST_GR = SEGMSTAM.SEGMCODE and
                      GASTKONT.MAND_NR = SEGMSTAM.MAND_NR)
                left outer join LEISTSTA on (TEMP_STAT_MANAG.LEIST_LNR = LEISTSTA.LNR)
                left outer join WARENGRU on (LEISTSTA.WG = WARENGRU.LNR)
                inner join ADRESSEN on (ADRESSEN.LNR = GASTKONT.GASTNR_1)
                where ((TEMP_STAT_MANAG.DRUCKNR = :DRUCKNR))

                      and
                      ((upper(ADRESSEN.ANREDE) <> 'FIRMA') and
                      (upper(ADRESSEN.ANREDE) <> 'FAMILIE'))

                      and
                      WARENGRU.DURCHL = 2 --Health
                      and
                      TEMP_STAT_MANAG.MONAT = extract(month from :P_TMPDATUM) and
                      TEMP_STAT_MANAG.TAG = extract(day from :P_TMPDATUM)) as SEGM_TAGBETRAG_HEALTH,

               /* Umsatz Sonstiges */
               (select iif(sum(B_TAG) is Null, 0, sum(B_TAG))
                from TEMP_STAT_MANAG
                left outer join GASTKONT on (TEMP_STAT_MANAG.GR_NR = GASTKONT.LNR)
                left outer join SEGMSTAM on (GASTKONT.GAST_GR = SEGMSTAM.SEGMCODE and
                      GASTKONT.MAND_NR = SEGMSTAM.MAND_NR)
                left outer join LEISTSTA on (TEMP_STAT_MANAG.LEIST_LNR = LEISTSTA.LNR)
                left outer join WARENGRU on (LEISTSTA.WG = WARENGRU.LNR)
                inner join ADRESSEN on (ADRESSEN.LNR = GASTKONT.GASTNR_1)
                where ((TEMP_STAT_MANAG.DRUCKNR = :DRUCKNR)) and
                      upper(ADRESSEN.ANREDE) <> 'FIRMA' and
                      upper(ADRESSEN.ANREDE) <> 'FAMILIE'

                      and
--                      WARENGRU.DURCHL = 3 --Sonstiges
                      WARENGRU.DURCHL in (3,4,5 ) --Sonstiges
                      and
                      TEMP_STAT_MANAG.MONAT = extract(month from :P_TMPDATUM) and
                      TEMP_STAT_MANAG.TAG = extract(day from :P_TMPDATUM)) as SEGM_TAGBETRAG_SONSTIGES

        from GASTKONT GA
        inner join ADRESSEN AD1 on (GA.GASTNR_1 = AD1.LNR)
        where AD1.ADR_WAHL = 0 and
              (upper(AD1.ANREDE) <> 'FIRMA' and
              (upper(AD1.ANREDE) <> 'FAMILIE')) and
              ((GA.VONAUFH >= :P_TMPDATUM and
              GA.VONAUFH <= :P_TMPDATUM) or (GA.BISAUFH > :P_TMPDATUM and
              GA.BISAUFH <= :P_TMPDATUM) or (GA.VONAUFH < :P_TMPDATUM and
              GA.BISAUFH > :P_TMPDATUM)) and
              --              GA.TA_STATUS < 1000 and
              GA.CI_STATUS < 2 and
              GA.BELEGUNGSART < 3 and
              GA.MAND_NR = MAND_NR
        group by GA.BUCH_STATUS

        union
        select :P_TMPDATUM as SEGM_DATUM, '2' as SEGM_ID, 'FIRMA' as SEGM_NAME,

               /* Umsatz Logi */
               (select iif(sum(B_TAG) is Null, 0, sum(B_TAG))
                from TEMP_STAT_MANAG
                left outer join GASTKONT on (TEMP_STAT_MANAG.GR_NR = GASTKONT.LNR)
                left outer join SEGMSTAM on (GASTKONT.GAST_GR = SEGMSTAM.SEGMCODE and
                      GASTKONT.MAND_NR = SEGMSTAM.MAND_NR)
                left outer join LEISTSTA on (TEMP_STAT_MANAG.LEIST_LNR = LEISTSTA.LNR)
                left outer join WARENGRU on (LEISTSTA.WG = WARENGRU.LNR)
                inner join ADRESSEN on (ADRESSEN.LNR = GASTKONT.GASTNR_1)

                where ((TEMP_STAT_MANAG.DRUCKNR = :DRUCKNR))

                      and
                      upper(ADRESSEN.ANREDE) = 'FIRMA' and

                      WARENGRU.DURCHL = 0 --Logi
                      --and WARENGRU.DURCHL = 1 --F&B
                      --and WARENGRU.DURCHL = 2 --Health
                      --and WARENGRU.DURCHL = 3 --Sonstiges

                      and
                      TEMP_STAT_MANAG.MONAT = extract(month from :P_TMPDATUM) and
                      TEMP_STAT_MANAG.TAG = extract(day from :P_TMPDATUM)) as SEGM_TAGBETRAG_LOGI,

               /* Umsatz F&B */
               (select iif(sum(B_TAG) is Null, 0, sum(B_TAG))
                from TEMP_STAT_MANAG
                left outer join GASTKONT on (TEMP_STAT_MANAG.GR_NR = GASTKONT.LNR)
                left outer join SEGMSTAM on (GASTKONT.GAST_GR = SEGMSTAM.SEGMCODE and
                      GASTKONT.MAND_NR = SEGMSTAM.MAND_NR)
                left outer join LEISTSTA on (TEMP_STAT_MANAG.LEIST_LNR = LEISTSTA.LNR)
                left outer join WARENGRU on (LEISTSTA.WG = WARENGRU.LNR)
                inner join ADRESSEN on (ADRESSEN.LNR = GASTKONT.GASTNR_1)

                where ((TEMP_STAT_MANAG.DRUCKNR = :DRUCKNR)) and
                      upper(ADRESSEN.ANREDE) = 'FIRMA'

                      and
                      WARENGRU.DURCHL = 1 --F&B
                      and
                      TEMP_STAT_MANAG.MONAT = extract(month from :P_TMPDATUM) and
                      TEMP_STAT_MANAG.TAG = extract(day from :P_TMPDATUM)) as SEGM_TAGBETRAG_FB,

               /* Umsatz Health */
               (select iif(sum(B_TAG) is Null, 0, sum(B_TAG))
                from TEMP_STAT_MANAG
                left outer join GASTKONT on (TEMP_STAT_MANAG.GR_NR = GASTKONT.LNR)
                left outer join SEGMSTAM on (GASTKONT.GAST_GR = SEGMSTAM.SEGMCODE and
                      GASTKONT.MAND_NR = SEGMSTAM.MAND_NR)
                left outer join LEISTSTA on (TEMP_STAT_MANAG.LEIST_LNR = LEISTSTA.LNR)
                left outer join WARENGRU on (LEISTSTA.WG = WARENGRU.LNR)
                inner join ADRESSEN on (ADRESSEN.LNR = GASTKONT.GASTNR_1)

                where ((TEMP_STAT_MANAG.DRUCKNR = :DRUCKNR))

                      and
                      upper(ADRESSEN.ANREDE) = 'FIRMA' and
                      WARENGRU.DURCHL = 2 --Health
                      and
                      TEMP_STAT_MANAG.MONAT = extract(month from :P_TMPDATUM) and
                      TEMP_STAT_MANAG.TAG = extract(day from :P_TMPDATUM)) as SEGM_TAGBETRAG_HEALTH,

               /* Umsatz Sonstiges */
               (select iif(sum(B_TAG) is Null, 0, sum(B_TAG))
                from TEMP_STAT_MANAG
                left outer join GASTKONT on (TEMP_STAT_MANAG.GR_NR = GASTKONT.LNR)
                left outer join SEGMSTAM on (GASTKONT.GAST_GR = SEGMSTAM.SEGMCODE and
                      GASTKONT.MAND_NR = SEGMSTAM.MAND_NR)
                left outer join LEISTSTA on (TEMP_STAT_MANAG.LEIST_LNR = LEISTSTA.LNR)
                left outer join WARENGRU on (LEISTSTA.WG = WARENGRU.LNR)
                inner join ADRESSEN on (ADRESSEN.LNR = GASTKONT.GASTNR_1)

                where ((TEMP_STAT_MANAG.DRUCKNR = :DRUCKNR))

                      and
                      upper(ADRESSEN.ANREDE) = 'FIRMA' and
--                      WARENGRU.DURCHL = 3 --Sonstiges
                      WARENGRU.DURCHL in (3,4,5) --Sonstiges
                      and
                      TEMP_STAT_MANAG.MONAT = extract(month from :P_TMPDATUM) and
                      TEMP_STAT_MANAG.TAG = extract(day from :P_TMPDATUM)) as SEGM_TAGBETRAG_SONSTIGES

        from GASTKONT GA
        inner join ADRESSEN AD2 on (GA.GASTNR_1 = AD2.LNR)
        where (AD2.ADR_WAHL = 1 or upper(AD2.ANREDE) = 'FIRMA') and
              ((GA.VONAUFH >= :P_TMPDATUM and
              GA.VONAUFH <= :P_TMPDATUM) or (GA.BISAUFH > :P_TMPDATUM and
              GA.BISAUFH <= :P_TMPDATUM) or (GA.VONAUFH < :P_TMPDATUM and
              GA.BISAUFH > :P_TMPDATUM)) and
              --              GA.TA_STATUS < 1000 and
              GA.CI_STATUS < 2 and
              GA.BELEGUNGSART < 3 and
              GA.MAND_NR = MAND_NR
        group by GA.BUCH_STATUS

        into :"SEGM_DATUM", :"SEGM_ID", :"SEGM_NAME", :"SEGM_TAGBETRAG_LOGI",
             :"SEGM_TAGBETRAG_FB", :"SEGM_TAGBETRAG_HEALTH", :"SEGM_TAGBETRAG_SONSTIGES"

    do
    begin
      suspend;
    end

  end

end ^

ALTER PROCEDURE PROC_GET_1ARRANG_PAUSCHALE (BELEGNR INTEGER)
RETURNS (ARRANG_BEZ VARCHAR(255) CHARACTER SET NONE,
PAUSCHALE INTEGER,
AUSWAHL_SYMBOL INTEGER,
MATCHC VARCHAR(20) CHARACTER SET NONE)
AS 
begin
  /* Procedure Text */

  for
    SELECT first 1 buchkont.bezeichn, buchkont.pausch, preislist.auswahl_symbol , preislist.matchc
       FROM BUCHKONT
         inner join preislist on (preislist.lnr = buchkont.prl_lnr)
       where buchkont.gk_lnr = :belegnr
         and buchkont.ta_status<1000 and buchkont.prl_lnr>0
         into :ARRANG_BEZ, :PAUSCHALE, :AUSWAHL_SYMBOL, :MATCHC

  do
  suspend;
end ^

ALTER PROCEDURE PROC_GET_ABREISEN (DATUM DATE)
RETURNS (BELEGNR INTEGER,
ANREDE VARCHAR(30) CHARACTER SET NONE,
NAME1 VARCHAR(60) CHARACTER SET NONE,
NAME2 VARCHAR(60) CHARACTER SET NONE,
STRASSE VARCHAR(60) CHARACTER SET NONE,
LAND VARCHAR(10) CHARACTER SET NONE,
PLZ VARCHAR(10) CHARACTER SET NONE,
ORT VARCHAR(60) CHARACTER SET NONE,
ANREISE DATE,
ABREISE DATE,
ERW INTEGER,
JUG INTEGER,
KIND INTEGER,
ZINR VARCHAR(10) CHARACTER SET NONE,
GASTNR INTEGER)
AS 
declare variable G1 integer;
declare variable G2 integer;
declare variable G3 integer;
declare variable BUCHNR integer;
begin
  /* Procedure Text */

    for
        select gastkont.lnr, gastkont.gastnr_1, gastkont.gastnr_2, gastkont.gastnr_3  from gastkont where gastkont.bisaufh = :DATUM
        and gastkont.ta_status <500
          into :buchnr ,:g1, :g2, :g3
    
    
    do
    begin
      if (g1>0) then
        for
          select proc_get_gkinfo.*, :G1 from proc_get_gkinfo(:buchnr,:g1)
           into   :BELEGNR, :ANREDE, :NAME1, :NAME2, :STRASSE, :LAND, :PLZ, :ORT, :ANREISE, :ABREISE, :ERW, :JUG, :KIND, :ZINR ,:gastnr
        do
        suspend;



      if (g2>0) then
        for
          select proc_get_gkinfo.*, :G2 from proc_get_gkinfo(:buchnr,:g2)
           into   :BELEGNR, :ANREDE, :NAME1, :NAME2, :STRASSE, :LAND, :PLZ, :ORT, :ANREISE, :ABREISE, :ERW, :JUG, :KIND, :ZINR, :gastnr
        do
        suspend;




      if (g3>0) then
        for
          select proc_get_gkinfo.*, :G3 from proc_get_gkinfo(:buchnr,:g3)
           into   :BELEGNR, :ANREDE, :NAME1, :NAME2, :STRASSE, :LAND, :PLZ, :ORT, :ANREISE, :ABREISE, :ERW, :JUG, :KIND,:ZINR, :gastnr
        do
        suspend;

    end
end ^

ALTER PROCEDURE PROC_GET_ABT_TEXTE (LNR_TODO INTEGER)
RETURNS (ABT_TEXT VARCHAR(1024) CHARACTER SET NONE)
AS 
declare variable TEMP_TEXT varchar(100);
begin
  /* Procedure Text */
  ABT_TEXT = '';
  for 

         select texte.BEZEICHN as text_bezeichn
           from todolist_add
             left outer join TEXTE on (TEXTE.lnr = todolist_add.lnr_bereich)
           where todolist_add.todo_lnr = :lnr_todo
                 and todolist_add.ta_status <1000
                 into :temp_text

      --ABT_TEXT = ABT_TEXT; -- + ' ' + temp_text;
  do
  begin
     ABT_TEXT = ABT_TEXT || ' / ' || temp_text;
  end
  suspend;
end ^

ALTER PROCEDURE PROC_GET_ADRESSE (ADR_LNR INTEGER)
RETURNS (ADR_WAHL INTEGER,
SPRACHE INTEGER,
ANREDE VARCHAR(30) CHARACTER SET NONE,
TITEL VARCHAR(30) CHARACTER SET NONE,
NAME1 VARCHAR(60) CHARACTER SET NONE,
NAME2 VARCHAR(60) CHARACTER SET NONE,
STRASSE VARCHAR(60) CHARACTER SET NONE,
LAND VARCHAR(10) CHARACTER SET NONE,
LANDKENN VARCHAR(10) CHARACTER SET NONE,
PLZ VARCHAR(10) CHARACTER SET NONE,
ORT VARCHAR(50) CHARACTER SET NONE,
TELE1 VARCHAR(30) CHARACTER SET NONE,
TELE2 VARCHAR(30) CHARACTER SET NONE,
TELEFAX VARCHAR(30) CHARACTER SET NONE,
GEBDAT DATE,
BERUF VARCHAR(30) CHARACTER SET NONE,
ANREDEBRF VARCHAR(80) CHARACTER SET NONE,
KFZ_KENNZ VARCHAR(20) CHARACTER SET NONE,
LNR INTEGER,
SBEZEICHN VARCHAR(50) CHARACTER SET NONE,
WBEZEICHN VARCHAR(50) CHARACTER SET NONE,
BEMERK BLOB,
TELE3 VARCHAR(30) CHARACTER SET NONE,
E_MAIL VARCHAR(100) CHARACTER SET NONE,
TISCH VARCHAR(10) CHARACTER SET NONE,
PR_CODE INTEGER,
NAMENZUS VARCHAR(60) CHARACTER SET NONE,
SUCHNAME VARCHAR(50) CHARACTER SET NONE,
BEGLEIT VARCHAR(60) CHARACTER SET NONE,
BEGLEIT_V VARCHAR(60) CHARACTER SET NONE,
ANREDE_B VARCHAR(30) CHARACTER SET NONE,
BUCHERL INTEGER)
AS 
begin
  for
    SELECT ADRESSEN.adr_wahl, ADRESSEN.sprache, ADRESSEN.anrede, ADRESSEN.titel, ADRESSEN.name1,
       ADRESSEN.name2, ADRESSEN.strasse, ADRESSEN.land, ADRESSEN.landkenn, ADRESSEN.plz,
       ADRESSEN.ort, ADRESSEN.tele1, ADRESSEN.tele2, ADRESSEN.telefax, ADRESSEN.gebdat,
       ADRESSEN.beruf, ADRESSEN.anredebrf, ADRESSEN.kfz_kennz, ADRESSEN.lnr, ADRESSEN.bemerk,
       ADRESSEN.tele3, ADRESSEN.e_mail, ADRESSEN.tisch, ADRESSEN.pr_code, ADRESSEN.namenzus,
       ADRESSEN.suchname, SPRACHE.bezeichn, ADR_AUSWAHL.bezeichn,
       ADRESSEN.begleit_v, adressen.begleit, adressen.anrede_b, adressen.bucherl

    FROM ADRESSEN
       LEFT OUTER JOIN SPRACHE ON (ADRESSEN.sprache = SPRACHE.lnr)
       LEFT OUTER JOIN  ADR_AUSWAHL ON (ADRESSEN.adr_wahl = ADR_AUSWAHL.lnr)

    WHERE ADRESSEN.LNR = :"ADR_LNR"

    INTO   :"ADR_WAHL", :"SPRACHE", :"ANREDE", :"TITEL",:"NAME1",:"NAME2",:"STRASSE",
           :"LAND", :"LANDKENN", :"PLZ", :"ORT", :"TELE1", :"TELE2", :"TELEFAX",
           :"GEBDAT", :"BERUF", :"ANREDEBRF", :"KFZ_KENNZ", :"LNR", :"BEMERK",
           :"TELE3", :"E_MAIL", :"TISCH", :"PR_CODE", :"NAMENZUS", :"SUCHNAME",
           :"SBEZEICHN", :"WBEZEICHN", :"BEGLEIT", :"BEGLEIT_V", :"ANREDE_B", :"BUCHERL"
  do
  suspend;
end ^

ALTER PROCEDURE PROC_GET_ADRESSE_2 (ADR_LNR INTEGER)
RETURNS (ADR_WAHL INTEGER,
SPRACHE INTEGER,
ANREDE VARCHAR(30) CHARACTER SET NONE,
TITEL VARCHAR(30) CHARACTER SET NONE,
NAME1 VARCHAR(60) CHARACTER SET NONE,
NAME2 VARCHAR(60) CHARACTER SET NONE,
STRASSE VARCHAR(60) CHARACTER SET NONE,
LAND VARCHAR(10) CHARACTER SET NONE,
LANDKENN VARCHAR(10) CHARACTER SET NONE,
PLZ VARCHAR(10) CHARACTER SET NONE,
ORT VARCHAR(50) CHARACTER SET NONE,
TELE1 VARCHAR(30) CHARACTER SET NONE,
TELE2 VARCHAR(30) CHARACTER SET NONE,
TELEFAX VARCHAR(30) CHARACTER SET NONE,
GEBDAT DATE,
BERUF VARCHAR(30) CHARACTER SET NONE,
ANREDEBRF VARCHAR(80) CHARACTER SET NONE,
KFZ_KENNZ VARCHAR(20) CHARACTER SET NONE,
LNR INTEGER,
SBEZEICHN VARCHAR(50) CHARACTER SET NONE,
WBEZEICHN VARCHAR(50) CHARACTER SET NONE,
BEMERK BLOB,
TELE3 VARCHAR(30) CHARACTER SET NONE,
E_MAIL VARCHAR(100) CHARACTER SET NONE,
TISCH VARCHAR(10) CHARACTER SET NONE,
PR_CODE INTEGER,
NAMENZUS VARCHAR(60) CHARACTER SET NONE,
SUCHNAME VARCHAR(50) CHARACTER SET NONE,
BEGLEIT VARCHAR(60) CHARACTER SET NONE,
BEGLEIT_V VARCHAR(60) CHARACTER SET NONE,
ANREDE_B VARCHAR(30) CHARACTER SET NONE,
BEMERK2 TV2048,
TEXT_LNR1 INTEGER,
ANZ_HIST INTEGER)
AS 
begin
  for
    SELECT ADRESSEN.adr_wahl, ADRESSEN.sprache, ADRESSEN.anrede, ADRESSEN.titel, ADRESSEN.name1,
       ADRESSEN.name2, ADRESSEN.strasse, ADRESSEN.land, ADRESSEN.landkenn, ADRESSEN.plz,
       ADRESSEN.ort, ADRESSEN.tele1, ADRESSEN.tele2, ADRESSEN.telefax, ADRESSEN.gebdat,
       ADRESSEN.beruf, ADRESSEN.anredebrf, ADRESSEN.kfz_kennz, ADRESSEN.lnr, ADRESSEN.bemerk,
       ADRESSEN.tele3, ADRESSEN.e_mail, ADRESSEN.tisch, ADRESSEN.pr_code, ADRESSEN.namenzus,
       ADRESSEN.suchname, SPRACHE.bezeichn, ADR_AUSWAHL.bezeichn,
       ADRESSEN.begleit_v, adressen.begleit, adressen.anrede_b, adressen.bemerk2,
       adressen.texte_lnr1
       ,(select count(*) from gasthist where gasthist.adr_lnr = adressen.lnr and gasthist.ta_status <1000 and gasthist.sto_betrag >0) as anz_hist


    FROM ADRESSEN
       LEFT OUTER JOIN SPRACHE ON (ADRESSEN.sprache = SPRACHE.lnr)
       LEFT OUTER JOIN  ADR_AUSWAHL ON (ADRESSEN.adr_wahl = ADR_AUSWAHL.lnr)

    WHERE ADRESSEN.LNR = :"ADR_LNR"

    INTO   :"ADR_WAHL", :"SPRACHE", :"ANREDE", :"TITEL",:"NAME1",:"NAME2",:"STRASSE",
           :"LAND", :"LANDKENN", :"PLZ", :"ORT", :"TELE1", :"TELE2", :"TELEFAX",
           :"GEBDAT", :"BERUF", :"ANREDEBRF", :"KFZ_KENNZ", :"LNR", :"BEMERK",
           :"TELE3", :"E_MAIL", :"TISCH", :"PR_CODE", :"NAMENZUS", :"SUCHNAME",
           :"SBEZEICHN", :"WBEZEICHN", :"BEGLEIT", :"BEGLEIT_V", :"ANREDE_B", :"BEMERK2",
           :TEXT_LNR1, :ANZ_HIST
  do
  suspend;
end ^

