ALTER PROCEDURE PROC_GET_ADR_REGK RETURNS (BELEGNR INTEGER,
ANREISE TIMESTAMP,
ABREISE TIMESTAMP,
ZINR VARCHAR(10) CHARACTER SET NONE,
NAME1 VARCHAR(60) CHARACTER SET NONE,
NAME2 VARCHAR(60) CHARACTER SET NONE,
BEMERK VARCHAR(100) CHARACTER SET NONE,
AUFP INTEGER,
GESPERRT INTEGER)
AS 
declare variable ci_status integer;
begin
  /* Procedure Text */
  for
      SELECT BELEGNR, ANREISE, ABREISE, ZINR, NAME1, NAME2, BEMERK, AUFP
      FROM GET_BUCH_REGK_VERB
      ORDER BY ZINR, BELEGNR, AUFP
      INTO :BELEGNR, :ANREISE, :ABREISE, :ZINR,
           :NAME1, :NAME2, :BEMERK, :AUFP
  do
  begin
      CI_STATUS = 0;
      if(BELEGNR > 0) THEN
      begin
        for
            select distinct ONLINE_VERBUND.CI_STATUS
            from ONLINE_VERBUND
            where ONLINE_VERBUND.GK_LNR = :BELEGNR
            order by online_verbund.lnr
            INTO :CI_STATUS
        do
        begin
           CI_STATUS = CI_STATUS;
        end
      end
      begin
            if(CI_STATUS != 2) THEN
            begin
               GESPERRT = 0;
               suspend;
            end
      end
  end
end ^

ALTER PROCEDURE PROC_GET_ADR_SELE (GASTNR INTEGER)
RETURNS (SELEKTIONEN VARCHAR(2048) CHARACTER SET NONE)
AS 
declare variable TEMPSTR varchar(50);
begin
  /* Procedure Text */
  :selektionen = '';
  begin
      for
        select selestam.bezeichn
          from selestam
            inner join adr_sele on (adr_sele.sele_lnr = selestam.lnr and selestam.ta_status <1000)
              where adr_sele.adr_lnr = :GASTNR and adr_sele.ta_status <1000
              into :tempstr
    
      do
      begin
        :selektionen = :selektionen || :tempstr || ' | ';
      end

  end
  suspend;
end ^

ALTER PROCEDURE PROC_GET_ANGEBOT_PRO_ANGKATEZI (ANG_LNR INTEGER)
RETURNS (ANG_LAUF INTEGER,
GBETRAG NUMERIC(12, 2),
ANREISE DATE,
ABREISE DATE,
LNR_KATE INTEGER,
LNR_ZINR VARCHAR(255) CHARACTER SET NONE,
ANZ_BUCH INTEGER,
LEIST_BEZ VARCHAR(1024) CHARACTER SET NONE,
ZINR VARCHAR(255) CHARACTER SET NONE,
BILD_LINK VARCHAR(255) CHARACTER SET NONE,
BEZEICHN VARCHAR(255) CHARACTER SET NONE,
ANZ_ZI INTEGER,
ANGKATEZI_LNR INTEGER,
ALT_ZILNR VARCHAR(255) CHARACTER SET NONE,
ALT_ZINR VARCHAR(255) CHARACTER SET NONE,
VERKNR INTEGER,
ERW INTEGER,
JUGEND INTEGER,
KIND INTEGER,
KIND2 INTEGER,
KK INTEGER,
ADR_LNR INTEGER,
ANG_UNDODER INTEGER,
MAND_NR INTEGER,
BEMERK VARCHAR(255) CHARACTER SET NONE)
AS 
declare variable ANG_TEMPLAUF integer;
declare variable TEMPZI_LNR varchar(255);
declare variable TEMPZINR varchar(255);
declare variable TEMPANZBUCH integer;
declare variable TEMP_ALLE_ZILNR varchar(255);
declare variable TEMP_BILD varchar(255);
declare variable TEMP_BEZEICHN varchar(255);
begin
    /* Procedure Text */
    TEMP_ALLE_ZILNR = '0';

    for select ANG_KATE_ZI.LNR, ANG_KATE_ZI.LNR_KATE, ANG_KATE_ZI.VONDATUM, ANG_KATE_ZI.BISDATUM, ANG_KATE_ZI.VERK_NR, ANG_KATE_ZI.ERW,
               ANG_KATE_ZI.JUG, ANG_KATE_ZI.KIND, ANG_KATE_ZI.KIND2, ANG_KATE_ZI.KK, ANGEBOT.ADR_LNR, ANGEBOT.BEMERKUNG
        from ANG_KATE_ZI
        inner join ANGEBOT on (ANGEBOT.LNR = ANG_KATE_ZI.ANG_LNR and
              ANG_KATE_ZI.TA_STATUS < 1000 and
              (ANGEBOT.TERMINDATUM is null or ANGEBOT.TERMINDATUM >= current_date))
        where ANGEBOT.LNR = :ANG_LNR
        group by ANG_KATE_ZI.LNR, ANG_KATE_ZI.LNR_KATE, ANG_KATE_ZI.VONDATUM, ANG_KATE_ZI.BISDATUM, ANG_KATE_ZI.VERK_NR, ANG_KATE_ZI.ERW, ANG_KATE_ZI.JUG, ANG_KATE_ZI.KIND, ANG_KATE_ZI.KIND2, ANG_KATE_ZI.KK, ANGEBOT.ADR_LNR, ANGEBOT.BEMERKUNG
        into :ANGKATEZI_LNR, :LNR_KATE, :ANREISE, :ABREISE, :VERKNR, :ERW, :JUGEND, :KIND, :KIND2, :KK, :ADR_LNR, :BEMERK
    do
    begin
        if (ANGKATEZI_LNR > 0) then
        begin
            ANZ_BUCH = 0;
            TEMPANZBUCH = 0;
            TEMPZI_LNR = 0;
            LNR_ZINR = '';
            TEMPZINR = '';
            ZINR = '';
            BILD_LINK = '';
            BEZEICHN = '';
            ALT_ZILNR = '';
            ALT_ZINR = '';
            ANG_TEMPLAUF = 0;

            select sum(ANG_LEISTUNG.GBETRAG) as GBETRAG, min(ANG_LEISTUNG.ANG_UNDODER), min(zimmstam.mand_nr)
            from ANG_LEISTUNG  
            inner join zimmstam on (zimmstam.lnr = ang_leistung.zimm_lnr)
            where ANG_LEISTUNG.ANG_LNR = :ANG_LNR and
                  ANG_LEISTUNG.ANG_KATE_ZI_LNR = :ANGKATEZI_LNR and
                  ANG_LEISTUNG.TA_STATUS < 1000
            into :GBETRAG, :ANG_UNDODER, :MAND_NR;

            select PROC_GET_LEIST_PRO_ANGKATEZI.LEIST_BEZ
            from PROC_GET_LEIST_PRO_ANGKATEZI(:ANG_LNR, :ANGKATEZI_LNR)
            into :LEIST_BEZ;

            for select ANG_LEISTUNG.ZIMM_LNR, 0 as ANG_LAUF, ANG_LEISTUNG.ANZ_ZI
                from ANG_LEISTUNG
                where ANG_LEISTUNG.ANG_LNR = :ANG_LNR and
                      ANG_LEISTUNG.ANG_KATE_ZI_LNR = :ANGKATEZI_LNR and
                      ANG_LEISTUNG.TA_STATUS < 1000 and
                      ANG_LEISTUNG.PRL_LNR > 0
                group by ANG_LEISTUNG.ZIMM_LNR, ANG_LEISTUNG.ANG_LAUF, ANG_LEISTUNG.ANZ_ZI
                into :TEMPZI_LNR, :ANG_LAUF, :ANZ_ZI
            do
            begin
                if (:TEMPZI_LNR > 0) then
                begin
                    select PROC_ZI_FREI_OHNE_ANGEBOTE.ANZ_BUCH
                    from PROC_ZI_FREI_OHNE_ANGEBOTE(:TEMPZI_LNR, :ANREISE, :ABREISE)
                    into :TEMPANZBUCH;

                    :ANZ_BUCH = :ANZ_BUCH + :TEMPANZBUCH;

                    if (:TEMPANZBUCH = 0) then
                    begin
                        if (:LNR_ZINR != '') then
                            :LNR_ZINR = :LNR_ZINR || ', ';
                        :LNR_ZINR = :LNR_ZINR || :TEMPZI_LNR;

                        select ZIMMSTAM.ZINR, ZIMMSTAM.BILD_LINK, ZIMMSTAM.BEZEICHN
                        from ZIMMSTAM
                        where ZIMMSTAM.LNR = :TEMPZI_LNR
                        into :TEMPZINR, :BILD_LINK, :BEZEICHN;

                        if (:ZINR != '') then
                            :ZINR = :ZINR || ', ';
                        :ZINR = :ZINR || :TEMPZINR;

                        :ANG_TEMPLAUF = :ANG_TEMPLAUF + 1;
                        :TEMP_ALLE_ZILNR = :TEMP_ALLE_ZILNR || ', ' || :TEMPZI_LNR;
                    end
                end
            end

            while (:ANG_TEMPLAUF < :ANZ_ZI) do
            begin
                :TEMPZI_LNR = 0;
                select first 1 ZIMMSTAM.LNR, ZIMMSTAM.ZINR, ZIMMSTAM.BILD_LINK, ZIMMSTAM.BEZEICHN
                from ZIMMSTAM
                where (:TEMP_ALLE_ZILNR = '0' or ZIMMSTAM.LNR not in (select GETINTEGERLIST.ID
                                                                      from GETINTEGERLIST(:TEMP_ALLE_ZILNR, ','))) and
                      ZIMMSTAM.lnr_kate = :LNR_KATE and
                      ZIMMSTAM.VERMIETJN = 1 and
                      ZIMMSTAM.SCHEINZ = 0 and
                      ZIMMSTAM.ta_status < 1000 and
                      (select PROC_ZI_FREI_OHNE_ANGEBOTE.ANZ_BUCH
                       from PROC_ZI_FREI_OHNE_ANGEBOTE(ZIMMSTAM.LNR, :ANREISE, :ABREISE)) = 0
                into :TEMPZI_LNR, :TEMPZINR, :TEMP_BILD, :TEMP_BEZEICHN;

                if (TEMPZI_LNR > 0) then
                begin
                    if (:BILD_LINK = '') then
                        :BILD_LINK = :TEMP_BILD;
                    if (:BEZEICHN = '') then
                        :BEZEICHN = :TEMP_BEZEICHN;

                   if (:ZINR != '') then
                            :ZINR = :ZINR || ', ';
                        :ZINR = :ZINR || :TEMPZINR;

                    if (:ALT_ZILNR != '') then
                        :ALT_ZILNR = :ALT_ZILNR || ', ';
                    :ALT_ZILNR = :ALT_ZILNR || :TEMPZI_LNR;

                    :TEMP_ALLE_ZILNR = :TEMP_ALLE_ZILNR || ', ' || :TEMPZI_LNR;
                end
                :ANG_TEMPLAUF = :ANG_TEMPLAUF + 1;
            end
        end
        if (:BILD_LINK = '' or :ANZ_ZI > 1) then
        begin
            select KATESTAM.BILD_LINK
            from KATESTAM
            where KATESTAM.LNR = :LNR_KATE
            into :BILD_LINK;
        end
        if (:BEZEICHN = '' or :ANZ_ZI > 1) then
        begin
            select KATESTAM.BEMERK1
            from KATESTAM
            where KATESTAM.LNR = :LNR_KATE
            into :BEZEICHN;
        end
        suspend;
    end
end ^

ALTER PROCEDURE PROC_GET_ANGEBOT_PRO_LAUF (ANG_LNR INTEGER)
RETURNS (ANG_LAUF INTEGER,
GBETRAG NUMERIC(12, 2),
ANREISE DATE,
ABREISE DATE,
LNR_KATE INTEGER,
LNR_ZINR INTEGER,
ANZ_BUCH INTEGER,
LEIST_BEZ VARCHAR(1024) CHARACTER SET NONE,
ZINR VARCHAR(255) CHARACTER SET NONE,
BILD_LINK VARCHAR(255) CHARACTER SET NONE,
BEZEICHN VARCHAR(50) CHARACTER SET NONE,
ERW INTEGER,
JUGEND INTEGER,
KIND INTEGER,
ALT_ZILNR INTEGER,
ANZ_ZI INTEGER,
ADR_LNR INTEGER,
MAND_NR INTEGER,
ANG_UNDODER INTEGER,
ANGLNRZI INTEGER,
BEMERK VARCHAR(255) CHARACTER SET NONE)
AS 
declare variable ANG_TEMPLAUF integer;
declare variable TEMPZI_LNR smallint;
declare variable TEMP_ALLE_ZILNR varchar(255);
begin
  :ANG_TEMPLAUF = 0;
  :TEMP_ALLE_ZILNR = '0';
  :ANZ_ZI = 1;
  /* Procedure Text */
  ANG_TEMPLAUF = 0;
  for select ANGEBOT.ADR_LNR, ANGEBOT.BEMERKUNG, ANG_LEISTUNG.ANG_LAUF, ANG_LEISTUNG.ZIMM_LNR, ANG_LEISTUNG.KATE_LNR

      from ANG_LEISTUNG
      inner join ANGEBOT on (ANGEBOT.LNR = ANG_LEISTUNG.ANG_LNR and ANG_LEISTUNG.TA_STATUS < 1000)
      where ANGEBOT.LNR = :ANG_LNR and
            ANGEBOT.TA_STATUS < 1000
      group by ANGEBOT.ADR_LNR, ANGEBOT.BEMERKUNG, ANG_LEISTUNG.ANG_LAUF, ANG_LEISTUNG.ZIMM_LNR, ANG_LEISTUNG.KATE_LNR
      into :ADR_LNR, :BEMERK, :ANG_TEMPLAUF, :TEMPZI_LNR, :LNR_KATE
  do
  begin
    :ALT_ZILNR = 0;
    :ZINR = 0;
    :ANGLNRZI = :TEMPZI_LNR;
    if (ANG_TEMPLAUF > 0) then
    begin
      ANG_LAUF = ANG_TEMPLAUF;

      if (:TEMPZI_LNR > 0) then
      begin
        select sum(ANG_LEISTUNG.GBETRAG) as GBETRAG
        from ANG_LEISTUNG
        where ANG_LEISTUNG.ANG_LNR = :ANG_LNR and
              ANG_LEISTUNG.ZIMM_LNR = :TEMPZI_LNR and
              ANG_LEISTUNG.ANG_LAUF = :ANG_TEMPLAUF and
              ANG_LEISTUNG.TA_STATUS < 1000
        into :GBETRAG;

        select min(ANG_LEISTUNG.VON) as ANREISE, max(ANG_LEISTUNG.BIS) as ABREISE, max(ANG_LEISTUNG.ERW) as ERW,
               max(ANG_LEISTUNG.JUGEND) as JUGEND, max(ANG_LEISTUNG.KIND) as KIND, min(ZIMMSTAM.MAND_NR),
               min(ANG_LEISTUNG.ANG_UNDODER)
        from ANG_LEISTUNG
        inner join ZIMMSTAM on (ZIMMSTAM.LNR = ANG_LEISTUNG.ZIMM_LNR)
        where ANG_LEISTUNG.ANG_LNR = :ANG_LNR and
              ANG_LEISTUNG.ZIMM_LNR = :TEMPZI_LNR and
              ANG_LEISTUNG.ANG_LAUF = :ANG_TEMPLAUF and
              ANG_LEISTUNG.TA_STATUS < 1000 and
              ANG_LEISTUNG.PRL_LNR > 0
        into :ANREISE, :ABREISE, :ERW, :JUGEND, :KIND, :MAND_NR, :ANG_UNDODER;

        select PROC_GET_ANG_LEIST.LEIST_BEZ
        from PROC_GET_ANG_LEIST(:ANG_LNR, :ANG_TEMPLAUF, :TEMPZI_LNR)
        into :LEIST_BEZ;

        select PROC_ZI_FREI_OHNE_ANGEBOTE.ANZ_BUCH
        from PROC_ZI_FREI_OHNE_ANGEBOTE(:TEMPZI_LNR, :ANREISE, :ABREISE)
        into :ANZ_BUCH;

        if (:ANZ_BUCH = 0) then
        begin
          :LNR_ZINR = :TEMPZI_LNR;

          select ZIMMSTAM.ZINR, ZIMMSTAM.BILD_LINK, ZIMMSTAM.BEZEICHN
          from ZIMMSTAM
          where ZIMMSTAM.LNR = :TEMPZI_LNR
          into :ZINR, :BILD_LINK, :BEZEICHN;

          :TEMP_ALLE_ZILNR = :TEMP_ALLE_ZILNR || ', ' || :TEMPZI_LNR;
        end
        else
        begin
          :LNR_ZINR = 0;
          select first 1 ZIMMSTAM.LNR, ZIMMSTAM.ZINR, ZIMMSTAM.BILD_LINK, ZIMMSTAM.BEZEICHN
          from ZIMMSTAM
          where (:TEMP_ALLE_ZILNR = '0' or ZIMMSTAM.LNR not in (select GETINTEGERLIST.ID
                                                                from GETINTEGERLIST(:TEMP_ALLE_ZILNR, ','))) and
                ZIMMSTAM.LNR_KATE = :LNR_KATE and
                ZIMMSTAM.VERMIETJN = 1 and
                ZIMMSTAM.SCHEINZ = 0 and
                ZIMMSTAM.ta_status < 1000 and
                (select PROC_ZI_FREI_OHNE_ANGEBOTE.ANZ_BUCH
                 from PROC_ZI_FREI_OHNE_ANGEBOTE(ZIMMSTAM.LNR, :ANREISE, :ABREISE)) = 0
          into :ALT_ZILNR, :ZINR, :BILD_LINK, :BEZEICHN;

          :TEMP_ALLE_ZILNR = :TEMP_ALLE_ZILNR || ', ' || :ALT_ZILNR;
        end
      end
      if (:BILD_LINK = '' or :ANZ_ZI > 1) then
      begin
        select KATESTAM.BILD_LINK
        from KATESTAM
        where KATESTAM.LNR = :LNR_KATE
        into :BILD_LINK;
      end
      if (:BEZEICHN = '' or :ANZ_ZI > 1) then
      begin
        select KATESTAM.BEMERK1
        from KATESTAM
        where KATESTAM.LNR = :LNR_KATE
        into :BEZEICHN;
      end
      suspend;
    end

  end
  --suspend;

end ^

ALTER PROCEDURE PROC_GET_ANGEBOT_PRO_LAUF_EIN (ANG_LNR INTEGER,
ANG_LAUF INTEGER)
RETURNS (ANREISE DATE,
ABREISE DATE,
LNR_KATE INTEGER,
LNR_ZINR INTEGER,
ADR_LNR INTEGER,
ERW INTEGER,
JUGEND INTEGER,
KIND INTEGER,
ANG_UNDODER INTEGER)
AS 
begin
  /* Procedure Text */

  SELECT angebot.adr_lnr, angebot.erw, angebot.jug, angebot.kind

   FROM angebot

   WHERE angebot.lnr = :ang_lnr

     INTO :ADR_LNR, :ERW, :JUGEND, :KIND;

   select min(ang_leistung.von) AS anreise, max(ang_leistung.bis) AS abreise,
          min(ang_leistung.kate_lnr),  min(ang_leistung.zimm_lnr) , min(ang_leistung.ang_undoder),
          max(ang_leistung.erw), max(ang_leistung.jugend), max(ang_leistung.kind)

          from ang_leistung

          where ang_leistung.ang_lnr = :ANG_LNR
               and ang_leistung.ang_lauf = :ANG_LAUF
               and ang_leistung.ta_status<1000
               and ang_leistung.prl_lnr>0
               into :ANREISE, :ABREISE, :LNR_KATE, :LNR_ZINR, :ANG_UNDODER,
               :ERW, :JUGEND, :KIND;





  suspend;


end ^

ALTER PROCEDURE PROC_GET_ANG_LEIST (ANG_LNR INTEGER,
ANG_LAUF INTEGER,
LNR_ZI INTEGER)
RETURNS (LEIST_BEZ VARCHAR(1024) CHARACTER SET NONE)
AS 
declare variable ARRANG_TEMP varchar(1024);
declare variable SORT_NR integer;
begin
    /* Procedure Text */
    ARRANG_TEMP = '';
    LEIST_BEZ = '';
    for select ANG_LEISTUNG.BEZEICHN, LEISTSTA.SORT_NR
        from ANG_LEISTUNG
        inner join LEISTSTA on (LEISTSTA.LNR = ANG_LEISTUNG.LEIST_LNR)
        where ANG_LEISTUNG.ANG_LNR = :ANG_LNR and
              ANG_LEISTUNG.ZIMM_LNR = :LNR_ZI and
              ANG_LEISTUNG.ANG_LAUF = :ANG_LAUF and
              ANG_LEISTUNG.TA_STATUS < 1000
        group by ANG_LEISTUNG.BEZEICHN, LEISTSTA.SORT_NR
        order by LEISTSTA.SORT_NR
        into :ARRANG_TEMP, :SORT_NR
    do
    begin
        if (position(:ARRANG_TEMP in :LEIST_BEZ) = 0) then
        begin
            if (LEIST_BEZ != '') then
                LEIST_BEZ = LEIST_BEZ || '<br/>';
            LEIST_BEZ = LEIST_BEZ || ARRANG_TEMP;
        end
        --LEIST_BEZ = LEIST_BEZ || '<br/>' || ARRANG_TEMP;
    end

    suspend;
end ^

ALTER PROCEDURE PROC_GET_ANREISEN (DATUM DATE)
RETURNS (BELEGNR INTEGER,
ANREDE VARCHAR(30) CHARACTER SET NONE,
NAME1 VARCHAR(60) CHARACTER SET NONE,
NAME2 VARCHAR(60) CHARACTER SET NONE,
STRASSE VARCHAR(60) CHARACTER SET NONE,
LAND VARCHAR(10) CHARACTER SET NONE,
PLZ VARCHAR(10) CHARACTER SET NONE,
ORT VARCHAR(60) CHARACTER SET NONE,
ANREISE DATE,
ABREISE DATE,
ERW INTEGER,
JUG INTEGER,
KIND INTEGER,
ZINR VARCHAR(10) CHARACTER SET NONE,
GASTNR INTEGER)
AS 
declare variable G1 integer;
declare variable G2 integer;
declare variable G3 integer;
declare variable BUCHNR integer;
begin
  /* Procedure Text */

    for
        select gastkont.lnr, gastkont.gastnr_1, gastkont.gastnr_2, gastkont.gastnr_3  from gastkont where gastkont.vonaufh = :DATUM
        and gastkont.ta_status <500
          into :buchnr ,:g1, :g2, :g3
    
    
    do
    begin
      if (g1>0) then
        for
          select proc_get_gkinfo.*, :G1 from proc_get_gkinfo(:buchnr,:g1)
           into   :BELEGNR, :ANREDE, :NAME1, :NAME2, :STRASSE, :LAND, :PLZ, :ORT, :ANREISE, :ABREISE, :ERW, :JUG, :KIND, :ZINR ,:gastnr
        do
        suspend;



      if (g2>0) then
        for
          select proc_get_gkinfo.*, :G2 from proc_get_gkinfo(:buchnr,:g2)
           into   :BELEGNR, :ANREDE, :NAME1, :NAME2, :STRASSE, :LAND, :PLZ, :ORT, :ANREISE, :ABREISE, :ERW, :JUG, :KIND, :ZINR, :gastnr
        do
        suspend;




      if (g3>0) then
        for
          select proc_get_gkinfo.*, :G3 from proc_get_gkinfo(:buchnr,:g3)
           into   :BELEGNR, :ANREDE, :NAME1, :NAME2, :STRASSE, :LAND, :PLZ, :ORT, :ANREISE, :ABREISE, :ERW, :JUG, :KIND,:ZINR, :gastnr
        do
        suspend;

    end
end ^

ALTER PROCEDURE PROC_GET_ANZAHL_SYS (BUCHNR INTEGER)
RETURNS (ZAHLBETRAG NUMERIC(12, 2))
AS 
declare variable BETRAG numeric(12,2) = 0;
declare variable BETRAG_PROZ numeric(12,2) = 0;
declare variable RUNDUNG integer;
declare variable MINBETRAG integer;
declare variable MAXBETRAG integer;
declare variable TEMPBETRAG numeric(12,2) = 0;
begin
  /* Procedure Text */
  :zahlbetrag = 0.00;

  for

    
      select buchkont.gbetrag,
      sys_stada_global.betrag01, sys_stada_global.rundung,
      sys_stada_global.minbetrag, sys_stada_global.maxbetrag
    
    
      from buchkont
         inner join preislist on (preislist.lnr = buchkont.prl_lnr)
         inner join sys_stada_global on (sys_stada_global.prog_modul = 20 and
             sys_stada_global.matchc = preislist.matchc and
             sys_stada_global.alterskreis = preislist.alterskreis
             and buchkont.von between sys_stada_global.vondatum and sys_stada_global.bisdatum
             and buchkont.tage between sys_stada_global.vontage and sys_stada_global.bistage)
    

    
    
    
       where buchkont.gk_lnr = :BUCHNR
       and buchkont.ta_status <500
       and buchkont.prl_lnr >0

       into :betrag, :betrag_proz, :rundung, :minbetrag, :maxbetrag
   do


   if (:betrag_proz!=0)   then
   begin
      :tempbetrag = ((:betrag/100) *:betrag_proz);
      if (rundung=1) then tempbetrag = round(tempbetrag,0);
      if (rundung=2) then tempbetrag = round(tempbetrag,-1);
      :zahlbetrag = :zahlbetrag + :tempbetrag;
   end
   if (:minbetrag>0 and :minbetrag>:zahlbetrag) then :zahlbetrag = :minbetrag;
   if (:maxbetrag>0 and :zahlbetrag>:maxbetrag) then :zahlbetrag = :maxbetrag;

  suspend;
end ^

ALTER PROCEDURE PROC_GET_ANZ_FREIEZIMMER (VONDATUM DATE,
BISDATUM DATE)
RETURNS (ANZAHL INTEGER)
AS 
declare variable LNR_ZINR integer;
declare variable ANZ_BUCH integer;
begin
  /* Procedure Text */
  anzahl  = 0;

  for
    select lnr from zimmstam
       where zimmstam.ta_status <1000  and zimmstam.scheinz =0
          and zimmstam.vermietjn = 1
       into :lnr_zinr
  do
  if(:"LNR_ZINR" > 0) then
  begin
   for


    select count(*) from belegung b
       where (b.lnr_zinr = :lnr_zinr)
              and (b.ta_status<1000)
              and ((b.anreise>=:VONDATUM and b.anreise<:BISDATUM)
              or   (b.abreise>:VONDATUM and b.abreise<=:BISDATUM)
              or   (b.anreise<:VONDATUM and b.abreise>:BISDATUM) )
            into :anz_buch

   do
     anzahl = 1;
     if (:"ANZ_BUCH">0) then anzahl =0;

   suspend;
   end
end ^

