ALTER PROCEDURE PROC_GET_ARRANG_TAG (BELEGNR INTEGER,
TAG DATE)
RETURNS (BU_ME INTEGER,
BU_BEZ VARCHAR(255) CHARACTER SET NONE,
PREISLIST_MATCH VARCHAR(20) CHARACTER SET NONE,
PR_PENSLIST INTEGER,
LEISTSTA_PENSLIST INTEGER)
AS 
begin
  /* Procedure Text */
  for
   select buchkont.me, buchkont.bezeichn, preislist.matchc , preislist.PENSLIST_LNR, leiststa.penslist_lnr as leiststa_penslist_lnr
       from  buchkont
            left outer join preislist on (buchkont.prl_lnr = preislist.lnr)
            inner join leiststa on (leiststa.lnr = buchkont.leist_lnr)
       where (buchkont.gk_lnr = :belegnr) and (buchkont.ta_status < 1000)
