ALTER PROCEDURE PROC_GET_AUSGB_ANSICHT (LNR_CO INTEGER)
RETURNS (NAME1 VARCHAR(100) CHARACTER SET NONE,
NAME2 VARCHAR(100) CHARACTER SET NONE,
STRASSE VARCHAR(100) CHARACTER SET NONE,
LAND VARCHAR(10) CHARACTER SET NONE,
PLZ VARCHAR(10) CHARACTER SET NONE,
ORT VARCHAR(100) CHARACTER SET NONE,
ANREISE DATE,
ABREISE DATE,
RECHNR INTEGER,
RECH_DATUM DATE,
UMSATZ NUMERIC(12, 2),
STORNO_KZ INTEGER,
BELEGNR INTEGER,
GASTNR INTEGER)
AS 
declare variable TEMP_ADRLNR integer;
declare variable TEMP_BELEGNR integer;
begin
  /* Procedure Text */
  select first 1 ausgbuch.adr_lnr, ausgbuch.belegnr, ausgbuch.rechnr, ausgbuch.rech_dat, ausgbuch.belegnr from  ausgbuch where ausgbuch.lnr_co = :LNR_CO
    into :temp_adrlnr, :temp_belegnr, :rechnr, :rech_datum, :belegnr;


  if (:temp_adrlnr>0) then

  begin
    select adressen.lnr, adressen.name1, adressen.name2, adressen.strasse, adressen.land, adressen.plz, adressen.ort from adressen where lnr = :temp_adrlnr
      into :gastnr,  :name1, :name2,:strasse, :land, :plz, :ort;

    select first 1 gastkont.vonaufh, gastkont.bisaufh from gastkont where gastkont.lnr = :temp_belegnr
      into :anreise, :abreise;

    select sum(coalesce(ausgbuch.umsatz,0) - coalesce(ausgbuch.sto_betrag,0)) from ausgbuch where ausgbuch.lnr_co = :lnr_co
      into :umsatz;

    select first 1 rechnung.storno_kz from rechnung where rechnung.lnr_co = :LNR_CO order by lnr DESC into :storno_kz;
    suspend;
  end

end ^

ALTER PROCEDURE PROC_GET_AUSLASTUNG_GK_MANDANT (VONDATUM DATE,
BISDATUM DATE,
MAND_NR INTEGER)
RETURNS (BELEGNR INTEGER,
ANZAHL INTEGER,
ERW INTEGER,
JUGEND INTEGER,
KINDER INTEGER,
KLEINKINDER INTEGER,
ZINR VARCHAR(10) CHARACTER SET NONE,
TAG_FUER DATE)
AS 
declare variable TAG date;
begin
  /* Procedure Text */
  tag = :vondatum;
  while (tag<=:bisdatum) do
  begin
     for select distinct gastkont.lnr as belegnr

     , count(*) as anzahl, sum(gastkont.perszahl) as erw, sum(gastkont.anzjugend) as jugend, sum(gastkont.anzkinder) as kinder,
        sum(gastkont.anzkleinkind) as kleinkinder, min(zimmstam.zinr) as zinr, :tag
        
        from gastkont
           inner join zimmstam on (zimmstam.lnr = gastkont.lnr_zinr)
           where  :TAG >= gastkont.vonaufh and :TAG < gastkont.bisaufh
           and gastkont.ta_status <1000
           and gastkont.share_nr <=0
           and (zimmstam.scheinz =0 or zimmstam.scheinz is null)
           and zimmstam.mand_nr = :MAND_NR
           and zimmstam.vermietjn = 1
           group by gastkont.lnr

           into :belegnr, :anzahl, :erw, :jugend, :kinder, :kleinkinder, :zinr, :tag_fuer
           do
           suspend;
    tag = tag+1;
  end

end ^

ALTER PROCEDURE PROC_GET_BEGL_ALS_ADR_PRO_GK (BUCHNR INTEGER)
RETURNS (OUTGASTNR INTEGER,
OUTANREDE VARCHAR(50) CHARACTER SET NONE,
OUTTITEL VARCHAR(50) CHARACTER SET NONE,
OUTNAME VARCHAR(100) CHARACTER SET NONE,
OUTVORNAME VARCHAR(100) CHARACTER SET NONE,
OUTSTRASSE VARCHAR(100) CHARACTER SET NONE,
OUTLAND VARCHAR(10) CHARACTER SET NONE,
OUTPLZ VARCHAR(10) CHARACTER SET NONE,
OUTORT VARCHAR(60) CHARACTER SET NONE,
OUTGEBDAT DATE,
OUT_IMHAUS INTEGER)
AS 
declare variable B1OK integer;
declare variable B2OK integer;
declare variable B3OK integer;
declare variable B4OK integer;
declare variable B5OK integer;
declare variable B6OK integer;
declare variable GASTNR integer;
declare variable LAUF integer;
begin
  /* Procedure Text */

  select gastkont.begleitok, gastkont.kind1ok, gastkont.kind2ok, gastkont.kind3ok, gastkont.kind4ok, gastkont.kind5ok, gastkont.gastnr_1

     from gastkont where gastkont.lnr = :BUCHNR
       into :b1ok, :b2ok, :b3ok , :b4ok, :b5ok, :b6ok, :gastnr;

  lauf=0;
  begin
    for

        select adressen.lnr, adressen.anrede, adressen.titel, adressen.name1, adressen.name2, adressen.strasse, adressen.land, adressen.plz,  adressen.ort, adressen.gebdat
    
        from adr_verkn
          inner join adressen on (adressen.lnr = adr_verkn.adr_verk and adr_verkn.ta_status<1000 and adressen.ta_status<1000)
             where adr_verkn.adr_lnr = :gastnr
          order by adr_verkn.lnr
             into :outgastnr, :outanrede, :outtitel, :outname, :outvorname, :outstrasse, :outland, :outplz, :outort, :outgebdat
    
    

    do
    begin
      :out_imhaus = 0;
      if (lauf=0 and b1ok=1) then :out_imhaus = 1;
      if (lauf=1 and b2ok=1) then :out_imhaus = 1;
      if (lauf=2 and b3ok=1) then :out_imhaus = 1;
      if (lauf=3 and b4ok=1) then :out_imhaus = 1;
      if (lauf=4 and b5ok=1) then :out_imhaus = 1;
      if (lauf=5 and b6ok=1) then :out_imhaus = 1;
      lauf = lauf+1;
      suspend;
    end
  end
end ^

ALTER PROCEDURE PROC_GET_BEGL_K_NAMEN (GASTNR INTEGER)
RETURNS (BEGL_NAME VARCHAR(60) CHARACTER SET NONE,
BEGL_VORNAME VARCHAR(60) CHARACTER SET NONE,
K1_NAME VARCHAR(60) CHARACTER SET NONE,
K1_VORNAME VARCHAR(60) CHARACTER SET NONE,
K2_NAME VARCHAR(60) CHARACTER SET NONE,
K2_VORNAME VARCHAR(60) CHARACTER SET NONE,
K3_NAME VARCHAR(60) CHARACTER SET NONE,
K3_VORNAME VARCHAR(60) CHARACTER SET NONE,
K4_NAME VARCHAR(60) CHARACTER SET NONE,
K4_VORNAME VARCHAR(60) CHARACTER SET NONE,
K5_NAME VARCHAR(60) CHARACTER SET NONE,
K5_VORNAME VARCHAR(60) CHARACTER SET NONE)
AS 
begin
  /* Procedure Text */
  for
  select a.begleit, a.begleit_v,
         a.k1_nname, a.k1,
         a.k2_nname, a.k2,
         a.k3_nname, a.k3,
         a.k4_nname, a.k4,
         a.k5_nname, a.k5


     from adressen a

     where a.lnr = :"GASTNR"
        into
              :"BEGL_NAME", :"BEGL_VORNAME",
              :"K1_NAME", :"K1_VORNAME",
              :"K2_NAME", :"K2_VORNAME",
              :"K3_NAME", :"K3_VORNAME",
              :"K4_NAME", :"K4_VORNAME",
              :"K5_NAME", :"K5_VORNAME"

  do
  suspend;
end ^

ALTER PROCEDURE PROC_GET_BUCHUNGEN (VONDATUM DATE,
BISDATUM DATE,
AUSWAHL INTEGER)
RETURNS (OUT_BUCHNR INTEGER,
OUT_ANREISE DATE,
OUT_ABREISE DATE,
OUT_GK_BEMERK VARCHAR(512) CHARACTER SET NONE,
OUT_GK_CI_STATUS INTEGER,
OUT_PERSZAHL INTEGER,
OUT_ANZJUGEND INTEGER,
OUT_ANZKINDER INTEGER,
OUT_ANZKK INTEGER,
OUT_KATEGORIE VARCHAR(30) CHARACTER SET NONE,
OUT_ZINR VARCHAR(20) CHARACTER SET NONE,
OUT_TITEL VARCHAR(50) CHARACTER SET NONE,
OUT_ANREDE VARCHAR(50) CHARACTER SET NONE,
OUT_NAME1 VARCHAR(100) CHARACTER SET NONE,
OUT_NAME2 VARCHAR(100) CHARACTER SET NONE,
OUT_STRASSE VARCHAR(100) CHARACTER SET NONE,
OUT_LAND VARCHAR(10) CHARACTER SET NONE,
OUT_PLZ VARCHAR(10) CHARACTER SET NONE,
OUT_ORT VARCHAR(100) CHARACTER SET NONE,
OUT_EMAIL VARCHAR(100) CHARACTER SET NONE,
OUT_GASTNR INTEGER,
OUT_GEBDATUM DATE,
OUT_HOCHZEIT DATE,
OUT_COUNT_HIST INTEGER,
OUT_PERS_TRACE INTEGER,
OUT_RESV_TRACE INTEGER,
OUT_BEGLEIT VARCHAR(100) CHARACTER SET NONE,
OUT_BEGLEIT_V VARCHAR(100) CHARACTER SET NONE,
OUT_BEGLEIT_G DATE,
OUT_K1_GEB DATE,
OUT_K2_GEB DATE,
OUT_K3_GEB DATE,
OUT_K4_GEB DATE,
OUT_K5_GEB DATE,
OUT_ADR_MAIN INTEGER,
OUT_LAST_STAY_FROM DATE,
OUT_LAST_STAY_TO DATE,
OUT_TABLENUMBER VARCHAR(10) CHARACTER SET NONE,
ROOM_STATUS INTEGER,
OUT_SALDO NUMERIC(12, 2))
AS 
begin
  /* Procedure Text */
  if (:auswahl=0) then
  begin

      for

      select gastkont.lnr as buchnr, gastkont.vonaufh as anreise, gastkont.bisaufh as abreise, gastkont.bemerk, gastkont.ci_status,
      coalesce(gastkont.perszahl,0) as perszahl, coalesce(gastkont.anzjugend,0) as anzjugend,
      coalesce(gastkont.anzkinder,0) + coalesce(gastkont.anzkinder2,0) as anzkinder,
      coalesce(gastkont.anzkleinkind,0) as anzkleinkind,
      katestam.kategorie, zimmstam.zinr,
      adressen.titel, adressen.anrede, adressen.name1, adressen.name2, adressen.strasse, adressen.land, adressen.plz,  adressen.ort
      ,adressen.e_mail, adressen.lnr as gastnr, adressen.gebdat, adressen.hochzeitstag,
      (select count(*) from gasthist where gasthist.adr_lnr = adressen.lnr and (gasthist.sto_betrag is null or gasthist.sto_betrag=0) and gasthist.ta_status <1000) as anz_history,
      (select count(*) from todolist where todolist.adr_lnr = adressen.lnr and todolist.ta_status <1000) as anz_pers_tracing,
      (select count(*) from todolist where todolist.gk_lnr = gastkont.lnr and todolist.ta_status <1000) as anz_reserv_tracing,
      adressen.begleit, adressen.begleit_v, adressen.begleit_g,
      adressen.k1_geb, adressen.k2_geb, adressen.k3_geb, adressen.k4_geb, adressen.k5_geb, 0 ,
      proc_get_last_hist.vondatum, proc_get_last_hist.bisdatum ,
      (select first 1 tischplan.tischnr
           from tischbelegung
              left outer join tischplan on (tischplan.lnr = tischbelegung.tischplan_lnr)
           where (tischbelegung.gk_lnr = gastkont.lnr and tischbelegung.ta_status <1000 and :vondatum between tischbelegung.vonbelg and tischbelegung.bisbelg))
      ,zimmstam.clean_st

      ,(select GET_OFFEN_ZAHLBETRAG.offen_betrag from GET_OFFEN_ZAHLBETRAG(gastkont.lnr)) as offenen_betrag
         from gastkont
            inner join adressen on (adressen.lnr = gastkont.gastnr_1 and gastkont.gastnr_1>0)
            left outer join katestam on (katestam.lnr = gastkont.lnr_kate)
            left outer join zimmstam on (zimmstam.lnr = gastkont.lnr_zinr)
            left outer join proc_get_last_hist(adressen.lnr) on (1=1)
           where gastkont.vonaufh between :vondatum and :bisdatum and gastkont.ta_status <1000  and coalesce(zimmstam.scheinz,0)=0
         into :out_buchnr, :out_anreise, :out_abreise,:out_gk_bemerk, :out_gk_ci_status,
         :out_perszahl, :out_anzjugend, :out_anzkinder, :out_anzkk,
         :out_kategorie, :out_zinr,
         :out_titel, :out_anrede, :out_name1, :out_name2, :out_strasse, :out_land, :out_plz, :out_ort, :out_email, :out_gastnr, :out_gebdatum,
         :out_hochzeit, :out_count_hist, :out_pers_trace, :out_resv_trace,
         :out_begleit, :out_begleit_v, :out_begleit_g, :out_k1_geb, :out_k2_geb,
         :out_k3_geb, :out_k4_geb, :out_k5_geb, :out_adr_main,
         :out_last_stay_from, :out_last_stay_to, :out_tablenumber, :room_status, :out_saldo
     do
     suspend;

  end


  if (:auswahl=1) then -- bleiben
  begin

      for

      select gastkont.lnr as buchnr, gastkont.vonaufh as anreise, gastkont.bisaufh as abreise, gastkont.bemerk, gastkont.ci_status,
      coalesce(gastkont.perszahl,0) as perszahl, coalesce(gastkont.anzjugend,0) as anzjugend,
      coalesce(gastkont.anzkinder,0) + coalesce(gastkont.anzkinder2,0) as anzkinder,
      coalesce(gastkont.anzkleinkind,0) as anzkleinkind,
      katestam.kategorie, zimmstam.zinr,
      adressen.titel, adressen.anrede, adressen.name1, adressen.name2, adressen.strasse, adressen.land, adressen.plz,  adressen.ort
      ,adressen.e_mail, adressen.lnr as gastnr, adressen.gebdat, adressen.hochzeitstag,
      (select count(*) from gasthist where gasthist.adr_lnr = adressen.lnr and (gasthist.sto_betrag is null or gasthist.sto_betrag=0) and gasthist.ta_status <1000) as anz_history,
      (select count(*) from todolist where todolist.adr_lnr = adressen.lnr and todolist.ta_status <1000) as anz_pers_tracing,
      (select count(*) from todolist where todolist.gk_lnr = gastkont.lnr and todolist.ta_status <1000) as anz_reserv_tracing,
      adressen.begleit, adressen.begleit_v, adressen.begleit_g,
      adressen.k1_geb, adressen.k2_geb, adressen.k3_geb, adressen.k4_geb, adressen.k5_geb ,0,
      proc_get_last_hist.vondatum, proc_get_last_hist.bisdatum,
      (select first 1 tischplan.tischnr
           from tischbelegung
              left outer join tischplan on (tischplan.lnr = tischbelegung.tischplan_lnr)
           where (tischbelegung.gk_lnr = gastkont.lnr and tischbelegung.ta_status <1000 and :vondatum between tischbelegung.vonbelg and tischbelegung.bisbelg))
      ,zimmstam.clean_st
      ,(select GET_OFFEN_ZAHLBETRAG.offen_betrag from GET_OFFEN_ZAHLBETRAG(gastkont.lnr)) as offenen_betrag
         from gastkont
            inner join adressen on (adressen.lnr = gastkont.gastnr_1 and gastkont.gastnr_1>0)
            left outer join katestam on (katestam.lnr = gastkont.lnr_kate)
            left outer join zimmstam on (zimmstam.lnr = gastkont.lnr_zinr)
            left outer join proc_get_last_hist(adressen.lnr) on (1=1)
           where (:vondatum between gastkont.vonaufh and gastkont.bisaufh or
                  :bisdatum between gastkont.vonaufh and gastkont.bisaufh or
                  (:vondatum < gastkont.vonaufh  and :bisdatum > gastkont.bisaufh ))
                   and gastkont.ta_status <1000
         into :out_buchnr, :out_anreise, :out_abreise,:out_gk_bemerk, :out_gk_ci_status,
              :out_perszahl, :out_anzjugend, :out_anzkinder, :out_anzkk,
              :out_kategorie, :out_zinr,
              :out_titel, :out_anrede, :out_name1, :out_name2, :out_strasse, :out_land, :out_plz, :out_ort, :out_email, :out_gastnr, :out_gebdatum,
              :out_hochzeit, :out_count_hist, :out_pers_trace, :out_resv_trace,
              :out_begleit, :out_begleit_v, :out_begleit_g, :out_k1_geb, :out_k2_geb,
              :out_k3_geb, :out_k4_geb, :out_k5_geb, :out_adr_main,
              :out_last_stay_from, :out_last_stay_to, :out_tablenumber, :room_status, :out_saldo
     do
     suspend;
  end

  if (:auswahl=2) then -- abreisen
  begin

      for

      select gastkont.lnr as buchnr, gastkont.vonaufh as anreise, gastkont.bisaufh as abreise, gastkont.bemerk, gastkont.ci_status,
      coalesce(gastkont.perszahl,0) as perszahl, coalesce(gastkont.anzjugend,0) as anzjugend,
      coalesce(gastkont.anzkinder,0) + coalesce(gastkont.anzkinder2,0) as anzkinder,
      coalesce(gastkont.anzkleinkind,0) as anzkleinkind,
      katestam.kategorie, zimmstam.zinr,
      adressen.titel, adressen.anrede, adressen.name1, adressen.name2, adressen.strasse, adressen.land, adressen.plz,  adressen.ort
      ,adressen.e_mail, adressen.lnr as gastnr, adressen.gebdat, adressen.hochzeitstag,
      (select count(*) from gasthist where gasthist.adr_lnr = adressen.lnr and (gasthist.sto_betrag is null or gasthist.sto_betrag=0) and gasthist.ta_status <1000) as anz_history,
      (select count(*) from todolist where todolist.adr_lnr = adressen.lnr and todolist.ta_status <1000) as anz_pers_tracing,
      (select count(*) from todolist where todolist.gk_lnr = gastkont.lnr and todolist.ta_status <1000) as anz_reserv_tracing,
      adressen.begleit, adressen.begleit_v, adressen.begleit_g,
      adressen.k1_geb, adressen.k2_geb, adressen.k3_geb, adressen.k4_geb, adressen.k5_geb ,0,
      proc_get_last_hist.vondatum, proc_get_last_hist.bisdatum,
      (select first 1 tischplan.tischnr
           from tischbelegung
              left outer join tischplan on (tischplan.lnr = tischbelegung.tischplan_lnr)
           where (tischbelegung.gk_lnr = gastkont.lnr and tischbelegung.ta_status <1000 and :vondatum between tischbelegung.vonbelg and tischbelegung.bisbelg))
      ,zimmstam.clean_st
      ,(select GET_OFFEN_ZAHLBETRAG.offen_betrag from GET_OFFEN_ZAHLBETRAG(gastkont.lnr)) as offenen_betrag
         from gastkont
            inner join adressen on (adressen.lnr = gastkont.gastnr_1 and gastkont.gastnr_1>0)
            left outer join katestam on (katestam.lnr = gastkont.lnr_kate)
            left outer join zimmstam on (zimmstam.lnr = gastkont.lnr_zinr)
            left outer join proc_get_last_hist(adressen.lnr) on (1=1)
           where gastkont.bisaufh between :vondatum and :bisdatum and gastkont.ta_status <1000
         into :out_buchnr, :out_anreise, :out_abreise,:out_gk_bemerk, :out_gk_ci_status,
         :out_perszahl, :out_anzjugend, :out_anzkinder, :out_anzkk,
         :out_kategorie, :out_zinr,
         :out_titel, :out_anrede, :out_name1, :out_name2, :out_strasse, :out_land, :out_plz, :out_ort, :out_email, :out_gastnr, :out_gebdatum,
         :out_hochzeit, :out_count_hist, :out_pers_trace, :out_resv_trace,
         :out_begleit, :out_begleit_v, :out_begleit_g, :out_k1_geb, :out_k2_geb,
         :out_k3_geb, :out_k4_geb, :out_k5_geb, :out_adr_main,
         :out_last_stay_from, :out_last_stay_to, :out_tablenumber, :room_status, :out_saldo
     do
     suspend;
  end



end ^

ALTER PROCEDURE PROC_GET_BUCH_ANAB (MAND_NR INTEGER,
ANREISE DATE,
ABREISE DATE)
RETURNS (B_LNR INTEGER,
LNR_ZINR INTEGER,
LNR_GK INTEGER,
VON DATE,
BIS DATE,
FARBE INTEGER,
ANZ_ZI INTEGER,
NAME1 VARCHAR(80) CHARACTER SET NONE,
NAME2 VARCHAR(80) CHARACTER SET NONE,
BUCH_STATUS INTEGER,
BU_ST_OPTION INTEGER,
BEMERK VARCHAR(100) CHARACTER SET NONE,
CI_STATUS INTEGER)
AS 
begin
  /* Procedure Text */
  for
    SELECT BELEGUNG.LNR, BELEGUNG.LNR_ZINR, BELEGUNG.LNR_GK, BELEGUNG.ANREISE, BELEGUNG.ABREISE, BELEGUNG.FARBE,
     BELEGUNG.ANZ_ZI,  ADRESSEN.NAME1, ADRESSEN.NAME2,
     GASTKONT.BUCH_STATUS, GASTKONT.BU_ST_OPTION, GASTKONT.BEMERK, GASTKONT.CI_STATUS
    FROM ADRESSEN
    INNER JOIN GASTKONT ON (ADRESSEN.LNR = GASTKONT.GASTNR_1)
    INNER JOIN BELEGUNG ON (GASTKONT.LNR = BELEGUNG.LNR_GK)
    WHERE
     (
      (belegung.TA_STATUS<1000)
      and
      (GASTKONT.MAND_NR = :"MAND_NR")
       and
      ((belegung.anreise>=:"ANREISE" and belegung.anreise<:"ABREISE") or
       (belegung.abreise>:"ANREISE" and belegung.abreise<=:"ABREISE") or
       (belegung.anreise<:"ANREISE" and belegung.abreise>:"ABREISE"))
     )
      into :"B_LNR", :"LNR_ZINR",:"LNR_GK", :"VON", :"BIS", :"FARBE",
      :"ANZ_ZI", :"NAME1", :"NAME2", :"BUCH_STATUS",:"BU_ST_OPTION", :"BEMERK", :"CI_STATUS"
  do
  suspend;
end ^

