     BELEGUNG.ANZ_ZI,  ADRESSEN.NAME1, ADRESSEN.NAME2,
     GASTKONT.BUCH_STATUS, GASTKONT.BU_ST_OPTION, GASTKONT.BEMERK, GASTKONT.CI_STATUS
    FROM ADRESSEN
    INNER JOIN GASTKONT ON (ADRESSEN.LNR = GASTKONT.GASTNR_1)
    INNER JOIN BELEGUNG ON (GASTKONT.LNR = BELEGUNG.LNR_GK)
    WHERE
     (
        (GASTKONT.MAND_NR = :"MAND_NR")
       and
      ((belegung.anreise>=:"ANREISE" and belegung.anreise<:"ABREISE") or
       (belegung.abreise>:"ANREISE" and belegung.abreise<=:"ABREISE") or
       (belegung.anreise<:"ANREISE" and belegung.abreise>:"ABREISE"))
     )
      into :"B_LNR", :"LNR_ZINR",:"LNR_GK", :"VON", :"BIS", :"FARBE",
      :"ANZ_ZI", :"NAME1", :"NAME2", :"BUCH_STATUS",:"BU_ST_OPTION", :"BEMERK", :"CI_STATUS"
  do
  suspend;
end ^

ALTER PROCEDURE PROC_GET_BUCH_PRO_ZI (ZINR_LNR INTEGER,
SELEVON DATE,
SELEBIS DATE)
RETURNS (ANREISE DATE,
ABREISE DATE)
AS 
begin
  /* Procedure Text */
  for
     select b.anreise, b.abreise
     from belegung b
         inner join gastkont on (gastkont.lnr = b.lnr_gk and gastkont.share_nr=0)
     where b.lnr_zinr = :"ZINR_LNR"
       and b.ta_status<500

     and
      ((b.anreise>=:"SELEVON" and b.anreise<:"SELEBIS")
      or
      (b.abreise>:"SELEVON" and b.abreise<=:"SELEBIS")
       or
      (b.anreise<:"SELEVON" and b.abreise>:"SELEBIS"))

     into :"ANREISE", :"ABREISE"
  do
  suspend;
end ^

ALTER PROCEDURE PROC_GET_FAKT_ERLOS (STATUS INTEGER,
VONDATUM DATE,
BISDATUM DATE,
MANDNR INTEGER)
RETURNS (LNR INTEGER,
MAND_NR INTEGER,
BUDAT DATE,
BELEGNR INTEGER,
LNR_LEIST INTEGER,
BEZEICHN VARCHAR(100) CHARACTER SET NONE,
BETRAG NUMERIC(12, 3),
RECHNR INTEGER,
RE_LAUF INTEGER,
VONAUFH DATE,
BISAUFH DATE,
MANUELL INTEGER,
TA_STATUS INTEGER,
LNR_BUCHKONT INTEGER,
ADR_LNR INTEGER,
KONTONR VARCHAR(10) CHARACTER SET NONE,
NAME1 VARCHAR(60) CHARACTER SET NONE,
NAME2 VARCHAR(60) CHARACTER SET NONE,
STRASSE VARCHAR(60) CHARACTER SET NONE,
LAND VARCHAR(10) CHARACTER SET NONE,
PLZ VARCHAR(10) CHARACTER SET NONE,
ORT VARCHAR(50) CHARACTER SET NONE,
STSATZ NUMERIC(12, 3))
AS 
begin
  /* Procedure Text */
  for
    SELECT FAKT_ERLOESE.LNR, FAKT_ERLOESE.MAND_NR, FAKT_ERLOESE.BUDAT, FAKT_ERLOESE.BELEGNR, FAKT_ERLOESE.lnr_leist,
           FAKT_ERLOESE.BEZEICHN, FAKT_ERLOESE.BETRAG, FAKT_ERLOESE.RECHNR,
           FAKT_ERLOESE.RE_LAUF, FAKT_ERLOESE.VOND, FAKT_ERLOESE.BISD,
           FAKT_ERLOESE.MANUELL, FAKT_ERLOESE.TA_STATUS, FAKT_ERLOESE.LNR_BUCHKONT, FAKT_ERLOESE.ADR_LNR,
           LEISTSTA.KONTONR,
           ADRESSEN.NAME1, ADRESSEN.NAME2, ADRESSEN.STRASSE, ADRESSEN.LAND, ADRESSEN.PLZ, ADRESSEN.ORT,
           STEUSTAM.stsatz
    FROM fakt_erloese
           INNER JOIN LEISTSTA ON (FAKT_ERLOESE.lnr_leist = LEISTSTA.LNR)
           INNER JOIN STEUSTAM ON (fakt_erloese.st_schl   = STEUSTAM.lnr)
           LEFT OUTER JOIN ADRESSEN ON (FAKT_ERLOESE.adr_lnr   = ADRESSEN.LNR)
      where
         fakt_erloese.budat>= :VONDATUM and
         fakt_erloese.budat<= :BISDATUM and
         fakt_erloese.ta_status <= :status and
         fakt_erloese.mand_nr = :mandnr

         into :"LNR", :"MAND_NR", :"BUDAT" , :"BELEGNR", :"LNR_LEIST",
              :"BEZEICHN", :"BETRAG", :"RECHNR",
              :"RE_LAUF", :"VONAUFH", :"BISAUFH",
              :"MANUELL", :"TA_STATUS", :"LNR_BUCHKONT", :"ADR_LNR",
              :"KONTONR",
              :"NAME1", :"NAME2", :"STRASSE", :"LAND", :"PLZ", :"ORT",
              :"STSATZ"



  do
  suspend;
end ^

ALTER PROCEDURE PROC_GET_FIRST_ARRANG (BUCHNR INTEGER)
RETURNS (BEZEICHN VARCHAR(512) CHARACTER SET NONE)
AS 
begin
  /* Procedure Text */
  for
  select first 1 buchkont.bezeichn
     from buchkont
       where buchkont.gk_lnr = :BUCHNR
       and buchkont.prl_lnr>0
       and buchkont.ta_status<1000
     order by buchkont.lnr
       into :BEZEICHN
  do
  suspend;
end ^

ALTER PROCEDURE PROC_GET_GASTKZUS_TEXT (GK_LNR INTEGER)
RETURNS (ZUS_TXT VARCHAR(1024) CHARACTER SET NONE)
AS 
declare variable STR_LENGTH integer;
declare variable TEMP_TXT varchar(50);
begin
  /* Procedure Text */
  ZUS_TXT = '';
  FOR
  SELECT ZUSATZ_TEXT.BEZEICHN
  FROM GASTKZUS_TEXT
     INNER JOIN ZUSATZ_TEXT ON (GASTKZUS_TEXT.ZUSTEXT_LNR = ZUSATZ_TEXT.LNR)
     where gastkzus_text.gk_lnr = :GK_LNR and gastkzus_text.ta_status < 1000
  ORDER BY ZUSATZ_TEXT.GRUPPEN_NR
  into   :TEMP_TXT
  do
  if(char_length(TEMP_TXT) > 0) then
  begin
     ZUS_TXT = ZUS_TXT || TEMP_TXT ||  ', ';
  end
  if(char_length(ZUS_TXT) > 2) then
  begin
    STR_LENGTH = char_length(ZUS_TXT) -2;
    ZUS_TXT = substring( ZUS_TXT from 1 for STR_LENGTH );
    suspend;
  end
end ^

ALTER PROCEDURE PROC_GET_GEBD_I_HAUS (DATUM DATE,
TAG INTEGER,
MONAT INTEGER)
RETURNS (GASTNR INTEGER,
BELEGNR INTEGER,
NAME1 VARCHAR(60) CHARACTER SET NONE,
NAME2 VARCHAR(60) CHARACTER SET NONE,
BEGLEIT VARCHAR(60) CHARACTER SET NONE,
BEGLEIT_V VARCHAR(60) CHARACTER SET NONE,
K1 VARCHAR(60) CHARACTER SET NONE,
K1_NNAME VARCHAR(60) CHARACTER SET NONE,
K2 VARCHAR(60) CHARACTER SET NONE,
K2_NNAME VARCHAR(60) CHARACTER SET NONE,
K3 VARCHAR(60) CHARACTER SET NONE,
K3_NNAME VARCHAR(60) CHARACTER SET NONE,
K4 VARCHAR(60) CHARACTER SET NONE,
K4_NNAME VARCHAR(60) CHARACTER SET NONE,
K5 VARCHAR(60) CHARACTER SET NONE,
K5_NNAME VARCHAR(60) CHARACTER SET NONE,
GEBDAT DATE,
BEGLEIT_G DATE,
K1_GEB DATE,
K2_GEB DATE,
K3_GEB DATE,
K4_GEB DATE,
K5_GEB DATE,
VONAUFH DATE,
BISAUFH DATE,
ZINR VARCHAR(10) CHARACTER SET NONE,
BEMERK VARCHAR(100) CHARACTER SET NONE)
AS 
begin
  /* Procedure Text */
    FOR

        select
        
        adressen.lnr ,  gastkont.lnr as belegnr,
        adressen.name1, adressen.name2,
        adressen.begleit, adressen.begleit_v,
        adressen.k1, adressen.k1_nname,
        adressen.k2, adressen.k2_nname,
        adressen.k3, adressen.k3_nname,
        adressen.k4, adressen.k4_nname,
        adressen.k5, adressen.k5_nname,
        
        
        
        adressen.gebdat, adressen.begleit_g,
        adressen.k1_geb, adressen.k2_geb,
        adressen.k3_geb, adressen.k4_geb,
        adressen.k5_geb,
        
        vonaufh, bisaufh ,
        zinr, gastkont.bemerk
        
        from
        adressen, gastkont, zimmstam
           --inner join gastkont on (adressen.lnr = gastkont.gastnr_1)


          -- left outer join zimmstam on (zimmstam.lnr = gastkont.lnr_zinr)
        
        where
        adressen.ta_status <1000 and ((adressen.lnr = gastkont.gastnr_1 and gastkont.ta_status <1000) or
                                      (adressen.lnr = gastkont.gastnr_2 and gastkont.ta_status <1000) or
                                      (adressen.lnr = gastkont.gastnr_3 and gastkont.ta_status <1000)  )
        and zimmstam.lnr = gastkont.lnr_zinr
        and :DATUM between vonaufh and  bisaufh
        and
           ((extract (day from adressen.gebdat)  = :TAG
           and extract (month from adressen.gebdat)  = :MONAT)
        
           or (extract (day from adressen.begleit_g)  = :TAG
           and extract (month from adressen.begleit_g)  = :MONAT)
        
           or (extract (day from adressen.k1_geb)  = :TAG
           and extract (month from adressen.k1_geb)  = :MONAT)
        
           or (extract (day from adressen.k2_geb)  = :TAG
           and extract (month from adressen.k2_geb)  = :MONAT)
        
           or (extract (day from adressen.k3_geb)  = :TAG
           and extract (month from adressen.k3_geb)  = :MONAT)
        
           or (extract (day from adressen.k4_geb)  = :TAG
           and extract (month from adressen.k4_geb)  = :MONAT)
        
           or (extract (day from adressen.k5_geb)  = :TAG
           and extract (month from adressen.k5_geb)  = :MONAT) )

    into :GASTNR,:BELEGNR, :NAME1, :NAME2, :BEGLEIT, :BEGLEIT_V, :K1, :K1_NNAME,
         :K2, :K2_NNAME, :K3, :K3_NNAME, :K4, :K4_NNAME,
         :K5, :K5_NNAME, :GEBDAT, :BEGLEIT_G, :K1_GEB,
         :K2_GEB, :K3_GEB, :K4_GEB, :K5_GEB, :VONAUFH, :BISAUFH, :ZINR, :BEMERK
        

  DO
  BEGIN
    SUSPEND;
  END
end ^

ALTER PROCEDURE PROC_GET_GK3_ADR (BELEGNR INTEGER)
RETURNS (NAME1 VARCHAR(100) CHARACTER SET NONE,
GASTNR1 INTEGER,
NAME2 VARCHAR(100) CHARACTER SET NONE,
GASTNR2 INTEGER,
NAME3 VARCHAR(100) CHARACTER SET NONE,
GASTNR3 INTEGER,
VORNAME1 VARCHAR(100) CHARACTER SET NONE,
VORNAME2 VARCHAR(100) CHARACTER SET NONE,
VORNAME3 VARCHAR(100) CHARACTER SET NONE)
AS 
begin
  /* Procedure Text */
  GASTNR1 = 0;
  GASTNR2 = 0;
  GASTNR3 = 0;

  for
  select a.name1,a.lnr, a.name2
     from gastkont g
     INNER JOIN ADRESSEN A ON (G.GASTNR_1 = A.LNR)
     where g.lnr = :"BELEGNR"
     into :"NAME1",:"GASTNR1", :"VORNAME1"
  do


  for
  select a.name1,a.lnr, a.name2
     from gastkont g
     LEFT OUTER JOIN ADRESSEN A ON (G.GASTNR_2 = A.LNR)
     where g.lnr = :"BELEGNR"
     into :"NAME2",:"GASTNR2", :"VORNAME2"
  do

  for
  select a.name1,a.lnr, a.name2
     from gastkont g
     LEFT OUTER JOIN ADRESSEN A ON (G.GASTNR_3 = A.LNR)
     where g.lnr = :"BELEGNR"
     into :"NAME3",:"GASTNR3", :"VORNAME3"
  do

  suspend;
end ^

ALTER PROCEDURE PROC_GET_GK3_ADR_GESAMT (BELEGNR INTEGER)
RETURNS (ANREISE DATE,
ABREISE DATE,
G1_ANREDE VARCHAR(50) CHARACTER SET NONE,
G1_TITEL VARCHAR(50) CHARACTER SET NONE,
G1_NAME1 VARCHAR(100) CHARACTER SET NONE,
G1_NAME2 VARCHAR(100) CHARACTER SET NONE,
G1_STRASSE VARCHAR(60) CHARACTER SET NONE,
G1_LAND VARCHAR(5) CHARACTER SET NONE,
G1_PLZ VARCHAR(10) CHARACTER SET NONE,
G1_ORT VARCHAR(50) CHARACTER SET NONE,
GASTNR1 INTEGER,
G2_ANREDE VARCHAR(50) CHARACTER SET NONE,
G2_TITEL VARCHAR(50) CHARACTER SET NONE,
G2_NAME1 VARCHAR(100) CHARACTER SET NONE,
G2_NAME2 VARCHAR(100) CHARACTER SET NONE,
G2_STRASSE VARCHAR(60) CHARACTER SET NONE,
G2_LAND VARCHAR(5) CHARACTER SET NONE,
G2_PLZ VARCHAR(10) CHARACTER SET NONE,
G2_ORT VARCHAR(50) CHARACTER SET NONE,
GASTNR2 INTEGER,
G3_ANREDE VARCHAR(50) CHARACTER SET NONE,
G3_TITEL VARCHAR(50) CHARACTER SET NONE,
G3_NAME1 VARCHAR(100) CHARACTER SET NONE,
G3_NAME2 VARCHAR(100) CHARACTER SET NONE,
G3_STRASSE VARCHAR(60) CHARACTER SET NONE,
G3_LAND VARCHAR(5) CHARACTER SET NONE,
G3_PLZ VARCHAR(10) CHARACTER SET NONE,
G3_ORT VARCHAR(60) CHARACTER SET NONE,
GASTNR3 INTEGER)
AS 
begin
  /* Procedure Text */
  GASTNR1 = 0;
  GASTNR2 = 0;
  GASTNR3 = 0;

  for
  select a.anrede,a.titel,a.name1,a.name2, a.strasse,a.land, a.plz, a.ort, a.lnr,g.vonaufh, g.bisaufh
  from gastkont g, adressen a
  where g.lnr = :"BELEGNR" and
        g.gastnr_1 = a.lnr
  into :"G1_ANREDE", :"G1_TITEL", :"G1_NAME1", :"G1_NAME2", :"G1_STRASSE",
       :"G1_LAND", :"G1_PLZ", :"G1_ORT", :"GASTNR1", :"ANREISE", :"ABREISE"
  do

  for
  select a.anrede,a.titel,a.name1,a.name2, a.strasse,a.land, a.plz, a.ort, a.lnr
  from gastkont g, adressen a
  where g.lnr = :"BELEGNR" and
        g.gastnr_2 = a.lnr
  into :"G2_ANREDE", :"G2_TITEL", :"G2_NAME1", :"G2_NAME2", :"G2_STRASSE",
       :"G2_LAND", :"G2_PLZ", :"G2_ORT", :"GASTNR2"
  do


  for
  select a.anrede,a.titel,a.name1,a.name2, a.strasse,a.land, a.plz, a.ort, a.lnr
  from gastkont g, adressen a
  where g.lnr = :"BELEGNR" and
        g.gastnr_3 = a.lnr
  into :"G3_ANREDE", :"G3_TITEL", :"G3_NAME1", :"G3_NAME2", :"G3_STRASSE",
       :"G3_LAND", :"G3_PLZ", :"G3_ORT", :"GASTNR3"
  do

  suspend;
end ^

ALTER PROCEDURE PROC_GET_GKINFO (BUCHNR INTEGER,
GASTNR INTEGER)
RETURNS (BELEGNR INTEGER,
ANREDE VARCHAR(30) CHARACTER SET NONE,
NAME1 VARCHAR(60) CHARACTER SET NONE,
NAME2 VARCHAR(60) CHARACTER SET NONE,
STRASSE VARCHAR(60) CHARACTER SET NONE,
LAND VARCHAR(10) CHARACTER SET NONE,
PLZ VARCHAR(10) CHARACTER SET NONE,
ORT VARCHAR(60) CHARACTER SET NONE,
ANREISE DATE,
ABREISE DATE,
ERW INTEGER,
JUG INTEGER,
KIND INTEGER,
ZINR VARCHAR(10) CHARACTER SET NONE)
AS 
begin
  /* Procedure Text */
  for
    select
         gastkont.lnr  ,a.anrede, a.name1, a.name2, a.strasse, a.land, a.plz, a.ort, gastkont.vonaufh, gastkont.bisaufh, gastkont.perszahl, gastkont.anzjugend, gastkont.anzkinder + coalesce(gastkont.anzkinder2,0),
         zimmstam.zinr
    from gastkont
       inner join adressen a on  (a.lnr = :gastnr)
       left outer join zimmstam on (zimmstam.lnr = gastkont.lnr_zinr)
    where gastkont.lnr = :buchnr
    into  :BELEGNR, :ANREDE, :NAME1, :NAME2, :STRASSE, :LAND, :PLZ, :ORT, :ANREISE, :ABREISE, :ERW, :JUG, :KIND, :ZINR


    --and       ((:GASTNR =gastkont.gastnr_1) or (:GASTNR = gastkont.gastnr_2) or (:gastnr = gastkont.gastnr_3))

  do
  suspend;

end ^

ALTER PROCEDURE PROC_GET_GK_ADR_MEMO (BELEGNR INTEGER)
RETURNS (BEMERK BLOB CHARACTER SET NONE)
