ALTER PROCEDURE PROC_GET_HIST_BENDEF (GASTNR INTEGER)
RETURNS (ANZ_AUFENTH INTEGER,
ANZ_AUFTAGE INTEGER)
AS 
declare variable ANZAHL integer;
declare variable ANZ_GK integer;
declare variable TAGE_GK integer;
declare variable HIST_TAGE integer;
begin
  /* Procedure Text */
  anzahl = 0;
  hist_tage = 0;
  select count(*) as anzahl, coalesce( sum(gasthist.tage),0) as tage
  from gasthist
  where
  gasthist.adr_lnr = :gastnr
  and (gasthist.lnr_co is null or (gasthist.lnr_co =0))
     and  gasthist.ta_status <1000
     into :anzahl, :hist_tage;

  anz_gk =0;
  tage_gk = 0;

  
 select count(*) as anzahl, coalesce( sum(gastkont.auftage),0) as tage
 from gastkont
 where ((gastkont.gastnr_1 = :gastnr) or (gastkont.gastnr_2=:gastnr) or (gastkont.gastnr_3=:gastnr))
 and gastkont.ta_status between 500 and 999
    into :anz_gk, :tage_gk;




  anz_aufenth = anzahl + anz_gk;
  anz_auftage = hist_tage + tage_gk;


  suspend;
end ^

ALTER PROCEDURE PROC_GET_HOCHZEIT_I_HAUS (DATUM DATE,
TAG INTEGER,
MONAT INTEGER)
RETURNS (GASTNR INTEGER,
BELEGNR INTEGER,
NAME1 VARCHAR(60) CHARACTER SET NONE,
NAME2 VARCHAR(60) CHARACTER SET NONE,
BEGLEIT VARCHAR(60) CHARACTER SET NONE,
BEGLEIT_V VARCHAR(60) CHARACTER SET NONE,
K1 VARCHAR(60) CHARACTER SET NONE,
K1_NNAME VARCHAR(60) CHARACTER SET NONE,
K2 VARCHAR(60) CHARACTER SET NONE,
K2_NNAME VARCHAR(60) CHARACTER SET NONE,
K3 VARCHAR(60) CHARACTER SET NONE,
K3_NNAME VARCHAR(60) CHARACTER SET NONE,
K4 VARCHAR(60) CHARACTER SET NONE,
K4_NNAME VARCHAR(60) CHARACTER SET NONE,
K5 VARCHAR(60) CHARACTER SET NONE,
K5_NNAME VARCHAR(60) CHARACTER SET NONE,
GEBDAT DATE,
BEGLEIT_G DATE,
K1_GEB DATE,
K2_GEB DATE,
K3_GEB DATE,
K4_GEB DATE,
K5_GEB DATE,
VONAUFH DATE,
BISAUFH DATE,
ZINR VARCHAR(10) CHARACTER SET NONE,
BEMERK VARCHAR(100) CHARACTER SET NONE)
AS 
begin
  /* Procedure Text */
    FOR

        select
        
        adressen.lnr ,  gastkont.lnr as belegnr,
        adressen.name1, adressen.name2,
        adressen.begleit, adressen.begleit_v,
        adressen.k1, adressen.k1_nname,
        adressen.k2, adressen.k2_nname,
        adressen.k3, adressen.k3_nname,
        adressen.k4, adressen.k4_nname,
        adressen.k5, adressen.k5_nname,
        
        
        
        adressen.gebdat, adressen.begleit_g,
        adressen.k1_geb, adressen.k2_geb,
        adressen.k3_geb, adressen.k4_geb,
        adressen.k5_geb,
        
        vonaufh, bisaufh ,
        zinr, gastkont.bemerk
        
        from
        adressen, gastkont, zimmstam

        where
        adressen.hochzeitstag is not null and adressen.ta_status <1000 and  ((adressen.lnr = gastkont.gastnr_1 and gastkont.ta_status <1000) or
                                      (adressen.lnr = gastkont.gastnr_2 and gastkont.ta_status <1000) or
                                      (adressen.lnr = gastkont.gastnr_3 and gastkont.ta_status <1000)  )
        and zimmstam.lnr = gastkont.lnr_zinr
        and :DATUM between vonaufh and  bisaufh
        and
           (
           extract (day from adressen.hochzeitstag)  = :TAG
           and extract (month from adressen.hochzeitstag)  = :MONAT
            )

    into :GASTNR,:BELEGNR, :NAME1, :NAME2, :BEGLEIT, :BEGLEIT_V, :K1, :K1_NNAME,
         :K2, :K2_NNAME, :K3, :K3_NNAME, :K4, :K4_NNAME,
         :K5, :K5_NNAME, :GEBDAT, :BEGLEIT_G, :K1_GEB,
         :K2_GEB, :K3_GEB, :K4_GEB, :K5_GEB, :VONAUFH, :BISAUFH, :ZINR, :BEMERK
        

  DO
  BEGIN
    SUSPEND;
  END
end ^

ALTER PROCEDURE PROC_GET_LAND_STAT (VONDATUM DATE,
BISDATUM DATE,
MAND_NR INTEGER)
RETURNS (ERW INTEGER,
KINDER INTEGER,
JUGEND INTEGER,
ANZ_ANR INTEGER,
ANZ_NACHT INTEGER,
LAND VARCHAR(5) CHARACTER SET NONE,
LANDKENN VARCHAR(10) CHARACTER SET NONE,
BEZEICHN VARCHAR(30) CHARACTER SET NONE)
AS 
declare variable VERK_LNR integer;
begin
  if(:MAND_NR <= 0) then
  BEGIN
      /* Statistische Werte ohne Gruppen mit VERK_NR in GR_RES_ZUS holen */
      for
        select sum(anzerw) as erw , sum(stat_belegung.anzkinder) as kinder, sum(stat_belegung.anzjugend) as jugend,
            count(*)  as anz_nacht,
            adressen.land, adressen.landkenn,landstam.bezeichn,
            (stat_belegung.anzerw+stat_belegung.anzkinder + stat_belegung.anzjugend) as anz_anr, gr_res_zus.verk_lnr
        
        from stat_belegung
            
             left outer join gastkont on (gastkont.lnr = stat_belegung.gk_lnr)
             left outer join adressen on (adressen.lnr = gastkont.gastnr_1)
             left outer join landstam on (adressen.landkenn = landstam.landkenn)
             left outer join gr_res_zus on (gr_res_zus.verk_lnr = gastkont.verk_nr)
        
        where stat_belegung.datum>= :VONDATUM and stat_belegung.datum<= :BISDATUM
        and gr_res_zus.verk_lnr is null
        
        group by gk_lnr,adressen.land, adressen.landkenn,landstam.bezeichn,
        stat_belegung.anzerw, stat_belegung.anzkinder, stat_belegung.anzjugend, gr_res_zus.verk_lnr
    
        into :ERW, :KINDER, :JUGEND, :ANZ_NACHT, :LAND, :LANDKENN, :BEZEICHN, :ANZ_ANR, :VERK_LNR
      do
      suspend;
      /* Statistische Werte fuer Gruppen mit VERK_NR in GR_RES_ZUS holen */
      for
        select sum(anzerw) as erw , sum(stat_belegung.anzkinder) as kinder, sum(stat_belegung.anzjugend) as jugend,
            count(*)  as anz_nacht,
            landstam.zeichen, gr_res_zus.landkenn,landstam.bezeichn,
            (stat_belegung.anzerw+stat_belegung.anzkinder + stat_belegung.anzjugend) as anz_anr, gr_res_zus.verk_lnr
        
        from stat_belegung
            
             left outer join gastkont on (gastkont.lnr = stat_belegung.gk_lnr)
             left outer join gr_res_zus on (gr_res_zus.verk_lnr = gastkont.verk_nr)
             left outer join landstam on (gr_res_zus.landkenn = landstam.landkenn)
        
        where stat_belegung.datum>= :VONDATUM and stat_belegung.datum<= :BISDATUM
        and gr_res_zus.verk_lnr is not null
        
        group by gk_lnr, landstam.zeichen, gr_res_zus.landkenn,landstam.bezeichn,
        stat_belegung.anzerw, stat_belegung.anzkinder, stat_belegung.anzjugend, gr_res_zus.verk_lnr
    
        into :ERW, :KINDER, :JUGEND, :ANZ_NACHT, :LAND, :LANDKENN, :BEZEICHN, :ANZ_ANR, :VERK_LNR
      do
      suspend;
  END
  ELSE IF(:MAND_NR > 0) THEN
  BEGIN
       /* Statistische Werte ohne Gruppen mit VERK_NR in GR_RES_ZUS holen */
      for
         select sum(anzerw) as erw , sum(stat_belegung.anzkinder) as kinder, sum(stat_belegung.anzjugend) as jugend,
            count(*)  as anz_nacht,
            adressen.land, adressen.landkenn,landstam.bezeichn,
            (stat_belegung.anzerw+stat_belegung.anzkinder + stat_belegung.anzjugend) as anz_anr, gr_res_zus.verk_lnr
        
        from stat_belegung
            
             left outer join gastkont on (gastkont.lnr = stat_belegung.gk_lnr)
             left outer join adressen on (adressen.lnr = gastkont.gastnr_1)
             left outer join landstam on (adressen.landkenn = landstam.landkenn)
             left outer join gr_res_zus on (gr_res_zus.verk_lnr = gastkont.verk_nr)
        
        where stat_belegung.datum>= :VONDATUM and stat_belegung.datum<= :BISDATUM
        and gr_res_zus.verk_lnr is null AND gastkont.mand_nr = :MAND_NR

        group by gk_lnr,adressen.land, adressen.landkenn,landstam.bezeichn,
        stat_belegung.anzerw, stat_belegung.anzkinder, stat_belegung.anzjugend, gr_res_zus.verk_lnr
    
        into :ERW, :KINDER, :JUGEND, :ANZ_NACHT, :LAND, :LANDKENN, :BEZEICHN, :ANZ_ANR, :VERK_LNR
      do
      suspend;
      /* Statistische Werte fuer Gruppen mit VERK_NR in GR_RES_ZUS holen */
      for
        select sum(anzerw) as erw , sum(stat_belegung.anzkinder) as kinder, sum(stat_belegung.anzjugend) as jugend,
            count(*)  as anz_nacht,
            landstam.zeichen, gr_res_zus.landkenn,landstam.bezeichn,
            (stat_belegung.anzerw+stat_belegung.anzkinder + stat_belegung.anzjugend) as anz_anr, gr_res_zus.verk_lnr
        
        from stat_belegung
            
             left outer join gastkont on (gastkont.lnr = stat_belegung.gk_lnr)
             left outer join gr_res_zus on (gr_res_zus.verk_lnr = gastkont.verk_nr)
             left outer join landstam on (gr_res_zus.landkenn = landstam.landkenn)
        
        where stat_belegung.datum>= :VONDATUM and stat_belegung.datum<= :BISDATUM
        and gr_res_zus.verk_lnr is not null AND gastkont.mand_nr = :MAND_NR
        
        group by gk_lnr, landstam.zeichen, gr_res_zus.landkenn,landstam.bezeichn,
        stat_belegung.anzerw, stat_belegung.anzkinder, stat_belegung.anzjugend, gr_res_zus.verk_lnr
    
        into :ERW, :KINDER, :JUGEND, :ANZ_NACHT, :LAND, :LANDKENN, :BEZEICHN, :ANZ_ANR, :VERK_LNR
      do
      suspend;
  END
end ^

ALTER PROCEDURE PROC_GET_LAST_ABR (LNR_ZI INTEGER,
VONAUFH DATE)
RETURNS (NAME2 VARCHAR(60) CHARACTER SET NONE,
NAME1 VARCHAR(60) CHARACTER SET NONE,
ANREDE VARCHAR(30) CHARACTER SET NONE,
TITEL VARCHAR(30) CHARACTER SET NONE,
G2_NAME1 VARCHAR(60) CHARACTER SET NONE,
G2_NAME2 VARCHAR(60) CHARACTER SET NONE,
G3_NAME1 VARCHAR(60) CHARACTER SET NONE,
G3_NAME2 VARCHAR(60) CHARACTER SET NONE,
BEMERK VARCHAR(100) CHARACTER SET NONE,
GASTNR_2 INTEGER,
LNR INTEGER,
VON DATE,
BIS DATE)
AS 
declare variable LAUF integer;
begin
  /* Procedure Text */
  LAUF = 0;
  for
  SELECT
    first 1
  ADRESSEN.NAME1, ADRESSEN.NAME2, adressen.anrede, adressen.titel,
         a_2.name1 as g2_name1 , a_2.name2 as g2_name2,
         a_3.name1 as g3_name1 , a_3.name1 as g3_name2,
         GASTKONT.bemerk, GASTKONT.gastnr_2, gastkont.lnr, gastkont.vonaufh, gastkont.bisaufh
  FROM ZIMMSTAM
        INNER JOIN GASTKONT ON (GASTKONT.LNR_ZINR = ZIMMSTAM.LNR AND zimmstam.lnr = :LNR_ZI AND
        GASTKONT.bisaufh <= :VONAUFH and gastkont.ta_status < 1000)
        INNER JOIN ADRESSEN ON (GASTKONT.GASTNR_1 = ADRESSEN.LNR)
        INNER JOIN MANDANT ON (GASTKONT.MAND_NR = MANDANT.LNR)
        LEFT OUTER JOIN adressen a_2 on (gastkont.gastnr_2>0 and gastkont.gastnr_2 = a_2.lnr)
        LEFT OUTER JOIN adressen a_3 on (gastkont.gastnr_3>0 and gastkont.gastnr_3 = a_3.lnr)

  order by gastkont.bisaufh DESC
  into   :NAME1, :NAME2, :ANREDE, :TITEL, :G2_NAME1, :G2_NAME2, :G3_NAME1, :G3_NAME2, :BEMERK, :GASTNR_2,
         :LNR, :VON, :BIS
  do
--  if(LAUF = 0) then
--  begin
--    LAUF = 1;
--    suspend;
--  end
   suspend;
end ^

ALTER PROCEDURE PROC_GET_LAST_ABR_GAST (ADR_LNR INTEGER)
RETURNS (VONDATUM DATE,
BISDATUM DATE,
ZINR VARCHAR(10) CHARACTER SET NONE)
AS 
declare variable LAUF integer;
begin
  /* Procedure Text */
  LAUF = 0;
  for
  SELECT GASTHIST.VONDATUM, GASTHIST.BISDATUM, GASTHIST.ZINR
  FROM GASTHIST
  WHERE GASTHIST.adr_lnr = :ADR_LNR AND GASTHIST.STO_BETRAG <= 0 and GASTHIST.ta_status <1000
  order by GASTHIST.bisdatum DESC
  into   :VONDATUM, :BISDATUM, :ZINR
  do
  if(LAUF = 0) then
  begin
    LAUF = 1;
    suspend;
  end
end ^

ALTER PROCEDURE PROC_GET_LAST_HIST (GASTNR INTEGER)
RETURNS (VONDATUM DATE,
BISDATUM DATE,
TAGE INTEGER)
AS 
begin
  /* Procedure Text */
  for
    SELECT FIRST 1 gasthist.vondatum, bisdatum , gasthist.tage
    from gasthist
       where adr_lnr = :gastnr and gasthist.ta_status <1000 and     gasthist.sto_betrag<=0
       order by vondatum  DESC
            into :"VONDATUM", :"BISDATUM", :"TAGE"

 do
  suspend;
end
 ^

ALTER PROCEDURE PROC_GET_LEIST_PRO_ANGKATEZI (ANG_LNR INTEGER,
ANGKATEZI_LNR INTEGER)
RETURNS (LEIST_BEZ VARCHAR(1024) CHARACTER SET NONE)
AS 
declare variable ARRANG_TEMP varchar(1024);
begin
    /* Procedure Text */
    ARRANG_TEMP = '';
    LEIST_BEZ = '';
    for select ANG_LEISTUNG.BEZEICHN
        from ANG_LEISTUNG
        where ANG_LEISTUNG.ANG_LNR = :ANG_LNR and
              ANG_LEISTUNG.ANG_KATE_ZI_LNR = :ANGKATEZI_LNR and
              ANG_LEISTUNG.TA_STATUS < 1000
        into :ARRANG_TEMP
    do
    begin
        if (position(:ARRANG_TEMP in :LEIST_BEZ) = 0) then
        begin
            if (LEIST_BEZ != '') then
                LEIST_BEZ = LEIST_BEZ || '<br/>';
            LEIST_BEZ = LEIST_BEZ || ARRANG_TEMP;
        end
    end

    suspend;
end ^

ALTER PROCEDURE PROC_GET_LEIST_SYM_STATUS (BELEGNR INTEGER,
AUSWAHL_STATUS INTEGER)
RETURNS (BEZEICHN VARCHAR(512) CHARACTER SET NONE,
AUSWAHL_SYMBOL INTEGER,
AUSWAHL_SYMBOL_ANZEIGE INTEGER)
AS 
begin
  /* Procedure Text */
  for
     select first 1 buchkont.bezeichn,  leiststa.auswahl_symbol, leiststa.auswahl_symbol_anzeige
      from buchkont
         inner join leiststa on (leiststa.lnr = buchkont.leist_lnr)
    
      where buchkont.gk_lnr = :BELEGNR and buchkont.ta_status<1000
      and leiststa.AUSWAHL_SYMBOL = :AUSWAHL_STATUS
        into :bezeichn, :auswahl_symbol, :auswahl_symbol_anzeige
  do

  suspend;
end ^

ALTER PROCEDURE PROC_GET_NEXT_ANR (LNR_ZI INTEGER,
BISAUFH DATE)
RETURNS (NAME2 VARCHAR(60) CHARACTER SET NONE,
NAME1 VARCHAR(60) CHARACTER SET NONE,
ANREDE VARCHAR(30) CHARACTER SET NONE,
TITEL VARCHAR(30) CHARACTER SET NONE,
G2_NAME1 VARCHAR(60) CHARACTER SET NONE,
G2_NAME2 VARCHAR(60) CHARACTER SET NONE,
G3_NAME1 VARCHAR(60) CHARACTER SET NONE,
G3_NAME2 VARCHAR(60) CHARACTER SET NONE,
BEMERK VARCHAR(100) CHARACTER SET NONE,
GASTNR_2 INTEGER,
LNR INTEGER,
VON DATE,
BIS DATE,
VONZEIT TIME)
AS 
declare variable LAUF integer;
begin
  /* Procedure Text */
  LAUF = 0;
  for
  SELECT ADRESSEN.NAME1, ADRESSEN.NAME2, adressen.anrede, adressen.titel,
         a_2.name1 as g2_name1 , a_2.name2 as g2_name2,
         a_3.name1 as g3_name1 , a_3.name1 as g3_name2,
         GASTKONT.bemerk, GASTKONT.gastnr_2, gastkont.lnr, gastkont.vonaufh, gastkont.bisaufh, gastkont.vonzeit
  FROM ZIMMSTAM
        INNER JOIN GASTKONT ON (GASTKONT.LNR_ZINR = ZIMMSTAM.LNR AND zimmstam.lnr = :LNR_ZI AND
        GASTKONT.vonaufh>= :BISAUFH and gastkont.ta_status<500)
        INNER JOIN ADRESSEN ON (GASTKONT.GASTNR_1 = ADRESSEN.LNR)
        INNER JOIN MANDANT ON (GASTKONT.MAND_NR = MANDANT.LNR)
        LEFT OUTER JOIN adressen a_2 on (gastkont.gastnr_2 = a_2.lnr)
        LEFT OUTER JOIN adressen a_3 on (gastkont.gastnr_3 = a_3.lnr)


  order by gastkont.vonaufh
  into   :NAME1, :NAME2, :ANREDE, :TITEL, :G2_NAME1, :G2_NAME2, :G3_NAME1, :G3_NAME2, :BEMERK, :GASTNR_2,
         :LNR, :VON, :BIS, :VONZEIT
  do
  if(LAUF = 0) then
  begin
    LAUF = 1;
    suspend;
  end
end ^

ALTER PROCEDURE PROC_GET_NEXT_ANR_EINFACH (LNR_ZINR INTEGER,
DATUM DATE,
BELEGNR_VOR INTEGER)
RETURNS (BELEGNR INTEGER,
ANREISE DATE,
ABREISE DATE)
AS 
begin
  /* Procedure Text */

  for
  SELECT first 1  belegung.lnr_gk, belegung.anreise, belegung.abreise
  FROM belegung
        where belegung.lnr_zinr = :lnr_zinr and (belegung.anreise >= :datum)
        and belegung.ta_status <500
        and ((belegung.lnr_gk != :belegnr_vor) or (:belegnr_vor is null))
   order by belegung.anreise

  into   :BELEGNR, :ANREISE, :ABREISE
  do

  suspend;
end
 ^

ALTER PROCEDURE PROC_GET_NEXT_ANR_ERW (LNR_ZI INTEGER,
BISAUFH DATE)
RETURNS (NAME2 VARCHAR(60) CHARACTER SET NONE,
NAME1 VARCHAR(60) CHARACTER SET NONE,
ANREDE VARCHAR(30) CHARACTER SET NONE,
TITEL VARCHAR(30) CHARACTER SET NONE,
G2_NAME1 VARCHAR(60) CHARACTER SET NONE,
G2_NAME2 VARCHAR(60) CHARACTER SET NONE,
G3_NAME1 VARCHAR(60) CHARACTER SET NONE,
G3_NAME2 VARCHAR(60) CHARACTER SET NONE,
BEMERK VARCHAR(100) CHARACTER SET NONE,
GASTNR_2 INTEGER,
LNR INTEGER,
VON DATE,
BIS DATE,
VONZEIT TIME,
PERSZAHL INTEGER,
ANZJUGEND INTEGER,
ANZKINDER INTEGER,
ANZKK INTEGER)
AS 
declare variable LAUF integer;
begin
  /* Procedure Text */
  LAUF = 0;
  for
  SELECT ADRESSEN.NAME1, ADRESSEN.NAME2, adressen.anrede, adressen.titel,
         a_2.name1 as g2_name1 , a_2.name2 as g2_name2,
         a_3.name1 as g3_name1 , a_3.name1 as g3_name2,
         GASTKONT.bemerk, GASTKONT.gastnr_2, gastkont.lnr, gastkont.vonaufh, gastkont.bisaufh, gastkont.vonzeit,
         gastkont.perszahl,  gastkont.anzjugend, gastkont.anzkinder, gastkont.anzkleinkind
  FROM ZIMMSTAM
        INNER JOIN GASTKONT ON (GASTKONT.LNR_ZINR = ZIMMSTAM.LNR AND zimmstam.lnr = :LNR_ZI AND
        GASTKONT.vonaufh>= :BISAUFH and gastkont.ta_status<500)
        INNER JOIN ADRESSEN ON (GASTKONT.GASTNR_1 = ADRESSEN.LNR)
        INNER JOIN MANDANT ON (GASTKONT.MAND_NR = MANDANT.LNR)
        LEFT OUTER JOIN adressen a_2 on (gastkont.gastnr_2 = a_2.lnr)
        LEFT OUTER JOIN adressen a_3 on (gastkont.gastnr_3 = a_3.lnr)


  order by gastkont.vonaufh
  into   :NAME1, :NAME2, :ANREDE, :TITEL, :G2_NAME1, :G2_NAME2, :G3_NAME1, :G3_NAME2, :BEMERK, :GASTNR_2,
         :LNR, :VON, :BIS, :VONZEIT, :PERSZAHL, :ANZJUGEND, :ANZKINDER, :ANZKK
  do
  if(LAUF = 0) then
  begin
    LAUF = 1;
    suspend;
  end
end ^

ALTER PROCEDURE PROC_GET_PLZ (STRASSE_S VARCHAR(30) CHARACTER SET NONE,
PLZ_S VARCHAR(5) CHARACTER SET NONE,
ORT_S INTEGER)
RETURNS (STRASSE VARCHAR(30) CHARACTER SET NONE,
ORT VARCHAR(30) CHARACTER SET NONE,
PLZ VARCHAR(5) CHARACTER SET NONE)
AS 
BEGIN
  /* Procedure Text */
  if (PLZ_S is not null AND STRASSE_S IS NULL) then
  BEGIN
  FOR
        SELECT PLZ_ORT.PLZ, PLZ_ORT.ORT
        FROM PLZ_ORT
        WHERE PLZ_ORT.PLZ = :PLZ_S

        into :PLZ, :ORT
      do
      suspend;
  end

  ELSE IF (STRASSE_S is not null AND PLZ_S is not null) THEN
  BEGIN
      FOR
        SELECT PLZ_ORT.PLZ, PLZ_ORT.ORT, PLZ_STRASSE.STRASSE
        FROM PLZ_ORT
          INNER JOIN PLZ_STRASSE ON (PLZ_ORT.PLZ = PLZ_STRASSE.PLZ)
        WHERE PLZ_ORT.PLZ = :PLZ_S AND
              PLZ_STRASSE.Strasse STARTING WITH :STRASSE_S

        into :PLZ, :ORT, :STRASSE
      do
      suspend;
  end

  ELSE IF (STRASSE_S is not null AND ORT_S is not null) THEN
  BEGIN
      FOR
        SELECT PLZ_ORT.PLZ, PLZ_ORT.ORT, PLZ_STRASSE.STRASSE
        FROM PLZ_ORT
          INNER JOIN PLZ_STRASSE ON (PLZ_ORT.PLZ = PLZ_STRASSE.PLZ)
        WHERE PLZ_ORT.ort STARTING WITH :ORT_S AND
              PLZ_STRASSE.Strasse STARTING WITH :STRASSE_S

        into :PLZ, :ORT, :STRASSE
      do
      suspend;
  end

  suspend;
end ^

ALTER PROCEDURE PROC_GET_STAT_ANK (LAND_LNR VARCHAR(10) CHARACTER SET NONE,
VON DATE,
BIS DATE)
RETURNS (ANZ_ANK INTEGER,
ANZ_ERW_ANK INTEGER,
ANZ_JUG_ANK INTEGER,
ANZ_KIN_ANK INTEGER)
AS 
begin
  /* Procedure Text */
  for
    select sum(stat_belegung.anzerw+stat_belegung.anzkinder + stat_belegung.anzjugend) as anz_anr,
           sum(stat_belegung.anzerw), sum(stat_belegung.anzkinder), sum(stat_belegung.anzjugend)
    
      from stat_belegung
        
         left outer join gastkont on (gastkont.lnr = stat_belegung.gk_lnr)
         left outer join zimmstam on (gastkont.lnr_zinr = zimmstam.lnr)
         left outer join adressen on (adressen.lnr = gastkont.gastnr_1)
         left outer join landstam on (adressen.landkenn = landstam.landkenn)
    
      where   (ZIMMSTAM.SCHEINZ = 0 OR ZIMMSTAM.SCHEINZ IS NULL) AND ( ZIMMSTAM.ZINR not between '9000' AND '9999') AND
        stat_belegung.datum = gastkont.vonaufh and adressen.landkenn = :LAND_LNR
        and stat_belegung.datum between :VON and :BIS
        into :ANZ_ANK, :ANZ_ERW_ANK, :ANZ_KIN_ANK, :ANZ_JUG_ANK
   do
   suspend;
end ^

