ALTER PROCEDURE PROC_GET_SUM_UMS_FAKT (BELEGNR INTEGER = 0)
RETURNS (SUM_STAT_UMSATZ NUMERIC(12, 2),
SUM_FAKT_UMS NUMERIC(12, 2),
LEIST_LNR INTEGER,
LNR_BUCHKONT INTEGER)
AS 
begin
  /* Procedure Text */
    for
        select buchkont.lnr, sum((stat_umsatz.tag_betrag * stat_umsatz.me)) as summe_umsatz

          from gastkont

             inner join buchkont on (buchkont.gk_lnr = gastkont.lnr)
             inner join stat_umsatz on (stat_umsatz.lnr_buchkont = buchkont.lnr)
            where gastkont.lnr = :belegnr and buchkont.ta_status = 500
              group by buchkont.lnr
               into  :LNR_BUCHKONT, :SUM_STAT_UMSATZ
     do
     begin
         select sum(fakt_erloese.betrag)
          from fakt_erloese where lnr_buchkont = :lnr_buchkont
          into :SUM_FAKT_UMS;

       suspend;
     end


end ^

