ALTER PROCEDURE PROC_GET_TISCH_REGK RETURNS (BELEGNR INTEGER,
ANREISE TIMESTAMP,
ABREISE TIMESTAMP,
ZINR VARCHAR(10) CHARACTER SET NONE,
NAME1 VARCHAR(60) CHARACTER SET NONE,
NAME2 VARCHAR(60) CHARACTER SET NONE,
BEMERK VARCHAR(100) CHARACTER SET NONE,
TISCH VARCHAR(10) CHARACTER SET NONE,
GESPERRT INTEGER)
AS 
declare variable N1 varchar(60);
declare variable N2 varchar(60);
declare variable CI_STATUS integer;
begin
  /* Procedure Text */
  FOR
    SELECT DISTINCT GASTKONT.LNR, BELEGUNG.ANREISE, BELEGUNG.ABREISE, ZIMMSTAM.ZINR,
                    ADRESSEN.NAME1, ADRESSEN.NAME2,
                    GASTKONT.BEMERK, GASTKONT.TISCH
           FROM BELEGUNG
                INNER JOIN GASTKONT ON (BELEGUNG.LNR_GK = GASTKONT.LNR and BELEGUNG.lnr_zinr = gastkont.lnr_zinr)
                INNER JOIN ADRESSEN ON (GASTKONT.GASTNR_1 = ADRESSEN.LNR)
                LEFT OUTER JOIN ZIMMSTAM ON (ZIMMSTAM.LNR = GASTKONT.LNR_ZINR)
                LEFT OUTER JOIN ONLINE_VERBUND ON (BELEGUNG.LNR_GK = ONLINE_VERBUND.GK_LNR)
     WHERE
     (
        (ONLINE_VERBUND.CI_STATUS = 1) AND
        (GASTKONT.TA_STATUS<500) AND (GASTKONT.CI_STATUS = 1) AND
        (GASTKONT.GASTNR_1 > 0) AND ((GASTKONT.PM < 1) OR (GASTKONT.PM IS NULL) )
     )
     ORDER BY ZIMMSTAM.ZINR, GASTKONT.LNR
     INTO :BELEGNR, :ANREISE, :ABREISE, :ZINR, :N1, :N2, :BEMERK, :TISCH
  DO
  FOR
    SELECT PROC_SUBSTRING.RESULT FROM PROC_SUBSTRING
        (:N1, 1, 40 )
    INTO :NAME1
  DO
  FOR
    SELECT PROC_SUBSTRING.RESULT FROM PROC_SUBSTRING
        (:N2, 1, 40 )
    INTO :NAME2
  DO
  BEGIN
      CI_STATUS = 0;
      if(BELEGNR > 0) THEN
      begin
        for
            select distinct ONLINE_VERBUND.CI_STATUS
            from ONLINE_VERBUND
            where ONLINE_VERBUND.GK_LNR = :BELEGNR
            order by online_verbund.lnr
            INTO :CI_STATUS
        do
        begin
           CI_STATUS = CI_STATUS;
        end
      end
      begin
            if(CI_STATUS != 2) THEN
            begin
               GESPERRT = 0;
               suspend;
            end
      end
  end
end ^

ALTER PROCEDURE PROC_GET_TODOLIST (LNR INTEGER)
RETURNS (MEMO VARCHAR(512) CHARACTER SET NONE,
AKT_STATUS INTEGER,
ERF_DATUM TIMESTAMP,
ERLED_BISDATE DATE,
ERLED_VW INTEGER,
ERLED_STATUS INTEGER,
ERLED_BISTIME TIME,
PRIO INTEGER,
GK_LNR INTEGER,
ZINR VARCHAR(10) CHARACTER SET NONE,
SICHT_FUER_BED VARCHAR(100) CHARACTER SET NONE,
SICHT_ALLE SMALLINT)
AS 
begin
  /* Procedure Text */
  for
     SELECT ZIMMSTAM.ZINR, TODOLIST.ERLED_STATUS, TODOLIST.MEMO, TODOLIST.PRIO,
            TODOLIST.ERLED_BISTIME, TODOLIST.ERLED_BISDATE, TODOLIST.ERLED_VW,
            TODOLIST.ERF_DATUM, TODOLIST.AKT_STATUS, todolist.gk_lnr,
            TODOLIST.SICHT_FUER_BED, TODOLIST.SICHT_ALLE
      FROM TODOLIST
        LEFT OUTER JOIN GASTKONT ON (TODOLIST.GK_LNR = GASTKONT.LNR)
        LEFT OUTER JOIN ZIMMSTAM ON (GASTKONT.LNR_ZINR = ZIMMSTAM.LNR)
        LEFT OUTER JOIN ADRESSEN ON (GASTKONT.GASTNR_1 = ADRESSEN.LNR)

      where todolist.lnr=:"LNR"

      into :"ZINR", :"ERLED_STATUS", :"MEMO", :"PRIO",
           :"ERLED_BISTIME", :"ERLED_BISDATE", :"ERLED_VW",
           :"ERF_DATUM", :"AKT_STATUS", :"GK_LNR",
           :SICHT_FUER_BED, :SICHT_ALLE
  do
  suspend;
end ^

ALTER PROCEDURE PROC_GET_TODOLIST_PRO_ADR (ADRLNR INTEGER)
RETURNS (MEMO VARCHAR(1024) CHARACTER SET NONE,
AKT_STATUS INTEGER,
ERF_DATUM TIMESTAMP,
ERLED_BISDATE DATE,
ERLED_VW INTEGER,
ERLED_STATUS INTEGER,
ERLED_BISTIME TIME,
PRIO INTEGER,
ZINR VARCHAR(10) CHARACTER SET NONE)
AS 
begin
  /* Procedure Text */
  for
     SELECT ZIMMSTAM.ZINR,
            TODOLIST.ERLED_STATUS, TODOLIST.MEMO, TODOLIST.PRIO,
            TODOLIST.ERLED_BISTIME, TODOLIST.ERLED_BISDATE, TODOLIST.ERLED_VW,
            TODOLIST.ERF_DATUM, TODOLIST.AKT_STATUS
      FROM TODOLIST
        INNER JOIN GASTKONT ON (TODOLIST.GK_LNR = GASTKONT.LNR)
        INNER JOIN ZIMMSTAM ON (GASTKONT.LNR_ZINR = ZIMMSTAM.LNR)


      where todolist.adr_lnr =:"ADRLNR"

      into :"ZINR", :"ERLED_STATUS", :"MEMO", :"PRIO",
           :"ERLED_BISTIME", :"ERLED_BISDATE", :"ERLED_VW", :"ERF_DATUM", :"AKT_STATUS"
  do
  suspend;

  for
     SELECT '',
            TODOLIST.ERLED_STATUS, TODOLIST.MEMO, TODOLIST.PRIO,
            TODOLIST.ERLED_BISTIME, TODOLIST.ERLED_BISDATE, TODOLIST.ERLED_VW,
            TODOLIST.ERF_DATUM, TODOLIST.AKT_STATUS
      FROM TODOLIST


      where todolist.adr_lnr =:"ADRLNR" and todolist.gk_lnr = 0

      into :"ZINR", :"ERLED_STATUS", :"MEMO", :"PRIO",
           :"ERLED_BISTIME", :"ERLED_BISDATE", :"ERLED_VW", :"ERF_DATUM", :"AKT_STATUS"
  do
  suspend;

end ^

ALTER PROCEDURE PROC_GET_TRACING (BELEGNR INTEGER,
GASTNR INTEGER,
ABTEILUNG INTEGER)
RETURNS (ANZAHL INTEGER,
TODO_LNR INTEGER,
ABT_TEXT VARCHAR(30) CHARACTER SET NONE,
ERLED_BISDATE DATE,
INFOTEXT VARCHAR(1024) CHARACTER SET NONE,
BEREICH INTEGER,
ERLEDIGT_STATUS INTEGER,
TODO_ADD_LNR INTEGER,
TODOLIST_BELEGNR INTEGER,
BEDIENERNAME VARCHAR(20) CHARACTER SET NONE)
AS 
begin
  /* Procedure Text */
  for

   select
   --todolist_add.lnr_bereich  ,
   todolist.lnr,
   ERLED_BISDATE, left (texte.bezeichn,30) , todolist.memo ,
   todolist_add.lnr_bereich as BEREICH, todolist.erled_status, todolist_add.lnr, todolist.gk_lnr,
   bediener.name as bedienername
    from   todolist
     inner join todolist_add on (todolist_add.todo_lnr = todolist.lnr and todolist_add.ta_status <1000)
     left outer join bediener on (bediener.lnr = todolist.erf_userid )
     left outer join TEXTE on (TEXTE.LNR = TODOLIST_add.LNR_BEREICH)
    -- lef outer join abteilung on (abteilung.lnr = todolist.lnr_bereich)

     where
     ((todolist.gk_lnr = :BELEGNR)
        or (todolist.adr_lnr = :GASTNR and todolist.gk_lnr = 0))
        and todolist.ta_status <1000

      and ((todolist_add.lnr_bereich >0 and todolist_add.lnr_bereich = :abteilung)
      or (:ABTEILUNG=0)
       )


      into
      --:ANZAHL,
      :todo_lnr, :ERLED_BISDATE, :ABT_TEXT, :INFOTEXT, :BEREICH, :erledigt_status, :todo_add_lnr, :todolist_belegnr, :bedienername



  do
  suspend;
end ^

