ALTER PROCEDURE PROC_GET_ZA_KEIN_DEBI (LNR_CO INTEGER)
RETURNS (ZA_BETRAG NUMERIC(12, 2),
DEBI_BEZ_BETRAG NUMERIC(12, 2),
BEZ_ZA VARCHAR(50) CHARACTER SET NONE)
AS 
begin
  /* Procedure Text */
  select sum(zahlungen.betrag),
     sum(zahlungen.debi_bez_betr),
     min(zahlungen.bezeichn)

    from zahlungen
    left outer join devisen on ( devisen.lnr = zahlungen.lnr_devi )
    where zahlungen.lnr_co  = :lnr_co and zahlungen.ta_status<1000
      and devisen.m_debirechn!=1
       into :za_betrag, :debi_bez_betrag, :bez_za;

    --order by zahlungen.lnr
  suspend;
end ^

ALTER PROCEDURE PROC_HOUSEKEEPING_FIRSTFILL AS 
declare variable TMPLNR integer;
declare variable TMPANREISE date;
declare variable TMPABREISE date;
declare variable TMPGKLNR integer;
begin

  for

      select BELEGUNG.LNR, BELEGUNG.LNR_GK, BELEGUNG.ANREISE, BELEGUNG.ABREISE
      from BELEGUNG
      where BELEGUNG.TA_STATUS < 1000 and
            BELEGUNG.ABREISE > current_date
      into :TMPLNR, :TMPGKLNR, :TMPANREISE, :TMPABREISE

  do
  begin
    if (TMPLNR > 0) then
      execute procedure PROC_HOUSEKEEPING_INS(:TMPLNR, :TMPANREISE, :TMPABREISE, 0, 0, :TMPGKLNR, 1);

  end
  end ^

ALTER PROCEDURE PROC_HOUSEKEEPING_INS (BELEG_LNR INTEGER,
ANREISE DATE,
ABREISE DATE,
WW INTEGER,
BLEIBE INTEGER,
GK_LNR INTEGER,
MAND_NR INTEGER)
AS 
declare variable P_MAXSORTMAN integer;
declare variable P_MAXSORT integer;
declare variable P_UMZUG integer;
declare variable P_TMPDATUM date;
declare variable P_ANZGK integer;
begin
  /* Procedure Text */

  /* herausfinden, ob umzug */
  select count(*) from belegung
     WHERE belegung.lnr_gk = :gk_lnr into p_anzgk;

  p_umzug = 0;
  if (p_anzgk > 1) then p_umzug = 1;

                            
  p_tmpdatum = anreise;


  while (abreise >= p_tmpdatum) do
        begin 

              /* max Sortierung herausfinden */
              SELECT max(coalesce(sortierung,0))+1, max(coalesce(man_sortierung,0))+1 from housekeeping into p_maxsort, p_maxsortman;
              /* wichtig bei leerer Tabelle */
              if (p_maxsort is null) then p_maxsort = 0;
              if (p_maxsortman is null) then p_maxsortman = 0;



              /* insert in housekeeping */
              INSERT INTO housekeeping
              (
                datum
                , bleibe
                , umzug
                , GK_LNR
                , PUTZ_LNR_TAG
                , beleg_lnr
                , SORTIERUNG
                , MAN_SORTIERUNG
              )
              SELECT   :p_tmpdatum
                        , :bleibe
                        , :p_umzug
                        , belegung.lnr_gk
                        , zimmstam.putz_lnr
                        , :beleg_lnr
                        , :p_maxsort
                        , 0
              FROM belegung
              INNER JOIN zimmstam on zimmstam.lnr = belegung.lnr_zinr
              WHERE belegung.lnr = :beleg_lnr;

              p_tmpdatum = p_tmpdatum + 1;

         end

end ^

ALTER PROCEDURE PROC_INSERT_TEMP_RE_DRUCK (DRUCKNR INTEGER,
GASTNR INTEGER,
RECHNR INTEGER,
BUCHNR INTEGER,
AUFPERS INTEGER)
AS 
declare variable BELEGNR integer;
declare variable LEIST_LNR integer;
declare variable VON date;
declare variable BIS date;
declare variable MENGE integer;
declare variable TAGE integer;
declare variable BEZEICHN varchar(255);
declare variable TAGBETRAG numeric(12,2) = 0;
declare variable GBETRAG numeric(12,2) = 0;
declare variable ZINR varchar(10);
declare variable MAND_NR integer;
declare variable STS integer;
declare variable STSATZ numeric(12,2) = 0;
declare variable BK_LNR integer;
declare variable AUFP integer;
declare variable STSLNR integer;
begin
  /* Procedure Text */
 delete from rechnungsdruck where rechnungsdruck.drucknr = :drucknr;
 delete from REDRUCK_STEUER where REDRUCK_STEUER.drucknr = :drucknr;



 for
  select buchkont.gk_lnr, buchkont.leist_lnr, buchkont.von ,buchkont.bis, buchkont.me, buchkont.tage, buchkont.bezeichn,buchkont.tagbetrag, buchkont.gbetrag,
    zimmstam.zinr,
    gastkont.mand_nr,
    leiststa.sts ,
    steustam.stsatz,
    buchkont.lnr,
    buchkont.aufp,
    steustam.lnr


  from buchkont
     inner join gastkont on (gastkont.lnr = buchkont.gk_lnr)
     left outer join zimmstam on (zimmstam.lnr = gastkont.lnr_zinr)
     left outer join leiststa on (leiststa.lnr = buchkont.leist_lnr)
     left outer join steustam on (steustam.sts = leiststa.sts and buchkont.von between steustam.von and steustam.bis)

  where buchkont.gk_lnr = :buchnr
    and buchkont.ta_status <500

    into :belegnr, :leist_lnr, :von, :bis, :menge, :tage, :bezeichn, :tagbetrag, :gbetrag, :zinr , :mand_nr, :sts, :stsatz, :bk_lnr, :aufp, :stslnr


  do
  begin
     if (:aufpers=0 or (:aufpers = :aufp) ) then
     begin
        insert into RECHNUNGSDRUCK (DRUCKNR, GK_LNR, LEIST_LNR, GASTNR, VON, BIS, TAGE, ME, BEZEICHN, EBETRAG, GBETRAG,
                                        GASTNAME, RECHNR, ZINR, DUMMY, LEISTWAHL, M_DEBIRECHN, LFDNR, MAND_NR, BK_LNR, GASTVORNAME,
                                        GASTTITEL, GASTANREDE, ARRANG_SORT, SORT_FREI)
            values (:drucknr, :belegnr, :leist_lnr, :gastnr, :von, :bis, :tage, :menge, :bezeichn, :tagbetrag, :gbetrag, '', :rechnr, :zinr, '',
                     0, 0, 0, :mand_nr, :bk_lnr, '', '',
                    '', 9999, 1);

        insert into REDRUCK_STEUER (DRUCKNR, LEIST_LNR, BRUTTOBETRAG, STSLNR)
                                  values ( :drucknr, :leist_lnr, :gbetrag, :stslnr);

     end



  end



  --suspend;



end ^

ALTER PROCEDURE PROC_INS_FAKT_KASSE (VONDATUM DATE,
BISDATUM DATE,
DRUCK_NR INTEGER)
AS 
begin
  /* Procedure Text */
  delete from kassen where lnr >0;

  insert into kassen (LNR, MAND_NR, BUDAT, BELEGNR, LNR_LEIST, KURZBEZ, BEZEICHN, BETRAG, ST_SCHL, MERKER,
                         RECHNR, RE_LAUF, LNR_DEPI, DRUCK_NR, FIBU, OBJEKT, LNR_ZINR, VOND, BISD, MANUELL, GASTNR, WOHER,
                         ERF_DATUM, ERF_ZEIT, ERF_USERID, ZAHLUNGSART, DUMMY, TA_STATUS, SORT_DATUM, LNR_WOHER)

  select              LNR, MAND_NR, BUDAT, BELEGNR, LNR_LEIST, KURZBEZ, BEZEICHN, BETRAG, ST_SCHL, MERKER,
                         RECHNR, RE_LAUF, LNR_DEPI, 0,     FIBU, '', 0, VOND, BISD, MANUELL, ADR_LNR, LNR_WOHER,
                         ERF_DATUM, ERF_ZEIT, ERF_USERID, ZAHLUNGSART, DUMMY, TA_STATUS, SORT_DATUM, LNR_WOHER


  from fakt_erloese
     where budat between :VONDATUM   and :BISDATUM
       and ta_status <10
       and manuell = 0
        and fakt_erloese.rechnr >0
        and fakt_erloese.zahlungsart>0;



  
  insert into kassen (LNR, MAND_NR, BUDAT, BELEGNR, LNR_LEIST, KURZBEZ, BEZEICHN, BETRAG, ST_SCHL, MERKER,
                         RECHNR, RE_LAUF, LNR_DEPI, DRUCK_NR, FIBU, OBJEKT, LNR_ZINR, VOND, BISD, MANUELL, GASTNR, WOHER,
                         ERF_DATUM, ERF_ZEIT, ERF_USERID, ZAHLUNGSART, DUMMY, TA_STATUS, SORT_DATUM, LNR_WOHER)

  select              LNR, MAND_NR, BUDAT, BELEGNR, LNR_LEIST, KURZBEZ, BEZEICHN, BETRAG, ST_SCHL, MERKER,
                         RECHNR, RE_LAUF, LNR_DEPI, 0,     FIBU, '', 0, VOND, BISD, MANUELL, ADR_LNR, LNR_WOHER,
                         ERF_DATUM, ERF_ZEIT, ERF_USERID, ZAHLUNGSART, DUMMY, TA_STATUS, SORT_DATUM, LNR_WOHER


  from fakt_erloese
     where budat between :VONDATUM   and :BISDATUM
       and ta_status <10
          and fakt_erloese.erf_userid=9999
            and manuell = 0;



  update kassen set kassen.druck_nr = :druck_nr
  where lnr >0;



  suspend;
end ^

