ALTER PROCEDURE PROC_INS_PREISLIST_VERERB_FREIM (LNR INTEGER)
AS 
declare variable PROVIDER_LNR integer = 0;
begin
  /* Procedure Text */
 -- suspend;
   for
     select freimeld_pro.lnr
     from freimeld_pro
        where freimeld_pro.ta_status <1000 and freimeld_pro.online_preislisten=1
        and freimeld_pro.PROVIDER in (920)
        into :provider_lnr
   do
   begin
          update or insert into preislist_vererb_freim ( PREISLIST_VERERB_LNR ,   PROVIDER_LNR ,  TA_STATUS, DATUM_ZEIT)
            values(:lnr, :provider_lnr,0, current_timestamp)
                   matching (PREISLIST_VERERB_LNR ,   PROVIDER_LNR ,  TA_STATUS);
   end

end ^

