ALTER PROCEDURE PROC_INS_TEMP_ZIMMER_BELEG (ANREISE DATE,
ABREISE DATE,
LNR_KATE INTEGER,
BELEGNR INTEGER)
AS 
declare variable TAG date;
declare variable BELEGT_ALT integer = 0;
declare variable SHARER integer = 0;
begin
  tag = anreise;

  select gastkont.share_nr from gastkont where lnr = :belegnr
     into :sharer;

  if (sharer>0) then
  begin
  end
  else
  begin

      while (tag< abreise)
      do
      begin
        belegt_alt = 1;
        select belegt+1 from TEMP_BELEGTE_ZIMMER
        where TEMP_BELEGTE_ZIMMER.tag = :tag and TEMP_BELEGTE_ZIMMER.lnr_kate = :lnr_kate
          into :belegt_alt;
    
        update or insert into TEMP_BELEGTE_ZIMMER (TAG, BELEGT, LNR_KATE)
                                 values (:tag,:belegt_alt,:lnr_kate)
                                 matching (TAG, LNR_KATE);
    
        tag = tag+1;
      end
   end

end ^

ALTER PROCEDURE PROC_MELDE_SUCHE (VON DATE,
BIS DATE,
NR VARCHAR(20) CHARACTER SET NONE,
WAHL INTEGER)
RETURNS (NAME1 VARCHAR(60) CHARACTER SET NONE,
NAME2 VARCHAR(60) CHARACTER SET NONE,
STRASSE VARCHAR(60) CHARACTER SET NONE,
LAND VARCHAR(5) CHARACTER SET NONE,
PLZ VARCHAR(10) CHARACTER SET NONE,
ORT VARCHAR(50) CHARACTER SET NONE,
TELE1 VARCHAR(30) CHARACTER SET NONE,
VONAUFH TIMESTAMP,
BISAUFH TIMESTAMP,
AUFTAGE INTEGER,
ZINR VARCHAR(10) CHARACTER SET NONE,
BEMERK VARCHAR(100) CHARACTER SET NONE,
LNR VARCHAR(10) CHARACTER SET NONE,
MELDNR VARCHAR(20) CHARACTER SET NONE,
GK_LNR INTEGER,
ERF_DATUM DATE,
ANZKINDER INTEGER,
PERSZAHL INTEGER,
ANZJUGEND INTEGER,
GEBDAT DATE,
BEGLEIT VARCHAR(60) CHARACTER SET NONE,
K1 VARCHAR(60) CHARACTER SET NONE,
K2 VARCHAR(60) CHARACTER SET NONE,
K3 VARCHAR(60) CHARACTER SET NONE,
K4 VARCHAR(60) CHARACTER SET NONE,
KARTENNR VARCHAR(512) CHARACTER SET NONE,
MAND_NR INTEGER)
AS 
declare variable S varchar(512);
begin
  /* Procedure Text */
  S = '';
  KARTENNR = '';
  IF(:WAHL = 0)THEN  /* Suche über Zeitraum */
  BEGIN
      FOR
        SELECT DISTINCT ADRESSEN.NAME1, ADRESSEN.NAME2, ADRESSEN.STRASSE, ADRESSEN.LAND, ADRESSEN.PLZ,
         ADRESSEN.ORT, ADRESSEN.TELE1, GASTKONT.VONAUFH, GASTKONT.BISAUFH, GASTKONT.AUFTAGE,
         ZIMMSTAM.ZINR, GASTKONT.BEMERK, MELDEDATEN.LNR, MELDEDATEN.MELDNR,
         MELDEDATEN.GK_LNR, MELDEDATEN.ERF_DATUM, GASTKONT.ANZKINDER, GASTKONT.PERSZAHL,
         GASTKONT.ANZJUGEND, ADRESSEN.GEBDAT, ADRESSEN.BEGLEIT, ADRESSEN.K1, ADRESSEN.K2,
         ADRESSEN.K3, ADRESSEN.K4 ,zimmstam.mand_nr
        FROM MELDEDATEN
           LEFT OUTER JOIN MELDEKARTEN ON (MELDEDATEN.GK_LNR = MELDEKARTEN.GK_LNR AND MELDEKARTEN.LNR > 0)
           LEFT OUTER JOIN GASTKONT ON (MELDEDATEN.GK_LNR = GASTKONT.LNR)
           LEFT OUTER JOIN ZIMMSTAM ON (GASTKONT.LNR_ZINR = ZIMMSTAM.LNR)
           LEFT OUTER JOIN ADRESSEN ON (GASTKONT.GASTNR_1 = ADRESSEN.LNR)
        
        WHERE MELDEDATEN.LNR > 0
                AND (MELDEDATEN.ERF_DATUM >= :VON AND MELDEDATEN.ERF_DATUM <= :BIS)

        INTO   :"NAME1",:"NAME2", :"STRASSE",:"LAND",:"PLZ",:"ORT",:"TELE1",
               :"VONAUFH",:"BISAUFH", :"AUFTAGE",:"ZINR",:"BEMERK",:"LNR",:"MELDNR", :"GK_LNR",
               :"ERF_DATUM",:"ANZKINDER",:"PERSZAHL",:"ANZJUGEND",:"GEBDAT",:"BEGLEIT",
               :"K1", :"K2", :"K3", :"K4", :"MAND_NR"
        DO
        BEGIN
            IF(:GK_LNR>0) THEN
            BEGIN
                for
                    SELECT MELDEKARTEN.KARTENNR
                    FROM MELDEDATEN
                        LEFT OUTER JOIN MELDEKARTEN ON (MELDEDATEN.GK_LNR = MELDEKARTEN.GK_LNR AND MELDEKARTEN.LNR > 0)
                        LEFT OUTER JOIN GASTKONT ON (MELDEDATEN.GK_LNR = GASTKONT.LNR)
                        LEFT OUTER JOIN ZIMMSTAM ON (GASTKONT.LNR_ZINR = ZIMMSTAM.LNR)
                        LEFT OUTER JOIN ADRESSEN ON (GASTKONT.GASTNR_1 = ADRESSEN.LNR)
                    WHERE MELDEDATEN.LNR > 0
                            AND MELDEDATEN.GK_LNR = :GK_LNR
                    INTO   :S
                 DO
                 BEGIN
                    IF(:S IS NOT NULL) THEN
                    BEGIN
                        KARTENNR = KARTENNR || :S || '  ';
                        S = '';
                    END
                 END
                 SUSPEND;
                 BEGIN
                    KARTENNR = '';
                 END
             END
        END
  END
  IF(:WAHL = 1)THEN  /* Suche über Karten-Nr. */
  BEGIN
      FOR
        SELECT DISTINCT ADRESSEN.NAME1, ADRESSEN.NAME2, ADRESSEN.STRASSE, ADRESSEN.LAND, ADRESSEN.PLZ,
         ADRESSEN.ORT, ADRESSEN.TELE1, GASTKONT.VONAUFH, GASTKONT.BISAUFH, GASTKONT.AUFTAGE,
         ZIMMSTAM.ZINR, GASTKONT.BEMERK, MELDEDATEN.LNR, MELDEDATEN.MELDNR,
         MELDEDATEN.GK_LNR, MELDEDATEN.ERF_DATUM, GASTKONT.ANZKINDER, GASTKONT.PERSZAHL,
         GASTKONT.ANZJUGEND, ADRESSEN.GEBDAT, ADRESSEN.BEGLEIT, ADRESSEN.K1, ADRESSEN.K2,
         ADRESSEN.K3, ADRESSEN.K4, zimmstam.mand_nr
        FROM MELDEKARTEN
           LEFT OUTER JOIN MELDEDATEN ON (MELDEDATEN.GK_LNR = MELDEKARTEN.GK_LNR AND MELDEDATEN.LNR > 0)
           LEFT OUTER JOIN GASTKONT ON (MELDEKARTEN.GK_LNR = GASTKONT.LNR)
           LEFT OUTER JOIN ZIMMSTAM ON (GASTKONT.LNR_ZINR = ZIMMSTAM.LNR)
           LEFT OUTER JOIN ADRESSEN ON (GASTKONT.GASTNR_1 = ADRESSEN.LNR)
        
        WHERE MELDEKARTEN.LNR > 0
                AND MELDEKARTEN.KARTENNR = :NR

        INTO   :"NAME1",:"NAME2", :"STRASSE",:"LAND",:"PLZ",:"ORT",:"TELE1",
               :"VONAUFH",:"BISAUFH", :"AUFTAGE",:"ZINR",:"BEMERK",:"LNR",:"MELDNR", :"GK_LNR",
               :"ERF_DATUM",:"ANZKINDER",:"PERSZAHL",:"ANZJUGEND",:"GEBDAT",:"BEGLEIT",
               :"K1", :"K2", :"K3", :"K4", :"MAND_NR"
        DO
        BEGIN
            IF(:GK_LNR>0) THEN
            BEGIN
                for
                    SELECT MELDEKARTEN.KARTENNR
                    FROM MELDEKARTEN
                        LEFT OUTER JOIN MELDEDATEN ON (MELDEDATEN.GK_LNR = MELDEKARTEN.GK_LNR
                                    AND MELDEDATEN.LNR > 0)
                        LEFT OUTER JOIN GASTKONT ON (MELDEKARTEN.GK_LNR = GASTKONT.LNR)
                        LEFT OUTER JOIN ZIMMSTAM ON (GASTKONT.LNR_ZINR = ZIMMSTAM.LNR)
                        LEFT OUTER JOIN ADRESSEN ON (GASTKONT.GASTNR_1 = ADRESSEN.LNR)
                    WHERE MELDEKARTEN.LNR > 0
                            AND MELDEKARTEN.KARTENNR = :NR
                            AND MELDEKARTEN.GK_LNR = :GK_LNR
                    INTO   :S
                 DO
                 BEGIN
                    IF(:S IS NOT NULL) THEN
                    BEGIN
                        KARTENNR = KARTENNR || :S || '  ';
                        S = '';
                    END
                 END
                 SUSPEND;
                 BEGIN
                    KARTENNR = '';
                 END
             END
        END
  END
  IF(:WAHL = 2)THEN  /* Suche über Meldeschein-Nr. */
  BEGIN
      FOR
        SELECT DISTINCT ADRESSEN.NAME1, ADRESSEN.NAME2, ADRESSEN.STRASSE, ADRESSEN.LAND, ADRESSEN.PLZ,
         ADRESSEN.ORT, ADRESSEN.TELE1, GASTKONT.VONAUFH, GASTKONT.BISAUFH, GASTKONT.AUFTAGE,
         ZIMMSTAM.ZINR, GASTKONT.BEMERK, MELDEDATEN.LNR, MELDEDATEN.MELDNR,
         MELDEDATEN.GK_LNR, MELDEDATEN.ERF_DATUM, GASTKONT.ANZKINDER, GASTKONT.PERSZAHL,
         GASTKONT.ANZJUGEND, ADRESSEN.GEBDAT, ADRESSEN.BEGLEIT, ADRESSEN.K1, ADRESSEN.K2,
         ADRESSEN.K3, ADRESSEN.K4, zimmstam.mand_nr
        FROM MELDEDATEN
           LEFT OUTER JOIN MELDEKARTEN ON (MELDEDATEN.GK_LNR = MELDEKARTEN.GK_LNR AND MELDEKARTEN.LNR > 0)
           LEFT OUTER JOIN GASTKONT ON (MELDEDATEN.GK_LNR = GASTKONT.LNR)
           LEFT OUTER JOIN ZIMMSTAM ON (GASTKONT.LNR_ZINR = ZIMMSTAM.LNR)
           LEFT OUTER JOIN ADRESSEN ON (GASTKONT.GASTNR_1 = ADRESSEN.LNR)
        
        WHERE MELDEDATEN.LNR > 0
                AND MELDEDATEN.MELDNR = :NR

        INTO   :"NAME1",:"NAME2", :"STRASSE",:"LAND",:"PLZ",:"ORT",:"TELE1",
               :"VONAUFH",:"BISAUFH", :"AUFTAGE",:"ZINR",:"BEMERK",:"LNR",:"MELDNR", :"GK_LNR",
               :"ERF_DATUM",:"ANZKINDER",:"PERSZAHL",:"ANZJUGEND",:"GEBDAT",:"BEGLEIT",
               :"K1", :"K2", :"K3", :"K4", :"MAND_NR"
        DO
        BEGIN
            IF(:GK_LNR>0) THEN
            BEGIN
                for
                    SELECT MELDEKARTEN.KARTENNR
                    FROM MELDEDATEN
                        LEFT OUTER JOIN MELDEKARTEN ON (MELDEDATEN.GK_LNR = MELDEKARTEN.GK_LNR AND MELDEKARTEN.LNR > 0)
                        LEFT OUTER JOIN GASTKONT ON (MELDEDATEN.GK_LNR = GASTKONT.LNR)
                        LEFT OUTER JOIN ZIMMSTAM ON (GASTKONT.LNR_ZINR = ZIMMSTAM.LNR)
                        LEFT OUTER JOIN ADRESSEN ON (GASTKONT.GASTNR_1 = ADRESSEN.LNR)
                    WHERE MELDEDATEN.LNR > 0
                            AND MELDEDATEN.GK_LNR = :GK_LNR
                    INTO   :S
                 DO
                 BEGIN
                    IF(:S IS NOT NULL) THEN
                    BEGIN
                        KARTENNR = KARTENNR || :S || '  ';
                        S = '';
                    END
                 END
                 SUSPEND;
                 BEGIN
                    KARTENNR = '';
                 END
             END
        END
  END
END ^

ALTER PROCEDURE PROC_ONLINE_BK (WAS INTEGER,
GK_LNR INTEGER,
LEIST_LNR INTEGER,
PRLNR INTEGER,
