AS 
begin
  /* Procedure Text */
  if (NR=1) then POST_EVENT 'EV_BELEGUNG';
  if (NR=5) then POST_EVENT 'EV_ANFRAGEN';
  /*suspend; */
end ^

ALTER PROCEDURE PROC_REGKASS_UMSATZ_VERBU (NEW_LNR INTEGER)
AS 
declare variable KOSTENSTELLE varchar(10);
declare variable LEISTLNR integer;
declare variable MENGE integer;
declare variable GBETRAG numeric(12,3);
declare variable TAGBETRAG numeric(12,3);
declare variable LNR integer;
declare variable TAGDATUM integer;
declare variable DATUM date;
declare variable BEZEICHN varchar(200);
declare variable KBEZ varchar(100);
declare variable KURZBEZ varchar(10);
declare variable STS integer;
declare variable LNR_CO integer;
declare variable MAND_NR integer;
declare variable KONTONR varchar(10);
declare variable STEUERSATZ numeric(12,2) = 0;
declare variable BEREICH integer;
begin
  /* Procedure Text */

     SELECT LEISTSTA.LNR, REGKAS_UMSATZ.MENGE, REGKAS_UMSATZ.GBETRAG,regkas_umsatz.lnr, REGKAS_UMSATZ.datum,regkas_umsatz.tage_seit,
            LEISTSTA.bezeichn, LEISTSTA.kurzbez, STEUSTAM.LNR, regkas_umsatz.lnr_co, left(leiststa.bezeichn,100), leiststa.mand_nr, left(leiststa.bemerkung,8),
                               leiststa.kontonr, STEUSTAM.stsatz,regkas_umsatz.bereich
        FROM LEISTSTA
             left outer join steustam on (steustam.sts = leiststa.sts and current_date between steustam.von and steustam.bis and steustam.ta_status <1000)
             INNER JOIN REGKAS_UMSATZ ON (LEISTSTA.WGKASS_LNR = REGKAS_UMSATZ.WGKASS_LNR)
             where regkas_umsatz.lnr = :NEW_LNR
             into :leistlnr, :MENGE, :gbetrag, :lnr, :datum,  :tagdatum, :bezeichn, :kurzbez, :sts, :lnr_co, :KBEZ, :MAND_NR, :KOSTENSTELLE, :KONTONR, :STEUERSATZ, :BEREICH;

             tagbetrag = gbetrag;
             if (menge>0) then tagbetrag = gbetrag / menge;


             insert into stat_umsatz (LEIST_LNR,ME,TAG_BETRAG,DATUM,LNR_CO,TAG_ABS_LNR,BEREICHNR)
             values (:leistlnr,:menge,:tagbetrag,:tagdatum,:lnr_co,0,:BEREICH);

             insert into fakt_erloese (MAND_NR, BUDAT, LNR_LEIST, KURZBEZ, BEZEICHN, BETRAG, ST_SCHL, ERF_DATUM, ERF_ZEIT,
                                       ERF_USERID,LNR_CO,TAG_ABS,TA_STATUS, MANUELL,BELEGNR,RECHNR,RE_LAUF,SORT_DATUM,fibu,merker,lnr_rez,zahlungsart,kostenstelle,konto_nr, STEUERSATZ)
             values (:MAND_NR,:datum,:leistlnr,:KURZBEZ,:KBEZ,:gbetrag,:STS,current_date,current_time,9999,:lnr_co,0,0,0,0,0,0,current_timestamp,0,0,0,9999,:kostenstelle,:kontonr, :steuersatz);

             update regkas_umsatz set regkas_umsatz.ta_status = 1000
                where regkas_umsatz.lnr = :NEW_LNR;


--  suspend;



end ^

ALTER PROCEDURE PROC_REGKASS_UMSATZ_VERBU_NEU (NEW_LNR INTEGER)
AS 
declare variable LEISTLNR integer;
declare variable MENGE integer;
declare variable GBETRAG numeric(12,3);
declare variable TAGBETRAG numeric(12,3);
declare variable LNR integer;
declare variable TAGDATUM integer;
declare variable DATUM date;
declare variable BEZEICHN varchar(200);
declare variable KBEZ varchar(100);
declare variable KURZBEZ varchar(10);
declare variable STS integer;
declare variable LNR_CO integer;
declare variable MAND_NR integer;
declare variable BEREICH integer;
begin
  /* Procedure Text */

     SELECT LEISTSTA.LNR, REGKAS_UMSATZ.MENGE, REGKAS_UMSATZ.GBETRAG,regkas_umsatz.lnr, REGKAS_UMSATZ.datum,regkas_umsatz.tage_seit,
            LEISTSTA.bezeichn, LEISTSTA.kurzbez, LEISTSTA.sts, regkas_umsatz.lnr_co, left(leiststa.bezeichn,100), leiststa.mand_nr, regkas_umsatz.bereich
        FROM LEISTSTA
             INNER JOIN REGKAS_UMSATZ ON (LEISTSTA.LNR = REGKAS_UMSATZ.WGKASS_LNR)
             where regkas_umsatz.lnr = :NEW_LNR
             into :leistlnr, :MENGE, :gbetrag, :lnr, :datum,  :tagdatum, :bezeichn, :kurzbez, :sts, :lnr_co, :KBEZ, :MAND_NR, :BEREICH;

             tagbetrag = gbetrag;
             if (menge>0) then tagbetrag = gbetrag / menge;


             insert into stat_umsatz (LEIST_LNR,ME,TAG_BETRAG,DATUM,LNR_CO,TAG_ABS_LNR,BEREICHNR)
             values (:leistlnr,:menge,:tagbetrag,:tagdatum,:lnr_co,0,:BEREICH);

             insert into fakt_erloese (MAND_NR, BUDAT, LNR_LEIST, KURZBEZ, BEZEICHN, BETRAG, ST_SCHL, ERF_DATUM, ERF_ZEIT,
                                       ERF_USERID,LNR_CO,TAG_ABS,TA_STATUS, MANUELL,BELEGNR,RECHNR,RE_LAUF,SORT_DATUM,fibu,merker,lnr_rez,zahlungsart,kostenstelle)
             values (:MAND_NR,current_date,:leistlnr,:KURZBEZ,:KBEZ,:gbetrag,:STS,current_date,current_time,9999,:lnr_co,0,0,0,0,0,0,current_timestamp,0,0,0,9999,'');

             update regkas_umsatz set regkas_umsatz.ta_status = 1000
                where regkas_umsatz.lnr = :NEW_LNR;



--  suspend;



end ^

ALTER PROCEDURE PROC_REVINATE_SEGMCODE (ADR_LNR INTEGER)
RETURNS (SEGMENTTYP VARCHAR(20) CHARACTER SET NONE)
AS 
begin
  for select 'FAMILIE' as SEGMENTTYP
      from ADRESSEN
      where ADRESSEN.ADR_WAHL = 0 and
            (upper(ADRESSEN.ANREDE) = 'FAMILIE') and
            ADRESSEN.LNR = :ADR_LNR
      union
      select 'FREIZEITGAST' as SEGMENTTYP
      from ADRESSEN
      where ADRESSEN.ADR_WAHL = 0 and
            (upper(ADRESSEN.ANREDE) <> 'FIRMA' and
            (upper(ADRESSEN.ANREDE) <> 'FAMILIE')) and
            ADRESSEN.LNR = :ADR_LNR
      union
      select 'FIRMA' as SEGMENTTYP
      from ADRESSEN
      where ((ADRESSEN.ADR_WAHL = 0 and
            (upper(ADRESSEN.ANREDE) = 'FIRMA')) or (ADRESSEN.ADR_WAHL = 1)) and
            ADRESSEN.LNR = :ADR_LNR

      into :"SEGMENTTYP"
  do
  begin
    suspend;
  end
end ^

ALTER PROCEDURE PROC_SET_BUCHKONT (BUCHUNGSNR INTEGER,
BETRAG NUMERIC(12, 3),
RECH_NR INTEGER)
AS 
declare variable GBETRAG numeric(12,3);
declare variable KASSE_LNR integer;
declare variable BEZEICHN varchar(255);
begin
  /* Procedure Text */
  FOR

        SELECT SUM(REGKAS_DETAIL.gbetrag), STEUSTAM.KASSE_LNR, LEISTSTA.bezeichn
        FROM REGKAS_DETAIL
        left outer JOIN STEUSTAM ON (STEUSTAM.sts_kasse = REGKAS_DETAIL.STSATZ and current_date between steustam.von and steustam.bis)
        INNER JOIN LEISTSTA ON (LEISTSTA.LNR = STEUSTAM.KASSE_LNR)

        WHERE REGKAS_DETAIL.RECHNR = :RECH_NR AND REGKAS_DETAIL.GK_LNR = :BUCHUNGSNR

        group by STEUSTAM.KASSE_LNR, LEISTSTA.bezeichn

        into :GBETRAG, :KASSE_LNR, :BEZEICHN
  do
  begin

      INSERT INTO BUCHKONT
      (MAND_NR, GK_LNR, LEIST_LNR, VON, BIS, TAGE, ME, PRL_LNR, BEZEICHN,
         AUFP, ZIPREIS, PAUSCH, GBETRAG, TAGBETRAG, L_TGABS, TA_STATUS, ERF_DATUM, ERF_ZEIT, ERF_USERID,
         ZAHLUNG_LNR, UMB_GK_LNR, AUTO_WOHER, SPLIT_MANU, ANFANG, ENDE, E_PREIS, RECHNR_KASSE)
      VALUES
      (1, :BUCHUNGSNR, :KASSE_LNR, CURRENT_DATE, CURRENT_DATE, 1, 1, 0, :BEZEICHN,
         0, 0, 0, :GBETRAG, :GBETRAG, NULL, 0, current_date, current_time, 5555,
         0, 0, 0, 0, 0, 0, 0, :RECH_NR);

      update REGKAS_DETAIL
      set ta_status=500
      where gk_lnr = :BUCHUNGSNR AND rechnr = :RECH_NR;
  end
end ^

ALTER PROCEDURE PROC_SET_KURTAXE_UPD (BELEGNR INTEGER,
ME INTEGER,
ME_JUG INTEGER,
ME_KIND INTEGER)
AS 
begin
  /* Procedure Text */
  begin
    /* 1. für erw. */
    update buchkont set buchkont.me = :me, buchkont.gbetrag = buchkont.tage*buchkont.me*buchkont.tagbetrag
    where
        buchkont.lnr = (
        select distinct buchkont.lnr
               from buchkont
                     inner join kurtstam on (kurtstam.LEISTLNR_ERW = buchkont.leist_lnr)
                     where buchkont.gk_lnr = :belegnr and buchkont.ta_status <500);

    /* 2. für jugend. */
    update buchkont set buchkont.me = :me_jug, buchkont.gbetrag = buchkont.tage*buchkont.me*buchkont.tagbetrag
    where
        buchkont.lnr = (
        select distinct buchkont.lnr
               from buchkont
                     inner join kurtstam on (kurtstam.LEISTLNR_JUG = buchkont.leist_lnr)
                     where buchkont.gk_lnr = :belegnr and buchkont.ta_status <500);
    /* 3. für kinder. */
    update buchkont set buchkont.me = :me_kind, buchkont.gbetrag = buchkont.tage*buchkont.me*buchkont.tagbetrag
    where
        buchkont.lnr = (
        select distinct buchkont.lnr
               from buchkont
                     inner join kurtstam on (kurtstam.leistlnr_kind = buchkont.leist_lnr)
                     where buchkont.gk_lnr = :belegnr and buchkont.ta_status <500);


   end
end ^

