ALTER PROCEDURE PROC_UPDATE_ZAHL_DEBIBETRAG (LNR INTEGER,
BETRAG NUMERIC(12, 2))
AS 
declare variable hbetrag numeric(12,2);
begin
  /* Procedure Text */
  FOR
    select zahlungen.debi_bez_betr
       from zahlungen 
          where zahlungen.lnr = :lnr
          into :hbetrag

  do
  begin
    if (hbetrag is null) then hbetrag = 0;
    hbetrag = hbetrag + betrag;
    update zahlungen set zahlungen.debi_bez_betr = :hbetrag
       where lnr = :lnr;
  end
  suspend;
end ^

ALTER PROCEDURE PROC_UPD_ADR_ALTHIST AS 
declare variable TEMP_ADR integer;
declare variable LAST_JAHR integer;
declare variable ADR_LNR integer;
begin
  /* Procedure Text */
  for
  select gasthist.adr_lnr, MAX( EXTRACT(year FROM gasthist.bisdatum) ) AS LAST_JAHR
    from gasthist
        LEFT OUTER JOIN adressen ON (adressen.lnr = gasthist.adr_lnr)
    where gasthist.ta_status < 1000
    group by gasthist.adr_lnr
    order by gasthist.adr_lnr
  into :ADR_LNR, :LAST_JAHR
  do
    if(LAST_JAHR < 2009) then
    begin
        TEMP_ADR = ADR_LNR;
        update adressen set adressen.ta_status = 1002 where adressen.lnr = :ADR_LNR;
    end
  suspend;
end ^

ALTER PROCEDURE PROC_UPD_BUCHK_GKLNR (NEU_GK_LNR INTEGER,
OLD_GK_LNR INTEGER)
AS 
begin
  /* Procedure Text */
  update buchkont set gk_lnr  = :neu_gk_lnr, umb_gk_lnr = :old_gk_lnr
     where gk_lnr = :old_gk_lnr;

  suspend;
end ^

ALTER PROCEDURE PROC_UPD_LEIST_WG AS 
declare variable leist_lnr integer;
declare variable waren_lnr integer;
begin
  /* Procedure Text */
  FOR
      select warengru.lnr, leiststa.lnr
      from leiststa
       inner join warengru on (leiststa.wg = warengru.wgnr)
      into :WAREN_LNR, :LEIST_LNR
  do
  begin
      if(WAREN_LNR > 0 AND LEIST_LNR > 0) THEN
      begin
        update leiststa set leiststa.wg = :WAREN_LNR
        WHERE LEISTSTA.LNR = :LEIST_LNR;
        suspend;
      end
  end
end ^

ALTER PROCEDURE PROC_UPD_NEWSLETTER (MAIL VARCHAR(100) CHARACTER SET NONE,
NEWS_OK SMALLINT)
AS 
declare variable LNR integer;
begin
  /* Procedure Text */
  for
    select adressen.lnr
    from adressen
    where adressen.e_mail = :MAIL and adressen.ta_status < 1000
      into  :LNR
  do
  if(:LNR > 0) THEN
  begin
    update adressen set adressen.newsletter = :NEWS_OK
    where adressen.lnr = :LNR;
  end
end ^

ALTER PROCEDURE PROC_VAKANZ (ANREISE DATE,
ABREISE DATE,
TAGE INTEGER)
RETURNS (MAND_NR INTEGER,
ZINR VARCHAR(10) CHARACTER SET NONE,
KATEGORIE VARCHAR(10) CHARACTER SET NONE,
VERMIETJN INTEGER,
ZIMMERART INTEGER,
HAUSTIER INTEGER,
RAUCHER INTEGER,
TO_OPERATOR INTEGER,
ANZ_BUCH INTEGER,
BELEGTAGE INTEGER,
MAND_ZINR INTEGER,
KATE_LNR INTEGER,
BETTZAHL INTEGER,
GARAGE INTEGER,
ZI_LNR INTEGER)
AS 
declare variable zinr_lnr integer;
declare variable i integer;
begin
  /* Procedure Text */
  ZINR_LNR = 0;
  BELEGTAGE = 0;
  for
    SELECT KATESTAM.KATEGORIE, ZIMMSTAM.lnr, ZIMMSTAM.VERMIETJN, ZIMMSTAM.ZIMMERART, ZIMMSTAM.HAUSTIER,
           ZIMMSTAM.RAUCHER, ZIMMSTAM.TO_OPERATOR,ZIMMSTAM.MAND_NR,ZIMMSTAM.zinr,ZIMMSTAM.mand_nr,
           ZIMMSTAM.lnr_kate,ZIMMSTAM.bettzahl,ZIMMSTAM.garage,ZIMMSTAM.lnr
       FROM ZIMMSTAM
       INNER JOIN KATESTAM ON (ZIMMSTAM.LNR_KATE = KATESTAM.LNR)
          WHERE  (ZIMMSTAM.LNR>0) and (ZIMMSTAM.TA_STATUS < 1000)
      into :kategorie, :zinr_lnr,:vermietjn,:zimmerart,:haustier,:raucher,
           :to_operator,:mand_nr,:zinr,:mand_zinr,:kate_lnr,:bettzahl,:garage,:zi_lnr

  do

  begin
    i = extract(year from :ANREISE);
    execute procedure PROC_ZI_BELEGUNG (:zinr_lnr, i)
           returning_values :BELEGTAGE;
    if(:BELEGTAGE is null) then BELEGTAGE = 0;

    anz_buch = 0;
    if (:tage>0) then
    begin
      select count(*) from belegung b
        where (b.lnr_zinr = :zinr_lnr)
        and (b.ta_status<1000)
        and
          ((b.anreise>=:anreise and b.anreise<:abreise)
        or
          (b.abreise>:anreise and b.abreise<=:abreise)
        or
          (b.anreise<:anreise and b.abreise>:abreise))

        into :anz_buch;
    end
    suspend;
  end
  /*suspend; entfällt weil suspend in schleife - sonst letztes zimmer immer doppelt */

end ^

ALTER PROCEDURE PROC_YIELD (ABREISE DATE,
ANREISE DATE,
KATEGORIE INTEGER)
AS 
declare variable DERZEITAUSLAST integer;
declare variable TAG date;
declare variable ANZ_KATE integer;
declare variable PREISLIST_LNR integer;
declare variable LNR_KATE integer;
declare variable MAXAUSLASTUNG integer;
declare variable PROZAUSLAST integer;
declare variable AUFSCHLAGINPROZ integer;
declare variable PR_LNR integer;
declare variable LNRCALC integer;
declare variable AUFLASTPROZ integer;
declare variable LNRCALC_ALT integer;
declare variable ANZ_VERERBUNG integer;
declare variable MANDNR integer;
declare variable MATCHC varchar(20);
declare variable ANZ_CALC integer;
declare variable LIZENZ_OK integer;


begin
  
  select param_lizenz.yield_verwaltung
      from param_lizenz
         into :LIZENZ_OK;
  if (LIZENZ_OK>0) then
  begin
  
      TAG = ANREISE;
      while (TAG < ABREISE) do
      begin
        /* MAX ZIMMERZAHL UND BELEGT ZIMMERZAHL UND PREISLISTLNR */
        for select KATESTAM.ANZ_KATE, KATESTAM.PREISLIST, TEMP_BELEGTE_ZIMMER.TAG, TEMP_BELEGTE_ZIMMER.BELEGT,
                   TEMP_BELEGTE_ZIMMER.LNR_KATE, KATESTAM.MAND_NR
            from TEMP_BELEGTE_ZIMMER
            inner join KATESTAM on (TEMP_BELEGTE_ZIMMER.LNR_KATE = KATESTAM.LNR)
            where TEMP_BELEGTE_ZIMMER.TAG = :TAG and
                  TEMP_BELEGTE_ZIMMER.LNR_KATE = :KATEGORIE
            into :ANZ_KATE, :PREISLIST_LNR, :TAG, :DERZEITAUSLAST, :LNR_KATE, :MANDNR
        do
        begin
          /* MATCHCODES AUS PREISLIST PRO TAG UND PRO PREISLISTNR (K?nnen mehr sein) */
          for select MATCHC
              from PREISLIST
              left outer join SAISSTAM on (SAISSTAM.SAISON = PREISLIST.SAISON)
              where ((PREISLIST.VON <= :TAG and
                    PREISLIST.BIS > :TAG) or (SAISSTAM.VON <= :TAG and
                    SAISSTAM.BIS > :TAG)) and
                    PREISLIST_LNR = :PREISLIST_LNR
              into :MATCHC
          do
          begin
            MAXAUSLASTUNG = ANZ_KATE;
    
            if (MAXAUSLASTUNG <> 0) then
              /* Prozent */
              PROZAUSLAST = DERZEITAUSLAST * 100 / MAXAUSLASTUNG;
            else
            begin
              /* Verhindern der Division durch 0, ANZAHL DER KATEGORIEN AUS DEM ZIMMERSTAM */
              select count(*)
              from ZIMMSTAM
              where LNR_KATE = :KATEGORIE and
                    TA_STATUS < 1000
              into :ANZ_KATE;
              MAXAUSLASTUNG = ANZ_KATE;
              /* Prozent */
              PROZAUSLAST = DERZEITAUSLAST * 100 / MAXAUSLASTUNG;
            end
    
            /* NEUER AUFSCHLAG IN PROZENT AUS PREISLISTCALC (Kann nur max ein Datensatz sein) */
            ANZ_CALC = 0;
            for select first 1 PRCODE_LNR, LNR, AUF_AB_PROZENT
                from PREISLIST_CALC
                where PREISLIST_CALC.DATUM = :TAG and
                      LNR_KATE = :LNR_KATE and
                      :PROZAUSLAST between PREISLIST_CALC.START_AUSL and PREISLIST_CALC.END_AUSL and
                      MATCHC = :MATCHC and
                      TA_STATUS < 1000
                into :PR_LNR, :LNRCALC, :AUFSCHLAGINPROZ
            do
            begin
              ANZ_CALC = 1;
    
              /* ANZAHL DER VERERBUNGEN */
              select count(*)
              from PREISLIST_VERERB
              where PREISLIST_VERERB.PREISLIST_LNR = :PR_LNR and
                    PREISLIST_VERERB.F_DATUM = :TAG and
                    PREISLIST_VERERB.MATCHC = :MATCHC and
                    PREISLIST_VERERB.TA_STATUS < 1000
              into :ANZ_VERERBUNG;
    
              /* WENN VERERBUNG VORHANDEN */
              if (ANZ_VERERBUNG > 0) then
              begin
    
                /* ALTE AUSLASTUNG IN PROZENT AUS Preislisten Vererbung */
                select AUFLASTUNG_PROZENT
                from PREISLIST_VERERB
                where PREISLIST_VERERB.PREISLIST_LNR = :PR_LNR and
                      PREISLIST_VERERB.F_DATUM = :TAG and
                      PREISLIST_VERERB.MATCHC = :MATCHC and
                      PREISLIST_VERERB.TA_STATUS < 1000
                into :AUFLASTPROZ;
    
                /* ALTE LNR AUS PREISLIST_CALC HOLEN F?R PR?FUNG */
                select LNR
                from PREISLIST_CALC
                where PREISLIST_CALC.DATUM = :TAG and
                      LNR_KATE = :LNR_KATE and
                      :AUFLASTPROZ between PREISLIST_CALC.START_AUSL and PREISLIST_CALC.END_AUSL and
                      MATCHC = :MATCHC
                into :LNRCALC_ALT;
    
                /* WENN KEIN DATENSATZ F?R VORHERIGE AUSLASTUNG IN PREISLIST_CALC */
                if (LNRCALC_ALT is null) then
                  LNRCALC_ALT = -10;
    
                /* WENN ALTE LNR NICHT GLEICH NEUE LNR DANN UPDATE ODER INSERT */
                if (LNRCALC != LNRCALC_ALT) then
                begin
                  update or insert into PREISLIST_VERERB (F_DATUM, PREISLIST_LNR, AUFSCHLAG_ERW_CALC, AUFLASTUNG_PROZENT,
                                                          MAND_NR, MATCHC)
                  values (:TAG, :PREISLIST_LNR, :AUFSCHLAGINPROZ, :PROZAUSLAST, :MANDNR, :MATCHC)
                  matching (F_DATUM, PREISLIST_LNR, MAND_NR, MATCHC);
    
                  update PREISLIST
                  set TA_STATUS = 1,
                      KOR_DATUM = current_date,
                      KOR_ZEIT = current_time
                  where PREISLIST.PREISLIST_LNR = :PREISLIST_LNR and
                        TA_STATUS < 1000 and
                        MATCHC = :MATCHC;
    
                end
              end
              else
              begin
                /* NEUE VERBUNG SCHREIBEN, WENN KEINE VORHANDEN */
                insert into PREISLIST_VERERB (F_DATUM, PREISLIST_LNR, AUFSCHLAG_ERW_CALC, AUFLASTUNG_PROZENT, MAND_NR,
                                              MATCHC)
                values (:TAG, :PREISLIST_LNR, :AUFSCHLAGINPROZ, :PROZAUSLAST, :MANDNR, :MATCHC);
    
                update PREISLIST
                set TA_STATUS = 1,
                    KOR_DATUM = current_date,
                    KOR_ZEIT = current_time
                where PREISLIST.PREISLIST_LNR = :PREISLIST_LNR and
                      TA_STATUS < 1000 and
                      MATCHC = :MATCHC;
              end
            end
    
            /* WENN KEIN DATENSATZ F?R JETZIGE AUSLASTUNG IN PREISLIST_CALC */
            if (ANZ_CALC = 0) then
            begin
              /* STANDARD PREISLISTE */
              update or insert into PREISLIST_VERERB (F_DATUM, PREISLIST_LNR, AUFSCHLAG_ERW_CALC, AUFLASTUNG_PROZENT,
                                                      MAND_NR, MATCHC)
              values (:TAG, :PREISLIST_LNR, 0, :PROZAUSLAST, :MANDNR, :MATCHC)
              matching (F_DATUM, PREISLIST_LNR, MAND_NR, MATCHC);
    
              update PREISLIST
              set TA_STATUS = 1,
                  KOR_DATUM = current_date,
                  KOR_ZEIT = current_time
              where PREISLIST.PREISLIST_LNR = :PREISLIST_LNR and
                    TA_STATUS < 1000 and
                    MATCHC = :MATCHC;
    
            end
          end
    
        end
        TAG = TAG + 1;
      end
   end
end ^

ALTER PROCEDURE PROC_ZI_BELEGUNG (LNR_ZINR INTEGER,
JAHR INTEGER)
RETURNS (TAGE INTEGER)
AS 
begin
  /* Procedure Text */
  for
    SELECT SUM(belegung.abreise - belegung.anreise) AS TAGE
      FROM belegung
        inner join gastkont on (gastkont.lnr = belegung.lnr_gk and gastkont.belegungsart = 0)
           WHERE (belegung.lnr_zinr = :"LNR_ZINR") and
           EXTRACT(YEAR from belegung.anreise) = :"JAHR"
           and (belegung.ta_status < 1000)

       into :"TAGE"


  do
  suspend;
end ^

ALTER PROCEDURE PROC_ZI_FREI ("zinr_lnr" INTEGER,
"anreise" DATE,
"abreise" DATE)
RETURNS ("anz_buch" INTEGER)
AS 
begin
  /* Procedure Text */
  "anz_buch" = 0;
  select count(*) from belegung b
     where (b.lnr_zinr = :"zinr_lnr")
     and (b.ta_status<1000)
     and
      ((b.anreise>=:"anreise" and b.anreise<:"abreise")
      or
      (b.abreise>:"anreise" and b.abreise<=:"abreise")
       or
      (b.anreise<:"anreise" and b.abreise>:"abreise")

          )

     into :"anz_buch";

  suspend;
end ^

ALTER PROCEDURE PROC_ZI_FREI_MIT_BUCHNR (LNRZI INTEGER,
BUCHNR INTEGER,
ANREISE DATE,
ABREISE DATE)
RETURNS (ANZ_BUCH INTEGER)
AS 
begin
    /* Procedure Text */
    ANZ_BUCH = 0;
    select count(*)
    from BELEGUNG
    where (BELEGUNG.LNR_GK <> :BUCHNR) and
          (BELEGUNG.LNR_ZINR = :LNRZI) and
          (BELEGUNG.TA_STATUS < 1000) and
          ((BELEGUNG.ANREISE >= :ANREISE and
          BELEGUNG.ANREISE < :ABREISE) or (BELEGUNG.ABREISE > :ANREISE and
          BELEGUNG.ABREISE <= :ABREISE) or (BELEGUNG.ANREISE < :ANREISE and
          BELEGUNG.ABREISE > :ABREISE))
    into :ANZ_BUCH;

    suspend;
end ^

ALTER PROCEDURE PROC_ZI_FREI_OHNE_ANGEBOTE (ZINR_LNR INTEGER,
ANREISE DATE,
ABREISE DATE)
RETURNS (ANZ_BUCH INTEGER)
AS 
begin
  /* Procedure Text */
  ANZ_BUCH = 0;
  select count(*)
  from belegung b
     inner join  gastkont on (gastkont.lnr = b.lnr_gk and gastkont.BUCH_STATUS <>100)
     where (b.lnr_zinr = :ZINR_LNR)
     and (b.ta_status<1000)
     and
      ((b.anreise>=:ANREISE and b.anreise<:ABREISE)
      or
      (b.abreise>:ANREISE and b.abreise<=:ABREISE)
       or
      (b.anreise<:ANREISE and b.abreise>:ABREISE)

          )

     into :ANZ_BUCH;

  suspend;
end ^

ALTER PROCEDURE PROG_ANZ_PLAN (TA_STATUS INTEGER,
VON DATE,
BIS DATE)
RETURNS (LNR INTEGER,
LNR_ZINR INTEGER,
LNR_GK INTEGER,
ANREISE DATE,
ABREISE DATE,
FARBE INTEGER,
ANZ_ZI INTEGER,
NAME1 VARCHAR(100) CHARACTER SET NONE,
NAME2 VARCHAR(100) CHARACTER SET NONE,
BUCH_STATUS INTEGER,
BU_ST_OPTION INTEGER,
GK_LNR INTEGER)
AS 
begin
  /* Procedure Text */
  for

  select b.lnr, b.lnr_zinr,b.lnr_gk, b.anreise, b.abreise, b.farbe, b.anz_zi,
       a.name1,a.name2,gk.buch_status, gk.bu_st_option,gk.lnr
        from belegung b, adressen a, gastkont gk
  where (gk.lnr = b.lnr_gk and
         a.lnr  = gk.gastnr_1 and
         b.ta_status<:TA_STATUS and
         ((b.anreise>=:von and b.anreise<=:bis) or
          (b.abreise>=:von and b.abreise<=:bis)
         ))


  into :LNR,:LNR_ZINR,:LNR_GK,:ANREISE,:ABREISE,:FARBE,:ANZ_ZI,:NAME1,:NAME2,:BUCH_STATUS,:BU_ST_OPTION,:GK_LNR
  do
  suspend;
end ^

ALTER PROCEDURE PROG_GET_BKLEIST_MIT_SYMB (BELEGNR INTEGER)
RETURNS (AUSWAHL_SYMBOL_LEIST INTEGER)
AS 
begin
  /* Procedure Text */
  for
  select
     first 1
     leiststa.auswahl_symbol  from buchkont
        inner join leiststa on (leiststa.lnr = buchkont.leist_lnr  and leiststa.auswahl_symbol >0)
        where buchkont.gk_lnr = :belegnr
        and (current_Date   between buchkont.von and buchkont.bis)  and buchkont.ta_status <500
          order by buchkont.von
          into :auswahl_symbol_leist
  do
  suspend;
end
 ^

