ALTER PROCEDURE PRO_LESEN_FAKT_VAR2 (VOND DATE,
BISD DATE,
VARIANT_2 INTEGER)
RETURNS (LNR INTEGER,
MAND_NR INTEGER,
BUDAT DATE,
LNR_DEVI INTEGER,
BEZEICHN VARCHAR(50) CHARACTER SET NONE,
BETRAG NUMERIC(12, 3),
RE_NR INTEGER,
TA_STATUS INTEGER,
WOHER INTEGER,
LEIST_LNR INTEGER,
KONTONR VARCHAR(10) CHARACTER SET NONE,
ZAHLUNGSART INTEGER,
CI_STATUS INTEGER,
VONAUFH DATE,
BISAUFH DATE,
LNR_GK INTEGER,
TATIGK VARCHAR(80) CHARACTER SET NONE,
RE_LAUF INTEGER,
UHRZEIT TIME,
GASTNR_1 INTEGER,
RETINT INTEGER,
LNR_CO INTEGER)
AS 
DECLARE VARIABLE BELEGNR INTEGER;
DECLARE VARIABLE HLNR INTEGER;
DECLARE VARIABLE HVOND DATE;
DECLARE VARIABLE HBISD DATE;
DECLARE VARIABLE HBUDAT DATE;
begin
  /* Procedure Text */

  for

  select zahlungen.lnr,zahlungen.mand_nr,zahlungen.budat,zahlungen.lnr_devi,zahlungen.bezeichn,
         zahlungen.betrag,zahlungen.re_nr,zahlungen.ta_status, zahlungen.woher,zahlungen.leist_lnr, 
         devisen.kontonr, devisen.zahlungsart,gastkont.ci_status, gastkont.vonaufh, gastkont.bisaufh,
         gastkont.lnr as belegnr,zahlungen.lnr_gk ,
         zahlungen.tatigk,zahlungen.re_lauf, zahlungen.uhrzeit, zahlungen.gastnr_1,zahlungen.lnr_co 
     from zahlungen
         inner join  devisen on (zahlungen.lnr_devi = devisen.lnr )
         inner join gastkont on (gastkont.lnr = zahlungen.lnr_gk)
     where (zahlungen.lnr>0 and zahlungen.lnr_gk>0 and zahlungen.budat <= :BISD)
            and (devisen.FAKT_AUSW_VAR2=:VARIANT_2)
            and (zahlungen.ta_status<1000)
            and (devisen.ta_status<1000)

         into :LNR, :MAND_NR, :BUDAT, :LNR_DEVI,:BEZEICHN,  :BETRAG, :RE_NR, :ta_status, :woher, :leist_lnr,
              :KONTONR, :ZAHLUNGSART, : CI_STATUS, :VONAUFH, :BISAUFH, :belegnr, :lnr_gk , :tatigk, :re_lauf, :uhrzeit, :gastnr_1,  :lnr_co

  do
  /*suspend; */

  if (belegnr>0) then
  begin
     hlnr = 0;
     hvond = current_date;
     hbisd = current_date;
     for

        select fakt_erloese.lnr as fakt_lnr , fakt_erloese.vond, fakt_erloese.bisd,fakt_erloese.budat
            from fakt_erloese
             where (fakt_erloese.belegnr = :belegnr) and (fakt_erloese.ta_status<1000) and
                  (fakt_erloese.budat between :vond and :bisd)
              into :hlnr, :hvond, :hbisd, :hbudat
     do
     retint = 1;
     if (hlnr is null or (hlnr=0) ) then
     begin
        CI_STATUS = -1;
        retint = 10;
     end
     else
     begin
          vonaufh = hvond;
          bisaufh = hbisd;
          budat = hbudat;
          retint = 2;
     end
     suspend;
  end

end ^

ALTER PROCEDURE SEL_EIGT_ABR_MT (MONAT INTEGER,
JAHR INTEGER,
MAND_NR INTEGER,
BELAST INTEGER)
RETURNS (LEIST_LNR INTEGER,
GBETRAG NUMERIC(12, 3),
BELEGNR INTEGER)
AS 
DECLARE VARIABLE GK_LNR INTEGER;
begin
  /* Procedure Text */
  for
    SELECT TEMP_DRUCK_ZIM_ABRECH.BELEGNR
      FROM TEMP_DRUCK_ZIM_ABRECH
        INNER JOIN EIGT_ABR_LFD ON (TEMP_DRUCK_ZIM_ABRECH.EIGT_LFD = EIGT_ABR_LFD.LNR)
      WHERE     (EIGT_ABR_LFD.TA_STATUS = 0)
           and  (EIGT_ABR_LFD.MONAT = :MONAT)
           and  (EIGT_ABR_LFD.JAHR = :JAHR)
           and  (eigt_abr_lfd.mand_nr = :MAND_NR)
           and  (TEMP_DRUCK_ZIM_ABRECH.BELAST = :BELAST)
            group by belegnr
            into :gk_lnr


  do
  if (gk_lnr>0) then
  begin
     for
      select buchkont.leist_lnr, buchkont.gbetrag, buchkont.gk_lnr
        from buchkont
          where buchkont.gk_lnr = :gk_lnr  and buchkont.ta_status <1000
        into :leist_lnr, :gbetrag, :belegnr
     do
     suspend;
  end
end ^

ALTER PROCEDURE SEL_EIGT_ABR_MT_BELAST (MONAT INTEGER,
JAHR INTEGER,
MAND_NR INTEGER)
RETURNS (KONTONR VARCHAR(10) CHARACTER SET NONE,
BEZEICHN VARCHAR(255) CHARACTER SET NONE,
GBETRAG NUMERIC(12, 3),
ME INTEGER,
BELEGNR INTEGER,
VON DATE,
BIS DATE,
NAME1 VARCHAR(60) CHARACTER SET NONE,
NAME2 VARCHAR(60) CHARACTER SET NONE)
AS 
declare variable GK_LNR integer;
begin
  /* Procedure Text */
  for
    SELECT TEMP_DRUCK_ZIM_ABRECH.BELEGNR
      FROM TEMP_DRUCK_ZIM_ABRECH
        INNER JOIN EIGT_ABR_LFD ON (TEMP_DRUCK_ZIM_ABRECH.EIGT_LFD = EIGT_ABR_LFD.LNR)
      WHERE     (EIGT_ABR_LFD.TA_STATUS = 0)
           and  (EIGT_ABR_LFD.MONAT = :MONAT)
           and  (EIGT_ABR_LFD.JAHR = :JAHR)
           and  (eigt_abr_lfd.mand_nr = :MAND_NR)

            group by belegnr
            into :gk_lnr


  do
  if (gk_lnr>0) then
  begin

     for
       SELECT LEISTSTA.KONTONR, EIGT_KTO.BEZEICHN, EIGT_KTO.GBETRAG,
              EIGT_KTO.ME, EIGT_KTO.GK_LNR, EIGT_KTO.VON, EIGT_KTO.BIS,
              ADRESSEN.NAME1, ADRESSEN.NAME2
          FROM EIGT_KTO
               INNER JOIN LEISTSTA ON (EIGT_KTO.LEIST_LNR = LEISTSTA.LNR)
               INNER JOIN GASTKONT ON (EIGT_KTO.GK_LNR = GASTKONT.LNR)
               INNER JOIN ADRESSEN ON (GASTKONT.GASTNR_1 = ADRESSEN.LNR)
            where eigt_kto.gk_lnr = :gk_lnr and eigt_kto.ta_status<1000
        into :KONTONR, :BEZEICHN, :GBETRAG, :ME, :BELEGNR, :VON, :BIS, :NAME1, :NAME2

     do

     suspend;
  end
end ^

ALTER PROCEDURE SEL_EIGT_ABR_MT_HAUSBESITZER (MONAT INTEGER,
JAHR INTEGER,
MAND_NR INTEGER)
RETURNS (LEIST_LNR INTEGER,
GBETRAG NUMERIC(12, 3),
BELEGNR INTEGER,
EIGT_ABR INTEGER,
BELAST SMALLINT)
AS 
DECLARE VARIABLE GK_LNR INTEGER;
begin
  /* Procedure Text */
  for
    SELECT TEMP_DRUCK_ZIM_ABRECH.BELEGNR
      FROM TEMP_DRUCK_ZIM_ABRECH
        INNER JOIN EIGT_ABR_LFD ON (TEMP_DRUCK_ZIM_ABRECH.EIGT_LFD = EIGT_ABR_LFD.LNR)
      WHERE     (EIGT_ABR_LFD.TA_STATUS = 0)
           and  (EIGT_ABR_LFD.MONAT = :MONAT)
           and  (EIGT_ABR_LFD.JAHR = :JAHR)
           and  (eigt_abr_lfd.mand_nr = :MAND_NR)

            group by belegnr
            into :gk_lnr


  do
  if (gk_lnr>0) then
  begin
     for
      select temp_druck_zim_abrech.leist_lnr, temp_druck_zim_abrech.gbetrag,
             temp_druck_zim_abrech.belegnr, temp_druck_zim_abrech.eigt_abr, temp_druck_zim_abrech.belast

        from temp_druck_zim_abrech
          where temp_druck_zim_abrech.belegnr = :gk_lnr
        into :leist_lnr, :gbetrag, :belegnr, :eigt_abr, :belast
     do
     suspend;
  end
end ^

ALTER PROCEDURE TOOL_ABGL_ADR_LAND AS 
declare variable LNR integer;
declare variable LAND varchar(5);
declare variable LANDKENN varchar(10);
begin
  /* Procedure Text */
  /* Prozdur zum Zuweisen der Landkennung an die Adressen aus der Uebernahme*/
  FOR
    select adressen.lnr, adressen.land
       from adressen
    where adressen.ta_status < 1000
        into :LNR, :LAND
  do
  begin
    if(LNR > 0 AND LAND is not null) then
    begin
        for
           select landstam.landkenn
           from landstam
           where landstam.zeichen = :LAND
           into :LANDKENN
        do
        begin
            if(LANDKENN is not null) then
            begin
               update adressen set adressen.landkenn = :LANDKENN
               where adressen.lnr = :LNR;
            end
        end
    end
 end
end ^

ALTER PROCEDURE TOOL_ABGL_ADR_SELE (VON INTEGER,
BIS INTEGER,
SELE_NR INTEGER)
AS 
declare variable lnr integer;
begin
  /* Procedure Text */
  /* Prozdur zum Zuweisen von Adressen an bestimmte Adress-Selektion*/
  /* VON - BIS Lfd.Nr von Adressen auswaehlen und LNR von Selektionsstamm waehlen */
  FOR
    select adressen.lnr
       from adressen
          where adressen.lnr between :VON and :BIS
          into :LNR
  do
  begin
    insert into adr_sele(adr_lnr, sele_lnr, erf_datum, erf_zeit, ta_status)
    VALUES
    (:LNR, :SELE_NR, current_date, current_time, 0);
  end
  suspend;
end ^

ALTER PROCEDURE TOOL_ABGL_ANZ_ZI_KATE AS 
declare variable lnrkate integer;
declare variable anz integer;
begin
  /* Procedure Text */
  for
    select zimmstam.lnr_kate, count(*) from zimmstam
    where zimmstam.ta_status < 1000 and zimmstam.vermietjn = 1
    group by zimmstam.lnr_kate
    into :LNRKATE, :ANZ
  do
  if (LNRKATE > 0) then
  begin
    UPDATE KATESTAM SET KATESTAM.anz_kate = :ANZ
    WHERE KATESTAM.LNR = :LNRKATE;
  end
end ^

ALTER PROCEDURE TOOL_ABGL_BELEGUNG_LNR_KATE AS 
declare variable LNR integer;
declare variable LNR_KATE integer;
BEGIN
  LNR = 0;
  LNR_KATE = 0;
  FOR
    select belegung.lnr, zimmstam.lnr_kate
      from belegung
       inner join zimmstam on (belegung.lnr_zinr = zimmstam.lnr and belegung.lnr_zinr >0)
       inner join gastkont on ( gastkont.lnr = belegung.lnr_gk AND (GASTKONT.PM = 0 OR GASTKONT.PM IS NULL))
      where belegung.ta_status <500
        and belegung.anreise >= current_Date and (belegung.lnr_kate != zimmstam.lnr_kate)
        into :LNR, :LNR_KATE
  do
  if (LNR > 0) then
  begin
     update belegung set belegung.lnr_kate =:lnr_kate
       where belegung.lnr = :lnr;
  end

end ^

ALTER PROCEDURE TOOL_ABGL_BELEG_AUF_GASTKONT AS 
declare variable lnr_zinr integer;
declare variable lnr_gk integer;
declare variable lnr_kate integer;
BEGIN
  BEGIN
      LNR_ZINR = 0;
      LNR_GK = 0;
      LNR_KATE = 0;
      /* LNR_KATE, LNR_ZINR fuer alle Gastkonten abhänging von Belegungen aktualisieren */
      FOR
        SELECT BELEGUNG.LNR_ZINR, BELEGUNG.LNR_KATE, BELEGUNG.LNR_GK
        FROM BELEGUNG
        WHERE BELEGUNG.ta_status < 1000
    
        into :LNR_ZINR, :LNR_KATE, :LNR_GK
      do
      if (LNR_GK > 0) then
      begin
          UPDATE GASTKONT SET GASTKONT.lnr_kate = :LNR_KATE, GASTKONT.lnr_zinr = :LNR_ZINR
          WHERE GASTKONT.LNR = :LNR_GK;
      end
  end
end ^

ALTER PROCEDURE TOOL_ABGL_BELEG_MIT_GK AS 
declare variable LNR integer;
declare variable BELEG_LNR integer;
declare variable VONAUFH date;
declare variable BISAUFH date;
declare variable LNR_ZINR integer;
declare variable LNR_KATE integer;
declare variable TA_STATUS integer;
begin
  /* Procedure Text */
  /* Prozdur zum Zuweisen der Landkennung an die Adressen aus der Uebernahme*/
  FOR
   select
    gastkont.lnr, belegung.lnr, gastkont.vonaufh, gastkont.bisaufh, gastkont.lnr_zinr, gastkont.lnr_kate, gastkont.ta_status
   from gastkont
   inner join belegung on (gastkont.lnr = belegung.lnr_gk)
   WHERE GASTKONT.ta_status < 500 and
    (
    gastkont.lnr_zinr != belegung.lnr_zinr or gastkont.lnr_kate != belegung.lnr_kate
    or gastkont.vonaufh != belegung.anreise or gastkont.bisaufh != belegung.abreise  )
    into :LNR, :BELEG_LNR, :VONAUFH, :BISAUFH, :LNR_ZINR, :LNR_KATE, :TA_STATUS
  do
  begin
    if(LNR > 0 AND BELEG_LNR > 0) then
    begin
        update belegung set belegung.lnr_zinr = :LNR_ZINR, belegung.lnr_kate = :LNR_KATE, belegung.anreise = :VONAUFH, belegung.abreise = :BISAUFH,
                            belegung.ta_status = :TA_STATUS
        where belegung.lnr = :BELEG_LNR;
    end
 end
end ^

ALTER PROCEDURE TOOL_ABGL_GK_KONTI AS 
declare variable GK_KONTI_LNR integer;
declare variable KONTI_LNR integer;
declare variable LNR_TMP integer;
declare variable LNR_GK_TMP integer;
begin
   /* Alle GKs welche Kontigent haben auf KONTINGENT-Status == 1 setzen */
   for
    SELECT distinct gastkont.lnr
    FROM GASTKONT
        INNER JOIN KONTIGENT ON (KONTIGENT.adr_lnr = GASTKONT.GASTNR_1)
    INTO :GK_KONTI_LNR
    do
    begin
      if(:GK_KONTI_LNR > 0) THEN
      BEGIN
          UPDATE GASTKONT SET GASTKONT.KONTINGENT = 1
          WHERE GASTKONT.LNR = :GK_KONTI_LNR;
      END
    end
  /* Kontigenten-Verbrauch auf 0 setzten für zukünftige Kontingente */
  for
    SELECT KONTIGENT.LNR
    FROM GASTKONT
        INNER JOIN KONTIGENT ON (KONTIGENT.adr_lnr = GASTKONT.GASTNR_1 AND KONTIGENT.DATUM >= current_date)
    INTO :KONTI_LNR
    do
    begin
      if(:KONTI_LNR > 0 ) THEN
      BEGIN
          UPDATE KONTIGENT SET KONTIGENT.verbr_kont = 0
          WHERE KONTIGENT.LNR = :KONTI_LNR;
      END
    end
  /* Kontigenten-Verbrauch auf 0 setzten für zukünftige Kontingente */
  for
    SELECT DISTINCT KONTIGENT.LNR, GASTKONT.LNR AS GK_LNR
    FROM GASTKONT
        INNER JOIN KONTIGENT ON (KONTIGENT.adr_lnr = GASTKONT.GASTNR_1 AND
                                 KONTIGENT.DATUM BETWEEN GASTKONT.VONAUFH AND GASTKONT.BISAUFH-1 AND
                                 GASTKONT.LNR_KATE = KONTIGENT.LNR_KATE)
    WHERE GASTKONT.TA_STATUS < 500 AND GASTKONT.KONTINGENT = 1
    INTO :LNR_TMP, :LNR_GK_TMP
    do
    begin
          if(:LNR_TMP > 0 AND LNR_GK_TMP > 0) THEN
          BEGIN
              UPDATE KONTIGENT SET KONTIGENT.VERBR_KONT = KONTIGENT.VERBR_KONT + 1
              WHERE KONTIGENT.LNR = :LNR_TMP;
          END
    END
end ^

ALTER PROCEDURE TOOL_ABGL_LNR_KATE AS 
declare variable LNR_KATE integer;
declare variable LNR integer;
declare variable LNR_ZINR integer;
BEGIN
  BEGIN
      LNR_ZINR = 0;
      LNR = 0;
      LNR_KATE = 0;
      /* LNR_KATE fuer alle Belegungen aktualisieren mit entsp. ZINR */
      FOR
        SELECT BELEGUNG.LNR_ZINR, BELEGUNG.LNR
        FROM BELEGUNG
              inner join gastkont on (gastkont.lnr = belegung.lnr_gk AND (GASTKONT.PM = 0 OR GASTKONT.PM IS NULL))
        WHERE BELEGUNG.ta_status < 1000
    
        into :LNR_ZINR, :LNR
      do
      if (LNR_ZINR > 0) then
      begin
           SELECT ZIMMSTAM.LNR_KATE
           FROM ZIMMSTAM

           WHERE ZIMMSTAM.LNR = :LNR_ZINR
           into :LNR_KATE;
    
           if(LNR_KATE > 0) then
           begin    
                  UPDATE BELEGUNG SET BELEGUNG.lnr_kate = :LNR_KATE
                  WHERE BELEGUNG.LNR = :LNR;
           end
      end
  end
      BEGIN
      /* LNR_KATE fuer alle Gastkonten aktualisieren mit entsp. ZINR */
      FOR
        SELECT GASTKONT.LNR_ZINR, GASTKONT.LNR
        FROM GASTKONT
        WHERE GASTKONT.ta_status < 1000
        AND (GASTKONT.PM = 0 OR GASTKONT.PM IS NULL)
    
        into :LNR_ZINR, :LNR
      do
      if (LNR_ZINR > 0) then
      begin
           SELECT ZIMMSTAM.LNR_KATE
           FROM ZIMMSTAM
           WHERE ZIMMSTAM.LNR = :LNR_ZINR
           into :LNR_KATE;
    
           if(LNR_KATE > 0) then
           begin    
                  UPDATE GASTKONT SET GASTKONT.lnr_kate = :LNR_KATE
                  WHERE GASTKONT.LNR = :LNR;
           end
      end
  end
end ^

ALTER PROCEDURE TOOL_ABGL_PAUS_STD_PREISE AS 
declare variable SAIS_VON date;
declare variable SAIS_BIS date;
declare variable SAIS_LNR integer;
declare variable SAIS_NR integer;
declare variable VON date;
declare variable BIS date;
declare variable BETRAG numeric(12,3);
declare variable MIN_TAGE integer;
declare variable MINUS_TAGE integer;
declare variable MATCHC varchar(20);
declare variable SAISON integer;
declare variable LNR integer;
begin
  /* Procedure Text */
  for
     SELECT distinct saisstam.von AS SAIS_VON, saisstam.bis AS SAIS_BIS, saisstam.lnr AS SAIS_LNR, saisstam.saison AS SAIS_NR,
                        preislist.von, preislist.bis, preislist.betrag, preislist.min_tage, preislist.minus_tage, preislist.matchc, preislist.saison, preislist.lnr
    from PREISLIST
          left outer JOIN SAISSTAM ON
          (
            (preislist.von = saisstam.von and preislist.bis+1 = saisstam.bis)
            or (preislist.von+1 = saisstam.von and preislist.bis+1 = saisstam.bis)
            and ((saisstam.bemerk = 'Pauschale 14=11' and preislist.matchc = '14=11')
            or (saisstam.bemerk = 'Pauschale 7=6' and preislist.matchc = '7=6' )
            or (saisstam.bemerk = 'Pauschale 7=5' and preislist.matchc = '7=5' )
            or (saisstam.bemerk = 'Pauschale 7=4' and preislist.matchc = '7=4' ))
          )
           WHERE PREISLIST.TA_STATUS<1000 AND PREISLIST.MAND_NR = 1
                 AND PREISLIST.PREISTYP = 1
                 AND PREISLIST.PRCODE_LNR = 2
                 AND PREISLIST.LNR > 0 
                 and preislist.bis > current_date
     ORDER BY PREISLIST.SORT_NR, preislist.matchc, SAISSTAM.VON
     into :SAIS_VON, :SAIS_BIS, :SAIS_LNR, :SAIS_NR, :VON, :BIS, :BETRAG, :MIN_TAGE, :MINUS_TAGE, :MATCHC, :SAISON, :LNR
  do
  begin
  if(LNR > 0) then
    begin
        update preislist set preislist.betrag = preislist.betrag / (:MIN_TAGE - :MINUS_TAGE), preislist.pauschale = 0, preislist.saison = :SAIS_NR,
                preislist.betrag_pers = 1, preislist.prcode_lnr = 1, preislist.preistyp = 0, preislist.von = NULL, preislist.bis = NULL
        where preislist.lnr = :LNR;
    end
  end
end ^

ALTER PROCEDURE TOOL_AKT_LANDSTAM RETURNS (UPD_OK SMALLINT)
AS 
declare variable landkenn varchar(10);
declare variable anz integer;
declare variable begin_upd smallint;
begin
  /* Procedure Text */
  /* Prozdur zum Update des LANDSTAM*/
  /* VON - BIS Lfd.Nr von Adressen auswaehlen und LNR von Selektionsstamm waehlen */

  BEGIN_UPD = 1;
  UPD_OK = 0;

  FOR
    select landstam.landkenn, count(landstam.landkenn) AS ANZ
       from landstam
    where landstam.ta_status < 1000
    group by landstam.landkenn
    into :LANDKENN, :ANZ
  do
  begin
    if(ANZ > 1 or (LANDKENN = '' or LANDKENN is NULL) ) then
    begin
        BEGIN_UPD = 0;
    end
  end
  if(BEGIN_UPD = 1) then
  begin
      update landstam set landstam.lnr = landstam.lnr + 1000
      where landstam.ta_status < 1000;
      update landstam set landstam.lnr = landstam.landkenn
      where landstam.ta_status < 1000;
      UPD_OK = 1;
  end
  suspend;
end ^

ALTER PROCEDURE TOOL_BAR_FAKT_ZAHLUNGEN (VON DATE,
BIS DATE)
RETURNS (LNR_CO INTEGER,
SUMME_ZA NUMERIC(12, 2),
SUMME_FAKT NUMERIC(12, 2),
DIFFERENZ NUMERIC(12, 2))
AS 
declare variable TEMP_LNRCO integer;
declare variable TEMP_ZABETRAG numeric(12,2) = 0;
declare variable TEMP_DIF numeric(12,2) = 0;
declare variable TEMP_FAKTBETRAG numeric(12,2) = 0;
declare variable TEMP_DATUM date;
begin
  /* Procedure Text */

  for
      select distinct lnr_co
         from zahlungen
             inner join devisen on (devisen.lnr = zahlungen.lnr_devi)
         where zahlungen.budat between :von and :bis  and zahlungen.ta_status<1000
          and devisen.zahlungsart = 0
           group by lnr_co
           union
            select distinct lnr_co

         from fakt_erloese
         where budat between :von and :bis  and ta_status<1000
           group by lnr_co

          into :TEMP_LNRCO
  do
  begin

    select sum(betrag)
         from zahlungen
             inner join devisen on (devisen.lnr = zahlungen.lnr_devi)
         where zahlungen.lnr_co = :temp_lnrco and zahlungen.ta_status<1000
          and devisen.zahlungsart = 0
           group by lnr_co
       into :temp_zabetrag;


    select sum(fakt_erloese.betrag)
      from fakt_erloese
      where fakt_erloese.ta_status <1000

      and   fakt_erloese.lnr_co = :temp_lnrco
        into :temp_faktbetrag;

    differenz = :temp_zabetrag - :temp_faktbetrag;
    if (:differenz<>0 and temp_lnrco >0)    then
    begin
       --datum = :temp_datum;
       lnr_co = :temp_lnrco;
       summe_za = :temp_zabetrag;
       summe_fakt = :temp_faktbetrag;
       suspend;
    end
    temp_zabetrag = 0;
    temp_faktbetrag = 0;
    temp_lnrco = 0;



  end
 -- suspend;
end ^

ALTER PROCEDURE TOOL_DEL_ABGL_INTERNET AS 
declare variable lnr integer;
begin
  /* Procedure Text */
  for
    select gastkont.lnr
    from gastkont
    where gastkont.ie_gk_lnr > 0 and gastkont.lnr > 0
    into :LNR
  do
  begin
  if(LNR > 0) then
  begin
   update belegung set belegung.ta_status = 1000 where belegung.lnr_gk = :LNR;
   update gastkont set gastkont.ta_status = 1000 where gastkont.lnr = :LNR;
  end
  end
end ^

ALTER PROCEDURE TOOL_DEL_OLD_PREISLIST (DATUM DATE)
AS 
declare variable lnr integer;
begin
  /* Procedure Text */
  for
    SELECT VIEW_PREISLISTE.plnr
    FROM VIEW_PREISLISTE
    WHERE
    (VIEW_PREISLISTE.PPREISTYP > 0 AND VIEW_PREISLISTE.P_BIS < :DATUM)
    or
    (VIEW_PREISLISTE.PSAISON > 0 AND VIEW_PREISLISTE.S_BIS < :DATUM)
    into :LNR
  do
  begin
  if(LNR > 0) then
  begin
   update PREISLIST set PREISLIST.ta_status = 1000 where PREISLIST.lnr = :LNR;
  end
  end
end ^

ALTER PROCEDURE TOOL_FAKT_ERL_ADR_UPD AS 
DECLARE VARIABLE LNR INTEGER;
DECLARE VARIABLE BELEGNR INTEGER;
DECLARE VARIABLE GASTNR INTEGER;
BEGIN
  /* Procedure Text */
  FOR
    SELECT FAKT_ERLOESE.belegnr, FAKT_ERLOESE.LNR
    FROM FAKT_ERLOESE
    WHERE FAKT_ERLOESE.adr_lnr <= 0

    into :belegnr, :lnr

  do
  if (belegnr>0) then
  begin
       SELECT GASTKONT.gastnr_1
       FROM GASTKONT
       where GASTKONT.lnr = :belegnr
       into :GASTNR;

       if(gastnr>0) then
       begin
           UPDATE FAKT_ERLOESE SET FAKT_ERLOESE.adr_lnr = :GASTNR
              WHERE FAKT_ERLOESE.lnr = :LNR;
       end
  end
  suspend;
end ^

ALTER PROCEDURE TOOL_FREIMELD_LIZ_UPD AS 
declare variable hint integer;
begin
  /* Procedure Text */
  HINT = 0;
  FOR
    SELECT COUNT(freimeld_pro.lnr)
     FROM freimeld_pro
        WHERE freimeld_pro.ta_status < 1000
          INTO :hint
  DO
  IF (HINT > 0) then
  begin
     UPDATE param_lizenz SET param_lizenz.freimeld_prov = :hint
       WHERE lnr = 1;
  end
  suspend;
end ^

ALTER PROCEDURE TOOL_GET_ARR_LIST (BELEG_NR INTEGER)
RETURNS (ARRANG VARCHAR(512) CHARACTER SET NONE)
AS 
declare variable FIRST_WERT smallint;
declare variable ARRANG_TEMP varchar(512);
begin
  /* Procedure Text */
  ARRANG_TEMP = '';
  ARRANG = '';
  FIRST_WERT = 0;
  for
    select buchkont.me || ' ' ||leiststa.kurzbez
    from gastkont
        left outer join buchkont on (buchkont.gk_lnr = gastkont.lnr )
        left outer join preislist on (preislist.lnr = buchkont.prl_lnr)
           left outer join leiststa on (leiststa.lnr = preislist.leist_lnr)
    
      where  gastkont.lnr = :BELEG_NR and (leiststa.penslist_lnr > 0 or preislist.penslist_lnr > 0)
             and buchkont.ta_status < 1000
      into :ARRANG_TEMP
  do
  if(FIRST_WERT = 0) then
  begin
      ARRANG = ARRANG || ARRANG_TEMP;
      FIRST_WERT = 1;
  end
  else
  begin
      ARRANG = ARRANG || '; ' || ARRANG_TEMP;
  end
  suspend;
end ^

ALTER PROCEDURE TOOL_GET_ARR_LIST_TAG (BELEG_NR INTEGER,
TAG DATE)
RETURNS (ARRANG VARCHAR(255) CHARACTER SET NONE)
AS 
declare variable FIRST_WERT smallint = 0;
declare variable ARRANG_TEMP varchar(512);
begin
  /* Procedure Text */
  ARRANG_TEMP = '';
  ARRANG = '';
  FIRST_WERT = 0;
  for
    select buchkont.me || ' ' ||leiststa.kurzbez
    from gastkont
        left outer join buchkont on (buchkont.gk_lnr = gastkont.lnr )
        left outer join preislist on (preislist.lnr = buchkont.prl_lnr)
           left outer join leiststa on (leiststa.lnr = preislist.leist_lnr)
    
      where  (gastkont.lnr = :BELEG_NR and (leiststa.penslist_lnr > 0 or preislist.penslist_lnr > 0)
             and buchkont.ta_status < 1000)
             and (buchkont.bis > :TAG and buchkont.von<= :TAG)
      into :ARRANG_TEMP
  do
  if(FIRST_WERT = 0) then
  begin
      ARRANG = ARRANG || ARRANG_TEMP;
      FIRST_WERT = 1;
  end
  else
  begin
      ARRANG = ARRANG || '; ' || ARRANG_TEMP;
  end
  suspend;
end ^

ALTER PROCEDURE TOOL_GK_ZA_GASTNR_1_UPDATE AS 
DECLARE VARIABLE GASTNR INTEGER;
DECLARE VARIABLE GK_LNR INTEGER;
begin
  /* Procedure Text */
  for
    select LNR_GK
    from zahlungen
    where zahlungen.gastnr_1 is null or zahlungen.gastnr_1 <= 0

    into :gk_lnr

  do
  if (gk_lnr>0) then
  begin
       SELECT GASTNR_1
       FROM GASTKONT
       where GASTKONT.lnr = :gk_lnr
       into :GASTNR;

       if(gastnr>0) then
       begin
         UPDATE zahlungen SET GASTNR_1 = :GASTNR
            WHERE zahlungen.lnr_gk = :gk_lnr;
       end
  end
  suspend;
end ^

ALTER PROCEDURE TOOL_LISTEN_ALLE_MAND AS 
declare variable lnr integer;
declare variable name varchar(30) character set none;
declare variable bezeichn varchar(60) character set none;
declare variable drucker varchar(100) character set none;
declare variable bereich integer;
declare variable ubereich smallint;
declare variable ta_status integer;
begin
  /* Procedure Text */
   FOR
    SELECT mandant.lnr
    FROM MANDANT
    WHERE MANDANT.ta_status < 1000 AND MANDANT.LNR > 1

    into :LNR

  do
  if (LNR > 0) then
  begin
  FOR
       select 
            listen.list_namen,
            listen.list_bezeichn,
            listen.druckername,
            listen.bereich,
            listen.ubereich,
            listen.ta_status
       FROM LISTEN
       where LISTEN.mand_nr = 1
       into :NAME, :BEZEICHN, :DRUCKER, :BEREICH, :UBEREICH, :TA_STATUS
       do
       begin
           INSERT INTO LISTEN(MAND_NR,LIST_NAMEN,LIST_BEZEICHN,DRUCKERNAME,BEREICH,UBEREICH,TA_STATUS)
           VALUES (:LNR, :NAME, :BEZEICHN, :DRUCKER, :BEREICH, :UBEREICH, :TA_STATUS);
       end
  end
end ^

ALTER PROCEDURE TOOL_PRLIST_MUELLER (MAND_NR INTEGER)
AS 
declare variable lnr integer;
declare variable max_tage integer;
begin
  /* Procedure Text */
  for
       select preislist.lnr, preislist.max_tage
       from preislist
       where preislist.mand_nr = :MAND_NR and preislist.ta_status < 1000 and preislist.preistyp = 1
       into :LNR, :MAX_TAGE
  do
   if(LNR > 0 and MAX_TAGE > 0) then
   begin
       update preislist
       set preislist.preistyp = 0,
           preislist.betrag = preislist.betrag / MAX_TAGE,
           preislist.ezpreis = preislist.ezpreis / MAX_TAGE,
           preislist.ezzuschlag = preislist.ezzuschlag / MAX_TAGE,
           preislist.PAUFSCHLAG1 = preislist.PAUFSCHLAG1 / MAX_TAGE,
           preislist.PAUFSCHLAG2 = preislist.PAUFSCHLAG2 / MAX_TAGE,
           preislist.PAUFSCHLAG3 = preislist.PAUFSCHLAG3 / MAX_TAGE,
           preislist.PAUFSCHLAG4 = preislist.PAUFSCHLAG4 / MAX_TAGE,
           preislist.PAUFSCHLAG5 = preislist.PAUFSCHLAG5 / MAX_TAGE,
           preislist.PAUFSCHLAG6 = preislist.PAUFSCHLAG6 / MAX_TAGE,
           preislist.pauschale = 0
       where preislist.lnr = :LNR;
   end
end ^

