ALTER PROCEDURE TOOL_STAT_BELEG_GK (VONDATUM DATE,
BISDATUM DATE)
RETURNS (TAGEGK INTEGER,
TAGE INTEGER,
PERSZAHLGK INTEGER,
PERSZAHL INTEGER,
BELEGNR INTEGER)
AS 
declare variable TEMP_TAGEGK integer;
declare variable TEMP_PERSZAHLGK integer;
declare variable TEMP_TAGE integer;
declare variable TEMP_PERSZAHL integer;
declare variable TEMP_BELEGNR integer;
begin
  /* Procedure Text */

  for

    select
     min( stat_belegung.gk_lnr)
     from stat_belegung
     group by stat_belegung.gk_lnr
    
    union

     select
         gastkont.lnr
        from gastkont where
        (gastkont.ta_status<1000)
        and (gastkont.vonaufh  between :vondatum and :bisdatum)
          group by gastkont.lnr

          into :temp_belegnr

  do
  if ( temp_belegnr>0) then
  begin


    temp_perszahl = 0;
    temp_perszahlgk = 0;
    temp_tage = 0;
    temp_tagegk = 0;


    select
    sum(stat_belegung.anzerw),
    count(*)

    from stat_belegung
    where stat_belegung.gk_lnr = :temp_belegnr
    group by stat_belegung.gk_lnr

    into :temp_perszahl, :temp_tage;



    select
    min((gastkont.perszahl* auftage)),
    min(gastkont.auftage)

    from gastkont
    where gastkont.lnr = :temp_belegnr
    group by gastkont.lnr

    into :temp_perszahlgk, :temp_tagegk;

    if (:temp_perszahl <> :temp_perszahlgk or
        :temp_tage <> :temp_tagegk) then
    begin
       BELEGNR = :temp_belegnr;
       perszahl = :temp_perszahl;
       perszahlgk = :temp_perszahl;
       tage = :temp_tage;
       tagegk = :temp_tagegk;
       suspend;
    end
    temp_belegnr = 0;
--    temp_perszahl = 0;
--    temp_perszahlgk = 0;
--    temp_tage = 0;
--    temp_tagegk = 0;


  end
 -- suspend;
end ^

ALTER PROCEDURE TOOL_TERMINE_BETRAG_ABGLEICHEN AS 
declare variable old_lnr integer;
declare variable betrag numeric(12,2);
begin
  /* Procedure Text */
  for
     select termine.lnr, leiststa.betrag
        from termine
          inner join leiststa on (leiststa.lnr = termine.leist_lnr)
            into :OLD_LNR, :BETRAG
  do
  if (betrag>0) then
  begin
     update termine set betrag = :BETRAG
       where lnr = :OLD_LNR;

  end
  suspend;
end ^

ALTER PROCEDURE TOOL_UPDATE_SPLITTING (LEISTUNG INTEGER,
TAGE INTEGER)
AS 
