ALTER PROCEDURE TOOL_UPD_FAKT_KONTONR AS 
begin
  /* Procedure Text */
  update fakt_erloese set fakt_erloese.konto_nr = (select leiststa.kontonr from leiststa where leiststa.lnr = fakt_erloese.lnr_leist)
     where fakt_erloese.zahlungsart = 9999 and ((fakt_erloese.konto_nr is null) or (fakt_erloese.konto_nr = '')) ;


   update fakt_erloese set fakt_erloese.konto_nr = (select devisen.kontonr from devisen where devisen.lnr = fakt_erloese.lnr_leist)
     where fakt_erloese.zahlungsart < 9999 and ((fakt_erloese.konto_nr is null) or (fakt_erloese.konto_nr = ''));


end ^

ALTER PROCEDURE TOOL_UPD_FAKT_STEUER AS 
declare variable STS integer;
declare variable ST_SATZ numeric(12,2) = 0;
declare variable LNR_LEIST integer;
declare variable BUDAT date;
BEGIN
   for select fakt_erloese.lnr_leist, fakt_erloese.budat
   from fakt_erloese
     where fakt_erloese.zahlungsart = 9999
     group by fakt_erloese.lnr_leist, fakt_erloese.budat
     into :LNR_LEIST, :budat

   do
   begin
      select first 1 steustam.lnr, steustam.stsatz
      from leiststa
       inner join steustam on (steustam.sts = leiststa.sts and :budat between steustam.von and steustam.bis)
       where leiststa.lnr = :LNR_LEIST
        into :sts, st_satz;

      update fakt_erloese set fakt_erloese.st_schl = :sts, fakt_erloese.steuersatz = :st_satz
       where fakt_erloese.lnr_leist = :lnr_leist and  fakt_erloese.budat = :BUDAT;
   end
END ^

ALTER PROCEDURE TOOL_UPD_FARBE_MANUELL (OPTION_F INTEGER,
RUECK INTEGER,
OHNE_ZI_WECHSEL INTEGER,
ANG_OHNE_OPT INTEGER,
ANG_MIT_OPT INTEGER)
AS 
declare variable farbe integer;
declare variable lnr integer;
begin
  /* Procedure Text */
  LNR = 0;
  begin
  for
        select gastkont.lnr
        from belegung
        inner join gastkont on (gastkont.lnr = belegung.lnr_gk and gastkont.bu_st_option >= 10000
                                                    and (gastkont.buch_status = 0 or gastkont.buch_status is Null))
        into :LNR
  do
   update belegung set belegung.farbe = :OPTION_F
   where belegung.lnr_gk = :LNR;
  end

  LNR = 0;
  begin
  /* Procedure Text */
  for
        select gastkont.lnr
        from belegung
        inner join gastkont on (gastkont.lnr = belegung.lnr_gk and (gastkont.bu_st_option >= 1000 and gastkont.bu_st_option < 10000)
                                                    and (gastkont.buch_status = 0 or gastkont.buch_status is Null))
        into :LNR
  do
   update belegung set belegung.farbe = :RUECK
   where belegung.lnr_gk = :LNR;
  end

  LNR = 0;
  begin
   for
        select gastkont.lnr
        from belegung
        inner join gastkont on (gastkont.lnr = belegung.lnr_gk and gastkont.bu_st_option >= 100 and gastkont.bu_st_option < 1000
                                                    and (gastkont.buch_status = 0 or gastkont.buch_status is Null))
        into :LNR
  do
   update belegung set belegung.farbe = :OHNE_ZI_WECHSEL
   where belegung.lnr_gk = :LNR;
  end

  LNR = 0;
  begin
  /* Procedure Text */
  for
        select gastkont.lnr
        from belegung
        inner join gastkont on (gastkont.lnr = belegung.lnr_gk and gastkont.buch_status = 100
                                                    and gastkont.bu_st_option >= 10000)
        into :LNR
  do
   update belegung set belegung.farbe = :ANG_MIT_OPT
   where belegung.lnr_gk = :LNR;
  end

  LNR = 0;
  begin
  /* Procedure Text */
  for
        select gastkont.lnr
        from belegung
        inner join gastkont on (gastkont.lnr = belegung.lnr_gk and gastkont.buch_status = 100
                                                    and (gastkont.bu_st_option = 0 or gastkont.bu_st_option is NULL))
        into :LNR
  do
   update belegung set belegung.farbe = :ANG_OHNE_OPT
   where belegung.lnr_gk = :LNR;
  end
  suspend;
end ^

ALTER PROCEDURE TOOL_UPD_KONTI_AFTER_CHANGE (GK_LNR INTEGER,
LNR_ONLINETRANS INTEGER)
AS 
declare variable LNR_TMP integer;
declare variable ADR_LNR_TMP integer;
declare variable LNR_GK_TMP integer;
declare variable OLD_ANREISE date;
declare variable OLD_ABREISE date;
declare variable VON date;
declare variable BIS date;
begin
   /* Veränderung bei Kontingenten-Reservierung */
   for
    SELECT onlinetrans_alle.old_anreise, onlinetrans_alle.old_abreise, belegung.anreise, belegung.abreise
    FROM GASTKONT
        INNER JOIN onlinetrans_alle ON (onlinetrans_alle.lnr = :LNR_ONLINETRANS)
        left outer JOIN belegung ON (belegung.lnr_gk = gastkont.lnr and belegung.ta_status < 1000)
    WHERE GASTKONT.LNR = :GK_LNR AND GASTKONT.KONTINGENT = 1
    INTO :OLD_ANREISE, :OLD_ABREISE, :VON, :BIS
  do
  begin
      /* Verlängerung der Abreise */
      IF(:OLD_ABREISE < :BIS) THEN
      BEGIN
         for
            SELECT DISTINCT KONTIGENT.LNR, GASTKONT.GASTNR_1, GASTKONT.LNR
            FROM GASTKONT
                INNER JOIN KONTIGENT ON (KONTIGENT.adr_lnr = GASTKONT.GASTNR_1 AND KONTIGENT.DATUM BETWEEN :OLD_ABREISE AND :BIS-1 AND GASTKONT.LNR_KATE = KONTIGENT.LNR_KATE)
            WHERE GASTKONT.LNR = :GK_LNR AND GASTKONT.KONTINGENT = 1
            INTO :LNR_TMP, :ADR_LNR_TMP, :LNR_GK_TMP
         do
         if(:ADR_LNR_TMP > 0 AND :LNR_TMP > 0 AND :LNR_GK_TMP > 0) THEN
         BEGIN
            UPDATE KONTIGENT SET KONTIGENT.VERBR_KONT = KONTIGENT.VERBR_KONT + 1
            WHERE KONTIGENT.LNR = :LNR_TMP;
         END
      END
      /* Verkürzung der Abreise */
      ELSE IF(:OLD_ABREISE > :BIS) THEN
      BEGIN
         for
            SELECT DISTINCT KONTIGENT.LNR, GASTKONT.GASTNR_1, GASTKONT.LNR
            FROM GASTKONT
                INNER JOIN KONTIGENT ON (KONTIGENT.adr_lnr = GASTKONT.GASTNR_1 AND KONTIGENT.DATUM BETWEEN :BIS AND :OLD_ABREISE-1 AND GASTKONT.LNR_KATE = KONTIGENT.LNR_KATE)
            WHERE GASTKONT.LNR = :GK_LNR AND GASTKONT.KONTINGENT = 1
            INTO :LNR_TMP, :ADR_LNR_TMP, :LNR_GK_TMP
         do
         if(:ADR_LNR_TMP > 0 AND :LNR_TMP > 0 AND :LNR_GK_TMP > 0) THEN
         BEGIN
            UPDATE KONTIGENT SET KONTIGENT.VERBR_KONT = KONTIGENT.VERBR_KONT - 1
            WHERE KONTIGENT.LNR = :LNR_TMP;
         END
      END
      /* Anreise später*/
      IF(:OLD_ANREISE < :VON) THEN
      BEGIN
         for
            SELECT DISTINCT KONTIGENT.LNR, GASTKONT.GASTNR_1, GASTKONT.LNR
            FROM GASTKONT
                INNER JOIN KONTIGENT ON (KONTIGENT.adr_lnr = GASTKONT.GASTNR_1 AND KONTIGENT.DATUM BETWEEN :OLD_ANREISE AND :VON-1 AND GASTKONT.LNR_KATE = KONTIGENT.LNR_KATE)
            WHERE GASTKONT.LNR = :GK_LNR AND GASTKONT.KONTINGENT = 1
            INTO :LNR_TMP, :ADR_LNR_TMP, :LNR_GK_TMP
         do
         if(:ADR_LNR_TMP > 0 AND :LNR_TMP > 0 AND :LNR_GK_TMP > 0) THEN
         BEGIN
            UPDATE KONTIGENT SET KONTIGENT.VERBR_KONT = KONTIGENT.VERBR_KONT - 1
            WHERE KONTIGENT.LNR = :LNR_TMP;
         END
      END
      /* Anreise früher */
      ELSE IF(:OLD_ANREISE > :VON) THEN
      BEGIN
         for
            SELECT DISTINCT KONTIGENT.LNR, GASTKONT.GASTNR_1, GASTKONT.LNR
            FROM GASTKONT
                INNER JOIN KONTIGENT ON (KONTIGENT.adr_lnr = GASTKONT.GASTNR_1 AND KONTIGENT.DATUM BETWEEN :VON AND :OLD_ANREISE-1 AND GASTKONT.LNR_KATE = KONTIGENT.LNR_KATE)
            WHERE GASTKONT.LNR = :GK_LNR AND GASTKONT.KONTINGENT = 1
            INTO :LNR_TMP, :ADR_LNR_TMP, :LNR_GK_TMP
         do
         if(:ADR_LNR_TMP > 0 AND :LNR_TMP > 0 AND :LNR_GK_TMP > 0) THEN
         BEGIN
            UPDATE KONTIGENT SET KONTIGENT.VERBR_KONT = KONTIGENT.VERBR_KONT + 1
            WHERE KONTIGENT.LNR = :LNR_TMP;
         END
      END

  END
end ^

ALTER PROCEDURE TOOL_UPD_KONTI_AFTER_STORNO (GK_LNR INTEGER)
AS 
declare variable LNR_TMP integer;
declare variable ADR_LNR_TMP integer;
declare variable LNR_GK_TMP integer;
begin
  /* Procedure Text */
   for
    SELECT DISTINCT KONTIGENT.LNR, GASTKONT.GASTNR_1, GASTKONT.LNR
    FROM GASTKONT
        INNER JOIN KONTIGENT ON (KONTIGENT.adr_lnr = GASTKONT.GASTNR_1 AND
                                 KONTIGENT.DATUM BETWEEN GASTKONT.VONAUFH AND GASTKONT.BISAUFH-1 AND
                                 GASTKONT.LNR_KATE = KONTIGENT.LNR_KATE)
    WHERE GASTKONT.LNR = :GK_LNR AND GASTKONT.KONTINGENT = 1
    INTO :LNR_TMP, :ADR_LNR_TMP, :LNR_GK_TMP
  do
  begin
      if(:ADR_LNR_TMP > 0 AND :LNR_TMP > 0 AND :LNR_GK_TMP > 0) THEN
      BEGIN
          UPDATE KONTIGENT SET KONTIGENT.VERBR_KONT = KONTIGENT.VERBR_KONT - 1
          WHERE KONTIGENT.LNR = :LNR_TMP;
      END
  END
end ^

ALTER PROCEDURE TOOL_UPD_LNR_RECHNUNG (DATUMZEIT TIMESTAMP)
AS 
declare variable LNR integer;
declare variable LAUF integer;
declare variable LNR_CO integer;
begin

   /* Procedure Text */
  LAUF = 1;
  for
       select rechnung.lnr ,fakt_erloese.lnr_co
          from rechnung
        inner join fakt_erloese on (fakt_erloese.belegnr = rechnung.verk_nr and fakt_erloese.budat >= cast (:datumzeit as date))
        where rechnung.lnr_co = 0 and rechnung.datum_zeit >= :DATUMZEIT

        into :LNR, :LNR_CO
  do
  if(LNR > 0 AND LAUF > 0 and LNR_CO>0)
  then
  begin
   update rechnung set lnr_co = :lnr_co
     where rechnung.lnr = :LNR;
   LAUF = LAUF + 1;
  end

  suspend;
end ^

ALTER PROCEDURE TOOL_UPD_SORTNR_MAND AS 
declare variable lnr integer;
declare variable lauf integer;
begin
  /* Procedure Text */
  LAUF = 1;
  for
        select mandant.lnr
        from mandant
        where mandant.ta_status < 1000
        order by mandant.bezeichn
        into :LNR
  do
  if(LNR > 0 AND LAUF > 0)
  then
  begin
   update mandant set mandant.sort_nr = :LAUF
   where mandant.lnr = :LNR;
   LAUF = LAUF + 1;
  end
  suspend;
end ^

ALTER PROCEDURE TOOL_UP_BRIEFANREDE AS 
declare variable LNR integer;
declare variable ANREDE varchar(50);
declare variable NAME1 varchar(100);
declare variable LANG_STR integer;
declare variable BRIEFANREDE varchar(100);
declare variable TITEL varchar(30);
begin
  /* Procedure Text */

   FOR
    select adressen.lnr, adressen.anrede,adressen.titel, adressen.name1, adressen.anredebrf

       from adressen
         where adressen.ta_status < 1000
             into :LNR, :ANREDE, :TITEL, :NAME1, :briefanrede
    do
    begin
       if(LNR > 0 and :briefanrede='') then
       begin
           if (:anrede='Herr' or :anrede='Herrn') then :briefanrede = 'Sehr geehrter ';
               else :briefanrede = 'Sehr geehrte ';

            lang_str = 1;
            if (:titel='') then lang_str = 0;


            if (lang_str>0) then  :briefanrede = :briefanrede || :titel || ' ';
            :briefanrede = :briefanrede || :anrede || ' ';
            :briefanrede = :briefanrede || name1 || ',';

            update adressen set adressen.anredebrf = :briefanrede
                where adressen.lnr = :LNR;
       end
    end

end ^

