ALTER PROCEDURE TOOL_VERGL_FAKT_STAT_UMS (VONDATUM DATE,
BISDATUM DATE)
RETURNS (SUM_F_BETR FLOAT,
SUM_S_BETR FLOAT,
LNR_CO INTEGER)
AS 
begin
  /* Procedure Text */

  begin
    for

    select fakt_erloese.lnr_co
      from fakt_erloese
        where fakt_erloese.zahlungsart = 9999 and
              budat between :vondatum and :bisdatum
              and fakt_erloese.rechnr>0 and lnr_co >0
              group by lnr_co
                into :lnr_co
      /*      select stat_umsatz.lnr_co
         from stat_umsatz
           where stat_umsatz.datum between  41640 and   41820
             into :lnr_co
             */
    do
    begin
       select sum(stat_umsatz.tag_betrag*stat_umsatz.me) as summe
         from stat_umsatz
           left outer join leiststa on (leiststa.lnr = stat_umsatz.leist_lnr )
         where stat_umsatz.lnr_co = :lnr_co
         and leiststa.wg <99
           into :sum_s_betr;

       select sum(fakt_erloese.betrag) as summe
         from fakt_erloese
         left outer join leiststa on (leiststa.lnr = fakt_erloese.lnr_leist )
         where fakt_erloese.lnr_co = :lnr_co  and fakt_erloese.zahlungsart = 9999
            and leiststa.wg <99
           into :sum_f_betr;



       suspend;

    end

  end







end ^

ALTER PROCEDURE TOOL_ZAHLUNG_RE_UPDATE AS 
declare variable RECHNR integer;
declare variable LNR integer;
BEGIN
  /* Procedure Text */
  FOR

    SELECT distinct RECHNUNG.RECHNR,zahlungen.lnr
    FROM RECHNUNG
      INNER JOIN zahlungen ON (RECHNUNG.GK_LNR = zahlungen.lnr_gk and zahlungen.lnr_gk>0 )
      where zahlungen.re_nr<=0 and zahlungen.ta_status<1000
         into :rechnr, :lnr
  do
  if (rechnr>0) then
  begin
     update zahlungen set zahlungen.re_nr = :rechnr
        where zahlungen.lnr = :lnr;
  end
  suspend;
end ^

ALTER PROCEDURE TOOL_ZAHLUNG_RE_UPDATE_2 AS 
declare variable lnr integer;
declare variable rechnr integer;
begin
  /* Procedure Text */
  

  for
    select zahlungen.lnr, fakt_erloese.rechnr
    from zahlungen
     inner join fakt_erloese on (fakt_erloese.belegnr = zahlungen.lnr_gk)
        where fakt_erloese.ta_status <1000 and zahlungen.ta_status<1000
             and lnr_gk >0  and re_nr<=0
            into :lnr, :rechnr

  do
  if (rechnr>0) then
  begin
    update zahlungen set zahlungen.re_nr = :rechnr
        where zahlungen.lnr = :lnr;
  end
  suspend;
end ^

ALTER PROCEDURE TOOL_ZAHL_UPDATEN (VONDATUM DATE,
BISDATUM DATE,
LNR_DEVI_VON INTEGER,
LNR_DEVI_BIS INTEGER)
AS 
DECLARE VARIABLE HINT INTEGER;
begin
  /* Procedure Text */
  hint = 0;
  for
    select zahlungen.lnr
     from zahlungen
        inner join gastkont on ( gastkont.lnr = zahlungen.lnr_gk)
        where (zahlungen.lnr_devi = :lnr_devi_von and
            budat between :vondatum and :bisdatum
          and zahlungen.budat < gastkont.bisaufh-1 )
          into :hint
  do
  if (hint>0) then
  begin
     update zahlungen set lnr_devi = :lnr_devi_bis
       where lnr = :hint;

  end
  suspend;
end ^

ALTER PROCEDURE UPDATE_FK_AUSGB_ZAHL AS 
DECLARE VARIABLE BELEGNR INTEGER;
DECLARE VARIABLE BISDATUM DATE;
begin
  /* Procedure Text */
  for
   SELECT gastkont.lnr,  gastkont.bisaufh
    FROM GASTKONT
       where gastkont.ta_status<1000
       into :"BELEGNR", :"BISDATUM"
   do
    /* suspend; */
   if (belegnr>0) then
   begin
     update fakt_erloese set fakt_erloese.budat = :bisdatum
       where fakt_erloese.belegnr = :belegnr;

      update zahlungen set zahlungen.budat = :bisdatum
       where zahlungen.lnr_gk  = :belegnr;

     update ausgbuch set ausgbuch.rech_dat = :bisdatum
       where ausgbuch.belegnr = :belegnr;


   end
   suspend;
end ^

ALTER PROCEDURE UPDATE_VERKNR_XB AS 
