ALTER PROCEDURE UPD_GASTK_BUCHK_BELEG_CO (DATUM DATE)
AS 
declare variable lnr_tmp integer;
begin
  /* Procedure Text */
  for
    SELECT gastkont.lnr from gastkont
    where gastkont.erf_datum < :DATUM
    and gastkont.ta_status < 1000
    into :LNR_TMP
  do
  begin
    update gastkont
        set gastkont.ci_status = 2, gastkont.ta_status = 500
    where gastkont.lnr = :lnr_tmp;

    update buchkont
        set buchkont.ta_status = 500
    where buchkont.gk_lnr = :lnr_tmp;

    update belegung
        set belegung.ta_status = 500
    where belegung.lnr_gk = :lnr_tmp;

    update zahlungen
        set zahlungen.ta_status = 500
    where zahlungen.lnr_gk = :lnr_tmp;
  end 
  suspend;
end ^

