ALTER PROCEDURE UPD_KONTI_VERBR (VON DATE,
BIS DATE,
LNR_KATE INTEGER,
LNR_ADR INTEGER,
ANZ INTEGER)
AS 
declare variable lnr_tmp integer;
declare variable adr_lnr_tmp integer;
declare variable rest integer;
begin
  /* Procedure Text */
  for
    SELECT KONTIGENT.LNR, KONTIGENT.ADR_LNR, (KONTIGENT.MAX_KONT - KONTIGENT.VERBR_KONT) AS REST
    FROM KONTIGENT
    WHERE KONTIGENT.ta_status < 1000 AND KONTIGENT.LNR_KATE = :LNR_KATE
            AND KONTIGENT.DATUM BETWEEN :VON AND :BIS
    INTO :LNR_TMP, :ADR_LNR_TMP, :REST
  do
  begin
      if(:ADR_LNR_TMP = :LNR_ADR) THEN
      BEGIN
          UPDATE KONTIGENT SET KONTIGENT.VERBR_KONT = KONTIGENT.VERBR_KONT + :ANZ
          WHERE KONTIGENT.LNR = :LNR_TMP AND kontigent.ADR_LNR = :ADR_LNR_TMP;
      END
  END
end ^

