ALTER PROCEDURE WEB_GET_KATE_FREI_ARRANG (ANREISE DATE,
ABREISE DATE,
BUCH_STATUS INTEGER)
RETURNS (VON TIMESTAMP,
BIS TIMESTAMP,
LNR_KATE INTEGER,
ANZ_ZI INTEGER,
INT_TEMP INTEGER,
KATEGORIE VARCHAR(10) CHARACTER SET NONE,
PRL_LNR INTEGER,
MAND_NR INTEGER)
AS 
declare variable INT_KATEANZ integer;
declare variable INT_KATELNR integer;
declare variable INT_SAISON integer;
begin
  /* Procedure Text */
  int_temp = 0;
  for
    select lnr, katestam.anz_kate ,katestam.kategorie, katestam.preislist, katestam.mand_nr
       from katestam where katestam.lnr >0 and katestam.pseudo = 0 and katestam.ta_status <1000 and katestam.online_verfugbar=1
       into :int_katelnr, :anz_zi, :kategorie, :PRL_LNR, :MAND_NR
  DO
  BEGIN
    int_kateanz = anz_zi;
    int_temp = 0;

    for
     select  max(belegung.anz_zi)
        from belegung
          left outer join gastkont on (gastkont.lnr = belegung.lnr_gk --and gastkont.buch_status <= :buch_status
          )


        where (belegung.lnr_kate = :int_katelnr) and (belegung.ta_status<1000)
        and gastkont.buch_status <= :buch_status
        and
        (
        /*
        (anreise>=:anreise and anreise<=:abreise) or
        (abreise>=:anreise and abreise<=:abreise) or
        (anreise<:anreise  and abreise>:abreise)
        */
        (anreise>=:anreise and anreise<:abreise) or
        (abreise>:anreise and abreise<=:abreise) or
        (anreise<:anreise  and abreise>:abreise)
       )
        group by belegung.lnr_zinr

       into   :int_temp



     do

     int_kateanz = int_kateanz - int_temp;
     lnr_kate = int_katelnr;

     INT_TEMP = int_kateanz;

     if (anz_zi>0) then
     begin
      /* saison holen */

       von = :anreise;
       bis = :abreise;
       int_saison = 0;



     end

     suspend;

   END

end ^

ALTER PROCEDURE WEB_GET_KATE_FREI_VON_BIS (ANREISE DATE,
ABREISE DATE,
BUCH_STATUS INTEGER)
RETURNS (VON TIMESTAMP,
BIS TIMESTAMP,
LNR_KATE INTEGER,
ANZ_ZI INTEGER,
INT_TEMP INTEGER,
KATEGORIE VARCHAR(10) CHARACTER SET NONE,
PRL_LNR INTEGER,
MAND_NR INTEGER)
AS 
declare variable TAGE date;
declare variable INT_KATELNR integer;
declare variable TEMP_ANREISE date;
declare variable TEMP_ABREISE date;
begin
  /* Procedure Text */
  :TAGE = ANREISE;

  while (TAGE <= ABREISE) do

  begin


      int_temp = 0;
      for
        select lnr, katestam.anz_kate ,katestam.kategorie, katestam.preislist, katestam.mand_nr
           from katestam where katestam.lnr >0 and katestam.pseudo = 0 and katestam.ta_status <1000 and katestam.online_verfugbar=1
           into :int_katelnr, :anz_zi, :kategorie, :PRL_LNR, :MAND_NR
      DO
      BEGIN

         :temp_anreise = tage;
         :temp_abreise = tage+1;

         select  count(*) as anz_zi
           from belegung
             left outer join gastkont on (gastkont.lnr = belegung.lnr_gk )
        
                where (belegung.lnr_kate = :int_katelnr) and (belegung.ta_status<1000)
                --and gastkont.buch_status <= :buch_status
                and
                (
        
                (belegung.anreise>=:temp_anreise and belegung.anreise<:temp_abreise) or
                (belegung.abreise>:temp_anreise and belegung.abreise<=:temp_abreise) or
                (belegung.anreise<:temp_anreise  and belegung.abreise>:temp_abreise)
               )
               into :int_temp;



         von = temp_anreise;
         bis = temp_abreise;
         lnr_kate = int_katelnr;
         suspend;


      end

  
    
--      for
--       select *
--        from WEB_GET_KATE_FREI_ARRANG(:TAGE, :TAGE+1, :BUCH_STATUS)
--         into :VON, :BIS, :LNR_KATE, :ANZ_ZI, :INT_TEMP, :KATEGORIE, :PRL_LNR, :MAND_NR
--      do
--      begin
--        suspend;
--    
--      end
      tage = tage + 1;
  end

end ^

ALTER PROCEDURE WEB_GET_KATE_VAKANZ_PREISAB2020 (KIND3 INTEGER,
KIND2 INTEGER,
KIND1 INTEGER,
JUG INTEGER,
ERW INTEGER,
VONDATUM DATE,
BISDATUM DATE)
RETURNS (ALTERSKREIS INTEGER,
PREISLIST_LNR INTEGER,
MAND_NR INTEGER,
LNR_KATE INTEGER,
ANZ_KATE_MAX INTEGER,
ANZ_KATE_BELEGT INTEGER,
PRL_LNR INTEGER,
TAG_FUER DATE,
LOGI_BETRAG NUMERIC(12, 2),
BETRAG_PERS NUMERIC(12, 2),
KURT_BETRAG NUMERIC(12, 2),
SONST_BETRAG NUMERIC(12, 2),
OBJEKT_NR INTEGER,
MAX_ANZ_GESAMT INTEGER,
MIN_TAGE_WEB INTEGER,
MIN_GESAMTPERS INTEGER,
MIN_VOLLZAHLER INTEGER)
AS 
declare variable TAG date;
declare variable DIF_TAGE integer;
declare variable ZIMMERPREIS integer;
declare variable PAUSCHALE integer;
declare variable PAUSCHLAG numeric(12,2);
declare variable PSPLIT_BETRAG numeric(12,2);
declare variable PS_BETRAG numeric(12,2);
declare variable PS_MENGE integer;
declare variable PS_EINMALIG integer;
declare variable PS_TAEGLICH integer;
declare variable PS_PROPERSON integer;
declare variable PS_AUFPERSON integer;
declare variable PS_ABTAGE integer;
declare variable PS_BISTAGE integer;
declare variable SPERRZEIT_AKTIV integer;
declare variable PAUSCHLAG2 numeric(12,2) = 0;
declare variable PAUSCHLAG3 numeric(12,2) = 0;
declare variable PAUSCHLAG4 numeric(12,2) = 0;
declare variable PAUSCHLAG5 numeric(12,2) = 0;
declare variable PAUSCHLAG6 numeric(12,2) = 0;
declare variable TEMP_I date;
declare variable TEMP_SPERRAKT integer;
begin

  TAG = VONDATUM;
  DIF_TAGE = BISDATUM - VONDATUM;
  --Sperrzeit pr?fen nach von-bis
  TEMP_SPERRAKT = 0;
  TEMP_I = VONDATUM;
  while (TEMP_I < BISDATUM) do
  begin
    for select count(LNR)
        from SPERRZEIT
        where SPERRZEIT.TA_STATUS < 1000 and
              (:TEMP_I between SPERRZEIT.VONDATUM and SPERRZEIT.BISDATUM)
        into :SPERRZEIT_AKTIV
    do
    begin
      if (:SPERRZEIT_AKTIV > 0) then
        TEMP_SPERRAKT = 1;
    end
    TEMP_I = TEMP_I + 1;
  end

  :SPERRZEIT_AKTIV = TEMP_SPERRAKT;

  if (SPERRZEIT_AKTIV < 1) then
  begin

    for

        select KATESTAM.MAND_NR, KATESTAM.LNR as LNR_KATE, KATESTAM.ANZ_KATE,
               coalesce(TEMP_BELEGTE_ZIMMER.BELEGT, 0) as BELEGT, PREISLIST.LNR as PRL_LNR, 
               iif(preislist_vererb.AUFSCHLAG_ERW > 0, PREISLIST.BETRAG + preislist_vererb.AUFSCHLAG_ERW, PREISLIST.BETRAG) as betrag,
               PREISLIST.BETRAG_PERS, PREISLIST.ZIMMERPREIS, PREISLIST.PAUSCHALE, PREISLIST.PAUFSCHLAG1,
               PREISLIST.PAUFSCHLAG2, PREISLIST.PAUFSCHLAG3, PREISLIST.PAUFSCHLAG4, PREISLIST.PAUFSCHLAG5,
               PREISLIST.PAUFSCHLAG6, PREISLIST.PREISLIST_LNR, PREISLIST.ALTERSKREIS, KATESTAM.OBJEKT_NR, PREISLIST.MIN_VOLLZAHLER
        from KATESTAM

        inner join PREISLIST on (KATESTAM.PREISLIST = PREISLIST.PREISLIST_LNR or PREISLIST.PREISLIST_LNR = 9999)
        inner join SAISSTAM on (PREISLIST.SAISON = SAISSTAM.SAISON and
              :TAG between SAISSTAM.VON and SAISSTAM.BIS)
        left outer join TEMP_BELEGTE_ZIMMER on (KATESTAM.LNR = TEMP_BELEGTE_ZIMMER.LNR_KATE and
              (TEMP_BELEGTE_ZIMMER.TAG = :TAG and
              TEMP_BELEGTE_ZIMMER.TAG between SAISSTAM.VON and SAISSTAM.BIS))
        
        left outer join preislist_vererb on (preislist_vererb.PREISLIST_LNR = PREISLIST.PREISLIST_LNR and preislist_vererb.F_DATUM = :TAG and preislist_vererb.MATCHC = preislist.MATCHC and preislist_vererb.ALTERSKREIS = preislist.ALTERSKREIS and preislist_vererb.P_AB_2020 = 1)
        
        where
              PREISLIST.ONLINE_VERFUEGBAR = 1 and
              PREISLIST.TA_STATUS < 1000 and
              KATESTAM.ANZ_GESAPERS >= (:ERW + :JUG + :KIND1 + :KIND2 + :KIND3) and
              KATESTAM.ANZ_ERW_MIN <= :ERW
              and
              PREISLIST.P_AB_2020 = 1 and
              KATESTAM.PSEUDO = 0 and
              KATESTAM.TA_STATUS < 1000 and
              SAISSTAM.TA_STATUS < 1000

        into :MAND_NR, :LNR_KATE, :ANZ_KATE_MAX, :ANZ_KATE_BELEGT, :PRL_LNR, :LOGI_BETRAG, :BETRAG_PERS, :ZIMMERPREIS,
             :PAUSCHALE, :PAUSCHLAG, :PAUSCHLAG2, :PAUSCHLAG3, :PAUSCHLAG4, :PAUSCHLAG5, :PAUSCHLAG6,

             :PREISLIST_LNR, :ALTERSKREIS, :OBJEKT_NR, :MIN_VOLLZAHLER

    do
    begin

      -- temp_belegte_zimmer pr?fen nach von-bis !!!
      TEMP_SPERRAKT = 0;
      TEMP_I = VONDATUM;
      while (TEMP_I < BISDATUM) do
      begin
        for select coalesce(TEMP_BELEGTE_ZIMMER.BELEGT, 0) as BELEGT
            from TEMP_BELEGTE_ZIMMER
            where TEMP_BELEGTE_ZIMMER.LNR_KATE = :LNR_KATE and
                  (TEMP_BELEGTE_ZIMMER.TAG = :TEMP_I)
            into :SPERRZEIT_AKTIV
        do
        begin
          if (:SPERRZEIT_AKTIV > :ANZ_KATE_BELEGT) then
            :ANZ_KATE_BELEGT = :SPERRZEIT_AKTIV;
        end
        TEMP_I = TEMP_I + 1;
      end

      --erw
      if (ALTERSKREIS = 0) then
      begin
        if (:ERW >= :MIN_VOLLZAHLER) then
        begin
          if (:ERW > BETRAG_PERS) then
            LOGI_BETRAG = LOGI_BETRAG + PAUSCHLAG;
          if (:ERW > BETRAG_PERS + 1) then
            LOGI_BETRAG = LOGI_BETRAG + PAUSCHLAG2;
          if (:ERW > BETRAG_PERS + 2) then
            LOGI_BETRAG = LOGI_BETRAG + PAUSCHLAG3;
          if (:ERW > BETRAG_PERS + 3) then
            LOGI_BETRAG = LOGI_BETRAG + PAUSCHLAG4;
          if (:ERW > BETRAG_PERS + 4) then
            LOGI_BETRAG = LOGI_BETRAG + PAUSCHLAG5;
          if (:ERW > BETRAG_PERS + 5) then
            LOGI_BETRAG = LOGI_BETRAG + PAUSCHLAG6;
          if (:ERW > BETRAG_PERS + 6) then
            LOGI_BETRAG = LOGI_BETRAG + ((PAUSCHLAG6) * (:ERW - (BETRAG_PERS + 6)));
        end

        --noch MIN_VOLLZAHLER pr?fen
        if (:ERW < :MIN_VOLLZAHLER) then
          if (:MIN_VOLLZAHLER > BETRAG_PERS) then
          begin
            if (:MIN_VOLLZAHLER > BETRAG_PERS) then
              LOGI_BETRAG = LOGI_BETRAG + PAUSCHLAG;
            if (:MIN_VOLLZAHLER > BETRAG_PERS + 1) then
              LOGI_BETRAG = LOGI_BETRAG + PAUSCHLAG2;
            if (:MIN_VOLLZAHLER > BETRAG_PERS + 2) then
              LOGI_BETRAG = LOGI_BETRAG + PAUSCHLAG3;
            if (:MIN_VOLLZAHLER > BETRAG_PERS + 3) then
              LOGI_BETRAG = LOGI_BETRAG + PAUSCHLAG4;
            if (:MIN_VOLLZAHLER > BETRAG_PERS + 4) then
              LOGI_BETRAG = LOGI_BETRAG + PAUSCHLAG5;
            if (:MIN_VOLLZAHLER > BETRAG_PERS + 5) then
              LOGI_BETRAG = LOGI_BETRAG + PAUSCHLAG6;
            if (:MIN_VOLLZAHLER > BETRAG_PERS + 6) then
              LOGI_BETRAG = LOGI_BETRAG + ((PAUSCHLAG6) * (:MIN_VOLLZAHLER - (BETRAG_PERS + 6)));
          end

        if (:PAUSCHALE = 0) then
          LOGI_BETRAG = (LOGI_BETRAG * DIF_TAGE);

      end
      --jug
      if (ALTERSKREIS = 1) then
      begin
        if(:ERW < :MIN_VOLLZAHLER) then
          LOGI_BETRAG = 0;
        if (:JUG > BETRAG_PERS) then
          LOGI_BETRAG = LOGI_BETRAG + ((PAUSCHLAG) * (:JUG - BETRAG_PERS));
        if (:PAUSCHALE = 0) then
          LOGI_BETRAG = (LOGI_BETRAG * DIF_TAGE);
        --if (ZIMMERPREIS = 0) then
          --LOGI_BETRAG = (LOGI_BETRAG * :JUG);
      end
      --kind1
      if (ALTERSKREIS = 2) then
      begin
        if(:ERW + :JUG < :MIN_VOLLZAHLER) then
          LOGI_BETRAG = 0;
        if (:KIND1 > BETRAG_PERS) then
          LOGI_BETRAG = LOGI_BETRAG + ((PAUSCHLAG) * (:KIND1 - BETRAG_PERS));
        if (:PAUSCHALE = 0) then
          LOGI_BETRAG = (LOGI_BETRAG * DIF_TAGE);
        --if (ZIMMERPREIS = 0) then
        --  LOGI_BETRAG = (LOGI_BETRAG * :KIND1);
      end
      --kind2
      if (ALTERSKREIS = 3) then
      begin
        if(:ERW + :JUG + :KIND1 < :MIN_VOLLZAHLER) then
          LOGI_BETRAG = 0;
        if (:KIND2 > BETRAG_PERS) then
          LOGI_BETRAG = LOGI_BETRAG + ((PAUSCHLAG) * (:KIND2 - BETRAG_PERS));
        if (:PAUSCHALE = 0) then
          LOGI_BETRAG = (LOGI_BETRAG * DIF_TAGE);
        -- if (ZIMMERPREIS = 0) then
        --   LOGI_BETRAG = (LOGI_BETRAG * :KIND2);
      end
      --kind3
      if (ALTERSKREIS = 4) then
      begin
        if(:ERW + :JUG + :KIND1 + :KIND2 < :MIN_VOLLZAHLER) then
          LOGI_BETRAG = 0;
        if (:KIND3 > BETRAG_PERS) then
          LOGI_BETRAG = LOGI_BETRAG + ((PAUSCHLAG) * (:KIND3 - BETRAG_PERS));
        if (:PAUSCHALE = 0) then
          LOGI_BETRAG = (LOGI_BETRAG * DIF_TAGE);
        --if (ZIMMERPREIS = 0) then
        --   LOGI_BETRAG = (LOGI_BETRAG * :KIND3);
      end

      -- hier noch kurtaxe mit einbinden .....

      --erw
      if (ALTERSKREIS = 0) then
      begin

        select sum(KURTSTAM.ERBETR * :ERW) as KURTBETRAG
        from KURTSTAM
        where :VONDATUM between KURTSTAM.VON and KURTSTAM.BIS and
              KURTSTAM.TA_STATUS < 1000 and
              KURTSTAM.MAND_NR = :MAND_NR and
              KURTSTAM.OBJEKT_LNR = :OBJEKT_NR
        into :KURT_BETRAG;

        KURT_BETRAG = (KURT_BETRAG * DIF_TAGE);
      end

      --jug
      if (ALTERSKREIS = 1) then
      begin

        select sum(KURTSTAM.JUGBETR * :JUG) as KURTBETRAG
        from KURTSTAM
        where :VONDATUM between KURTSTAM.VON and KURTSTAM.BIS and
              KURTSTAM.TA_STATUS < 1000 and
              KURTSTAM.MAND_NR = :MAND_NR and
              KURTSTAM.OBJEKT_LNR = :OBJEKT_NR
        into :KURT_BETRAG;

        KURT_BETRAG = (KURT_BETRAG * DIF_TAGE);
      end

      --kind1
      if (ALTERSKREIS = 2) then
      begin

        select sum(KURTSTAM.KINDBETR * :KIND1) as KURTBETRAG
        from KURTSTAM
        where :VONDATUM between KURTSTAM.VON and KURTSTAM.BIS and
              KURTSTAM.TA_STATUS < 1000 and
              KURTSTAM.MAND_NR = :MAND_NR and
              KURTSTAM.OBJEKT_LNR = :OBJEKT_NR
        into :KURT_BETRAG;

        KURT_BETRAG = (KURT_BETRAG * DIF_TAGE);
      end

      --kind2
      if (ALTERSKREIS = 3) then
      begin

        select sum(KURTSTAM.K3BETR * :KIND2) as KURTBETRAG
        from KURTSTAM
        where :VONDATUM between KURTSTAM.VON and KURTSTAM.BIS and
              KURTSTAM.TA_STATUS < 1000 and
              KURTSTAM.MAND_NR = :MAND_NR and
              KURTSTAM.OBJEKT_LNR = :OBJEKT_NR
        into :KURT_BETRAG;

        KURT_BETRAG = (KURT_BETRAG * DIF_TAGE);
      end

      --kind3
      if (ALTERSKREIS = 4) then
      begin

        select sum(KURTSTAM.K4BETR * :KIND3) as KURTBETRAG
        from KURTSTAM
        where :VONDATUM between KURTSTAM.VON and KURTSTAM.BIS and
              KURTSTAM.TA_STATUS < 1000 and
              KURTSTAM.MAND_NR = :MAND_NR and
              KURTSTAM.OBJEKT_LNR = :OBJEKT_NR
        into :KURT_BETRAG;

        KURT_BETRAG = (KURT_BETRAG * DIF_TAGE);
      end

      -- hier noch den sonstigen_betrag berechnen.

      SONST_BETRAG = 0;

      PSPLIT_BETRAG = 0;
      for select PS.BETRAG, PS.MENGE, PS.EINMALIG, PS.TAEGLICH, PS.PROPERSON, PS.AUFPERSON, PS.ABTAGE, PS.BISTAGE
          from PREISSPLITTING PS
          --left outer join leiststa l on (l.lnr = ps.leistung_lnr)
          where PS.TA_STATUS < 1000 and
                PS.PAS_AKTIV = 0 and
                PS.PREISLIST_LNR = :PRL_LNR
          into :PS_BETRAG, :PS_MENGE, :PS_EINMALIG, :PS_TAEGLICH, :PS_PROPERSON, :PS_AUFPERSON, :PS_ABTAGE,
               :PS_BISTAGE
      do
      begin
        if (:PS_BISTAGE >= DIF_TAGE and
            :PS_ABTAGE <= DIF_TAGE) then
        begin
          PSPLIT_BETRAG = :PS_BETRAG * :PS_MENGE;
          if (:PS_EINMALIG = 1) then
            PSPLIT_BETRAG = PSPLIT_BETRAG;
          if (:PS_TAEGLICH = 1) then
            PSPLIT_BETRAG = PSPLIT_BETRAG * DIF_TAGE;
          if (:PS_PROPERSON = 1) then
            --PSPLIT_BETRAG = PSPLIT_BETRAG * (:ERW + :JUG + :KIND1 + :KIND2 + :KIND3);
            if (:PS_AUFPERSON = 0) then
              PSPLIT_BETRAG = PSPLIT_BETRAG * (:ERW + :JUG + :KIND1 + :KIND2 + :KIND3);
            else
            if (:PS_AUFPERSON = 1) then
              PSPLIT_BETRAG = PSPLIT_BETRAG * (:ERW);
            else
            if (:PS_AUFPERSON = 2) then
              PSPLIT_BETRAG = PSPLIT_BETRAG * (:JUG);
            else
            if (:PS_AUFPERSON = 3) then
              PSPLIT_BETRAG = PSPLIT_BETRAG * (:KIND1 + :KIND2 + :KIND3);

          SONST_BETRAG = SONST_BETRAG + PSPLIT_BETRAG;
        end

      end

      for select
                 max(TP.MIN_TAGE_WEB) as MIN_TAGE_WEB
          from TEMPLATE_PREISOPTION TP
          where TP.TA_STATUS < 1000 and
                TP.TEMPLATE_LNR = 1 and
                :VONDATUM between TP.VON and TP.BIS
          into :MIN_TAGE_WEB
      do
      begin
      end

      suspend;
    end
  end
end ^

ALTER PROCEDURE WEB_GET_KATE_VAKANZ_PRREIS (VONDATUM DATE,
BISDATUM DATE,
PERSZAHL INTEGER)
RETURNS (MAND_NR INTEGER,
LNR_KATE INTEGER,
ANZ_KATE_MAX INTEGER,
ANZ_KATE_BELEGT INTEGER,
PRL_LNR INTEGER,
TAG_FUER DATE,
LOGI_BETRAG NUMERIC(12, 2),
BETRAG_PERS INTEGER,
KURT_BETRAG NUMERIC(12, 2),
SONST_BETRAG NUMERIC(12, 2),
ANZ_KATE_FREI INTEGER)
AS 
declare variable TAG date = current_timestamp;
declare variable DIF_TAGE integer;
declare variable ZIMMERPREIS integer;
declare variable PAUSCHALE integer;
declare variable PAUSCHLAG numeric(12,2) = 0;
declare variable SPERRE integer;
begin
    TAG = VONDATUM;
    DIF_TAGE = BISDATUM - VONDATUM;

    select count(SPERRZEIT.LNR)
    from SPERRZEIT
    where ((:VONDATUM between SPERRZEIT.VONDATUM and SPERRZEIT.BISDATUM) or (:BISDATUM between SPERRZEIT.VONDATUM and SPERRZEIT.BISDATUM) or (:VONDATUM < SPERRZEIT.VONDATUM and
          :BISDATUM > SPERRZEIT.BISDATUM)) and
          SPERRZEIT.TA_STATUS < 1000 and
          SPERRZEIT.OPTISCHE_SPERRE_WEBMX = 1
    into :SPERRE;

    if (:SPERRE = 0) then
    begin
        for select KATESTAM.MAND_NR, KATESTAM.LNR as LNR_KATE, KATESTAM.ANZ_KATE, count(ZIMMSTAM.LNR) as FREI, --coalesce( temp_belegte_zimmer.belegt,0) as belegt,
                   PREISLIST.LNR as PRL_LNR,

                   PREISLIST.BETRAG, PREISLIST.BETRAG_PERS, PREISLIST.ZIMMERPREIS, PREISLIST.PAUSCHALE, PREISLIST.PAUFSCHLAG1

            from KATESTAM
            inner join ZIMMSTAM on ZIMMSTAM.LNR_KATE = KATESTAM.LNR and
                  ZIMMSTAM.TA_STATUS < 1000 and
                  ZIMMSTAM.VERMIETJN = 1 and
                  (select count(*)
                   from BELEGUNG
                   where (BELEGUNG.LNR_ZINR = ZIMMSTAM.LNR) and
                         (BELEGUNG.TA_STATUS < 1000) and
                         ((BELEGUNG.ANREISE >= :VONDATUM and
                         BELEGUNG.ANREISE < :BISDATUM) or (BELEGUNG.ABREISE > :VONDATUM and
                         BELEGUNG.ABREISE <= :BISDATUM) or (BELEGUNG.ANREISE <= :VONDATUM and
                         BELEGUNG.ABREISE >= :BISDATUM))) = 0
            inner join PREISLIST on (KATESTAM.PREISLIST = PREISLIST.PREISLIST_LNR)
            inner join SAISSTAM on (PREISLIST.SAISON = SAISSTAM.SAISON and
                  :TAG between SAISSTAM.VON and SAISSTAM.BIS)
                  --left outer join temp_belegte_zimmer on (katestam.lnr = temp_belegte_zimmer.lnr_kate
                  --                                         and (temp_belegte_zimmer.tag = :tag
                  --                                         and temp_belegte_zimmer.tag between saisstam.von and saisstam.bis))
            where PREISLIST.ONLINE_BUCHBAR = 1 and
                  PREISLIST.TA_STATUS < 1000 and
                  KATESTAM.ANZ_GESAPERS >= :PERSZAHL
            group by KATESTAM.MAND_NR, KATESTAM.LNR, KATESTAM.ANZ_KATE, PREISLIST.LNR, PREISLIST.BETRAG, PREISLIST.BETRAG_PERS, PREISLIST.ZIMMERPREIS, PREISLIST.PAUSCHALE, PREISLIST.PAUFSCHLAG1
            into :MAND_NR, :LNR_KATE, :ANZ_KATE_MAX, :ANZ_KATE_FREI, :PRL_LNR, :LOGI_BETRAG, :BETRAG_PERS, :ZIMMERPREIS, :PAUSCHALE, :PAUSCHLAG
        do
        begin
            if (PERSZAHL > BETRAG_PERS and
                BETRAG_PERS > 1) then
                LOGI_BETRAG = LOGI_BETRAG + ((PAUSCHLAG) * (PERSZAHL - BETRAG_PERS));
            if (:PAUSCHALE = 0) then
                LOGI_BETRAG = (LOGI_BETRAG * DIF_TAGE);
            if (ZIMMERPREIS = 0) then
                LOGI_BETRAG = (LOGI_BETRAG * PERSZAHL);
            -- hier noch kurtaxe mit einbinden .....
            select sum(KURTSTAM.ERBETR) as KURTBETRAG
            from KURTSTAM
            where :VONDATUM between KURTSTAM.VON and KURTSTAM.BIS and
                  KURTSTAM.TA_STATUS < 1000 and KURTSTAM.mand_nr = :MAND_NR
            into :KURT_BETRAG;

            KURT_BETRAG = (KURT_BETRAG * DIF_TAGE);
            -- hier noch den sonstigen_betrag berechnen.

            SONST_BETRAG = 0;
            suspend;
        end
    end
end ^

ALTER PROCEDURE WEB_GET_STAT_UMSATZ (VON INTEGER,
BIS INTEGER,
MONTH_FIRST INTEGER,
VON_DAT DATE,
MONTH_DAT DATE)
RETURNS (GR_NR INTEGER,
LFDNR INTEGER,
LEIST_LNR INTEGER,
B_TAG NUMERIC(12, 3),
B_MONAT NUMERIC(12, 3),
B_JAHR NUMERIC(12, 3),
B_TAG_LY NUMERIC(12, 3),
B_MONAT_LY NUMERIC(12, 3),
B_JAHR_LY NUMERIC(12, 3))
AS 
declare variable lnr integer;
declare variable gk_lnr integer;
declare variable leist_nr integer;
declare variable tag_betrag numeric(12,3);
declare variable me numeric(12,3);
declare variable datum integer;
declare variable t_b numeric(12,3);
declare variable m_b numeric(12,3);
declare variable j_b numeric(12,3);
declare variable lauf integer;
declare variable vondat integer;
declare variable bisdat integer;
declare variable lnr1 integer;
declare variable gbetrag numeric(12,3);
declare variable von1 date;
declare variable bis1 date;
declare variable menge integer;
declare variable leistnr integer;
declare variable tage integer;
declare variable betrag numeric(12,3);
declare variable rebetrag numeric(12,3);
declare variable gkrbetrag numeric(12,3);
declare variable hint integer;
begin
  /* Procedure Text */
  FOR
    select gastkont.lnr
    from gastkont
    where gastkont.ta_status < 500 and gastkont.vonaufh <= :VON_DAT
    INTO :LNR1
  DO
  BEGIN
      FOR
        SELECT BUCHKONT.gbetrag,buchkont.von,buchkont.bis,buchkont.me,buchkont.leist_lnr
        FROM BUCHKONT 
        where buchkont.gk_lnr = :LNR1 and buchkont.ta_status<1000
        INTO :GBETRAG, :VON1, :BIS1, :MENGE , :LEISTNR
      DO
      BEGIN
         TAGE = :BIS1 - :VON1;
         if(TAGE <= 0) THEN
         BEGIN
            TAGE = 1;
         END
         TAGE = TAGE * :MENGE;
         BETRAG = :GBETRAG;
         if(TAGE > 0) THEN
         BEGIN
            BETRAG = BETRAG / TAGE;
         END
         if(:BIS1 > :VON_DAT) THEN
         BEGIN
            TAGE = (:VON_DAT - :VON1) + 1;
         END
         ELSE
         BEGIN
            TAGE = :BIS1 - :VON1;
            IF(TAGE <= 0) THEN
            BEGIN
               TAGE = 1;
            END
         END
         TAGE = TAGE * :MENGE;
         IF(TAGE >= 0) THEN
         BEGIN
            REBETRAG = REBETRAG + (BETRAG * TAGE);
            GKRBETRAG = GKRBETRAG + (BETRAG * TAGE);
         END
         IF(TAGE > 0) THEN
         BEGIN
            GR_NR = :LNR1;
            LFDNR = 0;
            LEIST_LNR = LEISTNR;
            B_TAG = BETRAG;
            IF(:VON1 < :MONTH_DAT  AND :BIS1 >= :MONTH_DAT) THEN
            BEGIN
                HINT = 0;
                HINT = (:VON1 - :MONTH_DAT) +1;
                IF(:BIS1 > :VON_DAT) THEN
                BEGIN
                   HINT = (:VON_DAT - :MONTH_DAT) +1;
                END
                IF(:HINT = 0) THEN
                BEGIN
                   HINT = 1;
                END
                B_MONAT = :BETRAG * HINT;
            END
            ELSE
            BEGIN
                B_MONAT = :BETRAG * TAGE;
            END
            B_JAHR = :BETRAG * TAGE;
            B_TAG_LY = 0.000;
            B_MONAT_LY = 0.000;
            B_JAHR_LY = 0.000;
            suspend;
         END
      END
  END
  T_B = 0.000;
  M_B = 0.000;
  J_B = 0.000;
  LAUF = 0;
  while(:LAUF <= 1)
  do
  begin
      if(LAUF = 1) THEN
      BEGIN
        VONDAT = :VON - 365;
        BISDAT = :BIS - 365;
        MONTH_FIRST = :MONTH_FIRST - 365;
      END
      ELSE
      BEGIN
        VONDAT = :VON;
        BISDAT = :BIS;
        MONTH_FIRST = :MONTH_FIRST;
      END
      FOR
        SELECT STAT_UMSATZ.LNR, STAT_UMSATZ.GK_LNR, STAT_UMSATZ.LEIST_LNR, STAT_UMSATZ.TAG_BETRAG, STAT_UMSATZ.ME, STAT_UMSATZ.DATUM
        FROM STAT_UMSATZ
        WHERE STAT_UMSATZ.DATUM BETWEEN :VONDAT AND :BISDAT
        INTO :LNR, :GK_LNR, :LEIST_NR, :TAG_BETRAG, :ME, :DATUM
      DO
      BEGIN
           IF(:DATUM >= :VONDAT  AND :DATUM <= :BISDAT ) THEN
           BEGIN
                T_B = 0.000;
                M_B = 0.000;
                J_B = 0.000;
                IF(:ME <= 0.000) THEN
                BEGIN
                   ME = 1.000;
                END
                IF(:DATUM = :BISDAT) THEN
                BEGIN
                   T_B = :TAG_BETRAG * :ME;
                END
                IF(:DATUM <= :BISDAT AND :DATUM >= :MONTH_FIRST) THEN
                BEGIN
                   M_B = :TAG_BETRAG * :ME;
                END
                IF(:DATUM >= :VONDAT ) THEN
                BEGIN
                   J_B = :TAG_BETRAG * :ME;
                END
                IF((:T_B <> 0.000) OR :M_B <> 0.000 OR :J_B <> 0.000) THEN
                BEGIN
                   GR_NR = :GK_LNR;
                   LFDNR = 0;
                   LEIST_LNR = :LEIST_NR;
                   IF(:LAUF = 0) THEN
                   BEGIN
                        B_TAG = :T_B;
                        B_MONAT = :M_B;
                        B_JAHR = :J_B;
                        B_TAG_LY = 0.000;
                        B_MONAT_LY = 0.000;
                        B_JAHR_LY = 0.000;
                        suspend;
                   END
                   ELSE IF(:LAUF = 1) THEN
                   BEGIN
                        B_TAG = 0.000;
                        B_MONAT = 0.000;
                        B_JAHR = 0.000;
                        B_TAG_LY = T_B;
                        B_MONAT_LY = M_B;
                        B_JAHR_LY = J_B;
                        suspend;
                   END
                END
           END
      END
      BEGIN
        if(lauf = 0) THEN
        BEGIN
            lauf = 1;
        END
        else if(lauf = 1) THEN
        BEGIN
            lauf = 2;
        END
      END
  END
END ^

ALTER PROCEDURE WEB_GET_VAKANZ (JAHR INTEGER,
ANZ_PERS INTEGER,
ANREISE DATE,
ABREISE DATE)
RETURNS (TAGE INTEGER,
M_BEZEICHN VARCHAR(30) CHARACTER SET NONE,
ZIMMERART INTEGER,
STOCK INTEGER,
ZINR VARCHAR(10) CHARACTER SET NONE,
KATEGORIE VARCHAR(10) CHARACTER SET NONE,
O_BEZEICHN VARCHAR(30) CHARACTER SET NONE,
BETTZAHL INTEGER,
GARAGE INTEGER,
HAUSTIER INTEGER,
RAUCHER INTEGER,
LNR INTEGER,
LNR_KATE INTEGER,
MAND_NR INTEGER,
STATUSSTR VARCHAR(10) CHARACTER SET NONE,
ANZ_FREI INTEGER,
VERMIETJN SMALLINT,
TO_OPERATOR SMALLINT)
AS 
declare variable anz_buch integer;
begin
  /* Procedure Text */
  ANZ_FREI = 0;
  STATUSSTR = '';
  FOR
    SELECT TAGE, M_BEZEICHN, ZIMMERART, STOCK, ZINR, KATEGORIE, O_BEZEICHN,
            BETTZAHL, GARAGE, HAUSTIER, RAUCHER, LNR, LNR_KATE, MAND_NR, VERMIETJN, TO_OPERATOR
    FROM PROC_ANZ_NAECHTE_PLUS_ZI(:JAHR)
    WHERE BETTZAHL >= :ANZ_PERS
    INTO :TAGE, :M_BEZEICHN, :ZIMMERART, :STOCK, :ZINR, :KATEGORIE, :O_BEZEICHN,
            :BETTZAHL, :GARAGE, :HAUSTIER, :RAUCHER, :LNR, :LNR_KATE, :MAND_NR, :VERMIETJN, :TO_OPERATOR
  DO
  BEGIN
      FOR
        SELECT COUNT(*) FROM BELEGUNG
        WHERE LNR_ZINR = :LNR AND TA_STATUS < 1000
                AND ((ANREISE >= :ANREISE AND ANREISE < :ABREISE)
                        OR  (ABREISE > :ANREISE AND ABREISE <= :ABREISE)
                        OR  (ANREISE < :ANREISE AND ABREISE > :ABREISE))
        INTO :ANZ_BUCH
      DO
      BEGIN
           IF(:ANZ_BUCH <= 0 or :ANZ_BUCH IS NULL ) THEN
           BEGIN
                IF(GARAGE = 1) THEN
                BEGIN
                   STATUSSTR = 'GA-';
                END
                IF(HAUSTIER = 1) THEN
                BEGIN
                   STATUSSTR = 'HS-';
                END
                IF(RAUCHER = 1) THEN
                BEGIN
                   STATUSSTR = 'RA';
                END
                ANZ_FREI = ANZ_FREI + 1;
                anz_buch = 0;
              suspend;
           END
      END
  END
END ^

ALTER PROCEDURE WEB_GET_VAKANZ_NEU (JAHR INTEGER,
ANZ_PERS INTEGER,
ANREISE DATE,
ABREISE DATE)
RETURNS (TAGE INTEGER,
M_BEZEICHN VARCHAR(30) CHARACTER SET NONE,
ZIMMERART INTEGER,
STOCK INTEGER,
ZINR VARCHAR(10) CHARACTER SET NONE,
KATEGORIE VARCHAR(10) CHARACTER SET NONE,
O_BEZEICHN VARCHAR(30) CHARACTER SET NONE,
BETTZAHL INTEGER,
GARAGE INTEGER,
HAUSTIER INTEGER,
RAUCHER INTEGER,
LNR INTEGER,
LNR_KATE INTEGER,
MAND_NR INTEGER,
STATUSSTR VARCHAR(10) CHARACTER SET NONE,
ANZ_FREI INTEGER,
VERMIETJN SMALLINT,
TO_OPERATOR SMALLINT,
AUSSTATUNG VARCHAR(60) CHARACTER SET NONE,
BEZEICHN VARCHAR(60) CHARACTER SET NONE)
AS 
declare variable ANZ_BUCH integer;
begin
  /* Procedure Text */
  ANZ_FREI = 0;
  STATUSSTR = '';

  FOR

    SELECT  mandant.BEZEICHN,  zimmstam.ZIMMERART, zimmstam.STOCK, zimmstam.ZINR,
            katestam.KATEGORIE,  objekt.BEZEICHN,  zimmstam.BETTZAHL, zimmstam.GARAGE,
             zimmstam.HAUSTIER,  zimmstam.RAUCHER,   zimmstam.LNR,  zimmstam.LNR_KATE,
             zimmstam.MAND_NR,   zimmstam.VERMIETJN,  zimmstam.TO_OPERATOR,
             zimmstam.ausstatung, zimmstam.bezeichn

    FROM ZIMMSTAM
      LEFT OUTER JOIN KATESTAM ON (ZIMMSTAM.LNR_KATE = KATESTAM.LNR)
      LEFT OUTER JOIN OBJEKT ON (ZIMMSTAM.OBJEKT_NR = OBJEKT.LNR)
      LEFT OUTER JOIN MANDANT ON (ZIMMSTAM.MAND_NR = MANDANT.LNR)

    WHERE  (zimmstam.TA_STATUS < 500 and zimmstam.bettzahl>=:anz_pers)
       INTO  :M_BEZEICHN, :ZIMMERART, :STOCK, :ZINR, :KATEGORIE, :O_BEZEICHN,
            :BETTZAHL, :GARAGE, :HAUSTIER, :RAUCHER, :LNR, :LNR_KATE, :MAND_NR, :VERMIETJN, :TO_OPERATOR, :AUSSTATUNG,
            :BEZEICHN
  DO
  BEGIN
      FOR
        SELECT COUNT(*) FROM BELEGUNG
        WHERE LNR_ZINR = :LNR AND TA_STATUS < 1000
                AND ((ANREISE >= :ANREISE AND ANREISE < :ABREISE)
                        OR  (ABREISE > :ANREISE AND ABREISE <= :ABREISE)
                        OR  (ANREISE < :ANREISE AND ABREISE > :ABREISE))
        INTO :ANZ_BUCH
      DO
      BEGIN
           IF(:ANZ_BUCH <= 0 or :ANZ_BUCH IS NULL ) THEN
           BEGIN
                /*
                IF(GARAGE = 1) THEN
                BEGIN
                   STATUSSTR = 'GA-';
                END
                IF(HAUSTIER = 1) THEN
                BEGIN
                   STATUSSTR = 'HS-';
                END
                IF(RAUCHER = 1) THEN
                BEGIN
                   STATUSSTR = 'RA';
                END
                */
                ANZ_FREI = ANZ_FREI + 1;
                anz_buch = 0;
              suspend;
           END
      END
  END
END ^

ALTER PROCEDURE WEB_GET_VAKANZ_ZIMMER (JAHR INTEGER,
ANZ_PERS INTEGER,
ANREISE DATE,
ABREISE DATE,
SPRACHE1 INTEGER,
SPRACHE2 INTEGER,
SPRACHE3 INTEGER,
SPRACHE4 INTEGER)
RETURNS (LNR_KATE INTEGER,
LNR_ZINR INTEGER,
PREISLIST INTEGER,
ZINR TV10,
ZINR_BEZEICHN TV50,
ZINR_BEMERK1 TV255,
ZINR_BEMERK2 TV255,
ZINR_GARAGE INT0,
ZINR_HAUSTIER INT0,
ZINR_RAUCHER INT0,
ZINR_TO_OPERATOR INT0,
ZINR_BILDLINK TV255,
ZINR_MEMO BLOB_TYP1,
ZINR_ANZ_BETTEN INT0,
ZINR_ZIMMERART INT0,
ZINR_STOCK INT0,
SELE_GR1 TV100,
SELE_GR2 TV100,
SELE_GR3 TV100,
SELE_GR4 TV100,
SELE_GR5 TV100,
SELE_GR6 TV100,
SELE_GR7 TV100,
KATE_KATEGORIE TV100,
OBJ_BEZEICHN TV100,
ZINR_AUSSTATTUNG TV255,
BEZEICHN_S BLOB_TYP1,
BEMERK_1_S BLOB_TYP1,
MEMO_S BLOB_TYP1,
BEMERK_2_S BLOB_TYP1,
ANZ_FREI INTEGER)
AS 
declare variable ANZ_BUCH integer;
declare variable AUFTAGE integer;
declare variable ANZ_PREIS integer;
declare variable PREIS_VON date;
declare variable PREIS_BIS date;
declare variable SPERRE integer;
begin
    /* Procedure Text */
    ANZ_FREI = 0;
    :AUFTAGE = :ABREISE - :ANREISE;
    :SPERRE = 0;

    select count(SPERRZEIT.LNR)
    from SPERRZEIT
    where ((:ANREISE between SPERRZEIT.VONDATUM and SPERRZEIT.BISDATUM) or (:ABREISE between SPERRZEIT.VONDATUM and SPERRZEIT.BISDATUM) or (:ANREISE < SPERRZEIT.VONDATUM and
          :ABREISE > SPERRZEIT.BISDATUM)) and
          SPERRZEIT.TA_STATUS < 1000 and
          SPERRZEIT.OPTISCHE_SPERRE_WEBMX = 0 and
          SPERRZEIT.PROVIDER_NR = 0
    into :SPERRE;

    if (:SPERRE = 0) then
    begin
        for select KATESTAM.LNR as LNR_KATE, ZIMMSTAM.LNR as LNR_ZIM, ZIMMSTAM.PREISLIST, ZIMMSTAM.ZINR, ZIMMSTAM.BEZEICHN, ZIMMSTAM.BEMERK1,
                   ZIMMSTAM.BEMERK2, ZIMMSTAM.GARAGE, ZIMMSTAM.HAUSTIER, ZIMMSTAM.RAUCHER, ZIMMSTAM.TO_OPERATOR, ZIMMSTAM.BILD_LINK, ZIMMSTAM.MEMO,
                   ZIMMSTAM.BETTZAHL as ANZ_BETTEN, ZIMMSTAM.ZIMMERART, ZIMMSTAM.STOCK, ZIMMSTAM.SELE_GR1, ZIMMSTAM.SELE_GR2, ZIMMSTAM.SELE_GR3,
                   ZIMMSTAM.SELE_GR4, ZIMMSTAM.SELE_GR5, ZIMMSTAM.SELE_GR6, ZIMMSTAM.SELE_GR7, KATESTAM.KATEGORIE, OBJEKT.BEZEICHN,
                   ZIMMSTAM.AUSSTATUNG,
                   (select first 1 SPK.TEXTE as BEZEICHN_S
                    from SPRACHE_TEXTE SPK
                    where (SPK.TAB_LNR = ZIMMSTAM.LNR and
                          SPK.TA_STATUS < 1000 and
                          SPK.TAB_NR = 4 and
                          SPK.FELDNAME = 'BEZEICHN' and
                          SPK.SPRACHE = :SPRACHE1)),
                   (select first 1 SPK.TEXTE as BEMERK_1_S
                    from SPRACHE_TEXTE SPK
                    where (SPK.TAB_LNR = ZIMMSTAM.LNR and
                          SPK.TA_STATUS < 1000 and
                          SPK.TAB_NR = 4 and
                          SPK.FELDNAME = 'MEMO_WEB' and
                          SPK.SPRACHE = :SPRACHE2)),
                   (select first 1 SPK.TEXTE as MEMO_S
                    from SPRACHE_TEXTE SPK
                    where (SPK.TAB_LNR = ZIMMSTAM.LNR and
                          SPK.TA_STATUS < 1000 and
                          SPK.TAB_NR = 4 and
                          SPK.FELDNAME = 'BEMERK1' and
                          SPK.SPRACHE = :SPRACHE3)),
                   (select first 1 SPK.TEXTE as BEMERK_2_S
                    from SPRACHE_TEXTE SPK
                    where (SPK.TAB_LNR = ZIMMSTAM.LNR and
                          SPK.TA_STATUS < 1000 and
                          SPK.TAB_NR = 4 and
                          SPK.FELDNAME = 'BEMERK2' and
                          SPK.SPRACHE = :SPRACHE4))
            from ZIMMSTAM
            left outer join KATESTAM on (ZIMMSTAM.LNR_KATE = KATESTAM.LNR)
            left outer join OBJEKT on (ZIMMSTAM.OBJEKT_NR = OBJEKT.LNR)
            where (ZIMMSTAM.TA_STATUS < 500 and
                  ZIMMSTAM.ONLINE_VERFUGBAR = 1 and
                  ZIMMSTAM.BETTZAHL >= :ANZ_PERS and
                  ZIMMSTAM.PREISLIST > 0)
            into :LNR_KATE, :LNR_ZINR, :PREISLIST, :ZINR, :ZINR_BEZEICHN, :ZINR_BEMERK1, :ZINR_BEMERK2, :ZINR_GARAGE, :ZINR_HAUSTIER, :ZINR_RAUCHER,
                 :ZINR_TO_OPERATOR, :ZINR_BILDLINK, :ZINR_MEMO, :ZINR_ANZ_BETTEN, :ZINR_ZIMMERART, :ZINR_STOCK, :SELE_GR1, :SELE_GR2, :SELE_GR3,
                 :SELE_GR4, :SELE_GR5, :SELE_GR6, :SELE_GR7, :KATE_KATEGORIE, :OBJ_BEZEICHN, :ZINR_AUSSTATTUNG, :BEZEICHN_S, :BEMERK_1_S, :MEMO_S,
                 :BEMERK_2_S
        do
        begin
            for select count(*)
                from BELEGUNG
                where BELEGUNG.LNR_ZINR = :LNR_ZINR and
                      BELEGUNG.TA_STATUS < 1000 and
                      ((BELEGUNG.ANREISE >= :ANREISE and
                      BELEGUNG.ANREISE < :ABREISE) or (BELEGUNG.ABREISE > :ANREISE and
                      BELEGUNG.ABREISE <= :ABREISE) or (BELEGUNG.ANREISE < :ANREISE and
                      BELEGUNG.ABREISE > :ABREISE))
                into :ANZ_BUCH
            do
            begin
                if (:ANZ_BUCH <= 0 or :ANZ_BUCH is null) then
                begin
                    select count(*), min(SAISSTAM.VON), max(SAISSTAM.BIS) + 1
                    from PREISLIST
                    inner join SAISSTAM on (PREISLIST.SAISON = SAISSTAM.SAISON and
                          SAISSTAM.TA_STATUS < 1000 and
                          ((:ANREISE between SAISSTAM.VON and SAISSTAM.BIS or :ABREISE between SAISSTAM.VON and SAISSTAM.BIS) or (:ANREISE < SAISSTAM.VON and
                          :ABREISE > SAISSTAM.BIS)))
                    inner join GET_PREISTEMPLATE(:AUFTAGE, :ANREISE, 0, PREISLIST.TEMPLATE_LNR) on (GET_PREISTEMPLATE.OK = 1)
                          --inner join GET_PREISTEMPLATE(:AUFTAGE, :ABREISE, 1, PREISLIST.TEMPLATE_LNR) GETPREISTEMP on (GETPREISTEMP.OK = 1)
                    where (PREISLIST.PREISLIST_LNR = :PREISLIST) and
                          PREISLIST.ONLINE_BUCHBAR = 1 and
                          PREISLIST.TA_STATUS < 1000 and
                          PREISLIST.ALTERSKREIS = 0 and
                          PREISLIST.P_AB_2020 = 1 and
                          PREISLIST.ALTERSKREIS = 0 and
                          PREISLIST.MIN_TAGE_WEB <= :AUFTAGE
                          --                          and
                          --                          (select min(OK) from GET_PREISTEMPLATE(:AUFTAGE, :ANREISE, 0, PREISLIST.TEMPLATE_LNR)) > 0
                    into :ANZ_PREIS, :PREIS_VON, :PREIS_BIS;

                    if (:ANZ_PREIS > 0 and
                        :ANREISE >= :PREIS_VON and
                        :ABREISE <= :PREIS_BIS) then
                    begin
                        ANZ_FREI = ANZ_FREI + 1;
                        ANZ_BUCH = 0;
                        suspend;
                    end
                end
            end
            ANZ_FREI = 0;
        end
    end
end ^

ALTER PROCEDURE WEB_GET_ZIMMER_FREI_ARRANG (ANREISE DATE,
ABREISE DATE,
BUCH_STATUS INTEGER)
RETURNS (VON TIMESTAMP,
BIS TIMESTAMP,
LNR_KATE INTEGER,
ANZ_ZI INTEGER,
INT_TEMP INTEGER,
KATEGORIE VARCHAR(10) CHARACTER SET NONE,
PRL_LNR INTEGER)
AS 
declare variable INT_KATEANZ integer;
declare variable INT_KATELNR integer;
declare variable INT_SAISON integer;
begin
  /* Procedure Text */
  int_temp = 0;
  for
    select zimmstam.lnr, 1 as anz_kate ,zimmstam.zinr as kategorie, zimmstam.preislist
       from zimmstam
       where zimmstam.lnr >0 and zimmstam.ta_status <1000 and zimmstam.online_verfugbar=1
       into :int_katelnr, :anz_zi, :kategorie, :PRL_LNR
  DO
  BEGIN
    int_kateanz = anz_zi;
    int_temp = 0;

    for
     select  max(belegung.anz_zi)
        from belegung
           left outer join gastkont on (gastkont.lnr = belegung.lnr_gk and gastkont.buch_status <= :buch_status)

        where (belegung.lnr_zinr = :int_katelnr) and (belegung.ta_status<1000) and
        (
        /*
        (anreise>=:anreise and anreise<=:abreise) or
        (abreise>=:anreise and abreise<=:abreise) or
        (anreise<:anreise  and abreise>:abreise)
        */
        /*
        (anreise>=:anreise and anreise<=:abreise) or
        (abreise>=:anreise and abreise<=:abreise) or
        (anreise<:anreise  and abreise>:abreise)
        */
        (anreise>=:anreise and anreise<:abreise)


          or
          (abreise>:anreise and abreise<=:abreise)
          or

          (anreise<:anreise  and abreise>:abreise)
       )
        group by belegung.lnr_zinr

       into   :int_temp



     do

     int_kateanz = int_kateanz - int_temp;
     lnr_kate = int_katelnr;

     INT_TEMP = int_kateanz;

     if (anz_zi>0) then
     begin
      /* saison holen */

       von = :anreise;
       bis = :abreise;
       int_saison = 0;



     end

     suspend;

   END

end ^

ALTER PROCEDURE WEB_GET_ZIMPREIS (PREISLIST_NR INTEGER,
ANR_TAG DATE,
ABR_TAG DATE,
BETTZAHL INTEGER,
PERS INTEGER,
ANZ_KINDER INTEGER,
PRL_LNR INTEGER,
MAND_LNR INTEGER)
RETURNS (RETBETRAG NUMERIC(12, 3),
BEZEICHNUNG VARCHAR(200) CHARACTER SET NONE)
AS 
declare variable LNR integer = 0;
declare variable MATCHC varchar(20);
declare variable BETRAG numeric(12,3) = 0;
declare variable PERS_ZUWEISUNG integer = 0;
declare variable PRL_JUG integer = 0;
declare variable PRL_KIN integer = 0;
declare variable ZIMMERPREIS numeric(12,3);
declare variable PAUSCHALE integer = 0;
declare variable BETRAG_PERS integer = 0;
declare variable PAUFSCHLAG1 numeric(12,3) = 0;
declare variable PAUFSCHLAG2 numeric(12,3) = 0;
declare variable PAUFSCHLAG3 numeric(12,3) = 0;
declare variable PAUFSCHLAG4 numeric(12,3) = 0;
declare variable PAUFSCHLAG5 numeric(12,3);
declare variable PAUFSCHLAG6 numeric(12,3);
declare variable KINDFREIPREIS integer = 0;
declare variable EZZUSCHLAG numeric(12,3);
declare variable UTAG1 integer = 0;
declare variable UTAG2 integer = 0;
declare variable UTAG3 integer = 0;
declare variable UBETRAG2 numeric(12,3);
declare variable UBETRAG1 numeric(12,3);
declare variable KURTAX_INKL integer = 0;
declare variable UBETRAG3 numeric(12,3);
declare variable SAISON integer = 0;
declare variable EZPREIS numeric(12,3);
declare variable VON date;
declare variable BIS date;
declare variable JAUFSCHLAG_OK smallint = 0;
declare variable KAUFSCHLAG_OK smallint = 0;
declare variable JAUFSCHLAG1 numeric(12,2) = 0;
declare variable JAUFSCHLAG2 numeric(12,2) = 0;
declare variable JAUFSCHLAG3 numeric(12,2) = 0;
declare variable KAUFSCHLAG1 numeric(12,2) = 0;
declare variable KAUFSCHLAG2 numeric(12,2) = 0;
declare variable KAUFSCHLAG3 numeric(12,2) = 0;
declare variable MAX_TAGE integer = 0;
declare variable WE_VERWEND integer;
declare variable WE_BETRAG numeric(12,3);
declare variable TAGE integer;
declare variable HINT integer;
declare variable UNTERTAGE_AUFPR_AKT integer;
begin
  /* Procedure Text */
  if(PRL_LNR > 0) then
  begin
  FOR
      SELECT DISTINCT PREISLIST.LNR, PREISLIST.MATCHC, PREISLIST.BEZEICHUNG, PREISLIST.BETRAG, PREISLIST.PERS_ZUWEISUNG, PREISLIST.PRL_JUG, PREISLIST.PRL_KIN,
               PREISLIST.ZIMMERPREIS, PREISLIST.PAUSCHALE, PREISLIST.BETRAG_PERS,
               PREISLIST.PAUFSCHLAG1, PREISLIST.PAUFSCHLAG2, PREISLIST.PAUFSCHLAG3,
               PREISLIST.PAUFSCHLAG4, PREISLIST.PAUFSCHLAG5, PREISLIST.PAUFSCHLAG6,
               PREISLIST.KINDFREIPREIS, PREISLIST.EZZUSCHLAG, PREISLIST.UTAG1,
               PREISLIST.UTAG2, PREISLIST.UTAG3, PREISLIST.UBETRAG2, PREISLIST.UBETRAG1,PREISLIST.KURTAX_INKL,
               PREISLIST.UBETRAG3, PREISLIST.SAISON, PREISLIST.EZPREIS, SAISSTAM.VON, SAISSTAM.BIS,
               PREISLIST.JAUFSCHLAG_OK, PREISLIST.KAUFSCHLAG_OK, PREISLIST.JAUFSCHLAG1, PREISLIST.JAUFSCHLAG2, PREISLIST.JAUFSCHLAG3,
               PREISLIST.KAUFSCHLAG1, PREISLIST.KAUFSCHLAG2, PREISLIST.KAUFSCHLAG3, PREISLIST.MAX_TAGE, PREISLIST.we_verwend, PREISLIST.we_betrag,
               paramete.untertage_aufpr_akt
        FROM PREISLIST
            INNER JOIN SAISSTAM ON (PREISLIST.SAISON = SAISSTAM.LNR)
            LEFT OUTER JOIN PARAMETE ON (PARAMETE.mand_nr = :MAND_LNR)
        WHERE PREISLIST.LNR = :PRL_LNR
        ORDER BY PREISLIST.SORT_NR, preislist.matchc, SAISSTAM.VON
        INTO :LNR, :MATCHC, :BEZEICHNUNG, :BETRAG, :PERS_ZUWEISUNG, :PRL_JUG, :PRL_KIN,
               :ZIMMERPREIS, :PAUSCHALE, :BETRAG_PERS,
               :PAUFSCHLAG1, :PAUFSCHLAG2, :PAUFSCHLAG3,
               :PAUFSCHLAG4, :PAUFSCHLAG5, :PAUFSCHLAG6,
               :KINDFREIPREIS, :EZZUSCHLAG, :UTAG1,
               :UTAG2, :UTAG3, :UBETRAG2, :UBETRAG1,:KURTAX_INKL,
               :UBETRAG3, :SAISON, :EZPREIS, :VON, :BIS,
               :JAUFSCHLAG_OK, :KAUFSCHLAG_OK, :JAUFSCHLAG1, :JAUFSCHLAG2, :JAUFSCHLAG3,
               :KAUFSCHLAG1, :KAUFSCHLAG2, :KAUFSCHLAG3, :MAX_TAGE, :WE_VERWEND, :WE_BETRAG,
               :UNTERTAGE_AUFPR_AKT
  Do
    /* Preislisten_betrag_rechnen */
    if(:LNR > 0) then
    begin
          RETBETRAG = 0.00;
          TAGE = DATEDIFF(day, ANR_TAG, ABR_TAG);
          if (:KINDFREIPREIS > 0) then
          begin
            PERS = PERS - ANZ_KINDER;
          end
          if (:PERS <= 0) then
          begin
            suspend;
          end
          else
          begin
             /* basic preis einstellen ... */
             RETBETRAG = BETRAG;
             if(PERS < BETTZAHL and EZPREIS > 0) then
             begin
                 RETBETRAG = EZPREIS;
             end
             HINT = BETRAG_PERS;
             if(UNTERTAGE_AUFPR_AKT = 1) then
             begin
                if(UTAG3 > 0 and TAGE <= UTAG3) then begin RETBETRAG = RETBETRAG + UTAG3; end
                if(UTAG2 > 0 and TAGE <= UTAG2) then begin RETBETRAG = RETBETRAG + UTAG2; end
                if(UTAG1 > 0 and TAGE <= UTAG1) then begin RETBETRAG = RETBETRAG + UTAG1; end
             end
             else
             begin
                if(UTAG3 > 0 and TAGE <= UTAG3) then begin RETBETRAG = UTAG3; end
                if(UTAG2 > 0 and TAGE <= UTAG2) then begin RETBETRAG = UTAG2; end
                if(UTAG1 > 0 and TAGE <= UTAG1) then begin RETBETRAG = UTAG1; end
             end
             suspend;
          end
    end
  end
  ELSE
  begin
    FOR
      SELECT DISTINCT PREISLIST.LNR, PREISLIST.MATCHC, PREISLIST.BEZEICHUNG, PREISLIST.BETRAG, PREISLIST.PERS_ZUWEISUNG, PREISLIST.PRL_JUG, PREISLIST.PRL_KIN,
               PREISLIST.ZIMMERPREIS, PREISLIST.PAUSCHALE, PREISLIST.BETRAG_PERS,
               PREISLIST.PAUFSCHLAG1, PREISLIST.PAUFSCHLAG2, PREISLIST.PAUFSCHLAG3,
               PREISLIST.PAUFSCHLAG4, PREISLIST.PAUFSCHLAG5, PREISLIST.PAUFSCHLAG6,
               PREISLIST.KINDFREIPREIS, PREISLIST.EZZUSCHLAG, PREISLIST.UTAG1,
               PREISLIST.UTAG2, PREISLIST.UTAG3, PREISLIST.UBETRAG2, PREISLIST.UBETRAG1,PREISLIST.KURTAX_INKL,
               PREISLIST.UBETRAG3, PREISLIST.SAISON, PREISLIST.EZPREIS, SAISSTAM.VON, SAISSTAM.BIS,
               PREISLIST.JAUFSCHLAG_OK, PREISLIST.KAUFSCHLAG_OK, PREISLIST.JAUFSCHLAG1, PREISLIST.JAUFSCHLAG2, PREISLIST.JAUFSCHLAG3,
               PREISLIST.KAUFSCHLAG1, PREISLIST.KAUFSCHLAG2, PREISLIST.KAUFSCHLAG3, PREISLIST.MAX_TAGE, PREISLIST.we_verwend, PREISLIST.we_betrag,
               paramete.untertage_aufpr_akt
        FROM PREISLIST
            INNER JOIN SAISSTAM ON (PREISLIST.SAISON = SAISSTAM.LNR)
            LEFT OUTER JOIN PARAMETE ON (PARAMETE.mand_nr = 1)
        WHERE PREISLIST.TA_STATUS<1000 AND PREISLIST.MAND_NR = 1
                     AND PREISLIST.PREISTYP = 0
                     AND PREISLIST.PRCODE_LNR = 1
                     AND (PREISLIST.PREISLIST_LNR = :PREISLIST_NR)
                     AND PREISLIST.LNR > 0
              AND  (SAISSTAM.BIS > :ANR_TAG and SAISSTAM.VON < :ABR_TAG)
    
        ORDER BY PREISLIST.SORT_NR, preislist.matchc, SAISSTAM.VON
        INTO :LNR, :MATCHC, :BEZEICHNUNG, :BETRAG, :PERS_ZUWEISUNG, :PRL_JUG, :PRL_KIN,
               :ZIMMERPREIS, :PAUSCHALE, :BETRAG_PERS,
               :PAUFSCHLAG1, :PAUFSCHLAG2, :PAUFSCHLAG3,
               :PAUFSCHLAG4, :PAUFSCHLAG5, :PAUFSCHLAG6,
               :KINDFREIPREIS, :EZZUSCHLAG, :UTAG1,
               :UTAG2, :UTAG3, :UBETRAG2, :UBETRAG1,:KURTAX_INKL,
               :UBETRAG3, :SAISON, :EZPREIS, :VON, :BIS,
               :JAUFSCHLAG_OK, :KAUFSCHLAG_OK, :JAUFSCHLAG1, :JAUFSCHLAG2, :JAUFSCHLAG3,
               :KAUFSCHLAG1, :KAUFSCHLAG2, :KAUFSCHLAG3, :MAX_TAGE, :WE_VERWEND, :WE_BETRAG,
               :UNTERTAGE_AUFPR_AKT
   Do
   BEGIN
    /* Preislisten_betrag_rechnen */
    if(:LNR > 0) then
    begin
          RETBETRAG = 0.00;
          TAGE = DATEDIFF(day, ANR_TAG, ABR_TAG);
          if (:KINDFREIPREIS > 0) then
          begin
            PERS = PERS - ANZ_KINDER;
          end
          if (:PERS <= 0) then
          begin
            suspend;
          end
          else
          begin
             /* basic preis einstellen ... */
             RETBETRAG = BETRAG;
             if(PERS < BETTZAHL and EZPREIS > 0) then
             begin
                 RETBETRAG = EZPREIS;
             end
             HINT = BETRAG_PERS;
             if(UNTERTAGE_AUFPR_AKT = 1) then
             begin
                if(UTAG3 > 0 and TAGE <= UTAG3) then begin RETBETRAG = RETBETRAG + UTAG3; end
                if(UTAG2 > 0 and TAGE <= UTAG2) then begin RETBETRAG = RETBETRAG + UTAG2; end
                if(UTAG1 > 0 and TAGE <= UTAG1) then begin RETBETRAG = RETBETRAG + UTAG1; end
             end
             else
             begin
                if(UTAG3 > 0 and TAGE <= UTAG3) then begin RETBETRAG = UTAG3; end
                if(UTAG2 > 0 and TAGE <= UTAG2) then begin RETBETRAG = UTAG2; end
                if(UTAG1 > 0 and TAGE <= UTAG1) then begin RETBETRAG = UTAG1; end
             end
             suspend;
          end
    end
   END
  end
end ^

SET TERM ; ^
COMMIT WORK;
SET AUTODDL ON;
SET TERM ^ ;

