CREATE TRIGGER ADRESSEN_AI_AP FOR ADRESSEN 
ACTIVE AFTER INSERT POSITION 10 
AS
DECLARE VARIABLE S VARCHAR(20);
BEGIN
 /* Trigger text */
  FOR
    SELECT substring(name1 from 1 for 20)
      from adressen where adressen.lnr = new.lnr
    INTO :S
  DO
  BEGIN
    IF (NEW.LNR >0) THEN
      EXECUTE PROCEDURE PROC_ANWENDERPROT(1,NEW.LNR, NEW.ERF_USERID,10,0,0,S);
  END
END ^

CREATE TRIGGER ADRESSEN_AU_TA_STATUS FOR ADRESSEN 
ACTIVE BEFORE UPDATE POSITION 30 
AS
begin
  /* Trigger text */
  if (new.ta_status>=1000) then
     new.kor_datum = current_date;
end ^

CREATE TRIGGER ADRESSEN_AU_AP FOR ADRESSEN 
ACTIVE AFTER UPDATE POSITION 20 
AS
DECLARE VARIABLE S VARCHAR(20);
BEGIN
 /* Trigger text */
  FOR
    SELECT substring(name1 from 1 for 20)
      from adressen where adressen.lnr = old.lnr
    INTO :S
  DO
  BEGIN
    IF (OLD.LNR >0) THEN
      EXECUTE procedure PROC_ANWENDERPROT(1,OLD.LNR, NEW.KOR_USERID,20,0,0,S);
  END
END ^

