CREATE TRIGGER BELEGUNG_AU0 FOR BELEGUNG 
ACTIVE AFTER UPDATE POSITION 20 
AS
declare variable LIZENZ_OK integer;

begin
  /* Trigger text */
    select param_lizenz.housekeeping
      from param_lizenz
         into :LIZENZ_OK;
    if (LIZENZ_OK>0) then
    begin
        Update housekeeping
        set housekeeping.gk_lnr = new.lnr_gk,
            housekeeping.umzug = 1,
            housekeeping.gk_updated = 1
        where housekeeping.gk_lnr <> new.lnr_gk
        and housekeeping.beleg_lnr = new.lnr;
        
        Update housekeeping
        set housekeeping.datum = new.anreise
        where housekeeping.datum <> new.anreise
        and housekeeping.beleg_lnr = new.lnr_gk
        and housekeeping.gk_lnr = new.lnr;
        
        Update housekeeping
        set housekeeping.ta_status = new.ta_status
        where housekeeping.ta_status = new.ta_status
        and housekeeping.beleg_lnr = new.lnr_gk
        and housekeeping.gk_lnr = new.lnr;
    end

end ^

CREATE TRIGGER BELEGUNG_TISCHBELEGUNG FOR BELEGUNG 
ACTIVE AFTER UPDATE POSITION 25 
AS
    declare tischplanlizenz int = 0;
    declare kritisch int = 0;
begin
  /* Trigger text */
  select first 1 param_lizenz.tischplan_app from param_lizenz order by lnr
    into :tischplanlizenz;


  if (tischplanlizenz=1) then
  begin
     if (old.anreise=new.anreise and old.abreise=new.abreise) then kritisch = 0;
     else
     begin
        if (old.anreise>=new.anreise and old.abreise <= new.abreise) then kritisch = 1;
        if (old.anreise>new.anreise) then  kritisch=2;
        if (old.abreise<new.abreise) then  kritisch=3;
     end

     if (kritisch>0) then
     begin
       update tischbelegung set tischbelegung.kritisch = :kritisch, tischbelegung.kritisch_info = 'Zeitraum korrektur / Trigger'
         where tischbelegung.gk_lnr = new.lnr_gk and tischbelegung.ta_status <1000;

     end
  end
end ^

CREATE TRIGGER BELEGUNG_YIELD_UP FOR BELEGUNG 
ACTIVE AFTER UPDATE POSITION 50 
as
declare variable tempanreise Date;
declare variable tempabreise Date;
declare variable LIZENZ_OK integer;

begin

  /*  Bei gleicher Kategorie */
  select param_lizenz.yield_verwaltung
      from param_lizenz
         into :LIZENZ_OK;
  if (LIZENZ_OK>0) then
  begin
   
      if (old.LNR_KATE = new.LNR_KATE) then
      begin
        if (new.anreise > old.anreise) then
          tempanreise = old.anreise;
        else
          tempanreise = new.anreise;
    
        if (new.abreise > old.abreise) then
          tempabreise = new.abreise;
        else
          tempabreise = old.abreise;
    
        execute procedure proc_yield(tempabreise, tempanreise, new.lnr_kate);
      end
        else
        begin
          execute procedure PROC_YIELD(old.ABREISE, old.ANREISE, old.LNR_KATE);
          execute procedure PROC_YIELD(new.ABREISE, new.ANREISE, new.LNR_KATE);
        end
   end
end ^

