                             new.gbetrag, new.tagbetrag, new.l_tgabs, new.umb_gk_lnr, new.split_manu, new.tag_abs_lnr, new.basis_lnr,
                             new.prl_lnr_vererb, new.ta_status,new.gk_lnr);

