CREATE TRIGGER BUCHKONT_WIWA FOR BUCHKONT 
ACTIVE AFTER UPDATE POSITION 10 
AS


DECLARE VARIABLE WIWA_OK INTEGER;
DECLARE VARIABLE ALTE_MENGE INTEGER;
DECLARE VARIABLE NEU_MENGE INTEGER;


begin
  /* Trigger text */
  alte_menge = -9999999;
  for
    select param_lizenz.art_bestand_verw
      from param_lizenz where lnr = 1
         into :wiwa_ok
  do
  begin
    if (wiwa_ok>0 and old.ta_status<1000) then
    begin
       if (new.ta_status>=1000) then
       begin
          select leiststa.wiwa_bestand from leiststa
               where leiststa.lnr = old.leist_lnr and leiststa.wiwa_einheit>0
             into :alte_menge;

          if (alte_menge!=-9999999)  then
          begin
             alte_menge = alte_menge + old.me;
             update leiststa set
                 leiststa.wiwa_bestand = :alte_menge
                   where leiststa.lnr = old.leist_lnr;


          end

       end
       else
       begin
          alte_menge = -9999999;

          select leiststa.wiwa_bestand from leiststa
               where leiststa.lnr = old.leist_lnr and leiststa.wiwa_einheit>0
             into :alte_menge;
    
          if (alte_menge!=-9999999)  then
          begin
             neu_menge = alte_menge + old.me;
             update leiststa set
                 leiststa.wiwa_bestand = :neu_menge
                   where leiststa.lnr = old.leist_lnr;

          end
          alte_menge = -9999999;
          /* als 2 die neue leistung wieder abbuchen ....  */
          select leiststa.wiwa_bestand from leiststa
               where leiststa.lnr = new.leist_lnr and leiststa.wiwa_einheit>0
             into :alte_menge;
    
          if (alte_menge!=-9999999)  then
          begin
              neu_menge = alte_menge - new.me;
              update leiststa set
                 leiststa.wiwa_bestand = :neu_menge
                   where leiststa.lnr = new.leist_lnr;
    
          end
       end
    end
  end
end ^

CREATE TRIGGER BUCHKONT_FISKAL FOR BUCHKONT 
ACTIVE AFTER UPDATE POSITION 15 
AS
   DECLARE VARIABLE FISKAL_AKTIV INTEGER;
   DECLARE VARIABLE BETRAG FLOAT;
   DECLARE VARIABLE TAGBETRAG FLOAT;
begin
  /* Trigger text */
  FISKAL_AKTIV = 0;
  for
    select mandant.FISKAL_AKTIVE  from mandant where mandant.lnr = new.mand_nr
         into :FISKAL_AKTIV
  do
  begin
     if (FISKAL_AKTIV>0 and (new.sto_kennung != 1)) then
     begin
         if (((new.ta_status between 399 and 599) and (new.lnr_co = 0 or new.lnr_co is null)  )
            or ((new.ta_status = 500 ) and old.ta_status <=1 and (new.lnr_co > 0 )  ))
         then
         begin

            if (old.leist_lnr != new.leist_lnr or
                old.von       != new.von or
                old.bis       != new.bis  or
                old.me        != new.me   or
                old.prl_lnr   != new.prl_lnr  or
                old.bezeichn  !=  new.bezeichn or
                old.zipreis   !=  new.zipreis  or
                old.pausch    !=  new.pausch  or
                old.gbetrag   !=  new.gbetrag  or
                old.tagbetrag !=  new.tagbetrag or
                old.umb_gk_lnr != new.umb_gk_lnr or
                old.ta_status !=  new.ta_status

                --or (new.sto_kennung != 1)
    
    
    
              )
            then
            begin
                    betrag =  new.gbetrag;
                    tagbetrag = new.tagbetrag;
                    if (old.ta_status=400) then betrag = betrag - old.gbetrag;
                    if (new.sto_kennung = 2) then
                    begin
                       betrag = betrag *-1;
                       tagbetrag = tagbetrag *-1;
                    end
                    if (betrag!=0.000) then
                    begin
                        EXECUTE procedure
                        PROC_INS_FISKAL_BK ( new.lnr, new.leist_lnr ,new.von,new.bis,new.me, new.prl_lnr, new.bezeichn, new.zipreis, new.pausch,
                                             betrag, tagbetrag, new.l_tgabs, new.umb_gk_lnr, new.split_manu, new.tag_abs_lnr, new.basis_lnr,
                                             new.prl_lnr_vererb, new.ta_status,new.gk_lnr);
                    end
           end
        end
     end
  end
end ^

