CREATE TRIGGER GASTKONT_AU20 FOR GASTKONT 
INACTIVE AFTER UPDATE POSITION 20 
AS
DECLARE VARIABLE S VARCHAR(20);
begin
  /* Trigger text */
  FOR
    SELECT substring(gastkont.bemerk from 1 for 20)
       from gastkont where lnr = old.lnr
      INTO :S
  DO
   BEGIN
    IF (OLD.LNR >0) THEN
      EXECUTE procedure PROC_ANWENDERPROT(20,OLD.LNR, NEW.KOR_USERID,20,OLD.LNR,0,S);
  END
end ^

CREATE TRIGGER GASTKONT_TERMINE FOR GASTKONT 
ACTIVE AFTER UPDATE POSITION 25 
AS
begin
  /* Trigger text */
  if (new.ta_status>=1000 and new.lnr>0 and old.lnr>0 ) then
       update termine set termine.ta_status = 1000 where  termine.BELEGNR = new.lnr  and  termine.ta_status <1000 and termine.nur_pause<1;


  update meldedaten set meldedaten.ABREISE1 = new.bisaufh
      where meldedaten.gk_lnr = new.lnr and meldedaten.ta_status <1000 and meldedaten.abreise1 = old.bisaufh;

  update meldedaten set meldedaten.ABREISE2 = new.bisaufh
      where meldedaten.gk_lnr = new.lnr and meldedaten.ta_status <1000 and meldedaten.abreise2 = old.bisaufh;

  update meldedaten set meldedaten.ABREISE3 = new.bisaufh
      where meldedaten.gk_lnr = new.lnr and meldedaten.ta_status <1000 and meldedaten.abreise3 = old.bisaufh;

  update meldedaten set meldedaten.ABREISE4 = new.bisaufh
      where meldedaten.gk_lnr = new.lnr and meldedaten.ta_status <1000 and meldedaten.abreise4 = old.bisaufh;

  update meldedaten set meldedaten.ABREISE5 = new.bisaufh
      where meldedaten.gk_lnr = new.lnr and meldedaten.ta_status <1000 and meldedaten.abreise5 = old.bisaufh;

  update meldedaten set meldedaten.ABREISE6 = new.bisaufh
      where meldedaten.gk_lnr = new.lnr and meldedaten.ta_status <1000 and meldedaten.abreise6 = old.bisaufh;

  update meldedaten set meldedaten.ABREISE7 = new.bisaufh
      where meldedaten.gk_lnr = new.lnr and meldedaten.ta_status <1000 and meldedaten.abreise7 = old.bisaufh;

  update meldedaten set meldedaten.ABREISE8 = new.bisaufh
      where meldedaten.gk_lnr = new.lnr and meldedaten.ta_status <1000 and meldedaten.abreise8 = old.bisaufh;



end ^

