CREATE TRIGGER ONLINETRANS_ALLE_AI0 FOR ONLINETRANS_ALLE 
ACTIVE AFTER INSERT POSITION 5 
AS
begin
  /* Trigger für Kontigenten-Erhöhung nach Storno einer Konti-Reservierung */
  if(new.gk_lnr > 0 and new.ta_status >= 1000) then
  begin
    EXECUTE PROCEDURE TOOL_UPD_KONTI_AFTER_STORNO(new.gk_lnr);
  end
  else if(new.gk_lnr > 0 and new.ta_status < 1000) then
  begin
    EXECUTE PROCEDURE TOOL_UPD_KONTI_AFTER_CHANGE(new.gk_lnr, new.lnr);
  end
end ^

