CREATE TRIGGER TISCHBELEGUNG_ONL_VERB FOR TISCHBELEGUNG 
ACTIVE AFTER INSERT POSITION 10 
AS
begin
  /* Trigger text */
        insert into ONLINE_VERBUND (GK_LNR, TELEFON, KASSE, SCHLIESS, INTERNET_INTERN, INTERNET_EXTERN, INTERNET_ZUGANG,
                                                   FREI2, CI_STATUS, DATUM, TISCHMODUL)
                       select gastkont.lnr, 0, 0, 0, 0, 0, 0,0,
                               gastkont.ci_status, current_timestamp, 1
                               from gastkont where gastkont.lnr = new.gk_lnr and gastkont.ci_status = 1;


end ^

CREATE TRIGGER TISCHBELEGUNG_ACHRIV FOR TISCHBELEGUNG 
ACTIVE BEFORE UPDATE POSITION 25 
AS
  declare tischplanlizenz int = 0;
begin
  /* Trigger text */
  select first 1 param_lizenz.tischplan_app from param_lizenz order by lnr
    into :tischplanlizenz;


  if (tischplanlizenz=1) then
  begin
     insert into ARCHIV_TISCHBELEGUNG(TISCHBELEG_LNR, gk_lnr, tischplan_lnr, vonbelg, bisbelg, schicht,kritisch, kritisch_info,
                                      ta_status, erf_datum, erf_userid, kor_datum, kor_zeit, kor_userid, erf_zeit)

     Values (old.lnr, old.gk_lnr, old.tischplan_lnr, old.vonbelg, old.bisbelg, old.schicht,old.kritisch, old.kritisch_info,
              old.ta_status, current_date , old.erf_userid, old.kor_datum, old.kor_zeit, old.kor_userid, current_time);


  end
end ^

